window.UNITS=[{"g":1,"u":3,"title":"Fun and Games","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"beat","pos":"v","vi":"đánh bại ai","de":"defeat someone","ex":"Our team {beat} the champions.","k":"topic"},{"w":"board game","pos":"n phr","vi":"trò chơi bàn cờ","de":"a game played on a board","ex":"Chess is my favourite {board game}.","k":"topic"},{"w":"captain","pos":"n","vi":"đội trưởng","de":"the leader of a team","ex":"The {captain} encouraged every player.","k":"topic"},{"w":"challenge","pos":"v, n","vi":"thách thức; thử thách","de":"test someone's ability; a difficult task","ex":"The race was a real {challenge}.","k":"topic"},{"w":"champion","pos":"n","vi":"nhà vô địch","de":"a person who wins a competition","ex":"She became the national {champion}.","k":"topic"},{"w":"cheat","pos":"v","vi":"gian lận","de":"break rules to gain an advantage","ex":"You must not {cheat} in this game.","k":"topic"},{"w":"classical music","pos":"n phr","vi":"nhạc cổ điển","de":"music in a traditional formal style","ex":"My father enjoys {classical music}.","k":"topic"},{"w":"club","pos":"n","vi":"câu lạc bộ","de":"a group sharing an interest","ex":"I joined the school chess {club}.","k":"topic"},{"w":"coach","pos":"n","vi":"huấn luyện viên","de":"a person who trains a team","ex":"Our {coach} showed us a new technique.","k":"topic"},{"w":"competition","pos":"n","vi":"cuộc thi","de":"an event in which people try to win","ex":"The {competition} starts on Sunday.","k":"topic"},{"w":"concert","pos":"n","vi":"buổi hòa nhạc","de":"a public musical performance","ex":"We bought tickets for the {concert}.","k":"topic"},{"w":"defeat","pos":"v, n","vi":"đánh bại; sự thất bại","de":"win against; a loss in a contest","ex":"They suffered their first {defeat}.","k":"topic"},{"w":"entertaining","pos":"adj","vi":"thú vị, có tính giải trí","de":"enjoyable and interesting","ex":"The programme was very {entertaining}.","k":"topic"},{"w":"folk music","pos":"n phr","vi":"nhạc dân gian","de":"traditional music of a community","ex":"She sings Vietnamese {folk music}.","k":"topic"},{"w":"group","pos":"n","vi":"nhóm, ban nhạc","de":"people who perform or act together","ex":"The {group} released a new song.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"gym","pos":"n","vi":"phòng tập thể dục","de":"a place for physical exercise","ex":"He goes to the {gym} after work.","k":"topic"},{"w":"have fun","pos":"v phr","vi":"vui chơi, có thời gian vui vẻ","de":"enjoy yourself","ex":"We had fun at the festival.","k":"topic"},{"w":"interest","pos":"v, n","vi":"làm hứng thú; sự quan tâm","de":"attract attention; curiosity about something","ex":"Photography is one of her {interests}.","k":"topic"},{"w":"member","pos":"n","vi":"thành viên","de":"a person belonging to a group","ex":"Every {member} can vote.","k":"topic"},{"w":"opponent","pos":"n","vi":"đối thủ","de":"a person you compete against","ex":"My {opponent} played very well.","k":"topic"},{"w":"organise","pos":"v","vi":"tổ chức","de":"plan and arrange an activity","ex":"The students {organised} a sports day.","k":"topic"},{"w":"pleasure","pos":"n","vi":"niềm vui, sự thích thú","de":"a feeling of enjoyment","ex":"Reading gives me great {pleasure}.","k":"topic"},{"w":"referee","pos":"n","vi":"trọng tài","de":"an official who enforces game rules","ex":"The {referee} stopped the match.","k":"topic"},{"w":"rhythm","pos":"n","vi":"nhịp điệu","de":"a regular pattern of sounds or movement","ex":"Clap your hands to the {rhythm}.","k":"topic"},{"w":"risk","pos":"v, n","vi":"mạo hiểm; rủi ro","de":"expose to danger; a chance of harm","ex":"Do not {risk} your safety to win.","k":"topic"},{"w":"score","pos":"v, n","vi":"ghi điểm; tỉ số","de":"gain points; the number of points","ex":"She {scored} twice in the final.","k":"topic"},{"w":"support","pos":"v, n","vi":"ủng hộ; sự cổ vũ","de":"help or encourage a person or team","ex":"The crowd {supported} the home team.","k":"topic"},{"w":"team","pos":"n","vi":"đội, nhóm","de":"a group playing or working together","ex":"Our {team} practises on Fridays.","k":"topic"},{"w":"train","pos":"v","vi":"tập luyện","de":"practise to improve performance","ex":"He {trains} for an hour every day.","k":"topic"},{"w":"video game","pos":"n phr","vi":"trò chơi điện tử","de":"a game played on a screen","ex":"This {video game} has three levels.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"carry on","vi":"tiếp tục","ex":"Please carry {on} with your work.","k":"pv"},{"w":"eat out","vi":"ăn ở nhà hàng, quán ăn","ex":"We eat {out} once a month.","k":"pv"},{"w":"give up","vi":"từ bỏ một hoạt động hoặc thói quen","ex":"She gave {up} playing tennis.","k":"pv"},{"w":"join in","vi":"tham gia cùng người khác","ex":"Everyone joined {in} the game.","k":"pv"},{"w":"send off","vi":"truất quyền thi đấu, đuổi khỏi sân","ex":"The referee sent the player {off}.","k":"pv"},{"w":"take up","vi":"bắt đầu một sở thích hoặc môn thể thao","ex":"I took {up} swimming last year.","k":"pv"},{"w":"turn down","vi":"giảm âm lượng","ex":"Please turn the music {down}.","k":"pv"},{"w":"turn up","vi":"tăng âm lượng","ex":"Can you turn the radio {up}?","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"for a long time","vi":"trong một khoảng thời gian dài","ex":"We have known him {for} a long time.","k":"prep"},{"w":"for fun","vi":"để vui, không vì mục đích nghiêm túc","ex":"I paint {for} fun.","k":"prep"},{"w":"in the middle of","vi":"ở giữa","ex":"The lights failed {in} the middle of the show.","k":"prep"},{"w":"in time for","vi":"kịp giờ cho một việc","ex":"We arrived {in} time for the concert.","k":"prep"},{"w":"on CD/DVD/video","vi":"trên đĩa CD, DVD hoặc bản video","ex":"I have the film {on} DVD.","k":"prep"},{"w":"on stage","vi":"trên sân khấu","ex":"The singer appeared {on} stage.","k":"prep"},{"w":"act","vi":"hành động; năng động/không hoạt động; diễn viên","note":"act → action (n), active/inactive (adj), actor (n)","full":"hành động; năng động/không hoạt động; diễn viên","ex":"The actor leads an {active} life.","hint":"act","k":"wf"},{"w":"athlete","vi":"vận động viên; khỏe, giỏi thể thao; điền kinh","note":"athlete → athletic (adj), athletics (n)","full":"vận động viên; khỏe, giỏi thể thao; điền kinh","ex":"The athletic student enjoys {athletics}.","hint":"athlete","k":"wf"},{"w":"child","vi":"trẻ em; những đứa trẻ; tuổi thơ","note":"child → children (plural), childhood (n)","full":"trẻ em; những đứa trẻ; tuổi thơ","ex":"She spent her {childhood} in Hue.","hint":"child","k":"wf"},{"w":"collect","vi":"sưu tầm; bộ sưu tập; người sưu tầm","note":"collect → collection (n), collector (n)","full":"sưu tầm; bộ sưu tập; người sưu tầm","ex":"The collector showed us her {collection}.","hint":"collect","k":"wf"},{"w":"entertain","vi":"giải trí; sự giải trí","note":"entertain → entertainment (n)","full":"giải trí; sự giải trí","ex":"The festival provides free {entertainment}.","hint":"entertain","k":"wf"},{"w":"hero","vi":"anh hùng; anh dũng; nữ anh hùng","note":"hero → heroic (adj), heroine (n)","full":"anh hùng; anh dũng; nữ anh hùng","ex":"The {heroine} made a heroic decision.","hint":"hero","k":"wf"},{"w":"music","vi":"âm nhạc; thuộc âm nhạc; nhạc sĩ","note":"music → musical (adj), musician (n)","full":"âm nhạc; thuộc âm nhạc; nhạc sĩ","ex":"The {musician} has great musical talent.","hint":"music","k":"wf"},{"w":"play","vi":"chơi; người chơi; hay đùa nghịch","note":"play → player (n), playful (adj)","full":"chơi; người chơi; hay đùa nghịch","ex":"The {playful} child became a skilled player.","hint":"play","k":"wf"},{"w":"sail","vi":"đi thuyền; môn đi thuyền; thủy thủ","note":"sail → sailing (n), sailor (n)","full":"đi thuyền; môn đi thuyền; thủy thủ","ex":"The sailor taught us {sailing}.","hint":"sail","k":"wf"},{"w":"sing","vi":"hát; bài hát; ca sĩ; việc ca hát","note":"sing → sang (V2), sung (V3), song (n), singer (n), singing (n)","full":"hát; bài hát; ca sĩ; việc ca hát","ex":"The {singer} sang her latest song.","hint":"sing","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"bored with + N/V-ing","vi":"chán điều gì","ex":"I am bored {with} watching TV.","k":"pat"},{"w":"crazy about + N/V-ing","vi":"rất mê điều gì","ex":"He is crazy {about} football.","k":"pat"},{"w":"good at + N/V-ing","vi":"giỏi việc gì","ex":"She is good {at} drawing.","k":"pat"},{"w":"interested in + N/V-ing","vi":"quan tâm, hứng thú với","ex":"We are interested {in} sailing.","k":"pat"},{"w":"keen on + N/V-ing","vi":"rất thích","ex":"My brother is keen {on} chess.","k":"pat"},{"w":"popular with + sb","vi":"được ai ưa chuộng","ex":"This game is popular {with} teenagers.","k":"pat"},{"w":"feel like + N/V-ing","vi":"muốn, thích làm gì lúc này","ex":"I feel {like} going for a walk.","k":"pat"},{"w":"listen to + sb/sth","vi":"lắng nghe","ex":"Please listen {to} the coach.","k":"pat"},{"w":"take part in + sth","vi":"tham gia một hoạt động","ex":"We took part {in} the competition.","k":"pat"},{"w":"a book by sb about sth","vi":"sách do ai viết về điều gì","ex":"It is a book {by} a sailor about the sea.","k":"pat"},{"w":"a fan of + sb/sth","vi":"người hâm mộ","ex":"She is a fan {of} classical music.","k":"pat"},{"w":"a game against + sb","vi":"trận đấu với đối thủ","ex":"We have a game {against} Class 9A.","k":"pat"}]}]},{"g":1,"u":6,"title":"Learning and Doing","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"achieve","pos":"v","vi":"đạt được","de":"succeed in reaching a goal","ex":"She worked hard to {achieve} her goal.","k":"topic"},{"w":"brain","pos":"n","vi":"não","de":"the organ used for thought","ex":"Sleep helps your {brain} work well.","k":"topic"},{"w":"clever","pos":"adj","vi":"thông minh","de":"quick to learn or understand","ex":"That was a {clever} solution.","k":"topic"},{"w":"concentrate","pos":"v","vi":"tập trung","de":"give full attention to something","ex":"I cannot {concentrate} in this noise.","k":"topic"},{"w":"consider","pos":"v","vi":"cân nhắc","de":"think carefully about something","ex":"Please {consider} all the options.","k":"topic"},{"w":"course","pos":"n","vi":"khóa học","de":"a series of lessons","ex":"He is taking an English {course}.","k":"topic"},{"w":"degree","pos":"n","vi":"bằng đại học","de":"a university qualification","ex":"She has a {degree} in chemistry.","k":"topic"},{"w":"experience","pos":"v, n","vi":"trải nghiệm; kinh nghiệm","de":"go through; knowledge gained by doing","ex":"He has {experience} of teaching children.","k":"topic"},{"w":"expert","pos":"n, adj","vi":"chuyên gia; thành thạo","de":"a highly skilled person; highly skilled","ex":"Ask an {expert} for advice.","k":"topic"},{"w":"fail","pos":"v","vi":"thất bại, trượt","de":"not succeed or not pass","ex":"He {failed} the driving test.","k":"topic"},{"w":"guess","pos":"v, n","vi":"đoán; lời đoán","de":"answer without being certain","ex":"Can you {guess} the answer?","k":"topic"},{"w":"hesitate","pos":"v","vi":"do dự","de":"pause because of uncertainty","ex":"Do not {hesitate} to ask for help.","k":"topic"},{"w":"instruction","pos":"n","vi":"chỉ dẫn","de":"a direction telling you what to do","ex":"Read each {instruction} carefully.","k":"topic"},{"w":"make progress","pos":"v phr","vi":"tiến bộ","de":"improve or move forward","ex":"You are making good {progress}.","k":"topic"},{"w":"make sure","pos":"v phr","vi":"bảo đảm, kiểm tra chắc chắn","de":"check or ensure something is true","ex":"{Make sure} you save the file.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"mark","pos":"v, n","vi":"chấm bài; điểm","de":"assess work; a score","ex":"The teacher {marked} our essays.","k":"topic"},{"w":"mental","pos":"adj","vi":"thuộc trí óc","de":"relating to the mind","ex":"Chess requires {mental} effort.","k":"topic"},{"w":"pass","pos":"v","vi":"thi đỗ","de":"succeed in an examination","ex":"She {passed} all her exams.","k":"topic"},{"w":"qualification","pos":"n","vi":"bằng cấp, chứng chỉ","de":"official proof of training or skill","ex":"This job requires a teaching {qualification}.","k":"topic"},{"w":"remind","pos":"v","vi":"nhắc nhở","de":"help someone remember","ex":"Please {remind} me to call Nam.","k":"topic"},{"w":"report","pos":"n","vi":"báo cáo","de":"a written or spoken account","ex":"We wrote a {report} on the project.","k":"topic"},{"w":"revise","pos":"v","vi":"ôn tập","de":"study material again for an exam","ex":"I {revise} vocabulary every evening.","k":"topic"},{"w":"search","pos":"v, n","vi":"tìm kiếm; sự tìm kiếm","de":"try to find something","ex":"They {searched} for the missing notes.","k":"topic"},{"w":"skill","pos":"n","vi":"kĩ năng","de":"an ability developed through practice","ex":"Writing is an important {skill}.","k":"topic"},{"w":"smart","pos":"adj","vi":"thông minh, lanh lợi","de":"intelligent or quick-thinking","ex":"She is a {smart} student.","k":"topic"},{"w":"subject","pos":"n","vi":"môn học","de":"an area studied at school","ex":"Maths is my favourite {subject}.","k":"topic"},{"w":"take an exam","pos":"v phr","vi":"dự thi, làm bài thi","de":"sit an examination","ex":"We take our final exam in June.","k":"topic"},{"w":"talented","pos":"adj","vi":"có năng khiếu","de":"having natural ability","ex":"He is a {talented} young artist.","k":"topic"},{"w":"term","pos":"n","vi":"học kì","de":"one part of a school year","ex":"The new {term} starts next week.","k":"topic"},{"w":"wonder","pos":"v","vi":"tự hỏi","de":"think about something with curiosity","ex":"I {wonder} why the experiment failed.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"cross out","vi":"gạch bỏ","ex":"Cross {out} the wrong answer.","k":"pv"},{"w":"look up","vi":"tra cứu thông tin","ex":"Look the word {up} in a dictionary.","k":"pv"},{"w":"point out","vi":"chỉ ra thông tin đáng chú ý","ex":"The teacher pointed {out} my mistake.","k":"pv"},{"w":"read out","vi":"đọc thành tiếng","ex":"She read {out} the instructions.","k":"pv"},{"w":"rip up","vi":"xé vụn","ex":"He ripped {up} the old letter.","k":"pv"},{"w":"rub out","vi":"tẩy xóa bằng tẩy","ex":"Rub {out} the pencil marks.","k":"pv"},{"w":"turn over","vi":"lật sang mặt bên kia","ex":"Turn the page {over}.","k":"pv"},{"w":"write down","vi":"ghi chép lại","ex":"Write {down} the new words.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by heart","vi":"thuộc lòng","ex":"We learnt the poem {by} heart.","k":"prep"},{"w":"for instance","vi":"chẳng hạn","ex":"Some subjects, {for} instance history, need careful reading.","k":"prep"},{"w":"in conclusion","vi":"để kết luận, tóm lại","ex":"{In} conclusion, practice is essential.","k":"prep"},{"w":"in fact","vi":"thực tế là","ex":"I thought it was easy; {in} fact, it was difficult.","k":"prep"},{"w":"in favour of","vi":"ủng hộ","ex":"Most students are {in} favour of the plan.","k":"prep"},{"w":"in general","vi":"nhìn chung","ex":"{In} general, the class is making progress.","k":"prep"},{"w":"begin","vi":"bắt đầu; người mới học; sự khởi đầu","note":"begin → began (V2), begun (V3), beginner (n), beginning (n)","full":"bắt đầu; người mới học; sự khởi đầu","ex":"This course is suitable for beginners.","hint":"begin","k":"wf"},{"w":"brave","vi":"can đảm; lòng dũng cảm","note":"brave → bravery (n)","full":"can đảm; lòng dũng cảm","ex":"The child received an award for {bravery}.","hint":"brave","k":"wf"},{"w":"correct","vi":"sửa; sự sửa chữa; không đúng","note":"correct → correction (n), incorrect (adj)","full":"sửa; sự sửa chữa; không đúng","ex":"Please make a {correction} to the incorrect answer.","hint":"correct","k":"wf"},{"w":"divide","vi":"chia; phép chia, sự phân chia","note":"divide → division (n)","full":"chia; phép chia, sự phân chia","ex":"We practised {division} in class.","hint":"divide","k":"wf"},{"w":"educate","vi":"giáo dục; nền giáo dục","note":"educate → education (n)","full":"giáo dục; nền giáo dục","ex":"Every child deserves a good {education}.","hint":"educate","k":"wf"},{"w":"instruct","vi":"hướng dẫn; chỉ dẫn; người hướng dẫn","note":"instruct → instruction (n), instructor (n)","full":"hướng dẫn; chỉ dẫn; người hướng dẫn","ex":"The {instructor} gave clear instructions.","hint":"instruct","k":"wf"},{"w":"memory","vi":"trí nhớ; ghi nhớ; đài tưởng niệm/để tưởng niệm","note":"memory → memorise (v), memorial (n/adj)","full":"trí nhớ; ghi nhớ; đài tưởng niệm/để tưởng niệm","ex":"I memorised the dates before visiting the {memorial}.","hint":"memory","k":"wf"},{"w":"refer","vi":"đề cập, tham khảo; sự tham chiếu","note":"refer → reference (n)","full":"đề cập, tham khảo; sự tham chiếu","ex":"Keep these notes for future {reference}.","hint":"refer","k":"wf"},{"w":"silent","vi":"im lặng; sự im lặng; một cách lặng lẽ","note":"silent → silence (n), silently (adv)","full":"im lặng; sự im lặng; một cách lặng lẽ","ex":"The students worked {silently}.","hint":"silent","k":"wf"},{"w":"simple","vi":"đơn giản; đơn giản hóa; sự đơn giản","note":"simple → simplify (v), simplicity (n)","full":"đơn giản; đơn giản hóa; sự đơn giản","ex":"The diagram simplifies the process.","hint":"simple","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"capable of + N/V-ing","vi":"có khả năng","ex":"You are capable {of} solving this problem.","k":"pat"},{"w":"talented at + N/V-ing","vi":"có năng khiếu về","ex":"She is talented {at} designing clothes.","k":"pat"},{"w":"cheat at/in + sth","vi":"gian lận trong trò chơi, bài thi","ex":"He was caught cheating in the exam.","k":"pat"},{"w":"confuse sth with sth","vi":"nhầm điều này với điều kia","ex":"Do not confuse a planet {with} a star.","k":"pat"},{"w":"continue with + sth","vi":"tiếp tục việc gì","ex":"We continued {with} the lesson.","k":"pat"},{"w":"cope with + sth","vi":"đối phó, xoay xở với","ex":"She copes well {with} pressure.","k":"pat"},{"w":"help sb with sth","vi":"giúp ai việc gì","ex":"Can you help me {with} this exercise?","k":"pat"},{"w":"know about + sth","vi":"biết về","ex":"What do you know {about} robotics?","k":"pat"},{"w":"learn about + sth","vi":"học, tìm hiểu về","ex":"We are learning {about} electricity.","k":"pat"},{"w":"succeed in + N/V-ing","vi":"thành công trong việc","ex":"He succeeded {in} passing the test.","k":"pat"},{"w":"an opinion about/of + sth","vi":"ý kiến về","ex":"What is your opinion of this book?","k":"pat"},{"w":"a question about + sth","vi":"câu hỏi về","ex":"I have a question {about} the homework.","k":"pat"}]}]},{"g":1,"u":9,"title":"Coming and Going","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"abroad","pos":"adv","vi":"ở, ra nước ngoài","de":"in or to another country","ex":"She hopes to study {abroad}.","k":"topic"},{"w":"accommodation","pos":"n","vi":"chỗ ở","de":"a place to stay","ex":"We booked {accommodation} near the beach.","k":"topic"},{"w":"book","pos":"v","vi":"đặt trước","de":"reserve in advance","ex":"You should {book} your ticket early.","k":"topic"},{"w":"break","pos":"n","vi":"kì nghỉ ngắn, giờ nghỉ","de":"a short holiday or rest","ex":"We took a short {break} in Da Lat.","k":"topic"},{"w":"cancel","pos":"v","vi":"hủy","de":"decide an event will not happen","ex":"They {cancelled} the flight.","k":"topic"},{"w":"catch","pos":"v","vi":"bắt kịp tàu, xe","de":"get on transport before it leaves","ex":"Hurry or we will not {catch} the bus.","k":"topic"},{"w":"coach","pos":"n","vi":"xe khách đường dài","de":"a bus for longer journeys","ex":"We travelled to Hue by {coach}.","k":"topic"},{"w":"convenient","pos":"adj","vi":"thuận tiện","de":"easy and suitable for your needs","ex":"The hotel is in a {convenient} location.","k":"topic"},{"w":"crash","pos":"v, n","vi":"đâm, va chạm; vụ tai nạn","de":"collide violently; a collision","ex":"Two cars {crashed} near the bridge.","k":"topic"},{"w":"crowded","pos":"adj","vi":"đông đúc","de":"full of people","ex":"The station was {crowded}.","k":"topic"},{"w":"cruise","pos":"n","vi":"chuyến du ngoạn bằng tàu","de":"a holiday journey by ship","ex":"They went on a {cruise} around the islands.","k":"topic"},{"w":"delay","pos":"v, n","vi":"trì hoãn; sự chậm trễ","de":"make late; a period of waiting","ex":"Bad weather {delayed} our flight.","k":"topic"},{"w":"destination","pos":"n","vi":"điểm đến","de":"the place you are travelling to","ex":"Our final {destination} is Hue.","k":"topic"},{"w":"ferry","pos":"n","vi":"phà","de":"a boat carrying people or vehicles across water","ex":"We took a {ferry} across the river.","k":"topic"},{"w":"flight","pos":"n","vi":"chuyến bay","de":"a journey by aircraft","ex":"The {flight} takes two hours.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"foreign","pos":"adj","vi":"nước ngoài","de":"from another country","ex":"She speaks two {foreign} languages.","k":"topic"},{"w":"harbour","pos":"n","vi":"bến cảng","de":"a sheltered place for boats","ex":"The fishing boats returned to the {harbour}.","k":"topic"},{"w":"journey","pos":"n","vi":"hành trình","de":"travel from one place to another","ex":"The {journey} took six hours.","k":"topic"},{"w":"luggage","pos":"n","vi":"hành lí","de":"bags taken when travelling","ex":"Do not leave your {luggage} unattended.","k":"topic"},{"w":"nearby","pos":"adj, adv","vi":"gần đó","de":"not far away","ex":"We ate at a {nearby} restaurant.","k":"topic"},{"w":"pack","pos":"v","vi":"xếp hành lí","de":"put things into bags for travel","ex":"I need to {pack} my suitcase.","k":"topic"},{"w":"passport","pos":"n","vi":"hộ chiếu","de":"an official document for international travel","ex":"Keep your {passport} in a safe place.","k":"topic"},{"w":"platform","pos":"n","vi":"sân ga","de":"the area beside a railway track","ex":"Our train leaves from {platform} three.","k":"topic"},{"w":"public transport","pos":"n phr","vi":"giao thông công cộng","de":"shared transport available to everyone","ex":"{Public transport} is cheap here.","k":"topic"},{"w":"reach","pos":"v","vi":"đến được","de":"arrive at a place","ex":"We {reached} the hotel at noon.","k":"topic"},{"w":"resort","pos":"n","vi":"khu nghỉ dưỡng","de":"a place people visit for holidays","ex":"They stayed at a seaside {resort}.","k":"topic"},{"w":"souvenir","pos":"n","vi":"đồ lưu niệm","de":"something kept to remember a place","ex":"I bought a small {souvenir} for Mum.","k":"topic"},{"w":"traffic","pos":"n","vi":"xe cộ, giao thông","de":"vehicles moving on roads","ex":"There was heavy {traffic} this morning.","k":"topic"},{"w":"trip","pos":"n","vi":"chuyến đi","de":"a visit and usually the return journey","ex":"Our school organised a {trip} to the museum.","k":"topic"},{"w":"vehicle","pos":"n","vi":"phương tiện giao thông","de":"a machine used to carry people or goods","ex":"No {vehicles} are allowed in this street.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"get in/into","vi":"lên, vào ô tô","ex":"She got {into} the taxi.","k":"pv"},{"w":"get off","vi":"xuống xe buýt, tàu","ex":"Get {off} at the next stop.","k":"pv"},{"w":"get on/onto","vi":"lên xe buýt, tàu","ex":"We got on the train together.","k":"pv"},{"w":"get out of","vi":"ra khỏi ô tô, phòng hoặc tòa nhà","ex":"He got out {of} the car.","k":"pv"},{"w":"go away","vi":"rời đi, đi xa","ex":"We are going {away} this weekend.","k":"pv"},{"w":"go back to","vi":"quay trở lại","ex":"She went back {to} her hometown.","k":"pv"},{"w":"set off","vi":"khởi hành","ex":"We set {off} before sunrise.","k":"pv"},{"w":"take off","vi":"cất cánh","ex":"The plane took {off} on time.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by air/sea/bus/car","vi":"bằng đường hàng không, đường biển, xe buýt, ô tô","ex":"We travelled {by} sea.","k":"prep"},{"w":"on board","vi":"trên tàu, máy bay","ex":"There are fifty passengers {on} board.","k":"prep"},{"w":"on foot","vi":"đi bộ","ex":"The station is ten minutes away {on} foot.","k":"prep"},{"w":"on holiday","vi":"đang đi nghỉ","ex":"They are {on} holiday in Nha Trang.","k":"prep"},{"w":"on schedule","vi":"đúng lịch trình","ex":"The work is progressing {on} schedule.","k":"prep"},{"w":"on the coast","vi":"ở ven biển","ex":"My grandparents live {on} the coast.","k":"prep"},{"w":"attract","vi":"thu hút; hấp dẫn; điểm/sự thu hút","note":"attract → attractive (adj), attraction (n)","full":"thu hút; hấp dẫn; điểm/sự thu hút","ex":"The old town is a major tourist {attraction}.","hint":"attract","k":"wf"},{"w":"back","vi":"phía sau; ngược về sau","note":"back → backwards (adv)","full":"phía sau; ngược về sau","ex":"The driver moved {backwards} slowly.","hint":"back","k":"wf"},{"w":"choose","vi":"chọn; sự lựa chọn","note":"choose → chose (V2), chosen (V3), choice (n)","full":"chọn; sự lựa chọn","ex":"We {chose} the cheaper option.","hint":"choose","k":"wf"},{"w":"comfort","vi":"sự thoải mái; thoải mái/khó chịu","note":"comfort → comfortable/uncomfortable (adj)","full":"sự thoải mái; thoải mái/khó chịu","ex":"The seats were very {comfortable}.","hint":"comfort","k":"wf"},{"w":"depart","vi":"khởi hành; sự khởi hành","note":"depart → departure (n)","full":"khởi hành; sự khởi hành","ex":"Check the {departure} time carefully.","hint":"depart","k":"wf"},{"w":"direct","vi":"hướng dẫn, chỉ hướng; phương hướng","note":"direct → direction (n)","full":"hướng dẫn, chỉ hướng; phương hướng","ex":"We walked in the wrong {direction}.","hint":"direct","k":"wf"},{"w":"drive","vi":"lái xe; người lái xe","note":"drive → drove (V2), driven (V3), driver (n)","full":"lái xe; người lái xe","ex":"The {driver} drove us to the station.","hint":"drive","k":"wf"},{"w":"fly","vi":"bay; chuyến bay","note":"fly → flew (V2), flown (V3), flight (n)","full":"bay; chuyến bay","ex":"Our {flight} has been delayed.","hint":"fly","k":"wf"},{"w":"travel","vi":"đi lại; người đi du lịch","note":"travel → traveller (n)","full":"đi lại; người đi du lịch","ex":"The {traveller} carried a small bag.","hint":"travel","k":"wf"},{"w":"visit","vi":"thăm; khách tham quan","note":"visit → visitor (n)","full":"thăm; khách tham quan","ex":"The museum welcomes visitors daily.","hint":"visit","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"close to + sth","vi":"gần","ex":"The hotel is close {to} the station.","k":"pat"},{"w":"famous for + sth","vi":"nổi tiếng về","ex":"Hue is famous {for} its historic buildings.","k":"pat"},{"w":"far from + sth","vi":"xa","ex":"Our house is far {from} the airport.","k":"pat"},{"w":"late for + sth","vi":"trễ giờ","ex":"Do not be late {for} your flight.","k":"pat"},{"w":"suitable for + sb/sth","vi":"phù hợp với","ex":"This route is suitable {for} beginners.","k":"pat"},{"w":"arrive at/in + place","vi":"đến địa điểm cụ thể/thành phố, quốc gia","ex":"We arrived in Hue and then {at} the hotel.","k":"pat"},{"w":"ask sb about sth","vi":"hỏi ai về điều gì","ex":"I asked the guide {about} the castle.","k":"pat"},{"w":"ask for + sth","vi":"yêu cầu, xin","ex":"She asked {for} a map.","k":"pat"},{"w":"look at + sth","vi":"nhìn vào","ex":"Look {at} the sign above the door.","k":"pat"},{"w":"prepare for + sth","vi":"chuẩn bị cho","ex":"We are preparing {for} the journey.","k":"pat"},{"w":"provide sb with sth","vi":"cung cấp cho ai thứ gì","ex":"The hotel provided us {with} towels.","k":"pat"},{"w":"wait for + sb/sth","vi":"đợi","ex":"We waited {for} the next bus.","k":"pat"}]}]},{"g":1,"u":12,"title":"Friends and Relations","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"apologise","pos":"v","vi":"xin lỗi","de":"say you are sorry","ex":"You should {apologise} for being late.","k":"topic"},{"w":"boyfriend","pos":"n","vi":"bạn trai","de":"a male romantic partner","ex":"Her {boyfriend} studies engineering.","k":"topic"},{"w":"close","pos":"adj","vi":"thân thiết","de":"having a strong relationship","ex":"We have been {close} friends for years.","k":"topic"},{"w":"confident","pos":"adj","vi":"tự tin","de":"sure of your own ability","ex":"She feels {confident} about the interview.","k":"topic"},{"w":"cool","pos":"adj","vi":"sành điệu, điềm tĩnh","de":"fashionable or impressively calm","ex":"He stayed {cool} during the argument.","k":"topic"},{"w":"couple","pos":"n","vi":"cặp đôi","de":"two people in a relationship","ex":"The {couple} moved into a new flat.","k":"topic"},{"w":"decorate","pos":"v","vi":"trang trí","de":"make something look more attractive","ex":"We {decorated} the room for the party.","k":"topic"},{"w":"defend","pos":"v","vi":"bảo vệ","de":"protect from attack or criticism","ex":"She {defended} her friend against unfair criticism.","k":"topic"},{"w":"divorced","pos":"adj","vi":"đã li hôn","de":"no longer legally married","ex":"His parents are {divorced}.","k":"topic"},{"w":"flat","pos":"n","vi":"căn hộ","de":"a home within a larger building","ex":"They rent a small {flat}.","k":"topic"},{"w":"generous","pos":"adj","vi":"hào phóng","de":"willing to give or share","ex":"It was {generous} of you to help.","k":"topic"},{"w":"girlfriend","pos":"n","vi":"bạn gái","de":"a female romantic partner","ex":"He introduced his {girlfriend} to us.","k":"topic"},{"w":"grateful","pos":"adj","vi":"biết ơn","de":"feeling thankful","ex":"I am {grateful} for your support.","k":"topic"},{"w":"guest","pos":"n","vi":"khách được mời","de":"a person invited to visit","ex":"The {guests} arrived at seven.","k":"topic"},{"w":"independent","pos":"adj","vi":"độc lập","de":"able to act without relying on others","ex":"She became {independent} at a young age.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"introduce","pos":"v","vi":"giới thiệu","de":"tell people each other's names","ex":"Let me {introduce} my cousin.","k":"topic"},{"w":"loving","pos":"adj","vi":"yêu thương","de":"showing strong affection","ex":"He grew up in a {loving} family.","k":"topic"},{"w":"loyal","pos":"adj","vi":"trung thành","de":"remaining faithful and supportive","ex":"A {loyal} friend does not abandon you.","k":"topic"},{"w":"mood","pos":"n","vi":"tâm trạng","de":"the way someone feels at a time","ex":"Dad is in a good {mood} today.","k":"topic"},{"w":"neighbourhood","pos":"n","vi":"khu phố","de":"the area around your home","ex":"This is a friendly {neighbourhood}.","k":"topic"},{"w":"ordinary","pos":"adj","vi":"bình thường","de":"usual and not special","ex":"It was an {ordinary} school day.","k":"topic"},{"w":"patient","pos":"adj","vi":"kiên nhẫn","de":"able to wait calmly","ex":"Our teacher is very {patient}.","k":"topic"},{"w":"private","pos":"adj","vi":"riêng tư","de":"personal or not shared with everyone","ex":"Please respect her {private} life.","k":"topic"},{"w":"recognise","pos":"v","vi":"nhận ra","de":"identify someone or something known before","ex":"I did not {recognise} him at first.","k":"topic"},{"w":"relation","pos":"n","vi":"người họ hàng","de":"a member of your family","ex":"Many of my {relations} live nearby.","k":"topic"},{"w":"rent","pos":"v, n","vi":"thuê; tiền thuê","de":"pay to use property; the payment","ex":"They pay the {rent} every month.","k":"topic"},{"w":"respect","pos":"v, n","vi":"tôn trọng; sự kính trọng","de":"admire and treat properly","ex":"We {respect} each other's opinions.","k":"topic"},{"w":"single","pos":"adj","vi":"độc thân","de":"not married or without a partner","ex":"She is {single} and lives alone.","k":"topic"},{"w":"stranger","pos":"n","vi":"người lạ","de":"a person you do not know","ex":"Do not share passwords with {strangers}.","k":"topic"},{"w":"trust","pos":"v, n","vi":"tin tưởng; lòng tin","de":"believe someone is honest or reliable","ex":"I {trust} her completely.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"bring up","vi":"nuôi dưỡng một đứa trẻ","ex":"Her grandparents brought her {up}.","k":"pv"},{"w":"fall out with","vi":"cãi nhau rồi bất hòa với ai","ex":"He fell out {with} his best friend.","k":"pv"},{"w":"get on with","vi":"hòa thuận, có quan hệ tốt với","ex":"I get on well {with} my cousins.","k":"pv"},{"w":"go out with","vi":"hẹn hò với","ex":"She is going out {with} a classmate.","k":"pv"},{"w":"grow up","vi":"lớn lên, trưởng thành","ex":"I grew {up} in Ho Chi Minh City.","k":"pv"},{"w":"let down","vi":"làm ai thất vọng","ex":"I will not let you {down}.","k":"pv"},{"w":"look after","vi":"chăm sóc","ex":"Can you look {after} my cat?","k":"pv"},{"w":"split up","vi":"chia tay, kết thúc quan hệ","ex":"The couple split {up} last year.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by yourself","vi":"một mình, tự mình","ex":"Did you make this {by} yourself?","k":"prep"},{"w":"in common with","vi":"có điểm chung với","ex":"I have a lot {in} common with her.","k":"prep"},{"w":"in contact with","vi":"đang liên lạc với","ex":"Are you still {in} contact with Nam?","k":"prep"},{"w":"in love with","vi":"đang yêu","ex":"He is {in} love with his childhood friend.","k":"prep"},{"w":"on purpose","vi":"cố ý","ex":"I did not hurt you {on} purpose.","k":"prep"},{"w":"on your own","vi":"một mình, không có ai giúp","ex":"She completed the work {on} her own.","k":"prep"},{"w":"able","vi":"có khả năng; năng lực; khuyết tật/không thể","note":"able → ability (n), disabled/unable (adj)","full":"có khả năng; năng lực; khuyết tật/không thể","ex":"She has the {ability} to lead the group.","hint":"able","k":"wf"},{"w":"admire","vi":"ngưỡng mộ; sự ngưỡng mộ","note":"admire → admiration (n)","full":"ngưỡng mộ; sự ngưỡng mộ","ex":"I have great {admiration} for her courage.","hint":"admire","k":"wf"},{"w":"care","vi":"quan tâm; cẩn thận/bất cẩn","note":"care → careful/careless (adj)","full":"quan tâm; cẩn thận/bất cẩn","ex":"A {careless} mistake cost us a point.","hint":"care","k":"wf"},{"w":"confident","vi":"tự tin; sự tự tin","note":"confident → confidence (n)","full":"tự tin; sự tự tin","ex":"Practice helped him gain {confidence}.","hint":"confident","k":"wf"},{"w":"forgive","vi":"tha thứ; sự tha thứ","note":"forgive → forgave (V2), forgiven (V3), forgiveness (n)","full":"tha thứ; sự tha thứ","ex":"He asked for her {forgiveness}.","hint":"forgive","k":"wf"},{"w":"honest","vi":"trung thực; không trung thực; sự trung thực","note":"honest → dishonest (adj), honesty (n)","full":"trung thực; không trung thực; sự trung thực","ex":"We value {honesty} in friendship.","hint":"honest","k":"wf"},{"w":"introduce","vi":"giới thiệu; sự giới thiệu","note":"introduce → introduction (n)","full":"giới thiệu; sự giới thiệu","ex":"The meeting began with a short {introduction}.","hint":"introduce","k":"wf"},{"w":"lie","vi":"nói dối; người nói dối; đang nói dối","note":"lie → liar (n), lying (V-ing)","full":"nói dối; người nói dối; đang nói dối","ex":"The liar admitted {lying} to us.","hint":"lie","k":"wf"},{"w":"person","vi":"người; tính cách; cá nhân","note":"person → personality (n), personal (adj)","full":"người; tính cách; cá nhân","ex":"She has a cheerful {personality}.","hint":"person","k":"wf"},{"w":"relate","vi":"liên hệ; họ hàng; mối quan hệ","note":"relate → relative/relation (n), relationship (n)","full":"liên hệ; họ hàng; mối quan hệ","ex":"They have a strong {relationship}.","hint":"relate","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"fond of + N/V-ing","vi":"yêu thích","ex":"My aunt is fond {of} gardening.","k":"pat"},{"w":"jealous of + sb/sth","vi":"ghen tị với","ex":"He is jealous {of} his brother's success.","k":"pat"},{"w":"kind to + sb","vi":"tử tế với","ex":"She is kind {to} everyone.","k":"pat"},{"w":"married to + sb","vi":"kết hôn với","ex":"He is married {to} a teacher.","k":"pat"},{"w":"proud of + sb/sth","vi":"tự hào về","ex":"We are proud {of} our students.","k":"pat"},{"w":"admire sb for sth/V-ing","vi":"ngưỡng mộ ai vì","ex":"I admire her {for} helping others.","k":"pat"},{"w":"apologise to sb for sth/V-ing","vi":"xin lỗi ai vì","ex":"He apologised {to} me for shouting.","k":"pat"},{"w":"argue with sb about sth","vi":"tranh cãi với ai về","ex":"They argued about the plans.","k":"pat"},{"w":"care about + sb/sth","vi":"quan tâm đến","ex":"She cares {about} her family.","k":"pat"},{"w":"chat to sb about sth","vi":"trò chuyện với ai về","ex":"We chatted about school.","k":"pat"},{"w":"an argument with sb about sth","vi":"cuộc tranh cãi với ai về","ex":"I had an argument {with} him about money.","k":"pat"},{"w":"a relationship with + sb","vi":"mối quan hệ với","ex":"She has a good relationship {with} her parents.","k":"pat"}]}]},{"g":1,"u":15,"title":"Buying and Selling","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"advertisement","pos":"n","vi":"quảng cáo","de":"a message promoting a product","ex":"I saw an {advertisement} for this course.","k":"topic"},{"w":"afford","pos":"v","vi":"có đủ tiền, thời gian","de":"have enough money or time","ex":"We cannot {afford} a new car.","k":"topic"},{"w":"bargain","pos":"n","vi":"món hời","de":"something bought at a low price","ex":"This jacket was a real {bargain}.","k":"topic"},{"w":"brand","pos":"n","vi":"nhãn hiệu","de":"a product name used by a company","ex":"Which {brand} of phone do you prefer?","k":"topic"},{"w":"catalogue","pos":"n","vi":"danh mục hàng hóa","de":"a list of products with details","ex":"The {catalogue} shows all available colours.","k":"topic"},{"w":"change","pos":"n","vi":"tiền thừa trả lại","de":"money returned after payment","ex":"Keep the {change}.","k":"topic"},{"w":"coin","pos":"n","vi":"đồng xu","de":"a small metal piece of money","ex":"He dropped a {coin} into the machine.","k":"topic"},{"w":"cost","pos":"v, n","vi":"có giá; chi phí","de":"have a price; the amount needed","ex":"The repair {cost} more than expected.","k":"topic"},{"w":"customer","pos":"n","vi":"khách hàng","de":"a person who buys goods or services","ex":"The shop welcomes every {customer}.","k":"topic"},{"w":"debt","pos":"n","vi":"nợ","de":"money owed to someone","ex":"He is trying to pay off his {debt}.","k":"topic"},{"w":"demand","pos":"v","vi":"đòi hỏi, yêu cầu","de":"ask for something firmly","ex":"The customer {demanded} a refund.","k":"topic"},{"w":"export","pos":"v","vi":"xuất khẩu","de":"sell goods to another country","ex":"The company {exports} coffee.","k":"topic"},{"w":"fee","pos":"n","vi":"phí","de":"money paid for a service","ex":"The entrance {fee} is low.","k":"topic"},{"w":"fortune","pos":"n","vi":"gia tài, khoản tiền lớn","de":"a very large amount of money","ex":"Their new house cost a {fortune}.","k":"topic"},{"w":"import","pos":"v","vi":"nhập khẩu","de":"buy goods from another country","ex":"We {import} some electronic components.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"invest","pos":"v","vi":"đầu tư","de":"put money into something for future gain","ex":"She {invested} in a small business.","k":"topic"},{"w":"obtain","pos":"v","vi":"có được","de":"get something through effort or a process","ex":"You must {obtain} permission first.","k":"topic"},{"w":"owe","pos":"v","vi":"nợ ai tiền","de":"need to repay money","ex":"I {owe} Minh fifty thousand dong.","k":"topic"},{"w":"own","pos":"v","vi":"sở hữu","de":"have something as your property","ex":"They {own} a small shop.","k":"topic"},{"w":"profit","pos":"n","vi":"lợi nhuận","de":"money gained after costs","ex":"The shop made a small {profit}.","k":"topic"},{"w":"property","pos":"n","vi":"tài sản, bất động sản","de":"things, land or buildings owned","ex":"Do not damage public {property}.","k":"topic"},{"w":"purchase","pos":"v, n","vi":"mua; món hàng mua","de":"buy; something bought","ex":"Keep proof of {purchase}.","k":"topic"},{"w":"receipt","pos":"n","vi":"biên lai","de":"a document proving payment","ex":"Please keep your {receipt}.","k":"topic"},{"w":"require","pos":"v","vi":"yêu cầu, cần","de":"need or officially demand","ex":"The machine {requires} regular maintenance.","k":"topic"},{"w":"sale","pos":"n","vi":"việc bán; đợt giảm giá","de":"the selling of goods; a reduced-price period","ex":"I bought these shoes in the {sale}.","k":"topic"},{"w":"save","pos":"v","vi":"tiết kiệm","de":"keep money for later or avoid wasting it","ex":"I {save} part of my allowance.","k":"topic"},{"w":"select","pos":"v","vi":"lựa chọn","de":"choose carefully","ex":"{Select} the size you need.","k":"topic"},{"w":"supply","pos":"v, n","vi":"cung cấp; nguồn cung","de":"provide; an available amount","ex":"This farm {supplies} vegetables to the market.","k":"topic"},{"w":"variety","pos":"n","vi":"sự đa dạng","de":"a range of different things","ex":"The shop offers a wide {variety} of books.","k":"topic"},{"w":"waste","pos":"v, n","vi":"lãng phí; sự lãng phí","de":"use carelessly; unnecessary use","ex":"Do not {waste} your money.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"add up","vi":"cộng lại, tính tổng","ex":"Add {up} the prices on the receipt.","k":"pv"},{"w":"come back from","vi":"trở về từ","ex":"She came back {from} the market.","k":"pv"},{"w":"give away","vi":"cho, tặng miễn phí","ex":"They gave {away} free samples.","k":"pv"},{"w":"hurry up","vi":"nhanh lên","ex":"Hurry {up} or the shop will close.","k":"pv"},{"w":"pay back","vi":"trả lại tiền đã vay","ex":"I will pay you {back} tomorrow.","k":"pv"},{"w":"save up for","vi":"dành dụm tiền để mua","ex":"He is saving up {for} a laptop.","k":"pv"},{"w":"take back","vi":"mang trả về nơi mua hoặc nơi cũ","ex":"Take the faulty charger {back}.","k":"pv"},{"w":"take down","vi":"gỡ xuống từ vị trí cao","ex":"They took {down} the old sign.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by credit card/cheque","vi":"bằng thẻ tín dụng, séc","ex":"Can I pay {by} credit card?","k":"prep"},{"w":"for rent","vi":"để cho thuê","ex":"That flat is {for} rent.","k":"prep"},{"w":"for sale","vi":"đang được rao bán","ex":"The bicycle is {for} sale.","k":"prep"},{"w":"in cash","vi":"bằng tiền mặt","ex":"She paid {in} cash.","k":"prep"},{"w":"in debt","vi":"đang mắc nợ","ex":"The company is heavily {in} debt.","k":"prep"},{"w":"in good/bad condition","vi":"trong tình trạng tốt, xấu","ex":"The used bike is {in} good condition.","k":"prep"},{"w":"add","vi":"cộng; phép cộng, sự bổ sung","note":"add → addition (n)","full":"cộng; phép cộng, sự bổ sung","ex":"Check your {addition} carefully.","hint":"add","k":"wf"},{"w":"afford","vi":"đủ khả năng chi trả; có giá phải chăng","note":"afford → affordable (adj)","full":"đủ khả năng chi trả; có giá phải chăng","ex":"We need {affordable} accommodation.","hint":"afford","k":"wf"},{"w":"compare","vi":"so sánh; sự so sánh","note":"compare → comparison (n)","full":"so sánh; sự so sánh","ex":"The website offers a price {comparison}.","hint":"compare","k":"wf"},{"w":"decide","vi":"quyết định; quyết định được đưa ra","note":"decide → decision (n)","full":"quyết định; quyết định được đưa ra","ex":"Buying a car is a major {decision}.","hint":"decide","k":"wf"},{"w":"expense","vi":"chi phí; đắt/không đắt","note":"expense → expensive/inexpensive (adj)","full":"chi phí; đắt/không đắt","ex":"We found an {inexpensive} restaurant.","hint":"expense","k":"wf"},{"w":"judge","vi":"đánh giá; sự phán đoán","note":"judge → judgement (n)","full":"đánh giá; sự phán đoán","ex":"Use your own {judgement} before buying.","hint":"judge","k":"wf"},{"w":"serve","vi":"phục vụ; dịch vụ; người hầu","note":"serve → service (n), servant (n)","full":"phục vụ; dịch vụ; người hầu","ex":"The restaurant provides excellent {service}.","hint":"serve","k":"wf"},{"w":"true","vi":"đúng; sự thật; sai sự thật/trung thực","note":"true → truth (n), untrue/truthful (adj)","full":"đúng; sự thật; sai sự thật/trung thực","ex":"The advertisement was not {truthful}.","hint":"true","k":"wf"},{"w":"use","vi":"sử dụng; hữu ích/vô dụng","note":"use → useful/useless (adj)","full":"sử dụng; hữu ích/vô dụng","ex":"This tool is {useful} for repairs.","hint":"use","k":"wf"},{"w":"value","vi":"giá trị; có giá trị","note":"value → valuable (adj)","full":"giá trị; có giá trị","ex":"Keep {valuable} items in a safe place.","hint":"value","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"wrong about/with + sth","vi":"sai về/có vấn đề với","ex":"You are wrong {about} the price; something is wrong with the label.","k":"pat"},{"w":"belong to + sb","vi":"thuộc về","ex":"This wallet belongs {to} Mai.","k":"pat"},{"w":"borrow sth from sb","vi":"mượn thứ gì từ ai","ex":"I borrowed a pen {from} Hoa.","k":"pat"},{"w":"buy sth from sb/place","vi":"mua thứ gì từ","ex":"We bought fruit {from} a local farmer.","k":"pat"},{"w":"choose between + options","vi":"lựa chọn giữa","ex":"I cannot choose {between} these two bags.","k":"pat"},{"w":"compare sth to/with sth","vi":"so sánh thứ này với thứ kia","ex":"Compare this model with the cheaper one.","k":"pat"},{"w":"decide on + sth","vi":"quyết định chọn","ex":"Have you decided {on} a colour?","k":"pat"},{"w":"lend sth to sb","vi":"cho ai mượn thứ gì","ex":"He lent his bike {to} me.","k":"pat"},{"w":"pay for + sth","vi":"trả tiền cho","ex":"Who paid {for} the tickets?","k":"pat"},{"w":"spend money/time on sth","vi":"chi tiền, thời gian vào","ex":"She spends little money {on} clothes.","k":"pat"},{"w":"an advertisement for + sth","vi":"quảng cáo cho","ex":"I saw an advertisement {for} a new phone.","k":"pat"}]}]},{"g":1,"u":18,"title":"Inventions and Discoveries","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"artificial","pos":"adj","vi":"nhân tạo","de":"made by people rather than nature","ex":"The flowers are {artificial}.","k":"topic"},{"w":"automatic","pos":"adj","vi":"tự động","de":"working without direct human control","ex":"The doors are {automatic}.","k":"topic"},{"w":"complicated","pos":"adj","vi":"phức tạp","de":"difficult to understand or use","ex":"The instructions look {complicated}.","k":"topic"},{"w":"decrease","pos":"v, n","vi":"giảm; sự giảm","de":"become less; a reduction","ex":"The number of errors {decreased}.","k":"topic"},{"w":"digital","pos":"adj","vi":"kĩ thuật số","de":"using electronic information in numerical form","ex":"She uses a {digital} camera.","k":"topic"},{"w":"discover","pos":"v","vi":"khám phá, phát hiện","de":"find something previously unknown","ex":"Scientists {discovered} a new species.","k":"topic"},{"w":"effect","pos":"n","vi":"tác động, kết quả","de":"a change caused by something","ex":"The change had a positive {effect}.","k":"topic"},{"w":"equipment","pos":"n","vi":"thiết bị","de":"tools needed for an activity","ex":"The laboratory needs new {equipment}.","k":"topic"},{"w":"estimate","pos":"v","vi":"ước tính","de":"calculate approximately","ex":"We {estimated} the cost of the project.","k":"topic"},{"w":"exact","pos":"adj","vi":"chính xác","de":"completely accurate","ex":"What is the {exact} temperature?","k":"topic"},{"w":"experiment","pos":"v, n","vi":"thí nghiệm; cuộc thí nghiệm","de":"test an idea scientifically","ex":"We carried out a simple {experiment}.","k":"topic"},{"w":"gadget","pos":"n","vi":"thiết bị nhỏ, tiện ích","de":"a small useful device","ex":"This {gadget} measures room temperature.","k":"topic"},{"w":"hardware","pos":"n","vi":"phần cứng","de":"the physical parts of a computer","ex":"The problem is with the {hardware}.","k":"topic"},{"w":"invent","pos":"v","vi":"phát minh","de":"create something new","ex":"Who {invented} this machine?","k":"topic"},{"w":"involve","pos":"v","vi":"bao gồm, liên quan","de":"include as a necessary part","ex":"The project {involves} careful research.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"laboratory","pos":"n","vi":"phòng thí nghiệm","de":"a room for scientific work","ex":"Students must be careful in the {laboratory}.","k":"topic"},{"w":"lack","pos":"v, n","vi":"thiếu; sự thiếu hụt","de":"not have enough; a shortage","ex":"The team {lacks} experience.","k":"topic"},{"w":"laptop","pos":"n","vi":"máy tính xách tay","de":"a portable computer","ex":"My {laptop} is light enough to carry.","k":"topic"},{"w":"maximum","pos":"adj","vi":"tối đa","de":"the greatest amount allowed or possible","ex":"The {maximum} speed is shown here.","k":"topic"},{"w":"minimum","pos":"adj","vi":"tối thiểu","de":"the smallest amount allowed or possible","ex":"What is the {minimum} age?","k":"topic"},{"w":"operate","pos":"v","vi":"vận hành; hoạt động","de":"control a machine; function","ex":"Only trained staff may {operate} the machine.","k":"topic"},{"w":"plastic","pos":"n, adj","vi":"nhựa; bằng nhựa","de":"a manufactured material","ex":"The case is made of {plastic}.","k":"topic"},{"w":"program","pos":"v, n","vi":"lập trình; chương trình","de":"give computer instructions; a set of instructions","ex":"She wrote a {program} to sort the data.","k":"topic"},{"w":"research","pos":"n","vi":"nghiên cứu","de":"careful study to find new knowledge","ex":"More {research} is needed.","k":"topic"},{"w":"run","pos":"v","vi":"chạy, vận hành","de":"operate or make a system operate","ex":"Can this computer {run} the software?","k":"topic"},{"w":"screen","pos":"n","vi":"màn hình","de":"a surface displaying images","ex":"Do not touch the {screen}.","k":"topic"},{"w":"software","pos":"n","vi":"phần mềm","de":"computer programs","ex":"The {software} is easy to install.","k":"topic"},{"w":"sudden","pos":"adj","vi":"đột ngột","de":"happening quickly and unexpectedly","ex":"There was a {sudden} change in temperature.","k":"topic"},{"w":"technology","pos":"n","vi":"công nghệ","de":"scientific knowledge used practically","ex":"{Technology} can support learning.","k":"topic"},{"w":"unique","pos":"adj","vi":"độc đáo, duy nhất","de":"the only one of its kind","ex":"Each device has a {unique} code.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"break down","vi":"hỏng, ngừng hoạt động","ex":"Our printer broke {down} yesterday.","k":"pv"},{"w":"come across","vi":"tình cờ tìm thấy","ex":"I came {across} an old photograph.","k":"pv"},{"w":"find out","vi":"tìm ra thông tin","ex":"We need to find {out} the cause.","k":"pv"},{"w":"make up","vi":"bịa ra lời giải thích, câu chuyện","ex":"He made {up} an excuse.","k":"pv"},{"w":"pull off","vi":"kéo làm đứt hoặc rời ra","ex":"The child pulled the handle {off}.","k":"pv"},{"w":"throw away","vi":"vứt bỏ","ex":"Do not throw the instructions {away}.","k":"pv"},{"w":"turn off","vi":"tắt thiết bị","ex":"Turn {off} the lights before leaving.","k":"pv"},{"w":"turn on","vi":"bật thiết bị","ex":"She turned {on} the computer.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"at last","vi":"cuối cùng, sau thời gian chờ","ex":"{At} last, the machine worked.","k":"prep"},{"w":"by chance","vi":"tình cờ","ex":"We met the inventor {by} chance.","k":"prep"},{"w":"in my opinion","vi":"theo ý kiến của tôi","ex":"{In} my opinion, the design is practical.","k":"prep"},{"w":"in the end","vi":"cuối cùng, sau cả quá trình","ex":"{In} the end, we chose a simpler design.","k":"prep"},{"w":"in the future","vi":"trong tương lai","ex":"The system may improve {in} the future.","k":"prep"},{"w":"out of order","vi":"bị hỏng, không sử dụng được","ex":"The lift is {out} of order.","k":"prep"},{"w":"boil","vi":"đun sôi; nồi hơi, máy đun; nóng sôi","note":"boil → boiler (n), boiling (adj)","full":"đun sôi; nồi hơi, máy đun; nóng sôi","ex":"Do not touch the {boiling} water.","hint":"boil","k":"wf"},{"w":"chemist","vi":"nhà hóa học; hóa chất/thuộc hóa học; hóa học","note":"chemist → chemical (n/adj), chemistry (n)","full":"nhà hóa học; hóa chất/thuộc hóa học; hóa học","ex":"The chemist studies {chemical} reactions.","hint":"chemist","k":"wf"},{"w":"conclude","vi":"kết luận; kết luận được rút ra","note":"conclude → conclusion (n)","full":"kết luận; kết luận được rút ra","ex":"What {conclusion} can we draw?","hint":"conclude","k":"wf"},{"w":"examine","vi":"kiểm tra; kì thi; giám khảo","note":"examine → exam/examination (n), examiner (n)","full":"kiểm tra; kì thi; giám khảo","ex":"The {examiner} checked our answers.","hint":"examine","k":"wf"},{"w":"fascinate","vi":"làm mê thích; sự say mê; hấp dẫn","note":"fascinate → fascination (n), fascinating (adj)","full":"làm mê thích; sự say mê; hấp dẫn","ex":"The discovery was {fascinating}.","hint":"fascinate","k":"wf"},{"w":"history","vi":"lịch sử; có ý nghĩa lịch sử; sử gia","note":"history → historic (adj), historian (n)","full":"lịch sử; có ý nghĩa lịch sử; sử gia","ex":"The {historian} described a historic discovery.","hint":"history","k":"wf"},{"w":"identical","vi":"giống hệt; một cách giống hệt","note":"identical → identically (adv)","full":"giống hệt; một cách giống hệt","ex":"The two devices were made {identically}.","hint":"identical","k":"wf"},{"w":"long","vi":"dài; chiều dài","note":"long → length (n)","full":"dài; chiều dài","ex":"Measure the {length} of the wire.","hint":"long","k":"wf"},{"w":"measure","vi":"đo; số đo, sự đo lường","note":"measure → measurement (n)","full":"đo; số đo, sự đo lường","ex":"Record each {measurement} carefully.","hint":"measure","k":"wf"},{"w":"science","vi":"khoa học; nhà khoa học","note":"science → scientist (n)","full":"khoa học; nhà khoa học","ex":"The {scientist} tested the new material.","hint":"science","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"different from/to + sth","vi":"khác với; from dùng rộng rãi, to thường gặp trong Anh Anh","ex":"This design is different {from} the old one.","k":"pat"},{"w":"full of + sth","vi":"đầy","ex":"The box is full {of} cables.","k":"pat"},{"w":"begin sth with sth","vi":"bắt đầu thứ gì bằng","ex":"Begin the report {with} a short introduction.","k":"pat"},{"w":"connect sth to/with sth","vi":"kết nối","ex":"Connect the screen {to} the computer.","k":"pat"},{"w":"disconnect sth from sth","vi":"ngắt kết nối","ex":"Disconnect the device {from} the power supply.","k":"pat"},{"w":"fill sth with sth","vi":"làm đầy bằng","ex":"Fill the container {with} water.","k":"pat"},{"w":"result in + sth","vi":"dẫn tới kết quả","ex":"The fault resulted {in} a power cut.","k":"pat"},{"w":"a difference between + things","vi":"sự khác biệt giữa","ex":"What is the difference {between} these models?","k":"pat"},{"w":"an idea about + sth","vi":"ý tưởng, hiểu biết về","ex":"Do you have any ideas {about} the design?","k":"pat"},{"w":"a number of + N số nhiều","vi":"một số","ex":"A number {of} students joined the experiment.","k":"pat"},{"w":"a reason for + N/V-ing","vi":"lí do cho","ex":"What is the reason {for} the delay?","k":"pat"},{"w":"a type of + sth","vi":"một loại","ex":"This is a new type {of} battery.","k":"pat"}]}]},{"g":1,"u":21,"title":"Sending and Receiving","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"accent","pos":"n","vi":"giọng nói, giọng địa phương","de":"a way of pronouncing a language","ex":"She speaks English with a Scottish {accent}.","k":"topic"},{"w":"announcement","pos":"n","vi":"thông báo","de":"a public statement","ex":"Listen to the {announcement} carefully.","k":"topic"},{"w":"broadcast","pos":"v, n","vi":"phát sóng; chương trình phát sóng","de":"transmit a programme; a transmitted programme","ex":"The match will be {broadcast} live.","k":"topic"},{"w":"channel","pos":"n","vi":"kênh","de":"a television or radio station","ex":"Which {channel} is the film on?","k":"topic"},{"w":"clear","pos":"adj","vi":"rõ ràng","de":"easy to understand or hear","ex":"The instructions were {clear}.","k":"topic"},{"w":"click","pos":"v","vi":"nhấp chuột","de":"press a computer mouse button","ex":"{Click} the link to open the page.","k":"topic"},{"w":"contact","pos":"v, n","vi":"liên hệ; sự liên lạc","de":"communicate with; communication","ex":"Please {contact} us by email.","k":"topic"},{"w":"file","pos":"n","vi":"tệp tin","de":"a stored set of computer information","ex":"Save the {file} before closing it.","k":"topic"},{"w":"formal","pos":"adj","vi":"trang trọng","de":"suitable for official situations","ex":"Use {formal} language in the letter.","k":"topic"},{"w":"image","pos":"n","vi":"hình ảnh","de":"a picture or visual representation","ex":"The {image} is too small to read.","k":"topic"},{"w":"informal","pos":"adj","vi":"thân mật, không trang trọng","de":"relaxed and not official","ex":"The message was short and {informal}.","k":"topic"},{"w":"Internet","pos":"n","vi":"mạng Internet","de":"the worldwide computer network","ex":"We found the information on the {Internet}.","k":"topic"},{"w":"interrupt","pos":"v","vi":"ngắt lời, làm gián đoạn","de":"stop someone speaking or working briefly","ex":"Please do not {interrupt} the speaker.","k":"topic"},{"w":"link","pos":"v, n","vi":"liên kết; đường dẫn","de":"connect; a connection or clickable address","ex":"The email contains a useful {link}.","k":"topic"},{"w":"media","pos":"n","vi":"phương tiện truyền thông","de":"means of public communication","ex":"The story attracted {media} attention.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"mobile phone","pos":"n phr","vi":"điện thoại di động","de":"a portable telephone","ex":"Turn off your {mobile phone}.","k":"topic"},{"w":"online","pos":"adj, adv","vi":"trực tuyến","de":"connected to or using the Internet","ex":"The lesson is available {online}.","k":"topic"},{"w":"pause","pos":"v, n","vi":"tạm dừng; khoảng dừng","de":"stop briefly; a short stop","ex":"{Pause} the video and take notes.","k":"topic"},{"w":"persuade","pos":"v","vi":"thuyết phục","de":"make someone agree through reasons","ex":"She {persuaded} me to join the club.","k":"topic"},{"w":"pronounce","pos":"v","vi":"phát âm","de":"say the sounds of a word","ex":"How do you {pronounce} this word?","k":"topic"},{"w":"publish","pos":"v","vi":"xuất bản","de":"make writing available to the public","ex":"They {publish} a school magazine.","k":"topic"},{"w":"report","pos":"v, n","vi":"đưa tin; bản tin, báo cáo","de":"give information; an account","ex":"The journalist {reported} the results.","k":"topic"},{"w":"request","pos":"v, n","vi":"yêu cầu; lời yêu cầu","de":"ask politely; a polite demand","ex":"They {requested} more information.","k":"topic"},{"w":"ring","pos":"v","vi":"gọi điện; reo","de":"call by telephone; make a ringing sound","ex":"I will {ring} you after class.","k":"topic"},{"w":"signal","pos":"n","vi":"tín hiệu","de":"a transmitted message or sign","ex":"The phone {signal} is weak here.","k":"topic"},{"w":"swear","pos":"v","vi":"chửi thề; thề","de":"use offensive words; state a firm promise","ex":"He swore that he was telling the truth.","k":"topic"},{"w":"type","pos":"v","vi":"đánh máy","de":"write using a keyboard","ex":"Please {type} your name here.","k":"topic"},{"w":"viewer","pos":"n","vi":"người xem","de":"a person watching television or video","ex":"The programme attracted many {viewers}.","k":"topic"},{"w":"website","pos":"n","vi":"trang web","de":"a set of connected web pages","ex":"Visit our {website} for details.","k":"topic"},{"w":"whisper","pos":"v, n","vi":"thì thầm; lời thì thầm","de":"speak very quietly","ex":"She {whispered} the answer to me.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"call back","vi":"gọi điện lại","ex":"I will call you {back} later.","k":"pv"},{"w":"come out","vi":"được xuất bản, phát hành","ex":"The next issue comes {out} on Friday.","k":"pv"},{"w":"cut off","vi":"ngắt kết nối điện thoại, điện","ex":"We were cut {off} during the call.","k":"pv"},{"w":"fill in","vi":"điền thông tin vào mẫu","ex":"Please fill {in} this form.","k":"pv"},{"w":"hang up","vi":"kết thúc cuộc gọi, gác máy","ex":"Do not hang {up} yet.","k":"pv"},{"w":"log off","vi":"đăng xuất, ngắt phiên kết nối","ex":"Remember to log {off} after using the computer.","k":"pv"},{"w":"log on to","vi":"đăng nhập vào","ex":"Log on {to} the website to see your results.","k":"pv"},{"w":"print out","vi":"in ra giấy","ex":"Please print {out} the report.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by email/phone/letter","vi":"qua email, điện thoại, thư","ex":"We contacted the school {by} email.","k":"prep"},{"w":"on the Internet","vi":"trên Internet","ex":"The guide is available {on} the Internet.","k":"prep"},{"w":"on the news","vi":"trong bản tin","ex":"I heard the story {on} the news.","k":"prep"},{"w":"on the phone","vi":"đang nói chuyện qua điện thoại","ex":"She is {on} the phone at the moment.","k":"prep"},{"w":"on the radio","vi":"trên đài phát thanh","ex":"The interview was {on} the radio.","k":"prep"},{"w":"on TV","vi":"trên truyền hình","ex":"We watched the final {on} TV.","k":"prep"},{"w":"certain","vi":"chắc chắn; một cách chắc chắn; sự chắc chắn","note":"certain → certainly (adv), certainty (n)","full":"chắc chắn; một cách chắc chắn; sự chắc chắn","ex":"We cannot predict the result with {certainty}.","hint":"certain","k":"wf"},{"w":"communicate","vi":"giao tiếp; sự giao tiếp","note":"communicate → communication (n)","full":"giao tiếp; sự giao tiếp","ex":"Good {communication} prevents mistakes.","hint":"communicate","k":"wf"},{"w":"connect","vi":"kết nối; sự kết nối; ngắt kết nối","note":"connect → connection (n), disconnect (v)","full":"kết nối; sự kết nối; ngắt kết nối","ex":"The {connection} is slow today.","hint":"connect","k":"wf"},{"w":"deliver","vi":"giao, chuyển; việc giao hàng","note":"deliver → delivery (n)","full":"giao, chuyển; việc giao hàng","ex":"The {delivery} arrived this morning.","hint":"deliver","k":"wf"},{"w":"express","vi":"diễn đạt; sự diễn đạt; giàu biểu cảm","note":"express → expression (n), expressive (adj)","full":"diễn đạt; sự diễn đạt; giàu biểu cảm","ex":"Her face was very {expressive}.","hint":"express","k":"wf"},{"w":"inform","vi":"thông báo; giàu thông tin; thông tin","note":"inform → informative (adj), information (n)","full":"thông báo; giàu thông tin; thông tin","ex":"The article was highly {informative}.","hint":"inform","k":"wf"},{"w":"predict","vi":"dự đoán; lời dự đoán; dễ/khó đoán","note":"predict → prediction (n), predictable/unpredictable (adj)","full":"dự đoán; lời dự đoán; dễ/khó đoán","ex":"The ending was {unpredictable}.","hint":"predict","k":"wf"},{"w":"secret","vi":"bí mật; một cách bí mật; sự giữ bí mật","note":"secret → secretly (adv), secrecy (n)","full":"bí mật; một cách bí mật; sự giữ bí mật","ex":"They planned the event {secretly}.","hint":"secret","k":"wf"},{"w":"speak","vi":"nói; người nói; bài phát biểu","note":"speak → spoke (V2), spoken (V3), speaker (n), speech (n)","full":"nói; người nói; bài phát biểu","ex":"The {speaker} gave a short speech.","hint":"speak","k":"wf"},{"w":"translate","vi":"dịch; bản dịch; người dịch","note":"translate → translation (n), translator (n)","full":"dịch; bản dịch; người dịch","ex":"The translator checked the {translation}.","hint":"translate","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"comment on + sth","vi":"bình luận về","ex":"Would you like to comment {on} the plan?","k":"pat"},{"w":"communicate with + sb","vi":"giao tiếp với","ex":"We communicate {with} students online.","k":"pat"},{"w":"glance at + sth","vi":"liếc nhìn","ex":"She glanced {at} the message.","k":"pat"},{"w":"receive sth from sb","vi":"nhận thứ gì từ ai","ex":"I received a letter {from} my cousin.","k":"pat"},{"w":"reply to + sb/sth","vi":"trả lời","ex":"Please reply {to} my email.","k":"pat"},{"w":"send sth to sb","vi":"gửi thứ gì cho ai","ex":"I sent the document {to} Hoa.","k":"pat"},{"w":"talk to sb about sth","vi":"nói chuyện với ai về","ex":"Talk {to} your teacher about the problem.","k":"pat"},{"w":"tell sb about sth","vi":"kể, nói cho ai về","ex":"He told us {about} the trip.","k":"pat"},{"w":"translate from sth into sth","vi":"dịch từ ngôn ngữ này sang ngôn ngữ kia","ex":"She translated the poem {from} English into Vietnamese.","k":"pat"},{"w":"write to sb about sth","vi":"viết cho ai về","ex":"I wrote {to} him about the meeting.","k":"pat"},{"w":"information about + sth","vi":"thông tin về","ex":"Where can I find information {about} the course?","k":"pat"},{"w":"a letter from sb about sth","vi":"lá thư từ ai về điều gì","ex":"I received a letter {from} Lan about her new school.","k":"pat"}]}]},{"g":1,"u":24,"title":"People and Daily Life","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"admit","pos":"v","vi":"thừa nhận","de":"accept that something is true","ex":"He {admitted} making a mistake.","k":"topic"},{"w":"arrest","pos":"v","vi":"bắt giữ","de":"take someone into police custody","ex":"The police {arrested} the suspect.","k":"topic"},{"w":"charity","pos":"n","vi":"tổ chức từ thiện","de":"an organisation helping people in need","ex":"The school raised money for {charity}.","k":"topic"},{"w":"commit","pos":"v","vi":"phạm, thực hiện","de":"do something wrong or illegal","ex":"He was accused of {committing} a crime.","k":"topic"},{"w":"community","pos":"n","vi":"cộng đồng","de":"people living in an area or sharing something","ex":"The local {community} supported the project.","k":"topic"},{"w":"court","pos":"n","vi":"tòa án","de":"a place where legal cases are heard","ex":"The case will go to {court}.","k":"topic"},{"w":"criminal","pos":"n, adj","vi":"tội phạm; thuộc tội phạm","de":"a lawbreaker; related to crime","ex":"The {criminal} was sent to prison.","k":"topic"},{"w":"culture","pos":"n","vi":"văn hóa","de":"the customs and beliefs of a group","ex":"We learnt about local {culture}.","k":"topic"},{"w":"familiar","pos":"adj","vi":"quen thuộc","de":"known or recognised","ex":"Her face looks {familiar}.","k":"topic"},{"w":"government","pos":"n","vi":"chính phủ","de":"the people who manage a country","ex":"The {government} announced a new policy.","k":"topic"},{"w":"habit","pos":"n","vi":"thói quen","de":"something you do regularly","ex":"Reading before bed is a good {habit}.","k":"topic"},{"w":"identity card","pos":"n phr","vi":"thẻ căn cước","de":"an official document showing who you are","ex":"Please show your {identity card}.","k":"topic"},{"w":"illegal","pos":"adj","vi":"bất hợp pháp","de":"not allowed by law","ex":"It is {illegal} to steal.","k":"topic"},{"w":"politics","pos":"n","vi":"chính trị","de":"activities related to governing a country","ex":"She is interested in {politics}.","k":"topic"},{"w":"population","pos":"n","vi":"dân số","de":"the number of people in a place","ex":"The {population} of the town is growing.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"prison","pos":"n","vi":"nhà tù","de":"a place where offenders are held","ex":"The man spent two years in {prison}.","k":"topic"},{"w":"protest","pos":"v, n","vi":"phản đối; cuộc phản đối","de":"show strong disagreement publicly","ex":"Residents {protested} against the decision.","k":"topic"},{"w":"resident","pos":"n","vi":"cư dân","de":"a person who lives in a place","ex":"Local {residents} use the park daily.","k":"topic"},{"w":"responsible","pos":"adj","vi":"có trách nhiệm, chịu trách nhiệm","de":"having a duty or being the cause","ex":"Who is {responsible} for the damage?","k":"topic"},{"w":"rob","pos":"v","vi":"cướp","de":"steal from a person or place","ex":"Two men {robbed} the bank.","k":"topic"},{"w":"routine","pos":"n, adj","vi":"lịch sinh hoạt; thường lệ","de":"the usual order of activities; usual","ex":"Exercise is part of my daily {routine}.","k":"topic"},{"w":"schedule","pos":"n","vi":"lịch trình","de":"a plan showing times of activities","ex":"My {schedule} is full this week.","k":"topic"},{"w":"situation","pos":"n","vi":"tình huống","de":"the conditions at a particular time","ex":"We need to understand the {situation}.","k":"topic"},{"w":"social","pos":"adj","vi":"thuộc xã hội, giao tiếp","de":"relating to society or meeting people","ex":"The club organises {social} events.","k":"topic"},{"w":"society","pos":"n","vi":"xã hội","de":"people living together in an organised group","ex":"Education benefits {society}.","k":"topic"},{"w":"steal","pos":"v","vi":"trộm, lấy cắp","de":"take something without permission","ex":"Someone stole my bicycle.","k":"topic"},{"w":"tradition","pos":"n","vi":"truyền thống","de":"a custom passed through generations","ex":"We want to preserve this {tradition}.","k":"topic"},{"w":"typical","pos":"adj","vi":"điển hình","de":"having the usual qualities of a type","ex":"This is a {typical} village house.","k":"topic"},{"w":"vote","pos":"v, n","vi":"bỏ phiếu; lá phiếu","de":"choose formally in an election","ex":"Each member has one {vote}.","k":"topic"},{"w":"youth club","pos":"n phr","vi":"câu lạc bộ thanh thiếu niên","de":"a club providing activities for young people","ex":"The {youth club} meets on Saturdays.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"break in/into","vi":"đột nhập bất hợp pháp","ex":"Someone broke {into} the shop last night.","k":"pv"},{"w":"catch up with","vi":"đuổi kịp, theo kịp","ex":"I need to catch up {with} the class.","k":"pv"},{"w":"get away with","vi":"làm sai nhưng thoát bị phạt","ex":"He will not get away {with} cheating.","k":"pv"},{"w":"get up","vi":"ra khỏi giường, thức dậy","ex":"I get {up} at six every day.","k":"pv"},{"w":"move in","vi":"chuyển vào sống ở nơi mới","ex":"Our new neighbours moved {in} yesterday.","k":"pv"},{"w":"put away","vi":"cất về đúng chỗ","ex":"Put your books {away}.","k":"pv"},{"w":"wake up","vi":"tỉnh giấc, đánh thức","ex":"The noise woke me {up}.","k":"pv"},{"w":"wash up","vi":"rửa bát đĩa","ex":"We wash {up} after dinner.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"against the law","vi":"trái pháp luật","ex":"Driving without a licence is {against} the law.","k":"prep"},{"w":"at the age of","vi":"ở độ tuổi","ex":"She moved abroad {at} the age of ten.","k":"prep"},{"w":"in public","vi":"ở nơi công cộng, trước mọi người","ex":"He is nervous about speaking {in} public.","k":"prep"},{"w":"in response to","vi":"để đáp lại, phản hồi","ex":"She wrote {in} response to our request.","k":"prep"},{"w":"in touch with","vi":"giữ liên lạc với","ex":"I am still {in} touch with my classmates.","k":"prep"},{"w":"in your teens/twenties","vi":"ở tuổi thiếu niên, ở độ tuổi hai mươi","ex":"She started volunteering {in} her teens.","k":"prep"},{"w":"agree","vi":"đồng ý; sự thỏa thuận; không đồng ý","note":"agree → agreement (n), disagree (v)","full":"đồng ý; sự thỏa thuận; không đồng ý","ex":"We reached an {agreement} yesterday.","hint":"agree","k":"wf"},{"w":"belief","vi":"niềm tin; tin; đáng tin/khó tin","note":"belief → believe (v), believable/unbelievable (adj)","full":"niềm tin; tin; đáng tin/khó tin","ex":"His explanation was {unbelievable}.","hint":"belief","k":"wf"},{"w":"courage","vi":"lòng dũng cảm; can đảm","note":"courage → courageous (adj)","full":"lòng dũng cảm; can đảm","ex":"The {courageous} resident rescued a child.","hint":"courage","k":"wf"},{"w":"elect","vi":"bầu chọn; cuộc bầu cử","note":"elect → election (n)","full":"bầu chọn; cuộc bầu cử","ex":"The club holds an {election} every year.","hint":"elect","k":"wf"},{"w":"equal","vi":"bình đẳng; sự bình đẳng; không bình đẳng","note":"equal → equality (n), unequal (adj)","full":"bình đẳng; sự bình đẳng; không bình đẳng","ex":"The campaign promotes {equality}.","hint":"equal","k":"wf"},{"w":"life","vi":"cuộc sống; sống; còn sống","note":"life → live (v), alive (adj)","full":"cuộc sống; sống; còn sống","ex":"The rescued bird was still {alive}.","hint":"life","k":"wf"},{"w":"nation","vi":"quốc gia; quốc tịch; trong nước/quốc tế","note":"nation → nationality (n), national/international (adj)","full":"quốc gia; quốc tịch; trong nước/quốc tế","ex":"Students of different nationalities joined.","hint":"nation","k":"wf"},{"w":"peace","vi":"hòa bình; yên bình; một cách hòa bình","note":"peace → peaceful (adj), peacefully (adv)","full":"hòa bình; yên bình; một cách hòa bình","ex":"The residents live {peacefully} together.","hint":"peace","k":"wf"},{"w":"prison","vi":"nhà tù; tù nhân","note":"prison → prisoner (n)","full":"nhà tù; tù nhân","ex":"The {prisoner} wrote a letter.","hint":"prison","k":"wf"},{"w":"shoot","vi":"bắn; vụ bắn, việc bắn","note":"shoot → shot (V2/V3), shooting (n)","full":"bắn; vụ bắn, việc bắn","ex":"The {shooting} was reported to the police.","hint":"shoot","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"angry with sb about sth","vi":"giận ai về điều gì","ex":"She was angry {with} me about the noise.","k":"pat"},{"w":"guilty of + N/V-ing","vi":"có tội, có lỗi về","ex":"He was found guilty {of} theft.","k":"pat"},{"w":"accuse sb of sth/V-ing","vi":"buộc tội ai","ex":"They accused him {of} stealing.","k":"pat"},{"w":"blame sb for sth/V-ing","vi":"đổ lỗi cho ai vì","ex":"Do not blame her {for} the delay.","k":"pat"},{"w":"blame sth on sb/sth","vi":"quy điều gì là lỗi do","ex":"He blamed the mistake {on} poor instructions.","k":"pat"},{"w":"criticise sb for sth/V-ing","vi":"phê bình ai vì","ex":"They criticised him {for} arriving late.","k":"pat"},{"w":"forget about + sth","vi":"quên điều gì","ex":"Do not forget {about} the meeting.","k":"pat"},{"w":"forgive sb for sth/V-ing","vi":"tha thứ cho ai vì","ex":"She forgave me {for} losing the book.","k":"pat"},{"w":"invite sb to sth","vi":"mời ai đến","ex":"We invited our neighbours {to} dinner.","k":"pat"},{"w":"punish sb for sth/V-ing","vi":"phạt ai vì","ex":"The school punished him {for} cheating.","k":"pat"},{"w":"share sth with sb","vi":"chia sẻ thứ gì với ai","ex":"I share a room {with} my brother.","k":"pat"},{"w":"smile at + sb","vi":"mỉm cười với","ex":"The child smiled {at} the visitor.","k":"pat"}]}]},{"g":1,"u":27,"title":"Working and Earning","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"ambition","pos":"n","vi":"hoài bão","de":"a strong wish to achieve something","ex":"Her {ambition} is to become an engineer.","k":"topic"},{"w":"application","pos":"n","vi":"đơn ứng tuyển","de":"a formal request for a job or place","ex":"Please send your {application} by Friday.","k":"topic"},{"w":"bank account","pos":"n phr","vi":"tài khoản ngân hàng","de":"an arrangement for keeping money in a bank","ex":"My salary goes into my {bank account}.","k":"topic"},{"w":"boss","pos":"n","vi":"sếp","de":"the person in charge at work","ex":"I discussed the problem with my {boss}.","k":"topic"},{"w":"career","pos":"n","vi":"sự nghiệp","de":"your working life or professional path","ex":"She wants a {career} in science.","k":"topic"},{"w":"colleague","pos":"n","vi":"đồng nghiệp","de":"a person you work with","ex":"My {colleagues} helped me settle in.","k":"topic"},{"w":"company","pos":"n","vi":"công ty","de":"a business organisation","ex":"He works for a software {company}.","k":"topic"},{"w":"contract","pos":"n","vi":"hợp đồng","de":"a formal agreement","ex":"Read the {contract} before signing.","k":"topic"},{"w":"department","pos":"n","vi":"phòng ban","de":"one part of an organisation","ex":"She works in the sales {department}.","k":"topic"},{"w":"deserve","pos":"v","vi":"xứng đáng","de":"be worthy of something","ex":"You {deserve} a rest after that work.","k":"topic"},{"w":"earn","pos":"v","vi":"kiếm được tiền","de":"receive money for work","ex":"He {earns} enough to support his family.","k":"topic"},{"w":"fame","pos":"n","vi":"danh tiếng","de":"the state of being widely known","ex":"{Fame} did not change her attitude.","k":"topic"},{"w":"goal","pos":"n","vi":"mục tiêu","de":"something you want to achieve","ex":"Our {goal} is to improve the service.","k":"topic"},{"w":"impress","pos":"v","vi":"gây ấn tượng","de":"make someone admire you","ex":"Her presentation {impressed} the manager.","k":"topic"},{"w":"income","pos":"n","vi":"thu nhập","de":"money received regularly","ex":"Rent takes up half his {income}.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"industry","pos":"n","vi":"ngành công nghiệp","de":"a field of economic activity","ex":"She works in the tourism {industry}.","k":"topic"},{"w":"interview","pos":"v, n","vi":"phỏng vấn; buổi phỏng vấn","de":"question someone for a job; the meeting","ex":"My {interview} is on Monday.","k":"topic"},{"w":"leader","pos":"n","vi":"người lãnh đạo","de":"a person who guides a group","ex":"A good {leader} listens to others.","k":"topic"},{"w":"manager","pos":"n","vi":"người quản lí","de":"a person responsible for an operation","ex":"The {manager} approved the plan.","k":"topic"},{"w":"pension","pos":"n","vi":"lương hưu","de":"money paid regularly after retirement","ex":"He receives a {pension} every month.","k":"topic"},{"w":"poverty","pos":"n","vi":"sự nghèo đói","de":"the state of being very poor","ex":"The programme aims to reduce {poverty}.","k":"topic"},{"w":"pressure","pos":"n","vi":"áp lực","de":"demands causing difficulty or stress","ex":"Staff are under {pressure} to finish.","k":"topic"},{"w":"previous","pos":"adj","vi":"trước đó","de":"happening before the present one","ex":"What was your {previous} job?","k":"topic"},{"w":"profession","pos":"n","vi":"nghề chuyên môn","de":"a job requiring training or expertise","ex":"Teaching is a demanding {profession}.","k":"topic"},{"w":"retire","pos":"v","vi":"nghỉ hưu","de":"stop working, usually because of age","ex":"She plans to {retire} next year.","k":"topic"},{"w":"salary","pos":"n","vi":"tiền lương","de":"regular pay for a job","ex":"The position offers a reasonable {salary}.","k":"topic"},{"w":"staff","pos":"n","vi":"đội ngũ nhân viên","de":"the people working for an organisation","ex":"The company trained its {staff}.","k":"topic"},{"w":"strike","pos":"n","vi":"cuộc đình công","de":"a refusal to work as a protest","ex":"The {strike} lasted three days.","k":"topic"},{"w":"tax","pos":"v, n","vi":"đánh thuế; thuế","de":"charge a public payment; the payment","ex":"We pay {tax} on our income.","k":"topic"},{"w":"wealthy","pos":"adj","vi":"giàu có","de":"having a lot of money","ex":"The {wealthy} businessman funded a school.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"call off","vi":"hủy bỏ","ex":"They called {off} the meeting.","k":"pv"},{"w":"give back","vi":"trả lại thứ đã lấy hoặc mượn","ex":"Please give my calculator {back}.","k":"pv"},{"w":"go on","vi":"xảy ra","ex":"What is going {on} in the office?","k":"pv"},{"w":"put off","vi":"hoãn lại","ex":"We put {off} the interview until Friday.","k":"pv"},{"w":"set up","vi":"thành lập doanh nghiệp, tổ chức","ex":"She set {up} a small company.","k":"pv"},{"w":"stay up","vi":"thức khuya","ex":"I stayed {up} to finish the report.","k":"pv"},{"w":"take away","vi":"mang đi, lấy đi","ex":"Please take these boxes {away}.","k":"pv"},{"w":"take over","vi":"tiếp quản, nắm quyền kiểm soát","ex":"A new manager will take {over} next month.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"at the moment","vi":"ngay lúc này","ex":"The manager is busy {at} the moment.","k":"prep"},{"w":"in charge of","vi":"phụ trách","ex":"Who is {in} charge of the project?","k":"prep"},{"w":"on business","vi":"vì công việc, đi công tác","ex":"He is in Da Nang {on} business.","k":"prep"},{"w":"on strike","vi":"đang đình công","ex":"The workers are {on} strike.","k":"prep"},{"w":"on time","vi":"đúng giờ đã định","ex":"Please arrive {on} time for the interview.","k":"prep"},{"w":"on/off duty","vi":"đang làm nhiệm vụ/ngoài giờ làm","ex":"The guard is off duty now.","k":"prep"},{"w":"assist","vi":"hỗ trợ; trợ lí; sự trợ giúp","note":"assist → assistant (n), assistance (n)","full":"hỗ trợ; trợ lí; sự trợ giúp","ex":"Ask the assistant for {assistance}.","hint":"assist","k":"wf"},{"w":"beg","vi":"xin; người ăn xin","note":"beg → beggar (n)","full":"xin; người ăn xin","ex":"The charity offered the {beggar} support.","hint":"beg","k":"wf"},{"w":"boss","vi":"sếp; thích sai khiến","note":"boss → bossy (adj)","full":"sếp; thích sai khiến","ex":"She is helpful rather than {bossy}.","hint":"boss","k":"wf"},{"w":"employ","vi":"thuê; việc làm/thất nghiệp; chủ/nhân viên; thất nghiệp","note":"employ → employment/unemployment (n), employer/employee (n), unemployed (adj)","full":"thuê; việc làm/thất nghiệp; chủ/nhân viên; thất nghiệp","ex":"The {employer} hired two new employees.","hint":"employ","k":"wf"},{"w":"fame","vi":"danh tiếng; nổi tiếng","note":"fame → famous (adj)","full":"danh tiếng; nổi tiếng","ex":"She became {famous} for her designs.","hint":"fame","k":"wf"},{"w":"occupy","vi":"chiếm, đảm nhiệm; nghề nghiệp","note":"occupy → occupation (n)","full":"chiếm, đảm nhiệm; nghề nghiệp","ex":"Please state your {occupation}.","hint":"occupy","k":"wf"},{"w":"office","vi":"văn phòng; viên chức, sĩ quan; chính thức/không chính thức","note":"office → officer (n), official/unofficial (adj)","full":"văn phòng; viên chức, sĩ quan; chính thức/không chính thức","ex":"We received an {official} reply.","hint":"office","k":"wf"},{"w":"retire","vi":"nghỉ hưu; đã nghỉ hưu; sự nghỉ hưu","note":"retire → retired (adj), retirement (n)","full":"nghỉ hưu; đã nghỉ hưu; sự nghỉ hưu","ex":"He enjoys his {retirement}.","hint":"retire","k":"wf"},{"w":"safe","vi":"an toàn; cứu; không an toàn; sự an toàn","note":"safe → save (v), unsafe (adj), safety (n)","full":"an toàn; cứu; không an toàn; sự an toàn","ex":"Worker {safety} is essential.","hint":"safe","k":"wf"},{"w":"succeed","vi":"thành công; sự thành công; thành công/không thành công","note":"succeed → success (n), successful/unsuccessful (adj)","full":"thành công; sự thành công; thành công/không thành công","ex":"The new business was {successful}.","hint":"succeed","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"careful with + sth","vi":"cẩn thận với","ex":"Be careful {with} these documents.","k":"pat"},{"w":"difficult for + sb","vi":"khó đối với","ex":"The task is difficult {for} beginners.","k":"pat"},{"w":"fed up with + N/V-ing","vi":"chán ngấy","ex":"I am fed {up} with waiting.","k":"pat"},{"w":"ready for + sth","vi":"sẵn sàng cho","ex":"Are you ready {for} the interview?","k":"pat"},{"w":"responsible for + sth","vi":"chịu trách nhiệm về","ex":"She is responsible {for} staff training.","k":"pat"},{"w":"apply for + sth","vi":"nộp đơn xin","ex":"He applied {for} a part-time job.","k":"pat"},{"w":"depend on + sb/sth","vi":"phụ thuộc vào","ex":"The result depends {on} your effort.","k":"pat"},{"w":"inform sb about sth","vi":"thông báo cho ai về","ex":"Please inform us {about} any changes.","k":"pat"},{"w":"refer to + sth","vi":"đề cập, tham khảo","ex":"Refer {to} the guide for details.","k":"pat"},{"w":"work as + job","vi":"làm nghề","ex":"She works {as} a designer.","k":"pat"},{"w":"work for + employer","vi":"làm việc cho","ex":"He works {for} a local company.","k":"pat"},{"w":"a kind of + sth","vi":"một loại","ex":"What kind {of} work do you enjoy?","k":"pat"}]}]},{"g":1,"u":30,"title":"Body and Lifestyle","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"affect","pos":"v","vi":"ảnh hưởng đến","de":"have an influence on something","ex":"Lack of sleep {affects} concentration.","k":"topic"},{"w":"balance","pos":"v, n","vi":"giữ cân bằng; sự cân bằng","de":"keep steady; a stable state","ex":"It is important to {balance} work and rest.","k":"topic"},{"w":"benefit","pos":"v, n","vi":"có lợi; lợi ích","de":"help; a useful effect","ex":"Regular exercise {benefits} your health.","k":"topic"},{"w":"breathe","pos":"v","vi":"thở","de":"take air into and out of your lungs","ex":"{Breathe} slowly and relax.","k":"topic"},{"w":"chew","pos":"v","vi":"nhai","de":"break food with your teeth","ex":"{Chew} your food carefully.","k":"topic"},{"w":"chop","pos":"v","vi":"băm, chặt","de":"cut into small pieces","ex":"{Chop} the onions finely.","k":"topic"},{"w":"contain","pos":"v","vi":"chứa","de":"have something inside","ex":"This drink {contains} a lot of sugar.","k":"topic"},{"w":"cough","pos":"v, n","vi":"ho; cơn ho","de":"force air from the throat","ex":"He has had a {cough} for a week.","k":"topic"},{"w":"cure","pos":"v, n","vi":"chữa khỏi; cách chữa","de":"make well; something that removes an illness","ex":"Scientists are searching for a {cure}.","k":"topic"},{"w":"exercise","pos":"v, n","vi":"tập thể dục; sự vận động","de":"do physical activity","ex":"I {exercise} three times a week.","k":"topic"},{"w":"flu","pos":"n","vi":"cúm","de":"an infectious illness causing fever and aches","ex":"She stayed at home with {flu}.","k":"topic"},{"w":"have an operation","pos":"v phr","vi":"được phẫu thuật","de":"receive surgical treatment","ex":"He had {an operation} on his knee.","k":"topic"},{"w":"healthy","pos":"adj","vi":"khỏe mạnh; tốt cho sức khỏe","de":"in good health or good for health","ex":"A varied diet helps you stay {healthy}.","k":"topic"},{"w":"ignore","pos":"v","vi":"phớt lờ","de":"pay no attention to something","ex":"Do not {ignore} the warning signs.","k":"topic"},{"w":"infection","pos":"n","vi":"sự nhiễm trùng","de":"an illness caused by harmful organisms","ex":"The doctor treated the {infection}.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"ingredient","pos":"n","vi":"nguyên liệu","de":"one item used to make a dish","ex":"Rice is the main {ingredient}.","k":"topic"},{"w":"injury","pos":"n","vi":"chấn thương","de":"physical harm to the body","ex":"The player suffered a leg {injury}.","k":"topic"},{"w":"limit","pos":"v, n","vi":"giới hạn; mức giới hạn","de":"restrict; the greatest allowed amount","ex":"We should {limit} the amount of salt.","k":"topic"},{"w":"meal","pos":"n","vi":"bữa ăn","de":"food eaten at a regular eating time","ex":"Breakfast is an important {meal}.","k":"topic"},{"w":"pill","pos":"n","vi":"viên thuốc","de":"a small solid piece of medicine","ex":"Take this {pill} as directed by your doctor.","k":"topic"},{"w":"recover","pos":"v","vi":"hồi phục","de":"become well again","ex":"She {recovered} quickly after the operation.","k":"topic"},{"w":"salty","pos":"adj","vi":"mặn","de":"having a strong taste of salt","ex":"The soup is too {salty}.","k":"topic"},{"w":"slice","pos":"v, n","vi":"thái lát; lát mỏng","de":"cut thinly; a thin flat piece","ex":"Would you like a {slice} of bread?","k":"topic"},{"w":"sour","pos":"adj","vi":"chua","de":"having a sharp acidic taste","ex":"The lemon tastes {sour}.","k":"topic"},{"w":"spicy","pos":"adj","vi":"cay, nhiều gia vị","de":"containing strong hot spices","ex":"This curry is very {spicy}.","k":"topic"},{"w":"stir","pos":"v","vi":"khuấy","de":"mix by moving a spoon around","ex":"{Stir} the soup gently.","k":"topic"},{"w":"suffer","pos":"v","vi":"chịu đựng, mắc bệnh","de":"experience pain or difficulty","ex":"He {suffers} from back pain.","k":"topic"},{"w":"taste","pos":"v, n","vi":"có vị, nếm; vị","de":"have a flavour; flavour","ex":"The sauce {tastes} sweet.","k":"topic"},{"w":"treatment","pos":"n","vi":"sự điều trị","de":"medical care for illness or injury","ex":"The injury requires {treatment}.","k":"topic"},{"w":"vitamin","pos":"n","vi":"vitamin","de":"a substance needed in small amounts for health","ex":"Fruit contains useful {vitamins}.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"cut down on","vi":"giảm lượng tiêu thụ hoặc tần suất","ex":"I am trying to cut down {on} sugar.","k":"pv"},{"w":"fall down","vi":"ngã xuống","ex":"He fell {down} while running.","k":"pv"},{"w":"get over","vi":"hồi phục sau bệnh hoặc khó khăn","ex":"It took a week to get {over} the flu.","k":"pv"},{"w":"go off","vi":"ôi, hỏng, không còn tươi","ex":"The milk has gone {off}.","k":"pv"},{"w":"lie down","vi":"nằm xuống","ex":"You should lie {down} and rest.","k":"pv"},{"w":"put on","vi":"tăng cân","ex":"He put {on} weight during the holidays.","k":"pv"},{"w":"sit down","vi":"ngồi xuống","ex":"Please sit {down} here.","k":"pv"},{"w":"stand up","vi":"đứng lên","ex":"Stand {up} slowly if you feel dizzy.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"at night","vi":"vào ban đêm","ex":"She often works {at} night.","k":"prep"},{"w":"at risk","vi":"có nguy cơ","ex":"The injured animal is {at} risk.","k":"prep"},{"w":"in addition to","vi":"ngoài ra, bên cạnh","ex":"Drink water {in} addition to eating well.","k":"prep"},{"w":"in comparison to/with","vi":"so với","ex":"This meal is light {in} comparison with lunch.","k":"prep"},{"w":"in shape","vi":"có thể trạng tốt","ex":"Swimming helps her stay {in} shape.","k":"prep"},{"w":"on a diet","vi":"đang ăn kiêng","ex":"He says he is {on} a diet.","k":"prep"},{"w":"bake","vi":"nướng; thợ làm bánh; tiệm bánh","note":"bake → baker (n), bakery (n)","full":"nướng; thợ làm bánh; tiệm bánh","ex":"The baker works at the local {bakery}.","hint":"bake","k":"wf"},{"w":"bend","vi":"uốn, gập; đã uốn, gập","note":"bend → bent (V2/V3)","full":"uốn, gập; đã uốn, gập","ex":"She {bent} her knees slowly.","hint":"bend","k":"wf"},{"w":"cook","vi":"nấu ăn, đầu bếp; bếp nấu; nghệ thuật nấu ăn","note":"cook → cooker (n), cookery (n)","full":"nấu ăn, đầu bếp; bếp nấu; nghệ thuật nấu ăn","ex":"We use an electric {cooker}.","hint":"cook","k":"wf"},{"w":"intend","vi":"dự định; ý định; có chủ ý","note":"intend → intention (n), intentional (adj)","full":"dự định; ý định; có chủ ý","ex":"The mistake was not {intentional}.","hint":"intend","k":"wf"},{"w":"jog","vi":"chạy bộ chậm; việc chạy bộ; người chạy bộ","note":"jog → jogging (n), jogger (n)","full":"chạy bộ chậm; việc chạy bộ; người chạy bộ","ex":"The {jogger} exercises every morning.","hint":"jog","k":"wf"},{"w":"medicine","vi":"thuốc, y học; thuộc y khoa","note":"medicine → medical (adj)","full":"thuốc, y học; thuộc y khoa","ex":"She needs {medical} attention.","hint":"medicine","k":"wf"},{"w":"pain","vi":"đau; gây đau/không đau","note":"pain → painful/painless (adj)","full":"đau; gây đau/không đau","ex":"Moving the injured arm was {painful}.","hint":"pain","k":"wf"},{"w":"reduce","vi":"giảm; sự giảm","note":"reduce → reduction (n)","full":"giảm; sự giảm","ex":"There was a {reduction} in sugar intake.","hint":"reduce","k":"wf"},{"w":"sense","vi":"giác quan, ý thức; hợp lí/nhạy cảm","note":"sense → sensible/sensitive (adj)","full":"giác quan, ý thức; hợp lí/nhạy cảm","ex":"It is sensible to protect {sensitive} skin.","hint":"sense","k":"wf"},{"w":"weigh","vi":"cân nặng, cân; trọng lượng","note":"weigh → weight (n)","full":"cân nặng, cân; trọng lượng","ex":"The nurse checked his {weight}.","hint":"weigh","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"addicted to + N/V-ing","vi":"nghiện","ex":"He is addicted {to} playing online games.","k":"pat"},{"w":"allergic to + sth","vi":"dị ứng với","ex":"She is allergic {to} peanuts.","k":"pat"},{"w":"covered in/with + sth","vi":"được phủ đầy","ex":"The cake was covered with chocolate.","k":"pat"},{"w":"pleased with + sb/sth","vi":"hài lòng về","ex":"The doctor was pleased {with} her progress.","k":"pat"},{"w":"combine sth with sth","vi":"kết hợp","ex":"Combine exercise {with} a balanced diet.","k":"pat"},{"w":"complain to sb about sth","vi":"phàn nàn với ai về","ex":"She complained {to} the manager about the meal.","k":"pat"},{"w":"die from/of + sth","vi":"chết vì","ex":"Many plants died {from} lack of water.","k":"pat"},{"w":"fight against + sth","vi":"chiến đấu, chống lại","ex":"The body fights {against} infection.","k":"pat"},{"w":"recover from + sth","vi":"hồi phục sau","ex":"He is recovering {from} an injury.","k":"pat"},{"w":"smell of + sth","vi":"có mùi","ex":"The kitchen smells {of} fresh bread.","k":"pat"},{"w":"a cure for + sth","vi":"cách chữa khỏi","ex":"There is no simple cure {for} every illness.","k":"pat"},{"w":"a recipe for + sth","vi":"công thức chế biến","ex":"Can you give me a recipe {for} vegetable soup?","k":"pat"}]}]},{"g":1,"u":33,"title":"Creating and Building","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"ancient","pos":"adj","vi":"cổ đại, rất cổ","de":"belonging to the distant past","ex":"We visited an {ancient} temple.","k":"topic"},{"w":"checked","pos":"adj","vi":"có họa tiết ô vuông","de":"having a pattern of squares","ex":"He wore a {checked} shirt.","k":"topic"},{"w":"cotton","pos":"n","vi":"bông, vải cotton","de":"a soft natural fibre used for cloth","ex":"This shirt is made of {cotton}.","k":"topic"},{"w":"create","pos":"v","vi":"tạo ra","de":"make something new","ex":"The students {created} a model bridge.","k":"topic"},{"w":"design","pos":"v, n","vi":"thiết kế; bản thiết kế","de":"plan how something looks or works","ex":"The {design} is simple and practical.","k":"topic"},{"w":"fix","pos":"v","vi":"sửa; cố định","de":"repair or fasten something","ex":"Can you {fix} this broken chair?","k":"topic"},{"w":"fold","pos":"v","vi":"gấp","de":"bend one part over another","ex":"{Fold} the paper in half.","k":"topic"},{"w":"gallery","pos":"n","vi":"phòng trưng bày","de":"a place where art is displayed","ex":"The {gallery} displays local paintings.","k":"topic"},{"w":"improvement","pos":"n","vi":"sự cải thiện","de":"a change that makes something better","ex":"The new design is a major {improvement}.","k":"topic"},{"w":"loose","pos":"adj","vi":"rộng, lỏng","de":"not tight or firmly attached","ex":"These trousers are too {loose}.","k":"topic"},{"w":"maintain","pos":"v","vi":"bảo trì, duy trì","de":"keep in good condition","ex":"The tools must be {maintained} regularly.","k":"topic"},{"w":"match","pos":"v","vi":"hợp, ăn khớp","de":"look suitable together","ex":"Your shoes {match} your jacket.","k":"topic"},{"w":"material","pos":"n","vi":"vật liệu, chất liệu","de":"a substance used to make something","ex":"We need a stronger {material}.","k":"topic"},{"w":"notice","pos":"v, n","vi":"nhận thấy; thông báo","de":"become aware; a written announcement","ex":"Did you {notice} the new pattern?","k":"topic"},{"w":"pattern","pos":"n","vi":"hoa văn, mẫu","de":"a repeated design","ex":"The cloth has a floral {pattern}.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"pile","pos":"n","vi":"chồng, đống","de":"things placed on top of one another","ex":"There is a {pile} of wood outside.","k":"topic"},{"w":"practical","pos":"adj","vi":"thiết thực","de":"useful and suitable for real use","ex":"The bag is attractive and {practical}.","k":"topic"},{"w":"rough","pos":"adj","vi":"thô ráp","de":"not smooth or even","ex":"The surface feels {rough}.","k":"topic"},{"w":"shape","pos":"n","vi":"hình dạng","de":"the outer form of something","ex":"What {shape} is the table?","k":"topic"},{"w":"silk","pos":"n","vi":"lụa","de":"a fine fabric made from silkworm fibres","ex":"The scarf is made of {silk}.","k":"topic"},{"w":"sleeve","pos":"n","vi":"tay áo","de":"the part of clothing covering an arm","ex":"One {sleeve} is longer than the other.","k":"topic"},{"w":"smooth","pos":"adj","vi":"nhẵn, mịn","de":"having an even surface","ex":"Sand the wood until it is {smooth}.","k":"topic"},{"w":"stretch","pos":"v","vi":"kéo giãn","de":"pull to make longer or wider","ex":"Do not {stretch} the fabric too much.","k":"topic"},{"w":"striped","pos":"adj","vi":"có sọc","de":"having a pattern of lines","ex":"She bought a {striped} T-shirt.","k":"topic"},{"w":"style","pos":"n","vi":"phong cách","de":"a particular way something looks","ex":"The room has a modern {style}.","k":"topic"},{"w":"suit","pos":"v, n","vi":"hợp; bộ com lê","de":"look good on someone; matching clothes","ex":"That colour really {suits} you.","k":"topic"},{"w":"suitable","pos":"adj","vi":"phù hợp","de":"right for a purpose","ex":"This material is {suitable} for outdoor use.","k":"topic"},{"w":"tear","pos":"v, n","vi":"xé; vết rách","de":"pull apart; a rip","ex":"Be careful not to {tear} the paper.","k":"topic"},{"w":"tight","pos":"adj","vi":"chật, bó sát","de":"fitting closely or firmly","ex":"These shoes are too {tight}.","k":"topic"},{"w":"tool","pos":"n","vi":"dụng cụ","de":"an object used to do a job","ex":"Keep your {tools} clean.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"cut off","vi":"cắt rời, cắt bỏ","ex":"Cut {off} the damaged part.","k":"pv"},{"w":"do up","vi":"cài, kéo khóa quần áo","ex":"Do {up} your coat before going out.","k":"pv"},{"w":"fill up","vi":"làm đầy hoàn toàn","ex":"Fill {up} the bottle with water.","k":"pv"},{"w":"have on","vi":"đang mặc","ex":"She has a blue jacket {on}.","k":"pv"},{"w":"leave out","vi":"bỏ sót, không bao gồm","ex":"Do not leave {out} any details.","k":"pv"},{"w":"put on","vi":"mặc vào","ex":"Put {on} your safety gloves.","k":"pv"},{"w":"take off","vi":"cởi ra","ex":"Take {off} your wet shoes.","k":"pv"},{"w":"try on","vi":"mặc thử","ex":"Can I try this jacket {on}?","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"at the back of","vi":"ở phía sau","ex":"The label is {at} the back of the shirt.","k":"prep"},{"w":"at the end of","vi":"ở cuối","ex":"There is a door {at} the end of the hall.","k":"prep"},{"w":"in fashion/style","vi":"đang hợp thời trang","ex":"Wide trousers are {in} fashion.","k":"prep"},{"w":"in front of","vi":"ở phía trước","ex":"A sculpture stands {in} front of the gallery.","k":"prep"},{"w":"in the corner of","vi":"ở góc bên trong","ex":"The lamp is {in} the corner of the room.","k":"prep"},{"w":"out of fashion/style","vi":"lỗi thời","ex":"That pattern is {out} of fashion now.","k":"prep"},{"w":"art","vi":"nghệ thuật; nghệ sĩ; có tính nghệ thuật","note":"art → artist (n), artistic (adj)","full":"nghệ thuật; nghệ sĩ; có tính nghệ thuật","ex":"The artist has an {artistic} family.","hint":"art","k":"wf"},{"w":"break","vi":"làm vỡ; dễ vỡ/khó vỡ","note":"break → broke (V2), broken (V3), breakable/unbreakable (adj)","full":"làm vỡ; dễ vỡ/khó vỡ","ex":"Pack {breakable} objects carefully.","hint":"break","k":"wf"},{"w":"compose","vi":"sáng tác; tác phẩm; nhà soạn nhạc","note":"compose → composition (n), composer (n)","full":"sáng tác; tác phẩm; nhà soạn nhạc","ex":"The composer performed a new {composition}.","hint":"compose","k":"wf"},{"w":"exhibit","vi":"trưng bày; cuộc triển lãm","note":"exhibit → exhibition (n)","full":"trưng bày; cuộc triển lãm","ex":"The {exhibition} opens on Monday.","hint":"exhibit","k":"wf"},{"w":"free","vi":"tự do; sự tự do","note":"free → freedom (n)","full":"tự do; sự tự do","ex":"Art gives students {freedom} to experiment.","hint":"free","k":"wf"},{"w":"hand","vi":"tay; một nắm; tay cầm/xử lí","note":"hand → handful (n), handle (n/v)","full":"tay; một nắm; tay cầm/xử lí","ex":"The door {handle} is loose.","hint":"hand","k":"wf"},{"w":"imagine","vi":"tưởng tượng; trí tưởng tượng; giàu sáng tạo","note":"imagine → imagination (n), imaginative (adj)","full":"tưởng tượng; trí tưởng tượng; giàu sáng tạo","ex":"The {imaginative} design won a prize.","hint":"imagine","k":"wf"},{"w":"intelligent","vi":"thông minh; trí thông minh","note":"intelligent → intelligence (n)","full":"thông minh; trí thông minh","ex":"The task requires creativity and {intelligence}.","hint":"intelligent","k":"wf"},{"w":"perfect","vi":"hoàn hảo; sự hoàn hảo; chưa hoàn hảo","note":"perfect → perfection (n), imperfect (adj)","full":"hoàn hảo; sự hoàn hảo; chưa hoàn hảo","ex":"The first model was {imperfect}.","hint":"perfect","k":"wf"},{"w":"prepare","vi":"chuẩn bị; sự chuẩn bị","note":"prepare → preparation (n)","full":"chuẩn bị; sự chuẩn bị","ex":"Careful {preparation} saved time.","hint":"prepare","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"amazed at/by + sth","vi":"kinh ngạc trước","ex":"We were amazed by the design.","k":"pat"},{"w":"disappointed with + sb/sth","vi":"thất vọng về","ex":"He was disappointed {with} the result.","k":"pat"},{"w":"familiar with + sth","vi":"quen thuộc, biết rõ","ex":"Are you familiar {with} this tool?","k":"pat"},{"w":"involved in + sth","vi":"tham gia, liên quan đến","ex":"She is involved {in} the building project.","k":"pat"},{"w":"similar to + sth","vi":"tương tự","ex":"This pattern is similar {to} that one.","k":"pat"},{"w":"change sth from sth into sth","vi":"biến đổi từ dạng này sang dạng kia","ex":"They changed the warehouse into a gallery.","k":"pat"},{"w":"describe sth as sth","vi":"miêu tả là","ex":"She described the design {as} practical.","k":"pat"},{"w":"explain sth to sb","vi":"giải thích điều gì cho ai","ex":"Explain the process {to} your partner.","k":"pat"},{"w":"remind sb of sb/sth","vi":"gợi cho ai nhớ đến","ex":"The painting reminds me {of} my hometown.","k":"pat"},{"w":"remove sth from sth","vi":"lấy, loại bỏ khỏi","ex":"Remove the cover {from} the box.","k":"pat"},{"w":"an influence on + sb/sth","vi":"ảnh hưởng đến","ex":"Her teacher had an influence {on} her art.","k":"pat"},{"w":"a picture of + sb/sth","vi":"bức ảnh, tranh về","ex":"There is a picture {of} a bridge on the wall.","k":"pat"}]}]},{"g":1,"u":36,"title":"Nature and the Universe","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"amazing","pos":"adj","vi":"đáng kinh ngạc","de":"causing great surprise or admiration","ex":"The view from the mountain was {amazing}.","k":"topic"},{"w":"climate","pos":"n","vi":"khí hậu","de":"the usual weather of a region","ex":"The island has a warm {climate}.","k":"topic"},{"w":"countryside","pos":"n","vi":"vùng nông thôn","de":"land outside towns and cities","ex":"We spent the weekend in the {countryside}.","k":"topic"},{"w":"environment","pos":"n","vi":"môi trường","de":"the natural world and surroundings","ex":"We must protect the {environment}.","k":"topic"},{"w":"extinct","pos":"adj","vi":"tuyệt chủng","de":"no longer existing as a species","ex":"Many ancient species are {extinct}.","k":"topic"},{"w":"forecast","pos":"v, n","vi":"dự báo; bản dự báo","de":"predict weather; a weather prediction","ex":"The {forecast} says it will rain.","k":"topic"},{"w":"freezing","pos":"adj","vi":"rất lạnh, lạnh cóng","de":"extremely cold","ex":"It was {freezing} outside.","k":"topic"},{"w":"global","pos":"adj","vi":"toàn cầu","de":"relating to the whole world","ex":"Climate change is a {global} issue.","k":"topic"},{"w":"heatwave","pos":"n","vi":"đợt nắng nóng","de":"a period of unusually hot weather","ex":"The {heatwave} lasted a week.","k":"topic"},{"w":"insect","pos":"n","vi":"côn trùng","de":"a small animal with six legs","ex":"A bee is an {insect}.","k":"topic"},{"w":"lightning","pos":"n","vi":"chớp, tia sét","de":"a bright flash during a storm","ex":"{Lightning} lit up the sky.","k":"topic"},{"w":"litter","pos":"v, n","vi":"xả rác; rác vứt bừa bãi","de":"leave rubbish; rubbish left in public","ex":"Do not drop {litter} in the park.","k":"topic"},{"w":"local","pos":"adj","vi":"địa phương","de":"relating to a nearby area","ex":"{Local} volunteers cleaned the beach.","k":"topic"},{"w":"locate","pos":"v","vi":"xác định vị trí","de":"find the position of something","ex":"The team {located} the missing hikers.","k":"topic"},{"w":"mammal","pos":"n","vi":"động vật có vú","de":"an animal whose young drink its milk","ex":"A whale is a {mammal}.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"mild","pos":"adj","vi":"ôn hòa, dịu","de":"not very cold or severe","ex":"The region has {mild} winters.","k":"topic"},{"w":"name","pos":"v, n","vi":"đặt tên; tên","de":"give a name; a word identifying something","ex":"They {named} the rescued dog Lucky.","k":"topic"},{"w":"origin","pos":"n","vi":"nguồn gốc","de":"the beginning or source of something","ex":"Scientists studied the {origin} of the rock.","k":"topic"},{"w":"planet","pos":"n","vi":"hành tinh","de":"a large body moving around a star","ex":"Earth is a {planet} in our solar system.","k":"topic"},{"w":"preserve","pos":"v","vi":"bảo tồn","de":"protect from damage or loss","ex":"We should {preserve} natural habitats.","k":"topic"},{"w":"recycle","pos":"v","vi":"tái chế","de":"process used material for reuse","ex":"This factory {recycles} paper.","k":"topic"},{"w":"reptile","pos":"n","vi":"bò sát","de":"a cold-blooded animal such as a snake","ex":"A crocodile is a {reptile}.","k":"topic"},{"w":"rescue","pos":"v, n","vi":"cứu; sự giải cứu","de":"save from danger; the act of saving","ex":"The team {rescued} the injured bird.","k":"topic"},{"w":"satellite","pos":"n","vi":"vệ tinh","de":"an object orbiting a planet","ex":"The {satellite} sends images of Earth.","k":"topic"},{"w":"shower","pos":"n","vi":"cơn mưa rào","de":"a short period of rain","ex":"There may be {showers} this afternoon.","k":"topic"},{"w":"solar system","pos":"n phr","vi":"hệ Mặt Trời","de":"the Sun and the objects orbiting it","ex":"Earth belongs to the {solar system}.","k":"topic"},{"w":"species","pos":"n","vi":"loài","de":"a group of similar living organisms","ex":"This forest contains many rare {species}.","k":"topic"},{"w":"thunder","pos":"n","vi":"sấm","de":"the loud sound following lightning","ex":"We heard {thunder} in the distance.","k":"topic"},{"w":"wild","pos":"adj","vi":"hoang dã","de":"living naturally without human control","ex":"Do not feed {wild} animals.","k":"topic"},{"w":"wildlife","pos":"n","vi":"động thực vật hoang dã","de":"animals and plants living naturally","ex":"The reserve protects local {wildlife}.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"blow up","vi":"phát nổ","ex":"The abandoned vehicle blew {up}.","k":"pv"},{"w":"build up","vi":"tăng dần, tích tụ","ex":"Pollution can build {up} in rivers.","k":"pv"},{"w":"clear up","vi":"dọn dẹp cho gọn","ex":"We cleared {up} the campsite.","k":"pv"},{"w":"go out","vi":"tắt, ngừng cháy","ex":"The fire went {out} during the night.","k":"pv"},{"w":"keep out","vi":"ngăn không cho vào","ex":"The fence keeps animals {out}.","k":"pv"},{"w":"put down","vi":"đặt xuống, ngừng cầm","ex":"Put the injured bird {down} gently.","k":"pv"},{"w":"put out","vi":"dập tắt","ex":"The firefighters put {out} the fire.","k":"pv"},{"w":"put up","vi":"treo, dựng lên","ex":"They put {up} a warning sign.","k":"pv"}]},{"type":"v","title":"Cụm giới từ (Prepositional phrases)","words":[{"w":"at most","vi":"nhiều nhất","ex":"takes an hour {at} most.","k":"prep"},{"w":"at the top/bottom of","vi":"ở đỉnh, đáy hoặc đầu, cuối","ex":"{at} the top of the mountain.","k":"prep"},{"w":"in the beginning","vi":"lúc ban đầu","ex":"","k":"prep"},{"w":"in the distance","vi":"ở đằng xa","ex":"","k":"prep"},{"w":"in total","vi":"tổng cộng","ex":"","k":"prep"},{"w":"on top of","vi":"ở trên cùng, chồng lên","ex":"","k":"prep"},{"w":"IV. Word formation","vi":"","ex":"","k":"prep"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"centre","vi":"trung tâm; ở trung tâm","note":"centre → central (adj)","full":"trung tâm; ở trung tâm","ex":"The lake is in the {central} area.","hint":"centre","k":"wf"},{"w":"circle","vi":"hình tròn; có dạng tròn","note":"circle → circular (adj)","full":"hình tròn; có dạng tròn","ex":"The garden has a {circular} pond.","hint":"circle","k":"wf"},{"w":"danger","vi":"nguy hiểm; gây nguy hiểm","note":"danger → dangerous (adj)","full":"nguy hiểm; gây nguy hiểm","ex":"The path is {dangerous} after rain.","hint":"danger","k":"wf"},{"w":"deep","vi":"","note":"deep → deeply (adv), depth (n) sâu; sâu sắc; độ sâu","full":"","ex":"We measured the {depth} of the lake.","hint":"deep","k":"wf"},{"w":"destroy","vi":"destructive (adj) phá hủy; sự phá hủy; có tính phá hoại","note":"destroy → destruction (n),","full":"destructive (adj) phá hủy; sự phá hủy; có tính phá hoại","ex":"The storm caused serious {destruction}.","hint":"destroy","k":"wf"},{"w":"fog","vi":"sương mù; có sương mù","note":"fog → foggy (adj)","full":"sương mù; có sương mù","ex":"It was {foggy} in the mountains.","hint":"fog","k":"wf"},{"w":"garden","vi":"vườn; người làm vườn; việc làm vườn","note":"garden → gardener (n), gardening (n)","full":"vườn; người làm vườn; việc làm vườn","ex":"The gardener enjoys {gardening}.","hint":"garden","k":"wf"},{"w":"invade","vi":"xâm lấn; sự xâm lấn; kẻ xâm lược","note":"invade → invasion (n), invader (n)","full":"xâm lấn; sự xâm lấn; kẻ xâm lược","ex":"The {invasion} damaged the region.","hint":"invade","k":"wf"},{"w":"nature","vi":"thiên nhiên; tự nhiên; một cách tự nhiên","note":"nature → natural (adj), naturally (adv)","full":"thiên nhiên; tự nhiên; một cách tự nhiên","ex":"The area is rich in {natural} beauty.","hint":"nature","k":"wf"},{"w":"pollute","vi":"gây ô nhiễm; ô nhiễm; bị ô nhiễm","note":"pollute → pollution (n), polluted (adj)","full":"gây ô nhiễm; ô nhiễm; bị ô nhiễm","ex":"{Pollution} has harmed the polluted river's wildlife.","hint":"pollute","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"afraid of + N/V-ing","vi":"sợ","ex":"She is afraid {of} snakes.","k":"pat"},{"w":"aware of + sth","vi":"nhận thức được","ex":"We are aware {of} the danger.","k":"pat"},{"w":"enthusiastic about + N/V-ing","vi":"hào hứng về","ex":"They are enthusiastic {about} recycling.","k":"pat"},{"w":"serious about + N/V-ing","vi":"nghiêm túc với","ex":"He is serious {about} protecting wildlife.","k":"pat"},{"w":"short of + sth","vi":"thiếu","ex":"The village is short {of} clean water.","k":"pat"},{"w":"escape from + sth","vi":"thoát khỏi","ex":"The animals escaped {from} the fire.","k":"pat"},{"w":"prevent sb from V-ing","vi":"ngăn ai làm gì","ex":"The fence prevents visitors {from} entering.","k":"pat"},{"w":"save sth/sb from sth","vi":"cứu khỏi","ex":"The team saved the village {from} flooding.","k":"pat"},{"w":"think about + sth","vi":"suy nghĩ về","ex":"Think {about} the effects on wildlife.","k":"pat"},{"w":"worry about + sth","vi":"lo lắng về","ex":"Residents worry {about} the river.","k":"pat"},{"w":"damage to + sth","vi":"thiệt hại đối với","ex":"The storm caused damage {to} the forest.","k":"pat"},{"w":"an increase in + sth","vi":"sự gia tăng về","ex":"There has been an increase {in} temperature.","k":"pat"}]}]},{"g":1,"u":39,"title":"Laughing and Crying","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"amusing","pos":"adj","vi":"vui, gây buồn cười","de":"funny and entertaining","ex":"She told us an {amusing} story.","k":"topic"},{"w":"annoy","pos":"v","vi":"làm khó chịu","de":"make someone slightly angry","ex":"The constant noise {annoys} me.","k":"topic"},{"w":"attitude","pos":"n","vi":"thái độ","de":"the way you think or feel about something","ex":"She has a positive {attitude} to learning.","k":"topic"},{"w":"bad-tempered","pos":"adj","vi":"hay cáu gắt","de":"easily becoming angry","ex":"He gets {bad-tempered} when he is tired.","k":"topic"},{"w":"behave","pos":"v","vi":"cư xử","de":"act in a particular way","ex":"The children {behaved} well at the concert.","k":"topic"},{"w":"bully","pos":"v, n","vi":"bắt nạt; kẻ bắt nạt","de":"hurt or frighten a weaker person","ex":"No one should {bully} other students.","k":"topic"},{"w":"calm","pos":"adj","vi":"bình tĩnh","de":"not angry or worried","ex":"Try to remain {calm}.","k":"topic"},{"w":"celebrate","pos":"v","vi":"ăn mừng, kỉ niệm","de":"mark a happy occasion","ex":"We {celebrated} her success.","k":"topic"},{"w":"character","pos":"n","vi":"tính cách; nhân vật","de":"a person's qualities; a person in a story","ex":"The main {character} is very shy.","k":"topic"},{"w":"depressed","pos":"adj","vi":"chán nản, buồn bã","de":"very unhappy or without hope","ex":"He felt {depressed} after the failure.","k":"topic"},{"w":"embarrassing","pos":"adj","vi":"gây ngượng ngùng","de":"making someone feel awkward","ex":"Forgetting her name was {embarrassing}.","k":"topic"},{"w":"emotion","pos":"n","vi":"cảm xúc","de":"a strong feeling","ex":"Her voice was full of {emotion}.","k":"topic"},{"w":"enthusiastic","pos":"adj","vi":"hào hứng, nhiệt tình","de":"showing strong interest or excitement","ex":"The students were {enthusiastic} about the trip.","k":"topic"},{"w":"feeling","pos":"n","vi":"cảm giác, tình cảm","de":"an emotion or physical sensation","ex":"I had a strange {feeling}.","k":"topic"},{"w":"glad","pos":"adj","vi":"vui, mừng","de":"pleased or happy","ex":"I am {glad} you came.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"hurt","pos":"v, adj","vi":"làm đau; bị tổn thương","de":"cause pain; injured or emotionally upset","ex":"Her words {hurt} his feelings.","k":"topic"},{"w":"miserable","pos":"adj","vi":"khổ sở, buồn rầu","de":"very unhappy","ex":"She felt {miserable} without her friends.","k":"topic"},{"w":"naughty","pos":"adj","vi":"nghịch, không ngoan","de":"behaving badly, especially a child","ex":"The {naughty} child hid the keys.","k":"topic"},{"w":"noisy","pos":"adj","vi":"ồn ào","de":"making a lot of noise","ex":"The room was too {noisy} to study.","k":"topic"},{"w":"polite","pos":"adj","vi":"lịch sự","de":"showing good manners","ex":"It is {polite} to say thank you.","k":"topic"},{"w":"react","pos":"v","vi":"phản ứng","de":"respond to an event or action","ex":"How did she {react} to the news?","k":"topic"},{"w":"regret","pos":"v, n","vi":"hối tiếc; sự hối tiếc","de":"feel sorry about something","ex":"I {regret} saying those words.","k":"topic"},{"w":"ridiculous","pos":"adj","vi":"lố bịch, vô lí","de":"extremely silly or unreasonable","ex":"That excuse is {ridiculous}.","k":"topic"},{"w":"romantic","pos":"adj","vi":"lãng mạn","de":"related to love or an idealised view","ex":"They enjoyed a {romantic} evening.","k":"topic"},{"w":"rude","pos":"adj","vi":"thô lỗ","de":"not polite","ex":"It is {rude} to interrupt people.","k":"topic"},{"w":"sense of humour","pos":"n phr","vi":"khiếu hài hước","de":"the ability to notice and enjoy funny things","ex":"She has a great {sense of humour}.","k":"topic"},{"w":"shy","pos":"adj","vi":"nhút nhát","de":"nervous when meeting or speaking to people","ex":"The {shy} boy spoke quietly.","k":"topic"},{"w":"stress","pos":"n","vi":"căng thẳng","de":"mental pressure or worry","ex":"Exams can cause {stress}.","k":"topic"},{"w":"tell a joke","pos":"v phr","vi":"kể chuyện cười","de":"say something intended to make people laugh","ex":"He told {a joke} to cheer us up.","k":"topic"},{"w":"upset","pos":"v, adj","vi":"làm buồn; buồn, lo lắng","de":"make unhappy; unhappy or worried","ex":"She was {upset} about the argument.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"calm down","vi":"bình tĩnh lại, làm dịu","ex":"Take a breath and calm {down}.","k":"pv"},{"w":"cheer up","vi":"vui lên, làm ai vui hơn","ex":"The good news cheered her {up}.","k":"pv"},{"w":"come on","vi":"nhanh lên; lời thúc giục, khích lệ","ex":"Come {on}! We are going to be late.","k":"pv"},{"w":"go on","vi":"tiếp tục xảy ra hoặc tiếp tục làm","ex":"Please go {on} with your story.","k":"pv"},{"w":"hang on","vi":"chờ một chút","ex":"Hang {on} while I find my keys.","k":"pv"},{"w":"run away from","vi":"bỏ chạy khỏi","ex":"The child ran away {from} the dog.","k":"pv"},{"w":"shut up","vi":"im đi; cách nói thô, dễ xúc phạm","ex":"He rudely told his friend to shut {up}.","k":"pv"},{"w":"speak up","vi":"nói to hơn để người khác nghe","ex":"Please speak {up}; I cannot hear you.","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"at first","vi":"lúc đầu","ex":"{At} first, she was nervous.","k":"prep"},{"w":"at least","vi":"ít nhất","ex":"{At} least we tried our best.","k":"prep"},{"w":"at times","vi":"đôi khi","ex":"Everyone feels worried {at} times.","k":"prep"},{"w":"in secret","vi":"một cách bí mật","ex":"They planned the party {in} secret.","k":"prep"},{"w":"in spite of","vi":"mặc dù; theo sau bằng N/V-ing","ex":"She smiled {in} spite of her disappointment.","k":"prep"},{"w":"in tears","vi":"đang khóc, rơi nước mắt","ex":"The child was {in} tears.","k":"prep"},{"w":"bore","vi":"làm chán; gây chán/cảm thấy chán","note":"bore → boring/bored (adj)","full":"làm chán; gây chán/cảm thấy chán","ex":"The bored students found the talk {boring}.","hint":"bore","k":"wf"},{"w":"comedy","vi":"hài kịch; diễn viên hài","note":"comedy → comedian (n)","full":"hài kịch; diễn viên hài","ex":"The {comedian} made everyone laugh.","hint":"comedy","k":"wf"},{"w":"emotion","vi":"cảm xúc; xúc động, giàu cảm xúc","note":"emotion → emotional (adj)","full":"cảm xúc; xúc động, giàu cảm xúc","ex":"It was an {emotional} reunion.","hint":"emotion","k":"wf"},{"w":"energy","vi":"năng lượng; đầy năng lượng","note":"energy → energetic (adj)","full":"năng lượng; đầy năng lượng","ex":"The {energetic} children played outside.","hint":"energy","k":"wf"},{"w":"excite","vi":"làm hào hứng; sự hào hứng; gây hào hứng/cảm thấy hào hứng","note":"excite → excitement (n), exciting/excited (adj)","full":"làm hào hứng; sự hào hứng; gây hào hứng/cảm thấy hào hứng","ex":"The excited crowd enjoyed the {exciting} match.","hint":"excite","k":"wf"},{"w":"feel","vi":"cảm thấy; cảm giác, tình cảm","note":"feel → felt (V2/V3), feeling/feelings (n)","full":"cảm thấy; cảm giác, tình cảm","ex":"She felt a sudden {feeling} of relief.","hint":"feel","k":"wf"},{"w":"happy","vi":"vui; buồn; hạnh phúc/sự buồn bã","note":"happy → unhappy (adj), happiness/unhappiness (n)","full":"vui; buồn; hạnh phúc/sự buồn bã","ex":"Her smile showed her {happiness}.","hint":"happy","k":"wf"},{"w":"hate","vi":"ghét; lòng căm ghét","note":"hate → hatred (n)","full":"ghét; lòng căm ghét","ex":"The story warns against {hatred}.","hint":"hate","k":"wf"},{"w":"noise","vi":"tiếng ồn; ồn ào; một cách ồn ào","note":"noise → noisy (adj), noisily (adv)","full":"tiếng ồn; ồn ào; một cách ồn ào","ex":"The children laughed {noisily}.","hint":"noise","k":"wf"},{"w":"sympathy","vi":"sự cảm thông; cảm thông; biết cảm thông","note":"sympathy → sympathise (v), sympathetic (adj)","full":"sự cảm thông; cảm thông; biết cảm thông","ex":"The teacher was {sympathetic} to our problem.","hint":"sympathy","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"ashamed of + N/V-ing","vi":"xấu hổ về điều sai đã làm","ex":"He was ashamed {of} lying.","k":"pat"},{"w":"embarrassed about + sth","vi":"ngượng ngùng về","ex":"She was embarrassed {about} her mistake.","k":"pat"},{"w":"frightened of + N/V-ing","vi":"sợ","ex":"The child is frightened {of} the dark.","k":"pat"},{"w":"happy about/with + sth","vi":"vui về/hài lòng với","ex":"We are happy {about} the news and happy with the result.","k":"pat"},{"w":"nervous about + sth","vi":"lo lắng về","ex":"He is nervous {about} the exam.","k":"pat"},{"w":"scared of + N/V-ing","vi":"sợ","ex":"She is scared {of} flying.","k":"pat"},{"w":"sorry about/for + sth","vi":"lấy làm tiếc, xin lỗi vì","ex":"I am sorry {about} the delay and sorry for interrupting.","k":"pat"},{"w":"surprised at/by + sth","vi":"ngạc nhiên trước","ex":"We were surprised by her answer.","k":"pat"},{"w":"tired of + N/V-ing","vi":"chán, ngán việc gì","ex":"I am tired {of} waiting.","k":"pat"},{"w":"congratulate sb on sth/V-ing","vi":"chúc mừng ai về","ex":"We congratulated her {on} winning the prize.","k":"pat"},{"w":"laugh at + sb/sth","vi":"cười vì hoặc cười nhạo","ex":"Do not laugh {at} other people's mistakes.","k":"pat"},{"w":"a joke about + sth","vi":"câu chuyện cười về","ex":"He told a joke {about} school life.","k":"pat"}]}]},{"g":1,"u":42,"title":"Problems and Solutions","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"accident","pos":"n","vi":"tai nạn","de":"an unexpected event causing harm","ex":"There was an {accident} near the station.","k":"topic"},{"w":"assume","pos":"v","vi":"cho rằng, giả định","de":"accept something without proof","ex":"Do not {assume} that everyone agrees.","k":"topic"},{"w":"cause","pos":"v, n","vi":"gây ra; nguyên nhân","de":"make happen; the reason something happens","ex":"We need to find the {cause} of the problem.","k":"topic"},{"w":"claim","pos":"v","vi":"khẳng định, tuyên bố","de":"state that something is true","ex":"He {claims} that the story is true.","k":"topic"},{"w":"complain","pos":"v","vi":"phàn nàn","de":"say that something is unsatisfactory","ex":"Customers {complained} about the delay.","k":"topic"},{"w":"convince","pos":"v","vi":"thuyết phục","de":"make someone believe or agree","ex":"The evidence {convinced} us.","k":"topic"},{"w":"criticise","pos":"v","vi":"phê bình","de":"say what is wrong with someone or something","ex":"Try to help rather than {criticise}.","k":"topic"},{"w":"deny","pos":"v","vi":"phủ nhận","de":"say something is not true","ex":"She {denied} breaking the window.","k":"topic"},{"w":"discussion","pos":"n","vi":"cuộc thảo luận","de":"a conversation exploring a subject","ex":"We had a {discussion} about the plan.","k":"topic"},{"w":"doubt","pos":"v, n","vi":"nghi ngờ; sự nghi ngờ","de":"feel uncertain; uncertainty","ex":"I {doubt} that he meant to hurt you.","k":"topic"},{"w":"encourage","pos":"v","vi":"khuyến khích","de":"give support or confidence","ex":"Her teacher {encouraged} her to try again.","k":"topic"},{"w":"get rid of","pos":"v phr","vi":"loại bỏ","de":"remove something unwanted","ex":"We need to {get rid of} these old boxes.","k":"topic"},{"w":"gossip","pos":"v, n","vi":"buôn chuyện; chuyện ngồi lê","de":"talk about other people's private lives","ex":"Do not spread {gossip} about classmates.","k":"topic"},{"w":"ideal","pos":"adj","vi":"lí tưởng","de":"perfect for a particular purpose","ex":"This room is {ideal} for studying.","k":"topic"},{"w":"insult","pos":"v, n","vi":"xúc phạm; lời xúc phạm","de":"say something offensive","ex":"His rude remark was an {insult}.","k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"investigate","pos":"v","vi":"điều tra","de":"examine carefully to find facts","ex":"The team {investigated} the cause.","k":"topic"},{"w":"negative","pos":"adj","vi":"tiêu cực, phủ định","de":"focusing on bad aspects or expressing no","ex":"Try not to be {negative} about every idea.","k":"topic"},{"w":"positive","pos":"adj","vi":"tích cực, khẳng định","de":"hopeful or expressing agreement","ex":"She has a {positive} approach.","k":"topic"},{"w":"praise","pos":"v, n","vi":"khen ngợi; lời khen","de":"express approval","ex":"The teacher {praised} our effort.","k":"topic"},{"w":"pretend","pos":"v","vi":"giả vờ","de":"act as if something untrue were true","ex":"He {pretended} to be asleep.","k":"topic"},{"w":"purpose","pos":"n","vi":"mục đích","de":"the reason for doing something","ex":"What is the {purpose} of this meeting?","k":"topic"},{"w":"refuse","pos":"v","vi":"từ chối","de":"say you will not do or accept something","ex":"She {refused} to answer.","k":"topic"},{"w":"result","pos":"v, n","vi":"dẫn tới, phát sinh; kết quả","de":"happen as an effect; an outcome","ex":"The {result} surprised everyone.","k":"topic"},{"w":"rumour","pos":"n","vi":"tin đồn","de":"an unconfirmed story passed between people","ex":"The {rumour} turned out to be false.","k":"topic"},{"w":"sensible","pos":"adj","vi":"hợp lí, biết suy xét","de":"reasonable and showing good judgement","ex":"That seems like a {sensible} solution.","k":"topic"},{"w":"serious","pos":"adj","vi":"nghiêm trọng, nghiêm túc","de":"important, severe or not joking","ex":"We face a {serious} problem.","k":"topic"},{"w":"spare","pos":"adj","vi":"dự phòng, dư","de":"extra or available to use","ex":"Do you have a {spare} pen?","k":"topic"},{"w":"theory","pos":"n","vi":"lí thuyết, giả thuyết","de":"an explanation based on ideas or evidence","ex":"We tested the {theory} with new data.","k":"topic"},{"w":"thought","pos":"n","vi":"ý nghĩ, sự suy nghĩ","de":"an idea or the act of thinking","ex":"Give the question some {thought}.","k":"topic"},{"w":"warn","pos":"v","vi":"cảnh báo","de":"tell someone about possible danger","ex":"They {warned} us about the storm.","k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"hang up","vi":"treo quần áo lên","ex":"Hang {up} your coat in the wardrobe.","k":"pv"},{"w":"pick up","vi":"nhặt, cầm lên","ex":"Pick {up} the papers from the floor.","k":"pv"},{"w":"put back","vi":"đặt lại chỗ cũ","ex":"Put the book {back} when you finish.","k":"pv"},{"w":"run out of","vi":"hết, không còn","ex":"We have run out {of} paper.","k":"pv"},{"w":"share out","vi":"chia đều hoặc chia thành phần cho nhiều người","ex":"They shared {out} the food among the children.","k":"pv"},{"w":"sort out","vi":"giải quyết, sắp xếp ổn thỏa","ex":"We need to sort {out} this misunderstanding.","k":"pv"},{"w":"watch out","vi":"coi chừng, cẩn thận","ex":"Watch {out}! There is a hole ahead.","k":"pv"},{"w":"work out","vi":"tìm ra lời giải, tính ra","ex":"Can you work {out} the answer?","k":"pv"}]},{"type":"v","title":"Cụm giới từ & Cấu tạo từ (Prepositional phrases & Word formation)","words":[{"w":"by accident/mistake","vi":"do tình cờ, vô ý/nhầm lẫn","ex":"I deleted the file {by} mistake.","k":"prep"},{"w":"in a mess","vi":"trong tình trạng bừa bộn, rối tung","ex":"My notes are {in} a mess.","k":"prep"},{"w":"in danger of","vi":"có nguy cơ","ex":"The project is {in} danger of failing.","k":"prep"},{"w":"in my view","vi":"theo quan điểm của tôi","ex":"{In} my view, we should discuss it first.","k":"prep"},{"w":"in trouble","vi":"gặp rắc rối","ex":"He is {in} trouble for breaking the rules.","k":"prep"},{"w":"under pressure","vi":"chịu áp lực","ex":"She works well {under} pressure.","k":"prep"},{"w":"advice","vi":"lời khuyên; khuyên; người tư vấn","note":"advice → advise (v), adviser (n)","full":"lời khuyên; khuyên; người tư vấn","ex":"The {adviser} gave us useful advice.","hint":"advice","k":"wf"},{"w":"confuse","vi":"làm bối rối; bối rối; sự nhầm lẫn","note":"confuse → confused (adj), confusion (n)","full":"làm bối rối; bối rối; sự nhầm lẫn","ex":"The unclear message caused {confusion}.","hint":"confuse","k":"wf"},{"w":"except","vi":"ngoại trừ; ngoại lệ","note":"except → exception (n)","full":"ngoại trừ; ngoại lệ","ex":"There is one {exception} to the rule.","hint":"except","k":"wf"},{"w":"help","vi":"giúp; hữu ích/không giúp ích/bất lực","note":"help → helpful/unhelpful/helpless (adj)","full":"giúp; hữu ích/không giúp ích/bất lực","ex":"The clear instructions were {helpful}.","hint":"help","k":"wf"},{"w":"luck","vi":"may mắn; may/rủi; may thay/không may","note":"luck → lucky/unlucky (adj), luckily/unluckily (adv)","full":"may mắn; may/rủi; may thay/không may","ex":"{Luckily}, nobody was injured.","hint":"luck","k":"wf"},{"w":"prefer","vi":"thích hơn; sự ưa thích; đáng chọn hơn","note":"prefer → preference (n), preferable (adj)","full":"thích hơn; sự ưa thích; đáng chọn hơn","ex":"A simple solution is {preferable}.","hint":"prefer","k":"wf"},{"w":"recommend","vi":"đề xuất; lời đề xuất","note":"recommend → recommendation (n)","full":"đề xuất; lời đề xuất","ex":"We followed her {recommendation}.","hint":"recommend","k":"wf"},{"w":"refuse","vi":"từ chối; sự từ chối","note":"refuse → refusal (n)","full":"từ chối; sự từ chối","ex":"His {refusal} surprised us.","hint":"refuse","k":"wf"},{"w":"solve","vi":"giải quyết; giải pháp","note":"solve → solution (n)","full":"giải quyết; giải pháp","ex":"We finally found a {solution}.","hint":"solve","k":"wf"},{"w":"suggest","vi":"đề nghị; lời đề nghị","note":"suggest → suggestion (n)","full":"đề nghị; lời đề nghị","ex":"Thank you for your helpful {suggestion}.","hint":"suggest","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"sure about/of + sth","vi":"chắc chắn về","ex":"Are you sure {about} the answer?","k":"pat"},{"w":"advise against + N/V-ing","vi":"khuyên không làm","ex":"The teacher advised {against} leaving early.","k":"pat"},{"w":"agree with sb about sth","vi":"đồng ý với ai về","ex":"I agree {with} you about the main problem.","k":"pat"},{"w":"approve of + N/V-ing","vi":"tán thành","ex":"Her parents approve {of} the plan.","k":"pat"},{"w":"believe in + sb/sth","vi":"tin tưởng vào","ex":"You should believe {in} your ability.","k":"pat"},{"w":"deal with + sth","vi":"xử lí, đối phó","ex":"We must deal {with} the complaint.","k":"pat"},{"w":"happen to + sb/sth","vi":"xảy ra với","ex":"What happened {to} your phone?","k":"pat"},{"w":"hide sth from sb","vi":"giấu thứ gì khỏi ai","ex":"He hid the letter {from} his brother.","k":"pat"},{"w":"insist on + N/V-ing","vi":"khăng khăng yêu cầu","ex":"She insisted {on} checking the figures.","k":"pat"},{"w":"rely on + sb/sth","vi":"dựa vào, tin cậy","ex":"You can rely {on} me.","k":"pat"},{"w":"an advantage of + sth","vi":"ưu điểm của","ex":"One advantage {of} this plan is its low cost.","k":"pat"},{"w":"a solution to + sth","vi":"giải pháp cho","ex":"We need a solution {to} this problem.","k":"pat"}]}]},{"g":2,"u":2,"title":"Travel and Transport","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"voyage","pos":"n","vi":"hải trình","ex":"The journey took six hours, but the school trip was enjoyable.","grp":["voyage","journey","trip","travel","excursion"],"k":"topic"},{"w":"journey","pos":"n","vi":"hành trình","ex":"The {journey} took six hours, but the school trip was enjoyable.","grp":["voyage","journey","trip","travel","excursion"],"k":"topic"},{"w":"trip","pos":"n","vi":"chuyến đi","ex":"The journey took six hours, but the school {trip} was enjoyable.","grp":["voyage","journey","trip","travel","excursion"],"k":"topic"},{"w":"travel","pos":"n","vi":"việc đi lại (thường không đếm được)","ex":"The journey took six hours, but the school trip was enjoyable.","grp":["voyage","journey","trip","travel","excursion"],"k":"topic"},{"w":"excursion","pos":"n","vi":"chuyến tham quan ngắn","ex":"The journey took six hours, but the school trip was enjoyable.","grp":["voyage","journey","trip","travel","excursion"],"k":"topic"},{"w":"view","pos":"n","vi":"cảnh nhìn từ một vị trí","ex":"The room has a sea {view}; the old castle is a famous sight.","grp":["view","sight"],"k":"topic"},{"w":"sight","pos":"n","vi":"cảnh/vật nhìn thấy, thắng cảnh","ex":"The room has a sea view; the old castle is a famous {sight}.","grp":["view","sight"],"k":"topic"},{"w":"world","pos":"n","vi":"thế giới","ex":"People around the {world} are concerned about the earth.","grp":["world","earth"],"k":"topic"},{"w":"earth","pos":"n","vi":"Trái Đất, mặt đất","ex":"People around the world are concerned about the {earth}.","grp":["world","earth"],"k":"topic"},{"w":"area","pos":"n","vi":"khu vực","ex":"This {area} lies inside Canadian territory.","grp":["area","territory"],"k":"topic"},{"w":"territory","pos":"n","vi":"lãnh thổ, địa bàn thuộc quyền kiểm soát","ex":"This area lies inside Canadian {territory}.","grp":["area","territory"],"k":"topic"},{"w":"season","pos":"n","vi":"mùa, thời kì hoạt động","ex":"The rainy {season} is a difficult period for local drivers.","grp":["season","period"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"period","pos":"n","vi":"khoảng/giai đoạn thời gian","ex":"The rainy season is a difficult {period} for local drivers.","grp":["season","period"],"k":"topic"},{"w":"fare","pos":"n","vi":"tiền đi phương tiện","ex":"The bus {fare} is low, but the museum charges an entrance fee.","grp":["fare","ticket","fee"],"k":"topic"},{"w":"ticket","pos":"n","vi":"vé","ex":"The bus fare is low, but the museum charges an entrance fee.","grp":["fare","ticket","fee"],"k":"topic"},{"w":"fee","pos":"n","vi":"phí dịch vụ/tham gia","ex":"The bus fare is low, but the museum charges an entrance {fee}.","grp":["fare","ticket","fee"],"k":"topic"},{"w":"miss","pos":"v","vi":"lỡ chuyến, không bắt kịp","ex":"I lost my ticket and {missed} the train.","grp":["miss","lose"],"k":"topic"},{"w":"lose","pos":"v","vi":"làm mất, không còn giữ được","ex":"I {lost} my ticket and missed the train.","grp":["miss","lose"],"k":"topic"},{"w":"take","pos":"v","vi":"mang/đưa đi","ex":"{Take} an umbrella when you go out, and bring it back later.","grp":["take","bring","go"],"k":"topic"},{"w":"bring","pos":"v","vi":"mang/đưa đến điểm quy chiếu","ex":"Take an umbrella when you go out, and {bring} it back later.","grp":["take","bring","go"],"k":"topic"},{"w":"go","pos":"v","vi":"đi","ex":"Take an umbrella when you {go} out, and bring it back later.","grp":["take","bring","go"],"k":"topic"},{"w":"book","pos":"v","vi":"đặt trước","ex":"We {booked} a room and kept a copy of the confirmation.","grp":["book","keep"],"k":"topic"},{"w":"keep","pos":"v","vi":"giữ, duy trì","ex":"We booked a room and kept a copy of the confirmation.","grp":["book","keep"],"k":"topic"},{"w":"arrive","pos":"v","vi":"đến (in/at)","ex":"We {arrived} at the station and reached the hotel at noon.","grp":["arrive","reach"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"reach","pos":"v","vi":"đến được, theo sau trực tiếp bằng tân ngữ","ex":"We arrived at the station and {reached} the hotel at noon.","grp":["arrive","reach"],"k":"topic"},{"w":"live","pos":"v","vi":"sinh sống","ex":"She {lives} in Hue but is staying in Hanoi this week.","grp":["live","stay"],"k":"topic"},{"w":"stay","pos":"v","vi":"ở lại, lưu trú tạm thời","ex":"She lives in Hue but is {staying} in Hanoi this week.","grp":["live","stay"],"k":"topic"},{"w":"border","pos":"n","vi":"biên giới/ranh giới","ex":"A white line marks the edge of the road near the {border}.","grp":["border","edge","line"],"k":"topic"},{"w":"edge","pos":"n","vi":"mép/rìa","ex":"A white line marks the {edge} of the road near the border.","grp":["border","edge","line"],"k":"topic"},{"w":"line","pos":"n","vi":"đường/vạch","ex":"A white {line} marks the edge of the road near the border.","grp":["border","edge","line"],"k":"topic"},{"w":"length","pos":"n","vi":"chiều dài","ex":"The bridge's {length} is greater than the distance between the two houses.","grp":["length","distance"],"k":"topic"},{"w":"distance","pos":"n","vi":"khoảng cách","ex":"The bridge's length is greater than the {distance} between the two houses.","grp":["length","distance"],"k":"topic"},{"w":"guide","pos":"v","vi":"hướng dẫn, chỉ đường","ex":"A ranger {guided} us through the forest while Mai led the group.","grp":["guide","lead"],"k":"topic"},{"w":"lead","pos":"v","vi":"dẫn đầu/đưa đi","ex":"A ranger guided us through the forest while Mai led the group.","grp":["guide","lead"],"k":"topic"},{"w":"native","pos":"adj","vi":"thuộc nơi sinh ra/bản địa","ex":"Her {native} language is Vietnamese, and Hue is her home town.","grp":["native","home"],"k":"topic"},{"w":"home","pos":"adj","vi":"thuộc quê nhà/nơi ở","ex":"Her native language is Vietnamese, and Hue is her {home} town.","grp":["native","home"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"catch up with","vi":"đuổi kịp, đạt cùng mức với","ex":"Walk faster and you will catch up {with} us.","k":"pv"},{"w":"check in","vi":"làm thủ tục ở sân bay/khách sạn","ex":"We checked {in} two hours before departure.","k":"pv"},{"w":"check out","vi":"trả phòng; kiểm tra/tìm hiểu","ex":"Check {out} the route before you check out of the hotel.","k":"pv"},{"w":"drop off","vi":"cho xuống xe; ngủ thiếp đi","ex":"Dad dropped me {off} at the station, then I dropped off on the train.","k":"pv"},{"w":"get back","vi":"trở về","ex":"What time did you get {back} from Hue?","k":"pv"},{"w":"go away","vi":"đi xa, đi nghỉ","ex":"We usually go {away} in July.","k":"pv"},{"w":"keep up with","vi":"theo kịp, duy trì cùng tốc độ/mức độ","ex":"The children could not keep up {with} the guide.","k":"pv"},{"w":"make for","vi":"đi về phía","ex":"The hikers made {for} the nearest shelter.","k":"pv"},{"w":"pick up","vi":"đón bằng xe","ex":"Can you pick me {up} at six?","k":"pv"},{"w":"pull in","vi":"tấp xe vào lề/dừng bên đường","ex":"The driver pulled {in} to check the map.","k":"pv"},{"w":"run over","vi":"cán/đâm bằng xe","ex":"A cyclist was nearly run {over} at the crossing.","k":"pv"},{"w":"see off","vi":"tiễn người đi xa","ex":"My cousins came to see me {off}.","k":"pv"},{"w":"set out / set off","vi":"khởi hành","ex":"We set {off} before sunrise.","k":"pv"},{"w":"take off","vi":"cất cánh","ex":"The plane took {off} on time.","k":"pv"},{"w":"turn round","vi":"quay lại, đổi sang hướng ngược lại","ex":"We turned {round} when we reached the closed bridge.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"accident","vi":"gặp/liên quan tai nạn; vô tình làm","ex":"I deleted the booking by {accident}.","note":"have an accident; be (involved) in an accident; do sth by accident","k":"col"},{"w":"advance","vi":"trước; advance to/towards a place = tiến đến","ex":"Please book your seats in {advance}.","note":"in advance","k":"col"},{"w":"ahead","vi":"đi thẳng; tiến hành; ở phía trước","ex":"Go straight {ahead}; the museum is ahead of you.","note":"go straight ahead; go ahead; be ahead of sb/sth","k":"col"},{"w":"direction","vi":"đổi hướng; về phía; theo hướng này/kia","ex":"The wind blew in the {direction} of the coast.","note":"a change of direction; in the direction of; in this/that direction","k":"col"},{"w":"head","vi":"nói ngay theo trí nhớ; head for/towards = hướng đến; head over heels (in love) = yêu say đắm","ex":"We {headed} for the airport before dawn.","note":"off the top of your head","k":"col"},{"w":"holiday","vi":"đi/đang nghỉ; kì nghỉ; ngày nghỉ lễ","ex":"We took a short {holiday} over the bank holiday weekend.","note":"go/be on holiday; have/take a holiday; bank holiday","k":"col"},{"w":"left","vi":"rẽ/trái; ở bên/góc trái; thuận tay trái","ex":"Turn {left}; the desk is in the left-hand corner.","note":"go/turn left; on the left; on the left-hand side; in the left- hand corner; left-handed","k":"col"},{"w":"route","vi":"lập lộ trình; đi theo tuyến","ex":"We planned our {route} carefully.","note":"plan your/a route; take a route","k":"col"},{"w":"sights / sightseeing","vi":"tham quan các thắng cảnh","ex":"We went sightseeing and saw all the main sights.","note":"see the sights; go sightseeing","k":"col"},{"w":"speed","vi":"ở tốc độ; đợt tăng tốc; giới hạn tốc độ","ex":"The driver exceeded the {speed} limit.","note":"at (high/full) speed; a burst of speed; speed limit","k":"col"},{"w":"tour","vi":"đi tham quan; hướng dẫn viên","ex":"A local {tour} guide took us on a tour of the city.","note":"go on/take a tour of/(a)round; tour a place; tour guide","k":"col"},{"w":"trip","vi":"chuyến công tác/trường; đi đến","ex":"Our class took a {trip} to a wildlife park.","note":"business/school trip; go on a trip; take a trip to","k":"col"},{"w":"way","vi":"lạc/tìm/đi đường; phần nào; trên đường; đi tận","ex":"We lost our {way} on the way to the lake.","note":"lose/make/find your way; in a way; on the way; go all the way (to)","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"arrange","vi":"sắp xếp","note":"arrange (v) → rearrange (v), arrangement (n)","full":"sắp xếp → sắp xếp lại; sự sắp xếp.","ex":"The travel arrangements have changed.","hint":"arrange","k":"wf"},{"w":"arrive","vi":"đến","note":"arrive (v) → arrival (n)","full":"đến → sự đến/người mới đến.","ex":"We waited in the arrivals hall.","hint":"arrive","k":"wf"},{"w":"broad","vi":"rộng","note":"broad (adj) → breadth (n), broaden (v)","full":"rộng → chiều rộng; mở rộng.","ex":"Travel can {broaden} your understanding.","hint":"broad","k":"wf"},{"w":"culture","vi":"văn hóa","note":"culture (n) → cultural (adj), culturally (adv), cultured/uncultured (adj)","full":"văn hóa → thuộc văn hóa; có/thiếu sự tinh tế, giáo dưỡng.","ex":"The festival celebrates {cultural} diversity.","hint":"culture","k":"wf"},{"w":"differ","vi":"khác","note":"differ (v) → different (adj), differently (adv), difference (n)","full":"khác → khác biệt; một cách khác; sự khác biệt.","ex":"The two towns are very {different}.","hint":"differ","k":"wf"},{"w":"direct","vi":"chỉ dẫn/trực tiếp","note":"direct (v/adj) → indirect (adj), direction (n), director (n), directly/indirectly (adv)","full":"chỉ dẫn/trực tiếp → gián tiếp; phương hướng; giám đốc; trực tiếp/gián tiếp.","ex":"Could you give us directions to the station?","hint":"direct","k":"wf"},{"w":"distant","vi":"xa","note":"distant (adj) → distantly (adv), distance (n)","full":"xa → một cách xa cách; khoảng cách.","ex":"We could see a distant island.","hint":"distant","k":"wf"},{"w":"enter","vi":"đi vào","note":"enter (v) → entrance (n)","full":"đi vào → lối vào/sự gia nhập.","ex":"Meet me at the main {entrance}.","hint":"enter","k":"wf"},{"w":"inhabit","vi":"sinh sống ở","note":"inhabit (v) → inhabitant (n)","full":"sinh sống ở → cư dân.","ex":"The island has only fifty inhabitants.","hint":"inhabit","k":"wf"},{"w":"photograph","vi":"ảnh/chụp ảnh","note":"photograph (n/v) → photography (n), photographer (n), photographic (adj)","full":"ảnh/chụp ảnh → nhiếp ảnh; nhiếp ảnh gia; thuộc ảnh.","ex":"She works as a wildlife {photographer}.","hint":"photograph","k":"wf"},{"w":"recognise","vi":"nhận ra","note":"recognise (v) → recognisable/unrecognisable (adj), recognition (n)","full":"nhận ra → có/không thể nhận ra; sự nhận diện.","ex":"The building was almost {unrecognisable}.","hint":"recognise","k":"wf"},{"w":"time","vi":"thời gian","note":"time (n/v) → timetable (n)","full":"thời gian → thời gian biểu/lịch chạy tàu xe.","ex":"Check the new {timetable} before travelling.","hint":"time","k":"wf"},{"w":"tour","vi":"chuyến tham quan","note":"tour (n/v) → tourism (n), tourist (n)","full":"chuyến tham quan → ngành du lịch; du khách.","ex":"{Tourism} supports many local businesses.","hint":"tour","k":"wf"},{"w":"world","vi":"thế giới","note":"world (n) → worldwide (adj/adv)","full":"thế giới → trên toàn thế giới.","ex":"The city attracts visitors {worldwide}.","hint":"world","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"afraid of N/V-ing; afraid to V","vi":"sợ điều gì/việc gì; không dám làm","ex":"She is afraid {of} flying but is not afraid to ask for help.","k":"pat"},{"w":"appear to be","vi":"có vẻ là","ex":"The road appears {to} be closed.","k":"pat"},{"w":"arrange sth (with sb); arrange for sb to V","vi":"sắp xếp với ai; thu xếp để ai làm","ex":"We arranged for a driver to collect us.","k":"pat"},{"w":"arrive in/at; arrive here/there","vi":"in + thành phố/nước; at + địa điểm cụ thể; here/there không thêm giới từ","ex":"They arrived {in} Hue and arrived here at noon.","k":"pat"},{"w":"continue N/V-ing/to V; continue with N","vi":"tiếp tục hoạt động/công việc","ex":"They continued walking despite the rain.","k":"pat"},{"w":"differ from","vi":"khác với","ex":"This route differs {from} the one on our map.","k":"pat"},{"w":"dream of/about N/V-ing","vi":"mơ về, ao ước","ex":"He dreams {of} travelling abroad.","k":"pat"},{"w":"invite sb to V","vi":"mời ai làm","ex":"They invited us {to} stay for a week.","k":"pat"},{"w":"keen to V; keen on N/V-ing","vi":"háo hức muốn làm; thích","ex":"She is keen on hiking and keen {to} explore the island.","k":"pat"},{"w":"live in/at; live on/for; live here/there","vi":"sống ở; sống nhờ (tiền/thức ăn)/sống vì; here/there không có giới từ","ex":"They live on a small pension and live for their children.","k":"pat"},{"w":"regret (not) V-ing/N; regret to tell/inform","vi":"hối tiếc việc đã làm/không làm; lấy làm tiếc phải thông báo","ex":"I regret missing the trip. We regret {to} inform you that it is cancelled.","k":"pat"},{"w":"think of/about N/sb/V-ing","vi":"nghĩ đến/về","ex":"We are thinking {of} visiting Hue.","k":"pat"},{"w":"write (to sb); write sb sth / sth to sb; write about","vi":"viết cho ai; viết về điều gì","ex":"Please write {to} me and write about your journey.","k":"pat"}]}]},{"g":2,"u":4,"title":"Hobbies Sport and Games","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"pitch","pos":"n","vi":"sân bóng","ex":"The runners left the track while the boxers entered the ring.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"track","pos":"n","vi":"đường chạy","ex":"The runners left the {track} while the boxers entered the ring.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"court","pos":"n","vi":"sân quần vợt/bóng rổ","ex":"The runners left the track while the boxers entered the ring.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"course","pos":"n","vi":"sân gôn/đường đua","ex":"The runners left the track while the boxers entered the ring.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"ring","pos":"n","vi":"võ đài","ex":"The runners left the track while the boxers entered the {ring}.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"rink","pos":"n","vi":"sân trượt băng","ex":"The runners left the track while the boxers entered the ring.","grp":["pitch","track","court","course","ring","rink"],"k":"topic"},{"w":"win","pos":"v","vi":"thắng trận/giải","ex":"We beat their team, won the match and scored three goals.","grp":["win","beat","score"],"k":"topic"},{"w":"beat","pos":"v","vi":"đánh bại đối thủ","ex":"We {beat} their team, won the match and scored three goals.","grp":["win","beat","score"],"k":"topic"},{"w":"score","pos":"v","vi":"ghi bàn/điểm","ex":"We beat their team, won the match and {scored} three goals.","grp":["win","beat","score"],"k":"topic"},{"w":"play","pos":"n","vi":"sự chơi/cách chơi","ex":"The game was stopped because of dangerous {play}.","grp":["play","game"],"k":"topic"},{"w":"game","pos":"n","vi":"trò chơi/trận đấu","ex":"The {game} was stopped because of dangerous play.","grp":["play","game"],"k":"topic"},{"w":"spectator","pos":"n","vi":"khán giả trực tiếp","ex":"Thousands of {spectators} and millions of viewers watched the final.","grp":["spectator","viewer"],"k":"topic"},{"w":"viewer","pos":"n","vi":"người xem truyền hình/video","ex":"Thousands of spectators and millions of {viewers} watched the final.","grp":["spectator","viewer"],"k":"topic"},{"w":"umpire / referee","pos":"n","vi":"trọng tài; umpire thường ở tennis/cricket; referee thường ở bóng đá/quyền anh.","de":"","ex":"The tennis umpire checked the score; the football referee showed a card.","k":"topic"},{"w":"final","pos":"n","vi":"trận chung kết","ex":"The {final} ended late; the concert's finale was spectacular.","grp":["final","finale","end","ending"],"k":"topic"},{"w":"finale","pos":"n","vi":"phần kết hoành tráng","ex":"The final ended late; the concert's {finale} was spectacular.","grp":["final","finale","end","ending"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"end","pos":"n","vi":"điểm kết thúc","ex":"The final {ended} late; the concert's finale was spectacular.","grp":["final","finale","end","ending"],"k":"topic"},{"w":"ending","pos":"n","vi":"đoạn/kết cục câu chuyện","ex":"The final ended late; the concert's finale was spectacular.","grp":["final","finale","end","ending"],"k":"topic"},{"w":"bat","pos":"n","vi":"gậy bóng chày/cricket","ex":"He packed a fishing rod and a tennis racket.","grp":["bat","stick","rod","racket"],"k":"topic"},{"w":"stick","pos":"n","vi":"gậy hockey","ex":"He packed a fishing rod and a tennis racket.","grp":["bat","stick","rod","racket"],"k":"topic"},{"w":"rod","pos":"n","vi":"cần câu","ex":"He packed a fishing {rod} and a tennis racket.","grp":["bat","stick","rod","racket"],"k":"topic"},{"w":"racket","pos":"n","vi":"vợt","ex":"He packed a fishing rod and a tennis {racket}.","grp":["bat","stick","rod","racket"],"k":"topic"},{"w":"amateur","pos":"n/adj","vi":"người nghiệp dư/không chuyên","ex":"She began as an {amateur} and became a professional player.","grp":["amateur","professional"],"k":"topic"},{"w":"professional","pos":"n/adj","vi":"người chuyên nghiệp","ex":"She began as an amateur and became a {professional} player.","grp":["amateur","professional"],"k":"topic"},{"w":"sport","pos":"n","vi":"thể thao/môn thể thao","ex":"Athletics is her favourite {sport}.","grp":["sport","athletics"],"k":"topic"},{"w":"athletics","pos":"n","vi":"điền kinh trong Anh Anh","ex":"{Athletics} is her favourite sport.","grp":["sport","athletics"],"k":"topic"},{"w":"interval","pos":"n","vi":"giờ nghỉ giữa các phần","ex":"We bought drinks at half-time and during the concert {interval}.","grp":["interval","half-time"],"k":"topic"},{"w":"half-time","pos":"n","vi":"giờ nghỉ giữa hai hiệp","ex":"We bought drinks at {half-time} and during the concert interval.","grp":["interval","half-time"],"k":"topic"},{"w":"draw","pos":"v","vi":"hòa trận","ex":"They drew the match, and Lan equalled the school record.","grp":["draw","equal"],"k":"topic"},{"w":"equal","pos":"v","vi":"bằng/sánh ngang một thành tích","ex":"They drew the match, and Lan {equalled} the school record.","grp":["draw","equal"],"k":"topic"},{"w":"competitor","pos":"n","vi":"người dự thi/đối thủ cạnh tranh","ex":"Every {competitor} hopes to defeat their opponent.","grp":["competitor","opponent"],"k":"topic"},{"w":"opponent","pos":"n","vi":"đối thủ trực tiếp","ex":"Every competitor hopes to defeat their {opponent}.","grp":["competitor","opponent"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"bring forward","vi":"chuyển lịch lên sớm hơn","ex":"The final was brought {forward} to Friday.","k":"pv"},{"w":"carry on","vi":"tiếp tục","ex":"Carry {on} practising after the lesson.","k":"pv"},{"w":"get round to","vi":"cuối cùng cũng có thời gian bắt đầu (V- ing)","ex":"I finally got round {to} repairing my bike.","k":"pv"},{"w":"get up to","vi":"làm việc gì, thường hàm ý nghịch ngợm","ex":"What did the children get up {to} yesterday?","k":"pv"},{"w":"go in for","vi":"tham gia thi; thích một hoạt động","ex":"She goes in {for} long-distance races.","k":"pv"},{"w":"go off","vi":"không còn thích","ex":"He has gone {off} computer games.","k":"pv"},{"w":"join in","vi":"tham gia cùng","ex":"Everyone joined {in} the game.","k":"pv"},{"w":"knock out","vi":"loại khỏi cuộc thi; đánh bất tỉnh","ex":"Our team was knocked {out} in the semi-final.","k":"pv"},{"w":"look out","vi":"coi chừng","ex":"Look {out}! A ball is coming towards you.","k":"pv"},{"w":"pull out (of)","vi":"rút khỏi một hoạt động/cuộc thi","ex":"He pulled out {of} the race with an injury.","k":"pv"},{"w":"put off","vi":"hoãn","ex":"They put {off} the match until Sunday.","k":"pv"},{"w":"put up with","vi":"chịu đựng","ex":"I cannot put up {with} that noise.","k":"pv"},{"w":"take to","vi":"bắt đầu có thói quen/thích làm","ex":"She has taken {to} swimming before work.","k":"pv"},{"w":"take up","vi":"bắt đầu sở thích; chiếm thời gian/không gian","ex":"Tennis takes {up} most of his weekends.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"best","vi":"tận dụng hoàn cảnh; cố hết sức; giỏi nhất về","ex":"Do your {best} and make the best of the equipment available.","note":"make the best of; do your best; be best at","k":"col"},{"w":"chance","vi":"cơ hội/khả năng; liều thử; cơ hội hiếm có","ex":"She has a good {chance} of winning; this is the chance of a lifetime.","note":"have/take/get a chance to V; have a chance of V-ing; some/little chance of; the chances of; take a chance on; the chance of a lifetime","k":"col"},{"w":"go","vi":"lượt của bạn; thử làm","ex":"It is your {go}; have a go at solving the puzzle.","note":"your go; have a go","k":"col"},{"w":"height","vi":"về chiều cao; sợ độ cao; đỉnh điểm","ex":"The wall is three metres in {height}.","note":"in height; afraid of heights; the height of","k":"col"},{"w":"mad","vi":"mê; trở nên điên/giận dữ tùy ngữ cảnh","ex":"He is {mad} about basketball.","note":"mad about/on; go/become mad","k":"col"},{"w":"pleasure","vi":"thấy vui, có niềm vui từ","ex":"She takes {pleasure} in teaching beginners.","note":"take pleasure in; gain/get pleasure from","k":"col"},{"w":"popular","vi":"được một nhóm yêu thích","ex":"The club is {popular} among teenagers.","note":"popular with/among","k":"col"},{"w":"side","vi":"phía đối diện/xa; đứng về phe; ở đội thắng/thua","ex":"The café is on the far {side} of the pitch.","note":"opposite/far side; side with; on the winning/losing side","k":"col"},{"w":"talent","vi":"có năng khiếu về; cuộc thi tài năng","ex":"She has a {talent} for dancing.","note":"have a talent for; talent contest","k":"col"},{"w":"time","vi":"on time (đúng giờ); in time (kịp); the whole time (suốt); high/about time (đến lúc nên); take your time (cứ thong thả); take time to V / take up time (mất/chiếm thời gian); spend time V-ing/on N (dành thời gian); at/for a certain time (vào/trong thời gian cụ thể); time passes (trôi); find time to V / make/find time for (thu xếp thời gian); for the time being (tạm thời); have a good/nice time (vui vẻ); tell the time (xem giờ); free/spare/leisure time (thời gian rảnh).","ex":"Take your {time}, but finish in time for the show. I spend my spare time reading.","note":"on time (đúng giờ); in time (kịp); the whole time (suốt); high/about time (đến lúc nên); take your time (cứ thong thả); take time to V / take up time (mất/chiếm thời gian); spend time V-ing/on N (dành thời gian); at/for a certain time (vào/trong thời gian cụ thể); time passes (trôi); find time to V / make/find time for (thu xếp thời gian); for the time being (tạm thời); have a good/nice time (vui vẻ); tell the time (xem giờ); free/spare/leisure time (thời gian rảnh)","k":"col"},{"w":"turn","vi":"quay lại/đi; lật; lần lượt; thay phiên; lượt làm","ex":"We took it in {turns} to keep score.","note":"turn round/away; turn sth over; in turn; take turns; take it in turns to V; your turn to V","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"allow","vi":"cho phép","note":"allow (v) → disallow (v), allowance (n), allowable (adj)","full":"cho phép → không công nhận; khoản trợ cấp/mức cho phép; được phép.","ex":"The referee disallowed the goal.","hint":"allow","k":"wf"},{"w":"associate","vi":"liên hệ","note":"associate (v) → disassociate (v), association (n), associated/unassociated (adj)","full":"liên hệ → tách khỏi; hiệp hội/sự liên kết; có/không liên hệ.","ex":"The sports {association} organised the tournament.","hint":"associate","k":"wf"},{"w":"compete","vi":"thi đấu","note":"compete (v) → competition, competitor (n), competitive (adj), competitively (adv)","full":"thi đấu → cuộc thi; người thi; có tính cạnh tranh.","ex":"There were fifty competitors.","hint":"compete","k":"wf"},{"w":"enjoy","vi":"thích","note":"enjoy (v) → enjoyment (n), enjoyable (adj)","full":"thích → sự thích thú; thú vị.","ex":"It was an {enjoyable} afternoon.","hint":"enjoy","k":"wf"},{"w":"equip","vi":"trang bị","note":"equip (v) → equipment (n), equipped (adj)","full":"trang bị → thiết bị (không đếm được); được trang bị.","ex":"All the safety {equipment} is new.","hint":"equip","k":"wf"},{"w":"fortune","vi":"may mắn/tài sản","note":"fortune (n) → misfortune (n), fortunate/unfortunate (adj), fortunately/unfortunately (adv)","full":"may mắn/tài sản → điều bất hạnh; may/không may.","ex":"{Fortunately}, nobody was injured.","hint":"fortune","k":"wf"},{"w":"interest","vi":"sự quan tâm","note":"interest (n/v) → interesting/uninteresting (adj), interestingly/uninterestingly (adv)","full":"sự quan tâm → thú vị/không thú vị; trạng từ tương ứng.","ex":"The guide made the history {interesting}.","hint":"interest","k":"wf"},{"w":"know","vi":"biết","note":"know (v) → knowledge (n), knowledgeable/unknowledgeable (adj)","full":"biết → kiến thức; am hiểu/thiếu hiểu biết.","ex":"Our coach is {knowledgeable} about nutrition.","hint":"know","k":"wf"},{"w":"lose","vi":"mất/thua","note":"lose (v) → lost (V2/V3/adj), loss (n)","full":"mất/thua → đã mất/thua; sự mất/thất bại.","ex":"The team suffered its first {loss}.","hint":"lose","k":"wf"},{"w":"maintain","vi":"duy trì/bảo dưỡng","note":"maintain (v) → maintenance (n)","full":"duy trì/bảo dưỡng → sự bảo dưỡng.","ex":"The rink is closed for {maintenance}.","hint":"maintain","k":"wf"},{"w":"medal","vi":"huy chương","note":"medal (n) → medallist, medallion (n)","full":"huy chương → người đoạt huy chương; vật trang sức hình huy chương.","ex":"The gold {medallist} thanked her coach.","hint":"medal","k":"wf"},{"w":"oppose","vi":"phản đối","note":"oppose (v) → opposition, opponent (n), opposite, opposing (adj)","full":"phản đối → phe đối lập; đối thủ; đối diện/trái ngược; đối địch.","ex":"Their opponents defended well.","hint":"oppose","k":"wf"},{"w":"practice","vi":"sự luyện tập","note":"practice (n) → practise (v), practical/impractical (adj), practically/impractically (adv)","full":"sự luyện tập → luyện tập (Anh Anh); thực tế/không thực tế.","ex":"Regular practice improves accuracy.","hint":"practice","k":"wf"},{"w":"train","vi":"huấn luyện","note":"train (v) → retrain (v), trainer (n)","full":"huấn luyện → đào tạo lại; huấn luyện viên/giày thể thao.","ex":"The {trainer} designed a new programme.","hint":"train","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"compete against/with sb; compete for/in sth","vi":"thi đấu với; tranh giành/tham dự","ex":"They competed for a place in the team.","k":"pat"},{"w":"concentrate on N/V-ing","vi":"tập trung vào","ex":"Concentrate {on} keeping your balance.","k":"pat"},{"w":"difficult to V; find sth difficult; find it difficult to V","vi":"khó làm; thấy điều gì khó","ex":"I find it difficult {to} hit the ball accurately.","k":"pat"},{"w":"fond of N/V-ing","vi":"thích","ex":"She is fond {of} playing chess.","k":"pat"},{"w":"free to V; free from/of; free for","vi":"được tự do làm; không có/thoát khỏi; rảnh cho","ex":"Are you free for a game this evening?","k":"pat"},{"w":"interested in N/V-ing","vi":"quan tâm, thích","ex":"He is interested {in} collecting stamps.","k":"pat"},{"w":"involve N/V-ing; be involved in","vi":"bao gồm/đòi hỏi; tham gia","ex":"The activity involves working {in} pairs.","k":"pat"},{"w":"listen to","vi":"lắng nghe","ex":"Listen {to} the coach's instructions.","k":"pat"},{"w":"love N/V-ing/to V","vi":"yêu thích","ex":"I love watching live matches.","k":"pat"},{"w":"mean to V; mean that; mean V-ing","vi":"định làm; có nghĩa rằng; đồng nghĩa/đòi hỏi việc","ex":"I meant {to} call. Training seriously means giving up some free time.","k":"pat"},{"w":"prefer N/V-ing to N/V-ing; prefer to V rather than V","vi":"thích hơn; thích làm A hơn B","ex":"I prefer cycling {to} running.","k":"pat"},{"w":"sure/certain that/of; sure/certain to V; make sure/certain that","vi":"chắc chắn về/rằng; chắc sẽ; bảo đảm","ex":"Make sure that everyone knows the rules.","k":"pat"}]}]},{"g":2,"u":6,"title":"Science and Technology","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"artificial","pos":"adj","vi":"nhân tạo","ex":"{Artificial} flowers are useful, but false results are unacceptable.","grp":["artificial","false"],"k":"topic"},{"w":"false","pos":"adj","vi":"sai, giả, không thật","ex":"Artificial flowers are useful, but {false} results are unacceptable.","grp":["artificial","false"],"k":"topic"},{"w":"natural","pos":"adj","vi":"tự nhiên","ex":"Exercise improves physical health; clean water is a {natural} resource.","grp":["natural","physical"],"k":"topic"},{"w":"physical","pos":"adj","vi":"thuộc vật chất/cơ thể","ex":"Exercise improves {physical} health; clean water is a natural resource.","grp":["natural","physical"],"k":"topic"},{"w":"true","pos":"adj","vi":"đúng sự thật","ex":"The story is {true}, but some dates are not accurate.","grp":["true","accurate"],"k":"topic"},{"w":"accurate","pos":"adj","vi":"chính xác về chi tiết/số liệu","ex":"The story is true, but some dates are not {accurate}.","grp":["true","accurate"],"k":"topic"},{"w":"method","pos":"n","vi":"phương pháp có hệ thống","ex":"This {method} is a reliable way to measure temperature.","grp":["method","way"],"k":"topic"},{"w":"way","pos":"n","vi":"cách làm/đường lối nói chung","ex":"This method is a reliable {way} to measure temperature.","grp":["method","way"],"k":"topic"},{"w":"engine","pos":"n","vi":"động cơ tạo lực","ex":"The washing machine uses an electric motor; the car has a petrol {engine}.","grp":["engine","machine","motor"],"k":"topic"},{"w":"machine","pos":"n","vi":"máy","ex":"The washing {machine} uses an electric motor; the car has a petrol engine.","grp":["engine","machine","motor"],"k":"topic"},{"w":"motor","pos":"n","vi":"động cơ, thường chạy điện","ex":"The washing machine uses an electric {motor}; the car has a petrol engine.","grp":["engine","machine","motor"],"k":"topic"},{"w":"aim","pos":"n","vi":"mục tiêu","ex":"Our {aim} is to discover the cause of the fault and the reason for the delay.","grp":["aim","cause","reason"],"k":"topic"},{"w":"cause","pos":"n","vi":"nguyên nhân tạo kết quả","ex":"Our aim is to discover the {cause} of the fault and the reason for the delay.","grp":["aim","cause","reason"],"k":"topic"},{"w":"reason","pos":"n","vi":"lí do giải thích","ex":"Our aim is to discover the cause of the fault and the {reason} for the delay.","grp":["aim","cause","reason"],"k":"topic"},{"w":"estimate","pos":"v","vi":"ước tính","ex":"We {estimated} the cost, then calculated it more accurately.","grp":["estimate","calculate"],"k":"topic"},{"w":"calculate","pos":"v","vi":"tính toán","ex":"We estimated the cost, then {calculated} it more accurately.","grp":["estimate","calculate"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"electric","pos":"adj","vi":"dùng/tạo điện","ex":"An {electric} heater is simpler than an electronic control system.","grp":["electric","electronic"],"k":"topic"},{"w":"electronic","pos":"adj","vi":"dùng linh kiện/mạch điện tử","ex":"An electric heater is simpler than an {electronic} control system.","grp":["electric","electronic"],"k":"topic"},{"w":"invent","pos":"v","vi":"phát minh thứ mới","ex":"Scientists discovered the element; engineers {invented} a new sensor.","grp":["invent","discover"],"k":"topic"},{"w":"discover","pos":"v","vi":"tìm ra thứ đã tồn tại","ex":"Scientists {discovered} the element; engineers invented a new sensor.","grp":["invent","discover"],"k":"topic"},{"w":"research","pos":"n","vi":"nghiên cứu nói chung, thường không đếm được","ex":"Their {research} involved several experiments.","grp":["research","experiment"],"k":"topic"},{"w":"experiment","pos":"n","vi":"thí nghiệm cụ thể","ex":"Their research involved several {experiments}.","grp":["research","experiment"],"k":"topic"},{"w":"progress","pos":"n","vi":"sự tiến bộ","ex":"The development of the device represents real {progress}.","grp":["progress","development"],"k":"topic"},{"w":"development","pos":"n","vi":"sự phát triển/quá trình tạo ra cái mới","ex":"The {development} of the device represents real progress.","grp":["progress","development"],"k":"topic"},{"w":"modern","pos":"adj","vi":"hiện đại/thuộc thời hiện tại","ex":"Their new office is inside an old building with {modern} equipment.","grp":["modern","new"],"k":"topic"},{"w":"new","pos":"adj","vi":"mới","ex":"Their {new} office is inside an old building with modern equipment.","grp":["modern","new"],"k":"topic"},{"w":"industry","pos":"n","vi":"ngành công nghiệp","ex":"The car {industry} owns many factories.","grp":["industry","factory"],"k":"topic"},{"w":"factory","pos":"n","vi":"nhà máy cụ thể","ex":"The car industry owns many {factories}.","grp":["industry","factory"],"k":"topic"},{"w":"award","pos":"n/v","vi":"giải thưởng/trao giải","ex":"She won a research {award} and received a reward for finding the missing laptop.","grp":["award","reward"],"k":"topic"},{"w":"reward","pos":"n/v","vi":"phần thưởng/đền đáp việc tốt","ex":"She won a research award and received a {reward} for finding the missing laptop.","grp":["award","reward"],"k":"topic"},{"w":"take place","pos":"v","vi":"diễn ra, thường theo kế hoạch","ex":"The conference takes {place} in May; errors may occur during testing.","grp":["take place","occur"],"k":"topic"},{"w":"occur","pos":"v","vi":"xảy ra/xuất hiện","ex":"The conference takes place in May; errors may {occur} during testing.","grp":["take place","occur"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"break down","vi":"hỏng máy; ngừng hoạt động","ex":"The motor broke {down} yesterday.","k":"pv"},{"w":"carry out","vi":"thực hiện","ex":"They carried {out} a safety test.","k":"pv"},{"w":"come off","vi":"thành công như dự định","ex":"The experiment came {off} perfectly.","k":"pv"},{"w":"come on","vi":"tiến bộ, phát triển","ex":"Your project has really come {on} this month.","k":"pv"},{"w":"come up with","vi":"nghĩ ra","ex":"She came up {with} a better design.","k":"pv"},{"w":"cut off","vi":"cắt/ngừng cung cấp","ex":"The storm cut {off} the electricity.","k":"pv"},{"w":"find out","vi":"tìm ra thông tin","ex":"We need to find {out} why it failed.","k":"pv"},{"w":"give off","vi":"tỏa/phát ra nhiệt, mùi, khí","ex":"The battery was giving {off} heat.","k":"pv"},{"w":"narrow down","vi":"thu hẹp phạm vi/lựa chọn","ex":"The tests narrowed {down} the possible causes.","k":"pv"},{"w":"plug in","vi":"cắm điện/kết nối bằng phích","ex":"Plug it {in} before switching it on.","k":"pv"},{"w":"put through","vi":"nối máy điện thoại","ex":"Could you put me {through} to the laboratory?","k":"pv"},{"w":"turn into","vi":"biến thành","ex":"Heat turns ice {into} water.","k":"pv"},{"w":"turn off","vi":"tắt","ex":"Turn {off} the power before opening the case.","k":"pv"},{"w":"work out","vi":"giải được, tìm ra đáp án","ex":"We worked {out} how to repair the sensor.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"attempt","vi":"thử/cố làm; nhằm cố gắng","ex":"They repeated the test in an {attempt} to improve accuracy.","note":"make an attempt at N/V-ing / to V; attempt to V; in an attempt to V","k":"col"},{"w":"average","vi":"tính trung bình","ex":"The machine uses two units of electricity on {average} each day.","note":"on average","k":"col"},{"w":"beginning","vi":"lúc đầu; ở đầu; bắt đầu bằng","ex":"At the {beginning} of the lesson, we reviewed the results.","note":"in the beginning; at the beginning of; beginning with","k":"col"},{"w":"bottom","vi":"ở đáy/dưới cùng","ex":"Write your name at the {bottom} of the page.","note":"at/on the bottom of","k":"col"},{"w":"cause","vi":"nguyên nhân của","ex":"They identified the {cause} of the error.","note":"the cause of","k":"col"},{"w":"conclusion","vi":"đi đến kết luận; để kết luận","ex":"We reached the {conclusion} that the sample was damaged.","note":"come to/reach the conclusion that; in conclusion","k":"col"},{"w":"experiment","vi":"tiến hành thí nghiệm về; thử với","ex":"The team {experimented} with different materials.","note":"do/perform/carry out an experiment on; experiment with","k":"col"},{"w":"fact","vi":"thực ra; sự thật là; đối diện sự thật","ex":"The {fact} is that the first method was inaccurate.","note":"in fact; as a matter of fact; the fact is; face the facts","k":"col"},{"w":"introduction","vi":"cùng sự ra đời/áp dụng; bài nhập môn về","ex":"The book provides an {introduction} to robotics.","note":"with the introduction of; an introduction to","k":"col"},{"w":"phone call","vi":"gọi/nhận điện thoại","ex":"I received a {phone call} from the technician.","note":"make/receive/get a phone call","k":"col"},{"w":"photo","vi":"chụp ảnh","ex":"Take a {photo} of the wiring before removing it.","note":"take a photo of","k":"col"},{"w":"research","vi":"nghiên cứu về","ex":"They are doing {research} into renewable energy.","note":"carry out/do research on/into","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"appear","vi":"xuất hiện/có vẻ","note":"appear (v) → appearance (n), apparently (adv)","full":"xuất hiện/có vẻ → diện mạo/sự xuất hiện; dường như.","ex":"{Apparently}, the fault has been fixed.","hint":"appear","k":"wf"},{"w":"build","vi":"xây","note":"build (v) → builder, building (n)","full":"xây → thợ xây; công trình/việc xây dựng.","ex":"The {building} uses less energy.","hint":"build","k":"wf"},{"w":"discover","vi":"khám phá","note":"discover (v) → discovery (n)","full":"khám phá → sự khám phá.","ex":"The {discovery} changed their research.","hint":"discover","k":"wf"},{"w":"explain","vi":"giải thích","note":"explain (v) → explanation (n)","full":"giải thích → lời giải thích.","ex":"Her {explanation} was clear.","hint":"explain","k":"wf"},{"w":"important/unimportant","vi":"quan trọng/không quan trọng","note":"important/unimportant (adj) → importance (n), importantly (adv)","full":"quan trọng/không quan trọng → tầm quan trọng; trạng từ.","ex":"Accuracy is of great {importance}.","hint":"important/unimportant","k":"wf"},{"w":"introduce","vi":"giới thiệu","note":"introduce (v) → introduction (n), introductory (adj)","full":"giới thiệu → sự giới thiệu; nhập môn.","ex":"We attended an {introductory} course.","hint":"introduce","k":"wf"},{"w":"invent","vi":"phát minh","note":"invent (v) → inventor, invention (n)","full":"phát minh → nhà phát minh; phát minh.","ex":"The inventor demonstrated her {invention}.","hint":"invent","k":"wf"},{"w":"observe","vi":"quan sát","note":"observe (v) → observer, observation (n)","full":"quan sát → người quan sát; sự quan sát.","ex":"Careful {observation} is essential.","hint":"observe","k":"wf"},{"w":"possible/impossible","vi":"có thể/không thể","note":"possible/impossible (adj) → possibility/impossibility (n), possibly/impossibly (adv)","full":"có thể/không thể → khả năng/sự bất khả; trạng từ.","ex":"We investigated every {possibility}.","hint":"possible/impossible","k":"wf"},{"w":"psychology","vi":"tâm lí học","note":"psychology (n) → psychologist (n), psychological (adj), psychologically (adv)","full":"tâm lí học → nhà tâm lí; thuộc tâm lí.","ex":"The study examined {psychological} effects.","hint":"psychology","k":"wf"},{"w":"research","vi":"nghiên cứu","note":"research (n/v) → researcher (n)","full":"nghiên cứu → nhà nghiên cứu.","ex":"The researchers compared their findings.","hint":"research","k":"wf"},{"w":"revolution","vi":"cuộc cách mạng","note":"revolution (n) → revolutionary (adj/n)","full":"cuộc cách mạng → mang tính cách mạng/nhà cách mạng.","ex":"It was a {revolutionary} design.","hint":"revolution","k":"wf"},{"w":"science","vi":"khoa học","note":"science (n) → scientist (n), scientific/unscientific (adj), scientifically/unscientifically (adv)","full":"khoa học → nhà khoa học; có/thiếu tính khoa học.","ex":"The claim has not been {scientifically} tested.","hint":"science","k":"wf"},{"w":"technology","vi":"công nghệ; thuộc công nghệ/kĩ thuật; kĩ thuật viên; kĩ thuật/phương pháp.","note":"technology (n) → technological (adj), technologically (adv); technical (adj), technically (adv); technician, technique (n)","full":"công nghệ; thuộc công nghệ/kĩ thuật; kĩ thuật viên; kĩ thuật/phương pháp.","ex":"A {technician} checked the technical specifications.","hint":"technology","k":"wf"},{"w":"wood","vi":"gỗ","note":"wood (n) → wooden (adj)","full":"gỗ → bằng gỗ.","ex":"They built a {wooden} model.","hint":"wood","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"cause sth/sb to V","vi":"khiến điều gì/ai làm","ex":"Heat causes the metal {to} expand.","k":"pat"},{"w":"consider N/V-ing; consider if/whether; consider sb for sth; consider it + adj + for sb to V","vi":"cân nhắc; xem xét ai cho vị trí; cho rằng việc gì thế nào","ex":"We are considering buying a microscope.","k":"pat"},{"w":"discuss N/V-ing with sb","vi":"thảo luận với ai; không thêm about ngay sau discuss","ex":"We discussed changing the design {with} our teacher.","k":"pat"},{"w":"explain that; explain sth to sb","vi":"giải thích rằng/điều gì cho ai","ex":"She explained the method {to} us.","k":"pat"},{"w":"intend to V / V-ing","vi":"dự định làm","ex":"They intend {to} publish the results.","k":"pat"},{"w":"know about N/V-ing; know of sb; be known as","vi":"biết về; biết đến ai; được gọi là","ex":"This material is known as an insulator.","k":"pat"},{"w":"look at/for; look forward to N/V-ing","vi":"nhìn; tìm; mong đợi","ex":"We look forward to seeing your invention.","k":"pat"},{"w":"manage to V","vi":"xoay xở làm được","ex":"They managed {to} repair the engine.","k":"pat"},{"w":"plan sth / to V","vi":"lên kế hoạch cho việc gì/làm gì","ex":"We plan {to} carry out another test.","k":"pat"},{"w":"possible for sb to V; find sth possible; find it impossible to V","vi":"có thể làm; thấy điều gì khả thi/không thể làm","ex":"It is possible {for} students to use the lab after school.","k":"pat"},{"w":"result of N/V-ing; result in N/(sb's) V-ing; result from; as a result of","vi":"kết quả của; dẫn đến; bắt nguồn từ; do","ex":"The fault resulted in the machine stopping.","k":"pat"},{"w":"wonder about N/V-ing; wonder if/whether/why","vi":"tự hỏi, băn khoăn","ex":"I wonder whether the new method will work.","k":"pat"}]}]},{"g":2,"u":8,"title":"The Media","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"deny","pos":"v","vi":"phủ nhận điều đã xảy ra","ex":"He {denied} leaking the story and refused to comment.","grp":["deny","refuse"],"k":"topic"},{"w":"refuse","pos":"v","vi":"từ chối làm/nhận","ex":"He denied leaking the story and {refused} to comment.","grp":["deny","refuse"],"k":"topic"},{"w":"agree","pos":"v","vi":"đồng ý quan điểm/đề nghị","ex":"She {agreed} with the editor and accepted the invitation.","grp":["agree","accept"],"k":"topic"},{"w":"accept","pos":"v","vi":"chấp nhận, nhận","ex":"She agreed with the editor and {accepted} the invitation.","grp":["agree","accept"],"k":"topic"},{"w":"headline","pos":"n","vi":"tít báo","ex":"The {headline} attracted me, but one section heading was unclear.","grp":["headline","heading"],"k":"topic"},{"w":"heading","pos":"n","vi":"tiêu đề mục/phần","ex":"The headline attracted me, but one section {heading} was unclear.","grp":["headline","heading"],"k":"topic"},{"w":"feature","pos":"n","vi":"bài chuyên đề","ex":"The article is part of a {feature} on local schools.","grp":["feature","article"],"k":"topic"},{"w":"article","pos":"n","vi":"bài báo nói chung","ex":"The {article} is part of a feature on local schools.","grp":["feature","article"],"k":"topic"},{"w":"talk show","pos":"n","vi":"chương trình trò chuyện","ex":"The channel shows a {talk show} after the quiz show.","grp":["talk show","quiz show","game show"],"k":"topic"},{"w":"quiz show","pos":"n","vi":"thi kiến thức","ex":"The channel shows a talk show after the {quiz show}.","grp":["talk show","quiz show","game show"],"k":"topic"},{"w":"game show","pos":"n","vi":"trò chơi truyền hình","ex":"The channel shows a talk {show} after the quiz show.","grp":["talk show","quiz show","game show"],"k":"topic"},{"w":"announcer","pos":"n","vi":"người xướng/thông báo","ex":"The {announcer} introduced the event; the commentator described the action.","grp":["announcer","commentator"],"k":"topic"},{"w":"commentator","pos":"n","vi":"bình luận viên","ex":"The announcer introduced the event; the {commentator} described the action.","grp":["announcer","commentator"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"tabloid","pos":"n","vi":"báo khổ nhỏ, thường thiên tin giật gân","ex":"The {tabloid} and the broadsheet covered the story differently.","grp":["tabloid","broadsheet"],"k":"topic"},{"w":"broadsheet","pos":"n","vi":"báo khổ lớn, thường thiên phân tích","ex":"The tabloid and the {broadsheet} covered the story differently.","grp":["tabloid","broadsheet"],"k":"topic"},{"w":"journalist","pos":"n","vi":"nhà báo","ex":"The {journalist} later became a political columnist.","grp":["journalist","columnist"],"k":"topic"},{"w":"columnist","pos":"n","vi":"người viết chuyên mục định kì","ex":"The journalist later became a political {columnist}.","grp":["journalist","columnist"],"k":"topic"},{"w":"press","pos":"n","vi":"báo chí/giới báo","ex":"The {press} conference attracted representatives of several media organisations.","grp":["press","media"],"k":"topic"},{"w":"media","pos":"n","vi":"các phương tiện truyền thông","ex":"The press conference attracted representatives of several {media} organisations.","grp":["press","media"],"k":"topic"},{"w":"programme","pos":"n","vi":"chương trình phát sóng (Anh Anh)","ex":"We used a computer program to edit the television {programme}.","grp":["programme","program"],"k":"topic"},{"w":"program","pos":"n","vi":"chương trình máy tính. Anh Mỹ thường dùng program cho cả hai","ex":"We used a computer {program} to edit the television programme.","grp":["programme","program"],"k":"topic"},{"w":"channel","pos":"n/v","vi":"kênh","ex":"The {channel} will broadcast the debate live.","grp":["channel","broadcast"],"k":"topic"},{"w":"broadcast","pos":"n/v","vi":"buổi phát sóng/phát sóng","ex":"The channel will {broadcast} the debate live.","grp":["channel","broadcast"],"k":"topic"},{"w":"bulletin","pos":"n","vi":"bản tin","ex":"A newsflash interrupted the programme before the evening {bulletin}.","grp":["bulletin","newsflash"],"k":"topic"},{"w":"newsflash","pos":"n","vi":"tin ngắn đột xuất/ngắt chương trình","ex":"A {newsflash} interrupted the programme before the evening bulletin.","grp":["bulletin","newsflash"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"bring up","vi":"đề cập chủ đề","ex":"Do not bring {up} the rumour during the interview.","k":"pv"},{"w":"come on","vi":"được phát sóng, bắt đầu chiếu","ex":"The news comes {on} at six.","k":"pv"},{"w":"come out","vi":"được xuất bản/phát hành","ex":"The magazine comes {out} every Friday.","k":"pv"},{"w":"fill in","vi":"điền thông tin","ex":"Please fill {in} this form.","k":"pv"},{"w":"flick through","vi":"lật/xem lướt","ex":"I flicked {through} the newspaper.","k":"pv"},{"w":"go into","vi":"đề cập, phân tích chi tiết","ex":"The report goes {into} the causes of the accident.","k":"pv"},{"w":"hand out","vi":"phát cho từng người","ex":"They handed {out} free newspapers.","k":"pv"},{"w":"look up","vi":"tra cứu","ex":"Look {up} the unfamiliar term.","k":"pv"},{"w":"make out","vi":"giả vờ/khẳng định; nhìn/nghe/đọc ra khó khăn","ex":"I could not make {out} the words on the screen.","k":"pv"},{"w":"make up","vi":"bịa ra; tạo thành","ex":"The journalist did not make {up} the quotation.","k":"pv"},{"w":"put forward","vi":"đưa ra ý tưởng/đề xuất","ex":"She put {forward} a different explanation.","k":"pv"},{"w":"see through","vi":"nhìn thấu trò lừa","ex":"Readers soon saw {through} the false story.","k":"pv"},{"w":"stand out","vi":"nổi bật","ex":"The red headline stands {out}.","k":"pv"},{"w":"turn over","vi":"lật trang; chuyển kênh","ex":"Turn {over} the page to read the interview.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"control","vi":"kiểm soát/được kiểm soát/mất kiểm soát","ex":"The producer took {control} of the broadcast.","note":"in control; take control of; under control; under the control of; out of control","k":"col"},{"w":"description","vi":"mô tả","ex":"The witness gave a {description} of the vehicle.","note":"give a description of","k":"col"},{"w":"difference","vi":"tạo ảnh hưởng; phân biệt; có khác biệt","ex":"Can you tell the {difference} between fact and opinion?","note":"make a difference to; tell the difference between; there is a difference","k":"col"},{"w":"granted","vi":"coi là hiển nhiên, không biết trân trọng","ex":"Do not take reliable information for {granted}.","note":"take sb/sth for granted","k":"col"},{"w":"influence","vi":"ảnh hưởng đến","ex":"Online reviews have an {influence} on buyers.","note":"influence sb/sth; have/be an influence on","k":"col"},{"w":"Internet","vi":"trên/qua mạng; lướt mạng","ex":"They watched the interview over the {Internet}.","note":"on/over the Internet; surf the Internet","k":"col"},{"w":"news","vi":"thành tin; trên bản tin; nghe tin","ex":"I heard the {news} on the radio.","note":"in the news; on the news; hear the news; newsflash; newspaper","k":"col"},{"w":"place","vi":"diễn ra; thay cho; tại một nơi","ex":"The interview took {place} at the studio.","note":"take place; in place of; at a place","k":"col"},{"w":"question","vi":"hỏi/đáp; chất vấn; đang được nói tới; dấu hỏi","ex":"The article in {question} appeared yesterday.","note":"ask/answer a question; question sb/sth; in question; question mark","k":"col"},{"w":"view","vi":"quan điểm; xét đến; cảnh nhìn","ex":"In my {view}, the report is fair. In view of the evidence, we should wait.","note":"have/hold/take a view; be sb's view that; in my view; in view of; look at/see the view; a view of/from","k":"col"},{"w":"watch","vi":"xem; đề phòng; canh chừng","ex":"{Watch} out for misleading headlines.","note":"watch sth; watch out for; keep watch","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"announce","vi":"thông báo","note":"announce (v) → announcement (n), announced/unannounced (adj)","full":"thông báo → thông báo; được/chưa báo trước.","ex":"The {announcement} was unexpected.","hint":"announce","k":"wf"},{"w":"belief/disbelief","vi":"niềm tin/hoài nghi","note":"belief/disbelief (n) → believe (v), believable/unbelievable (adj), believably/unbelievably (adv)","full":"niềm tin/hoài nghi → tin; đáng tin/khó tin.","ex":"The witness gave a {believable} account.","hint":"belief/disbelief","k":"wf"},{"w":"communicate","vi":"giao tiếp","note":"communicate (v) → communication, communicator (n), communicative/uncommunicative (adj)","full":"giao tiếp → sự giao tiếp; người truyền đạt; cởi mở/ít nói.","ex":"She is an effective {communicator}.","hint":"communicate","k":"wf"},{"w":"convince","vi":"thuyết phục","note":"convince (v) → convinced (adj), convincing/unconvincing (adj)","full":"thuyết phục → tin chắc; có/thiếu sức thuyết phục.","ex":"The explanation was {unconvincing}.","hint":"convince","k":"wf"},{"w":"discuss","vi":"thảo luận","note":"discuss (v) → discussion (n)","full":"thảo luận → cuộc thảo luận.","ex":"The {discussion} lasted an hour.","hint":"discuss","k":"wf"},{"w":"edit","vi":"biên tập","note":"edit (v) → editor (n), editorial (adj/n), edited (V3/adj)","full":"biên tập → biên tập viên; thuộc biên tập/bài xã luận.","ex":"The {editor} approved the article.","hint":"edit","k":"wf"},{"w":"humour","vi":"sự hài hước","note":"humour (n) → humorous, humourless (adj)","full":"sự hài hước → hài hước; thiếu hài hước.","ex":"The column has a {humorous} style.","hint":"humour","k":"wf"},{"w":"inform","vi":"thông báo","note":"inform (v) → information (n), informed/uninformed, informative/uninformative (adj)","full":"thông báo → thông tin; hiểu/thiếu hiểu biết; nhiều/ít thông tin hữu ích.","ex":"It was an {informative} interview.","hint":"inform","k":"wf"},{"w":"journal","vi":"tạp chí","note":"journal (n) → journalist, journalism (n), journalistic (adj)","full":"tạp chí → nhà báo; nghề báo; thuộc báo chí.","ex":"She studies {journalism}.","hint":"journal","k":"wf"},{"w":"politics","vi":"chính trị","note":"politics (n) → political (adj), politically (adv), politician (n)","full":"chính trị → thuộc chính trị; chính trị gia.","ex":"The journalist interviewed a {politician}.","hint":"politics","k":"wf"},{"w":"power","vi":"quyền lực","note":"power (n/v) → powerful/powerless (adj), powerfully/powerlessly (adv), empower (v)","full":"quyền lực → mạnh/bất lực; trao quyền.","ex":"The article had a {powerful} impact.","hint":"power","k":"wf"},{"w":"ridicule","vi":"chế giễu","note":"ridicule (n/v) → ridiculous (adj), ridiculously (adv), ridiculousness (n)","full":"chế giễu → nực cười; sự nực cười.","ex":"The rumour was completely {ridiculous}.","hint":"ridicule","k":"wf"},{"w":"second","vi":"thứ hai","note":"second (n/adj) → secondly (adv), secondary (adj)","full":"thứ hai → thứ hai là; thứ yếu/trung học.","ex":"{Secondly}, we need a more reliable source.","hint":"second","k":"wf"},{"w":"write","vi":"viết","note":"write (v) → writer, writing (n), wrote (V2), written/unwritten (V3/adj)","full":"viết → người viết; bài/việc viết; đã viết; thành văn/bất thành văn.","ex":"There is an {unwritten} rule about protecting sources.","hint":"write","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"according to","vi":"theo nguồn/người nào; thường không dùng according to me để nêu ý kiến bản thân","ex":"According {to} the report, sales have fallen.","k":"pat"},{"w":"announce sth to sb; announce that","vi":"thông báo điều gì cho ai/rằng","ex":"They announced the result {to} the press.","k":"pat"},{"w":"believe N/that; believe in; be believed to be","vi":"tin điều gì; tin vào sự tồn tại/giá trị; được cho là","ex":"The painting is believed to be genuine.","k":"pat"},{"w":"comment on; make a comment to sb about","vi":"bình luận về","ex":"The editor refused to comment {on} the case.","k":"pat"},{"w":"confuse A with B; confused about/by","vi":"nhầm A với B; bối rối về/bởi","ex":"Do not confuse the headline {with} the heading.","k":"pat"},{"w":"correspond with","vi":"trao đổi thư từ với","ex":"She corresponds {with} readers regularly.","k":"pat"},{"w":"describe sb/sth as; describe sth to sb","vi":"miêu tả là; mô tả cho ai","ex":"He described the event to the reporter.","k":"pat"},{"w":"hear sth; hear about; hear from","vi":"nghe; nghe nói về; nhận tin từ","ex":"Have you heard from the editor?","k":"pat"},{"w":"inform sb that/about/of","vi":"thông báo cho ai rằng/về","ex":"They informed us of the change.","k":"pat"},{"w":"likely to V; likely that","vi":"có khả năng xảy ra","ex":"The programme is likely {to} attract many viewers.","k":"pat"},{"w":"persuade sb to V/that/of","vi":"thuyết phục ai làm/tin","ex":"She persuaded him {to} give an interview.","k":"pat"},{"w":"point in V-ing","vi":"ích/lí do của việc làm","ex":"There is no point {in} repeating an unverified rumour.","k":"pat"},{"w":"send sb sth; send sth to sb","vi":"gửi ai thứ gì","ex":"Send the photograph {to} the editor.","k":"pat"},{"w":"take sb by surprise; surprised at/by","vi":"làm ai ngạc nhiên; ngạc nhiên về/bởi","ex":"The announcement took everyone {by} surprise.","k":"pat"},{"w":"tell sb sth/that/about; tell sb (not) to V","vi":"nói/kể/bảo ai làm hoặc không làm","ex":"The director told us not to reveal the ending.","k":"pat"}]}]},{"g":2,"u":10,"title":"People and Society","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"relationship","pos":"n","vi":"mối quan hệ","ex":"Their family {relationship} explains the connection between the two businesses.","grp":["relationship","connection"],"k":"topic"},{"w":"connection","pos":"n","vi":"sự liên kết/mối liên hệ","ex":"Their family relationship explains the {connection} between the two businesses.","grp":["relationship","connection"],"k":"topic"},{"w":"blame","pos":"n","vi":"sự quy trách nhiệm","ex":"The mistake was my fault, so I accepted the {blame}.","grp":["blame","fault"],"k":"topic"},{"w":"fault","pos":"n","vi":"lỗi/trách nhiệm gây lỗi","ex":"The mistake was my {fault}, so I accepted the blame.","grp":["blame","fault"],"k":"topic"},{"w":"old","pos":"adj","vi":"cũ/già","ex":"An {old} house stands beside an ancient temple.","grp":["old","ancient"],"k":"topic"},{"w":"ancient","pos":"adj","vi":"cổ đại, rất lâu đời","ex":"An old house stands beside an {ancient} temple.","grp":["old","ancient"],"k":"topic"},{"w":"crowd","pos":"n","vi":"đám đông","ex":"A {crowd} gathered outside while the audience waited inside.","grp":["crowd","audience"],"k":"topic"},{"w":"audience","pos":"n","vi":"khán giả/người nghe","ex":"A crowd gathered outside while the {audience} waited inside.","grp":["crowd","audience"],"k":"topic"},{"w":"enjoy","pos":"v","vi":"thích/trải nghiệm vui","ex":"The children {enjoyed} the show, which pleased their parents.","grp":["enjoy","please"],"k":"topic"},{"w":"please","pos":"v","vi":"làm hài lòng","ex":"The children enjoyed the show, which {pleased} their parents.","grp":["enjoy","please"],"k":"topic"},{"w":"support","pos":"v","vi":"ủng hộ/hỗ trợ duy trì","ex":"Her family {supported} her decision and assisted her with the move.","grp":["support","assist"],"k":"topic"},{"w":"assist","pos":"v","vi":"giúp thực hiện việc","ex":"Her family supported her decision and {assisted} her with the move.","grp":["support","assist"],"k":"topic"},{"w":"kind","pos":"adj","vi":"tốt bụng","ex":"It was {kind} of him to help and polite of him to ask first.","grp":["kind","polite"],"k":"topic"},{"w":"polite","pos":"adj","vi":"lịch sự","ex":"It was kind of him to help and {polite} of him to ask first.","grp":["kind","polite"],"k":"topic"},{"w":"sympathetic","pos":"adj","vi":"cảm thông","ex":"The new teacher is likeable and {sympathetic} to our difficulties.","grp":["sympathetic","likeable"],"k":"topic"},{"w":"likeable","pos":"adj","vi":"dễ mến","ex":"The new teacher is {likeable} and sympathetic to our difficulties.","grp":["sympathetic","likeable"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"nervous","pos":"adj","vi":"lo lắng","ex":"She was {nervous} before the interview, not bad-tempered.","grp":["nervous","bad-tempered"],"k":"topic"},{"w":"bad-tempered","pos":"adj","vi":"cáu kỉnh","ex":"She was nervous before the interview, not {bad-tempered}.","grp":["nervous","bad-tempered"],"k":"topic"},{"w":"sensitive","pos":"adj","vi":"nhạy cảm","ex":"Be {sensitive} to her feelings and offer sensible advice.","grp":["sensitive","sensible"],"k":"topic"},{"w":"sensible","pos":"adj","vi":"có lí trí, hợp lí","ex":"Be sensitive to her feelings and offer {sensible} advice.","grp":["sensitive","sensible"],"k":"topic"},{"w":"company","pos":"n","vi":"sự bầu bạn/công ty","ex":"I enjoy her {company} when our group travels together.","grp":["company","group"],"k":"topic"},{"w":"group","pos":"n","vi":"nhóm","ex":"I enjoy her company when our {group} travels together.","grp":["company","group"],"k":"topic"},{"w":"popular","pos":"adj","vi":"được yêu thích","ex":"A famous actor is not necessarily {popular} with everyone.","grp":["popular","famous"],"k":"topic"},{"w":"famous","pos":"adj","vi":"nổi tiếng","ex":"A {famous} actor is not necessarily popular with everyone.","grp":["popular","famous"],"k":"topic"},{"w":"typical","pos":"adj","vi":"điển hình","ex":"It was an ordinary day, with the usual traffic and {typical} summer heat.","grp":["typical","usual","ordinary"],"k":"topic"},{"w":"usual","pos":"adj","vi":"thường lệ","ex":"It was an ordinary day, with the {usual} traffic and typical summer heat.","grp":["typical","usual","ordinary"],"k":"topic"},{"w":"ordinary","pos":"adj","vi":"bình thường, không đặc biệt","ex":"It was an {ordinary} day, with the usual traffic and typical summer heat.","grp":["typical","usual","ordinary"],"k":"topic"},{"w":"close","pos":"adj/adv","vi":"gần, thân thiết","ex":"Her {closest} friend lives near the school.","grp":["close","near"],"k":"topic"},{"w":"near","pos":"adj/adv","vi":"gần về vị trí/thời gian","ex":"Her closest friend lives {near} the school.","grp":["close","near"],"k":"topic"},{"w":"unknown","pos":"adj","vi":"không được biết đến","ex":"The previously {unknown} businessman became infamous after the scandal.","grp":["unknown","infamous"],"k":"topic"},{"w":"infamous","pos":"adj","vi":"nổi tiếng xấu","ex":"The previously unknown businessman became {infamous} after the scandal.","grp":["unknown","infamous"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"ask after","vi":"hỏi thăm sức khỏe/tình hình","ex":"Your aunt asked {after} you.","k":"pv"},{"w":"bring up","vi":"nuôi dạy","ex":"Her grandparents brought her {up}.","k":"pv"},{"w":"fall for","vi":"phải lòng; bị lừa tin","ex":"He fell for her smile but did not fall {for} her joke.","k":"pv"},{"w":"fall out with","vi":"cãi nhau, bất hòa với","ex":"I fell out {with} my cousin over money.","k":"pv"},{"w":"get on with","vi":"hòa thuận với","ex":"She gets on well {with} her neighbours.","k":"pv"},{"w":"grow up","vi":"lớn lên","ex":"He grew {up} in a small town.","k":"pv"},{"w":"look down on","vi":"coi thường","ex":"Never look down {on} people because of their jobs.","k":"pv"},{"w":"look up to","vi":"ngưỡng mộ, kính trọng","ex":"The pupils look up {to} their teacher.","k":"pv"},{"w":"make up","vi":"làm hòa","ex":"They argued yesterday but have made {up} now.","k":"pv"},{"w":"pass away","vi":"qua đời","ex":"Her grandfather passed {away} peacefully.","k":"pv"},{"w":"pick on","vi":"bắt nạt, nhắm vào để chê trách","ex":"The older boys kept picking {on} him.","k":"pv"},{"w":"put down","vi":"hạ thấp, chê bai","ex":"Do not put yourself {down} all the time.","k":"pv"},{"w":"settle down","vi":"bình tĩnh lại; sống ổn định, thường sau khi lập gia đình","ex":"After years abroad, they settled {down} in Hue.","k":"pv"},{"w":"stand up for","vi":"bảo vệ, lên tiếng bênh vực","ex":"She stood up {for} her friend.","k":"pv"},{"w":"take aback","vi":"làm sửng sốt, thường ở bị động be taken aback","ex":"I was taken aback by his kindness.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"approval","vi":"tán thành; được tán thành","ex":"The proposal met with their {approval}.","note":"show/give approval of/for; meet with approval","k":"col"},{"w":"argument","vi":"tranh cãi với ai về việc gì; thắng/thua lí lẽ","ex":"They had an {argument} about the timetable.","note":"have an argument with sb about sth; win/lose an argument","k":"col"},{"w":"care","vi":"chăm sóc; chăm sóc/thích; quan tâm","ex":"She takes {care} of her brother and cares about his education.","note":"take care of; care for/about","k":"col"},{"w":"courage","vi":"có/cần can đảm","ex":"It takes {courage} to admit a mistake.","note":"have the courage to V; it takes courage to V","k":"col"},{"w":"disguise","vi":"cải trang; đóng giả","ex":"The actor arrived {disguised} as a waiter.","note":"in disguise; wear a disguise; disguise yourself; disguised as","k":"col"},{"w":"dream","vi":"có giấc mơ; mơ mộng; ước mơ","ex":"She {dreams} of becoming a doctor.","note":"have a dream; daydream; dream of/about V-ing","k":"col"},{"w":"family","vi":"có/lập gia đình; gia đình hạt nhân/mở rộng","ex":"Three generations live in their extended {family}.","note":"have/start a family; nuclear/extended family","k":"col"},{"w":"favour","vi":"giúp/nợ ân huệ; ủng hộ","ex":"Could you do me a {favour}? I am in favour of the plan.","note":"do/owe sb a favour; in favour of","k":"col"},{"w":"friend","vi":"kết bạn/trở thành/tiếp tục là bạn; bạn thân nhất","ex":"They stayed {friends} after leaving school.","note":"make/become/be/stay friends; best friend","k":"col"},{"w":"love","vi":"yêu/phải lòng","ex":"They fell in {love} at university.","note":"be/fall in love with","k":"col"},{"w":"mood","vi":"có tâm trạng tốt/xấu; đúng/không đúng tâm trạng; có hứng","ex":"I am in the {mood} for a quiet evening.","note":"in a good/bad mood; in the right/wrong mood; in the mood for","k":"col"},{"w":"pity","vi":"thương hại; đáng tiếc rằng","ex":"It is a {pity} that she cannot join us.","note":"pity sb; take pity on; feel pity for; it is a pity that","k":"col"},{"w":"promise","vi":"hứa; đưa lời hứa; thất hứa","ex":"He {promised} to help and kept his promise.","note":"promise to V; give/make a promise; break a promise","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"able/unable","vi":"có/không có khả năng; năng lực/sự bất lực; khuyết tật; bị khuyết tật.","note":"able/unable (adj) → ability/inability, disability (n), disabled (adj)","full":"có/không có khả năng; năng lực/sự bất lực; khuyết tật; bị khuyết tật.","ex":"The building has access for {disabled} visitors.","hint":"able/unable","k":"wf"},{"w":"achieve","vi":"đạt được","note":"achieve (v) → achievement (n)","full":"đạt được → thành tựu.","ex":"Winning her trust was a real {achievement}.","hint":"achieve","k":"wf"},{"w":"argue","vi":"tranh cãi","note":"argue (v) → argument (n), argumentative (adj)","full":"tranh cãi → cuộc tranh cãi; hay cãi.","ex":"He can be {argumentative} when tired.","hint":"argue","k":"wf"},{"w":"care","vi":"quan tâm","note":"care (n/v) → careful/careless, caring/uncaring (adj), carefully/carelessly (adv)","full":"quan tâm → cẩn thận/bất cẩn; chu đáo/thờ ơ.","ex":"She is a {caring} friend.","hint":"care","k":"wf"},{"w":"correspond","vi":"trao đổi thư từ/tương ứng","note":"correspond (v) → correspondence (n)","full":"trao đổi thư từ/tương ứng → thư từ/sự tương ứng.","ex":"Their {correspondence} continued for years.","hint":"correspond","k":"wf"},{"w":"friend","vi":"bạn","note":"friend (n) → friendship (n), friendly/unfriendly (adj)","full":"bạn → tình bạn; thân thiện/không thân thiện.","ex":"Their {friendship} is important to both of them.","hint":"friend","k":"wf"},{"w":"happy/unhappy","vi":"vui/buồn","note":"happy/unhappy (adj) → happiness/unhappiness (n), happily/unhappily (adv)","full":"vui/buồn → hạnh phúc/bất hạnh; trạng từ.","ex":"They lived {happily} together.","hint":"happy/unhappy","k":"wf"},{"w":"jealous","vi":"ghen tị","note":"jealous (adj) → jealousy (n), jealously (adv)","full":"ghen tị → sự ghen tị; một cách ghen tị.","ex":"{Jealousy} damaged their friendship.","hint":"jealous","k":"wf"},{"w":"kind/unkind","vi":"tốt bụng/không tốt","note":"kind/unkind (adj) → kindness/unkindness (n), kindly (adv)","full":"tốt bụng/không tốt → lòng tốt/sự thiếu tử tế; tử tế.","ex":"Thank you for your {kindness}.","hint":"kind/unkind","k":"wf"},{"w":"marry","vi":"kết hôn","note":"marry (v) → marriage (n), married/unmarried (adj)","full":"kết hôn → hôn nhân; đã/chưa kết hôn.","ex":"Their {marriage} lasted fifty years.","hint":"marry","k":"wf"},{"w":"nerve","vi":"dây thần kinh/sự can đảm","note":"nerve (n) → nervous (adj), nervously (adv), nervousness (n)","full":"dây thần kinh/sự can đảm → lo lắng; sự lo lắng.","ex":"She smiled {nervously}.","hint":"nerve","k":"wf"},{"w":"obey/disobey","vi":"vâng/không vâng lời; ngoan/không ngoan; sự tuân lời/chống lệnh.","note":"obey/disobey (v) → obedient/disobedient (adj), obediently/disobediently (adv), obedience/disobedience (n)","full":"vâng/không vâng lời; ngoan/không ngoan; sự tuân lời/chống lệnh.","ex":"The child obeyed willingly.","hint":"obey/disobey","k":"wf"},{"w":"person","vi":"người","note":"person (n) → personal/impersonal (adj), personally/impersonally (adv), personality (n)","full":"người → cá nhân/không mang tính cá nhân; tính cách.","ex":"Her warm {personality} makes people comfortable.","hint":"person","k":"wf"},{"w":"polite/impolite","vi":"lịch sự/bất lịch sự; sự lịch sự/bất lịch sự.","note":"polite/impolite (adj) → politely/impolitely (adv), politeness/impoliteness (n)","full":"lịch sự/bất lịch sự; sự lịch sự/bất lịch sự.","ex":"He answered {politely}.","hint":"polite/impolite","k":"wf"},{"w":"relate","vi":"liên quan","note":"relate (v) → relative (n/adj), relatively (adv), relation, relationship (n)","full":"liên quan → họ hàng/tương đối; khá; quan hệ.","ex":"The two families are related.","hint":"relate","k":"wf"},{"w":"willing/unwilling","vi":"sẵn lòng/miễn cưỡng; sự sẵn lòng/không sẵn lòng.","note":"willing/unwilling (adj) → willingness/unwillingness (n), willingly/unwillingly (adv)","full":"sẵn lòng/miễn cưỡng; sự sẵn lòng/không sẵn lòng.","ex":"She {willingly} offered her help.","hint":"willing/unwilling","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"agree with/on/to; agree to V; agree that","vi":"đồng ý với người/quan điểm; thống nhất về; chấp thuận; đồng ý làm/rằng","ex":"We agreed on a date, and she agreed to come.","k":"pat"},{"w":"allow sb to V; allow sth","vi":"cho phép ai làm/cho phép điều gì","ex":"They allow visitors {to} stay until eight.","k":"pat"},{"w":"approve of N/V-ing; approve sth","vi":"tán thành; phê duyệt chính thức","ex":"Her parents approve {of} her choice; the council approved the plan.","k":"pat"},{"w":"ask sb sth/to V; ask about/for; ask if/whether","vi":"hỏi; nhờ; hỏi về/xin; hỏi liệu","ex":"She asked me {to} help and asked for advice.","k":"pat"},{"w":"attack sb/sth; attack sb for; an attack on","vi":"tấn công; chỉ trích vì; cuộc tấn công vào","ex":"The article attacked him {for} his remarks.","k":"pat"},{"w":"ban sb from N/V-ing; ban sth","vi":"cấm ai tham gia/làm; cấm điều gì","ex":"He was banned {from} entering the stadium.","k":"pat"},{"w":"convince sb of/to V/that","vi":"thuyết phục ai tin/làm/rằng","ex":"They convinced me that the plan was safe.","k":"pat"},{"w":"force sb to V / into N/V-ing","vi":"ép ai làm/tham gia","ex":"Nobody can force you {to} agree.","k":"pat"},{"w":"independent of/from","vi":"độc lập, không phụ thuộc","ex":"She is financially independent {of} her parents.","k":"pat"},{"w":"let sb V","vi":"để/cho ai làm; không thêm to","ex":"They let us leave early.","k":"pat"},{"w":"object to N/V-ing","vi":"phản đối; to là giới từ","ex":"I object {to} being treated unfairly.","k":"pat"},{"w":"pretend to be/to V/that","vi":"giả vờ là/làm/rằng","ex":"He pretended {to} be asleep.","k":"pat"},{"w":"rely on sb/sth","vi":"dựa vào, tin cậy","ex":"You can rely {on} her support.","k":"pat"}]}]},{"g":2,"u":12,"title":"The Law and Crime","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"proof","pos":"n","vi":"bằng chứng đủ xác lập sự thật","ex":"The evidence was strong but was not {proof} of his guilt.","grp":["proof","evidence"],"k":"topic"},{"w":"evidence","pos":"n","vi":"chứng cứ/thông tin làm căn cứ; thường không đếm được","ex":"The {evidence} was strong but was not proof of his guilt.","grp":["proof","evidence"],"k":"topic"},{"w":"suspect","pos":"v","vi":"nghi ngờ","ex":"Police {suspected} him, arrested him and charged him with theft.","grp":["suspect","arrest","charge"],"k":"topic"},{"w":"arrest","pos":"v","vi":"bắt giữ","ex":"Police suspected him, {arrested} him and charged him with theft.","grp":["suspect","arrest","charge"],"k":"topic"},{"w":"charge","pos":"v","vi":"buộc tội chính thức","ex":"Police suspected him, arrested him and {charged} him with theft.","grp":["suspect","arrest","charge"],"k":"topic"},{"w":"suspect","pos":"n","vi":"người bị tình nghi","ex":"The {suspect} was questioned; the accused later appeared in court.","grp":["suspect","accused"],"k":"topic"},{"w":"accused","pos":"n","vi":"bị cáo/người bị buộc tội","ex":"The suspect was questioned; the {accused} later appeared in court.","grp":["suspect","accused"],"k":"topic"},{"w":"decision","pos":"n","vi":"quyết định","ex":"The jury's {decision} was a verdict of not guilty.","grp":["decision","verdict"],"k":"topic"},{"w":"verdict","pos":"n","vi":"phán quyết có/không có tội của bồi thẩm đoàn/tòa","ex":"The jury's decision was a {verdict} of not guilty.","grp":["decision","verdict"],"k":"topic"},{"w":"commit","pos":"v","vi":"phạm tội/hành vi sai","ex":"Anyone who {commits} theft breaks the law.","grp":["commit","break"],"k":"topic"},{"w":"break","pos":"v","vi":"vi phạm luật/quy tắc","ex":"Anyone who commits theft {breaks} the law.","grp":["commit","break"],"k":"topic"},{"w":"rule","pos":"n","vi":"quy tắc","ex":"The law protects your rights and promotes justice.","grp":["rule","law","justice","right"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"law","pos":"n","vi":"luật","ex":"The {law} protects your rights and promotes justice.","grp":["rule","law","justice","right"],"k":"topic"},{"w":"justice","pos":"n","vi":"công lí","ex":"The law protects your rights and promotes {justice}.","grp":["rule","law","justice","right"],"k":"topic"},{"w":"right","pos":"n","vi":"quyền","ex":"The law protects your {rights} and promotes justice.","grp":["rule","law","justice","right"],"k":"topic"},{"w":"judge","pos":"n","vi":"thẩm phán","ex":"The jury reached a verdict, and the {judge} passed sentence.","grp":["judge","jury"],"k":"topic"},{"w":"jury","pos":"n","vi":"bồi thẩm đoàn","ex":"The {jury} reached a verdict, and the judge passed sentence.","grp":["judge","jury"],"k":"topic"},{"w":"prosecute","pos":"v","vi":"truy tố","ex":"They {prosecuted} the official who had persecuted local families.","grp":["prosecute","persecute"],"k":"topic"},{"w":"persecute","pos":"v","vi":"đàn áp/ngược đãi lâu dài","ex":"They prosecuted the official who had {persecuted} local families.","grp":["prosecute","persecute"],"k":"topic"},{"w":"capital punishment","pos":"n","vi":"án tử hình","ex":"The debate covered both capital and corporal {punishment}.","grp":["capital punishment","corporal punishment"],"k":"topic"},{"w":"corporal punishment","pos":"n","vi":"hình phạt lên thân thể","ex":"The debate covered both capital and {corporal punishment}.","grp":["capital punishment","corporal punishment"],"k":"topic"},{"w":"robber","pos":"n","vi":"kẻ cướp, thường dùng đe dọa","ex":"The burglar entered through a window; the {robber} threatened the cashier.","grp":["robber","burglar","thief"],"k":"topic"},{"w":"burglar","pos":"n","vi":"kẻ đột nhập trộm","ex":"The {burglar} entered through a window; the robber threatened the cashier.","grp":["robber","burglar","thief"],"k":"topic"},{"w":"thief","pos":"n","vi":"kẻ trộm nói chung","ex":"The burglar entered through a window; the robber threatened the cashier.","grp":["robber","burglar","thief"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"vandal","pos":"n","vi":"kẻ phá hoại tài sản","ex":"{Vandals} damaged the shelter after the hooligans left.","grp":["vandal","hooligan"],"k":"topic"},{"w":"hooligan","pos":"n","vi":"kẻ côn đồ gây rối","ex":"Vandals damaged the shelter after the {hooligans} left.","grp":["vandal","hooligan"],"k":"topic"},{"w":"sentence","pos":"v","vi":"tuyên án","ex":"The judge {sentenced} him to two years, and he was imprisoned.","grp":["sentence","imprison"],"k":"topic"},{"w":"imprison","pos":"v","vi":"bỏ tù","ex":"The judge sentenced him to two years, and he was {imprisoned}.","grp":["sentence","imprison"],"k":"topic"},{"w":"innocent","pos":"adj","vi":"vô tội","ex":"The court found one defendant guilty and the other {innocent}.","grp":["innocent","guilty"],"k":"topic"},{"w":"guilty","pos":"adj","vi":"có tội","ex":"The court found one defendant {guilty} and the other innocent.","grp":["innocent","guilty"],"k":"topic"},{"w":"witness","pos":"n","vi":"người chứng kiến/cung cấp lời khai","ex":"A bystander became a key {witness}.","grp":["witness","bystander"],"k":"topic"},{"w":"bystander","pos":"n","vi":"người có mặt nhưng không tham gia","ex":"A {bystander} became a key witness.","grp":["witness","bystander"],"k":"topic"},{"w":"lawyer","pos":"n","vi":"người hành nghề luật","ex":"She consulted a solicitor for legal advice.","grp":["lawyer","solicitor"],"k":"topic"},{"w":"solicitor","pos":"n","vi":"luật sư tư vấn/xử lí công việc pháp lí, nhất là tại Anh","ex":"She consulted a {solicitor} for legal advice.","grp":["lawyer","solicitor"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"back down","vi":"nhượng bộ, rút lại yêu cầu/lập trường","ex":"He refused to back {down}.","k":"pv"},{"w":"break out","vi":"vượt ngục","ex":"Two prisoners broke {out} last night.","k":"pv"},{"w":"bring in","vi":"ban hành/áp dụng luật","ex":"The government brought {in} new safety laws.","k":"pv"},{"w":"chase after","vi":"đuổi theo","ex":"The guard chased {after} the thief.","k":"pv"},{"w":"come forward","vi":"đứng ra cung cấp thông tin/giúp đỡ","ex":"Several witnesses came {forward}.","k":"pv"},{"w":"get away with","vi":"làm sai mà không bị phạt","ex":"You cannot get away {with} cheating forever.","k":"pv"},{"w":"go off","vi":"nổ; súng khai hỏa","ex":"A gun went {off} outside.","k":"pv"},{"w":"hand in","vi":"giao nộp","ex":"She handed {in} the wallet to the police.","k":"pv"},{"w":"hold up","vi":"cướp bằng đe dọa; làm chậm","ex":"The bank was held {up}; traffic was held up afterwards.","k":"pv"},{"w":"let off","vi":"tha/phạt nhẹ; cho nổ/phóng","ex":"The judge let him {off} with a warning.","k":"pv"},{"w":"look into","vi":"điều tra","ex":"Police are looking {into} the complaint.","k":"pv"},{"w":"make off","vi":"tẩu thoát nhanh","ex":"The thieves made {off} before dawn.","k":"pv"},{"w":"take down","vi":"ghi lại","ex":"The officer took {down} my address.","k":"pv"},{"w":"take in","vi":"lừa","ex":"Many people were taken {in} by the fake website.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"account","vi":"vì; tính đến; giải thích/chiếm tỉ lệ","ex":"The court took his age into {account}.","note":"on account of; take into account; account for","k":"col"},{"w":"advantage","vi":"lợi dụng/tận dụng; có lợi thế so với; ưu điểm của","ex":"She had an {advantage} over the other applicants.","note":"take advantage of; have an advantage over; at an advantage; the advantage of","k":"col"},{"w":"blame","vi":"có lỗi; chịu/quy lỗi","ex":"Do not {blame} the delay on the driver.","note":"be to blame; get/take the blame; put the blame on; blame sth on sb; blame sb for sth","k":"col"},{"w":"damage","vi":"gây thiệt hại cho; damage không đếm được trong nghĩa hư hại","ex":"The fire caused {damage} to the shop.","note":"do/cause damage to","k":"col"},{"w":"fault","vi":"có lỗi; bắt lỗi","ex":"The investigation established who was at {fault}.","note":"at fault; find fault with","k":"col"},{"w":"intention","vi":"có/không có ý định","ex":"He had no {intention} of breaking the rules.","note":"have (no) intention of V-ing","k":"col"},{"w":"mistake","vi":"mắc lỗi; nhầm A là B; do nhầm","ex":"I took your bag by {mistake}.","note":"make a mistake; a mistake to V; mistake A for B; by mistake","k":"col"},{"w":"necessary","vi":"cần thiết để ai làm","ex":"It is {necessary} for witnesses to tell the truth.","note":"necessary for sb to V","k":"col"},{"w":"order","vi":"ngăn nắp/hoạt động; sắp xếp; để; ra lệnh","ex":"They put the files in {order}.","note":"in order; put in order; in order to V; give an order to sb to V","k":"col"},{"w":"permission","vi":"cho/xin/có sự cho phép","ex":"We got {permission} from the owner to enter.","note":"give sb permission to V; ask for permission; have/ask/get permission from sb to V","k":"col"},{"w":"purpose","vi":"cố ý; mục đích của","ex":"The damage was not caused on {purpose}.","note":"on purpose; the purpose of","k":"col"},{"w":"reason","vi":"lí do; dùng lí lẽ thuyết phục","ex":"There is no {reason} for violence.","note":"the reason why; the reason for; reason with sb","k":"col"},{"w":"solution","vi":"tìm/nghĩ ra giải pháp cho","ex":"They worked out a {solution} to the problem.","note":"have/find/think of/work out/come up with/figure out a solution to","k":"col"},{"w":"wrong","vi":"làm sai; trục trặc; lộn ngược","ex":"Something went {wrong} with the alarm.","note":"do wrong; do the wrong thing; the wrong thing to V; go wrong; the wrong way up","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"accuse","vi":"buộc tội","note":"accuse (v) → accused (n/adj), accusation (n)","full":"buộc tội → bị cáo/bị buộc tội; lời buộc tội.","ex":"The {accusation} was false.","hint":"accuse","k":"wf"},{"w":"addict","vi":"người nghiện","note":"addict (n) → addicted/addictive (adj), addiction (n)","full":"người nghiện → bị nghiện/gây nghiện; sự nghiện.","ex":"The treatment helps people with {addiction}.","hint":"addict","k":"wf"},{"w":"convict","vi":"kết án/tù nhân","note":"convict (v/n) → convicted (adj), conviction (n)","full":"kết án/tù nhân → đã bị kết án; bản án/niềm tin chắc.","ex":"He has a {conviction} for theft.","hint":"convict","k":"wf"},{"w":"crime","vi":"tội phạm","note":"crime (n) → criminal (n/adj)","full":"tội phạm → người phạm tội/thuộc hình sự.","ex":"The police opened a {criminal} investigation.","hint":"crime","k":"wf"},{"w":"evident","vi":"rõ ràng","note":"evident (adj) → evidence (n), evidently (adv)","full":"rõ ràng → chứng cứ; hiển nhiên.","ex":"There was no {evidence} against her.","hint":"evident","k":"wf"},{"w":"forge","vi":"làm giả","note":"forge (v) → forgery, forger (n)","full":"làm giả → hành vi/vật giả; người làm giả.","ex":"The signature was a {forgery}.","hint":"forge","k":"wf"},{"w":"honest/dishonest","vi":"trung thực/gian dối; tính trung thực/gian dối.","note":"honest/dishonest (adj) → honesty/dishonesty (n), honestly/dishonestly (adv)","full":"trung thực/gian dối; tính trung thực/gian dối.","ex":"Her {honesty} impressed the judge.","hint":"honest/dishonest","k":"wf"},{"w":"investigate","vi":"điều tra","note":"investigate (v) → investigative (adj), investigation, investigator (n)","full":"điều tra → thuộc điều tra; cuộc điều tra; điều tra viên.","ex":"The {investigation} took months.","hint":"investigate","k":"wf"},{"w":"law","vi":"luật","note":"law (n) → lawyer (n), lawful/unlawful (adj)","full":"luật → luật sư; hợp pháp/trái luật.","ex":"They questioned whether the search was {lawful}.","hint":"law","k":"wf"},{"w":"murder","vi":"giết người","note":"murder (n/v) → murderer (n)","full":"giết người → kẻ giết người.","ex":"The {murderer} was caught.","hint":"murder","k":"wf"},{"w":"offence","vi":"hành vi phạm luật/sự xúc phạm","note":"offence (n) → offensive (adj), offend (v), offender (n)","full":"hành vi phạm luật/sự xúc phạm → xúc phạm; làm phật ý; người vi phạm.","ex":"It was his first offence.","hint":"offence","k":"wf"},{"w":"prison","vi":"nhà tù","note":"prison (n) → prisoner (n), imprisoned (adj), imprisonment (n)","full":"nhà tù → tù nhân; bị giam; việc phạt tù.","ex":"The offence can lead to {imprisonment}.","hint":"prison","k":"wf"},{"w":"prove","vi":"chứng minh","note":"prove (v) → proof (n), proven/unproven (adj/V3), disprove (v)","full":"chứng minh → bằng chứng; đã/chưa được chứng minh; bác bỏ bằng chứng.","ex":"The new evidence disproved the claim.","hint":"prove","k":"wf"},{"w":"rob","vi":"cướp","note":"rob (v) → robbery, robber (n)","full":"cướp → vụ cướp; kẻ cướp.","ex":"Two robbers were arrested after the {robbery}.","hint":"rob","k":"wf"},{"w":"secure/insecure","vi":"an toàn/không an toàn","note":"secure/insecure (adj) → security/insecurity (n)","full":"an toàn/không an toàn → an ninh/sự bất an.","ex":"The bank improved its {security}.","hint":"secure/insecure","k":"wf"},{"w":"theft","vi":"trộm cắp","note":"theft (n) → thief (n), thieves (số nhiều)","full":"trộm cắp → kẻ trộm; những kẻ trộm.","ex":"The {thieves} were charged with theft.","hint":"theft","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"accuse sb of N/V-ing","vi":"buộc tội ai làm","ex":"They accused him {of} stealing the money.","k":"pat"},{"w":"arrest sb for N/V-ing","vi":"bắt vì","ex":"She was arrested {for} damaging the car.","k":"pat"},{"w":"charge sb with N/V-ing","vi":"chính thức buộc tội","ex":"He was charged {with} robbery.","k":"pat"},{"w":"claim to be/to V; claim that","vi":"tuyên bố, khẳng định","ex":"The caller claimed {to} be a police officer.","k":"pat"},{"w":"deny N/V-ing","vi":"phủ nhận; không dùng deny to V","ex":"He denied entering the building.","k":"pat"},{"w":"doubt N/that/if/whether","vi":"nghi ngờ","ex":"I doubt whether the story is true.","k":"pat"},{"w":"forgive sb for N/V-ing","vi":"tha thứ vì","ex":"She forgave him {for} lying.","k":"pat"},{"w":"glimpse sth; catch a glimpse of","vi":"thoáng nhìn thấy","ex":"I caught a glimpse {of} the driver.","k":"pat"},{"w":"guilty of N/V-ing","vi":"có tội về","ex":"The court found him guilty {of} fraud.","k":"pat"},{"w":"legal for sb to V","vi":"hợp pháp để ai làm","ex":"Is it legal {for} them to record the call?","k":"pat"},{"w":"make sb V; be made to V","vi":"bắt ai làm; bị bắt làm (bị động có to)","ex":"They made him wait; he was made {to} wait outside.","k":"pat"},{"w":"refuse N/to V","vi":"từ chối","ex":"The suspect refused {to} answer.","k":"pat"},{"w":"respect sb for; have respect for","vi":"kính trọng ai vì; có sự tôn trọng","ex":"I respect her {for} telling the truth.","k":"pat"},{"w":"threaten to V; threaten sb with","vi":"dọa làm; đe dọa ai bằng","ex":"They threatened him with legal action.","k":"pat"}]}]},{"g":2,"u":14,"title":"Health and Fitness","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"prescription","pos":"n","vi":"đơn thuốc","ex":"The doctor wrote a {prescription}; the chef shared a recipe.","grp":["prescription","recipe"],"k":"topic"},{"w":"recipe","pos":"n","vi":"công thức nấu ăn","ex":"The doctor wrote a prescription; the chef shared a {recipe}.","grp":["prescription","recipe"],"k":"topic"},{"w":"operation","pos":"n","vi":"ca phẫu thuật (đếm được)","ex":"She needs surgery and will have an {operation} tomorrow.","grp":["operation","surgery"],"k":"topic"},{"w":"surgery","pos":"n","vi":"việc/ngành phẫu thuật, phòng khám (tùy nghĩa)","ex":"She needs {surgery} and will have an operation tomorrow.","grp":["operation","surgery"],"k":"topic"},{"w":"sore","pos":"adj/v/n","vi":"đau/rát (adj)","ex":"My throat is {sore}, my leg hurts, and I have a pain in my back.","grp":["sore","hurt","pain"],"k":"topic"},{"w":"hurt","pos":"adj/v/n","vi":"đau/làm đau (v)","ex":"My throat is sore, my leg {hurts}, and I have a pain in my back.","grp":["sore","hurt","pain"],"k":"topic"},{"w":"pain","pos":"adj/v/n","vi":"cơn/sự đau (n)","ex":"My throat is sore, my leg hurts, and I have a {pain} in my back.","grp":["sore","hurt","pain"],"k":"topic"},{"w":"illness","pos":"n","vi":"tình trạng/đợt bị bệnh","ex":"The disease caused a long period of {illness}.","grp":["illness","disease"],"k":"topic"},{"w":"disease","pos":"n","vi":"căn bệnh có đặc điểm xác định","ex":"The {disease} caused a long period of illness.","grp":["illness","disease"],"k":"topic"},{"w":"injured","pos":"adj","vi":"bị thương, thường về người/động vật","ex":"The driver was {injured} and the car was damaged.","grp":["injured","damaged"],"k":"topic"},{"w":"damaged","pos":"adj","vi":"bị hư hại, thường về vật","ex":"The driver was injured and the car was {damaged}.","grp":["injured","damaged"],"k":"topic"},{"w":"thin","pos":"adj","vi":"gầy/mỏng, trung tính hoặc tiêu cực","ex":"She is naturally slim; he became very {thin} after the illness.","grp":["thin","slim"],"k":"topic"},{"w":"slim","pos":"adj","vi":"mảnh mai, thường tích cực","ex":"She is naturally {slim}; he became very thin after the illness.","grp":["thin","slim"],"k":"topic"},{"w":"remedy","pos":"n","vi":"cách/thuốc giảm vấn đề","ex":"The therapy reduced her symptoms, but there is no complete cure yet.","grp":["remedy","cure","therapy"],"k":"topic"},{"w":"cure","pos":"n","vi":"cách chữa khỏi","ex":"The therapy reduced her symptoms, but there is no complete {cure} yet.","grp":["remedy","cure","therapy"],"k":"topic"},{"w":"therapy","pos":"n","vi":"liệu pháp","ex":"The {therapy} reduced her symptoms, but there is no complete cure yet.","grp":["remedy","cure","therapy"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"effect","pos":"n","vi":"ảnh hưởng/tác dụng","ex":"The medicine had a positive {effect}, and the test result was encouraging.","grp":["effect","result"],"k":"topic"},{"w":"result","pos":"n","vi":"kết quả/đầu ra","ex":"The medicine had a positive effect, and the test {result} was encouraging.","grp":["effect","result"],"k":"topic"},{"w":"healthy","pos":"adj","vi":"khỏe mạnh/tốt cho sức khỏe","ex":"A {healthy} diet can help you stay fit.","grp":["healthy","fit"],"k":"topic"},{"w":"fit","pos":"adj","vi":"thể lực tốt","ex":"A healthy diet can help you stay {fit}.","grp":["healthy","fit"],"k":"topic"},{"w":"examine","pos":"v","vi":"khám/kiểm tra kĩ","ex":"The doctor {examined} the patient and investigated the cause of the fever.","grp":["examine","investigate"],"k":"topic"},{"w":"investigate","pos":"v","vi":"điều tra nguyên nhân/sự việc","ex":"The doctor examined the patient and {investigated} the cause of the fever.","grp":["examine","investigate"],"k":"topic"},{"w":"infection","pos":"n","vi":"nhiễm trùng/lây nhiễm","ex":"Water pollution can increase the risk of {infection}.","grp":["infection","pollution"],"k":"topic"},{"w":"pollution","pos":"n","vi":"ô nhiễm","ex":"Water {pollution} can increase the risk of infection.","grp":["infection","pollution"],"k":"topic"},{"w":"plaster","pos":"n","vi":"băng cá nhân/thạch cao bó bột","ex":"Use a {plaster} for the small cut and a bandage for the larger wound.","grp":["plaster","bandage"],"k":"topic"},{"w":"bandage","pos":"n","vi":"băng cuộn băng vết thương","ex":"Use a plaster for the small cut and a {bandage} for the larger wound.","grp":["plaster","bandage"],"k":"topic"},{"w":"ward","pos":"n","vi":"khu/phòng bệnh trong viện","ex":"The clinic referred her to the children's {ward}.","grp":["ward","clinic"],"k":"topic"},{"w":"clinic","pos":"n","vi":"phòng khám/cơ sở khám chuyên biệt","ex":"The {clinic} referred her to the children's ward.","grp":["ward","clinic"],"k":"topic"},{"w":"dose","pos":"n","vi":"liều thuốc","ex":"Take the prescribed {dose}; a fix refers to an addict's drug supply.","grp":["dose","fix"],"k":"topic"},{"w":"fix","pos":"n","vi":"liều chất gây nghiện (khẩu ngữ)","ex":"Take the prescribed dose; a {fix} refers to an addict's drug supply.","grp":["dose","fix"],"k":"topic"},{"w":"fever","pos":"n","vi":"sốt","ex":"The child developed a {fever} and a rash.","grp":["fever","rash"],"k":"topic"},{"w":"rash","pos":"n","vi":"phát ban","ex":"The child developed a fever and a {rash}.","grp":["fever","rash"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"break out","vi":"bùng phát, nổ ra (cháy/chiến tranh; có thể nói bệnh)","ex":"A fire broke {out} in the kitchen.","k":"pv"},{"w":"bring on","vi":"gây ra bệnh/triệu chứng","ex":"Stress can bring {on} headaches.","k":"pv"},{"w":"come down with","vi":"bắt đầu bị bệnh","ex":"I think I am coming down {with} flu.","k":"pv"},{"w":"come round / come to","vi":"tỉnh lại sau bất tỉnh","ex":"She came round a few minutes later.","k":"pv"},{"w":"cut down on","vi":"giảm lượng dùng","ex":"You should cut down {on} sugary drinks.","k":"pv"},{"w":"feel up to","vi":"cảm thấy đủ khỏe/sẵn sàng làm (V-ing)","ex":"I do not feel up {to} going out.","k":"pv"},{"w":"get over","vi":"hồi phục sau bệnh/vượt qua","ex":"It took him a week to get {over} the infection.","k":"pv"},{"w":"give up","vi":"từ bỏ thói quen","ex":"She gave {up} smoking.","k":"pv"},{"w":"look after","vi":"chăm sóc","ex":"Who will look {after} you after the operation?","k":"pv"},{"w":"pass out","vi":"ngất","ex":"He passed {out} in the heat.","k":"pv"},{"w":"pull through","vi":"qua khỏi bệnh/tình trạng nguy hiểm","ex":"The doctors hope she will pull {through}.","k":"pv"},{"w":"put down","vi":"cho động vật chết nhân đạo","ex":"The badly injured animal had to be put {down}.","k":"pv"},{"w":"put on","vi":"tăng cân khi đi với weight","ex":"He has put {on} weight recently.","k":"pv"},{"w":"wear off","vi":"hết dần tác dụng/cảm giác","ex":"The pain returned as the medicine wore {off}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"alternative","vi":"y học/liệu pháp thay thế; tìm lựa chọn khác","ex":"They discussed an {alternative} therapy with the doctor.","note":"alternative medicine/therapy; find an alternative","k":"col"},{"w":"appointment","vi":"đặt/có/không giữ cuộc hẹn","ex":"I have an {appointment} with the dentist.","note":"make/have/break an appointment","k":"col"},{"w":"bath","vi":"tắm bồn; xả nước vào bồn","ex":"She ran a warm {bath}.","note":"have/take a bath; run a bath","k":"col"},{"w":"danger","vi":"đang trong/qua nguy hiểm","ex":"The patient is now out of {danger}.","note":"in/out of danger","k":"col"},{"w":"exercise","vi":"làm một bài; do exercise / take/get exercise = vận động","ex":"Regular {exercise} helps me sleep better.","note":"do an exercise","k":"col"},{"w":"fit","vi":"trở nên/giữ thể lực; khỏe mạnh","ex":"Swimming helps her keep {fit}.","note":"get/stay/keep/be fit; fit and healthy","k":"col"},{"w":"good","vi":"có lợi cho ai/làm gì có lợi","ex":"A short rest will do you {good}.","note":"do sb good; sth does you good; good for sb to V","k":"col"},{"w":"health","vi":"tình trạng sức khỏe; trung tâm/dịch vụ y tế","ex":"Her grandfather is in good {health}.","note":"in good/bad/poor health; health centre; health care","k":"col"},{"w":"injection","vi":"tiêm để trị/phòng; tiêm cho ai","ex":"The nurse gave him an {injection}.","note":"have an injection for/against; give sb an injection","k":"col"},{"w":"medicine","vi":"uống/kê thuốc; hành nghề/học y; cách chữa tốt nhất","ex":"She studies {medicine} and hopes to practise medicine locally.","note":"take/prescribe medicine; practise/study medicine; the best medicine; alternative medicine","k":"col"},{"w":"shape","vi":"lấy lại/giữ thể trạng; hình dạng; dưới dạng","ex":"He cycles to stay in {shape}.","note":"get in/into shape; stay/keep in shape; the shape of; in the shape of","k":"col"},{"w":"spread","vi":"lan/trải; phết lên; lan đến","ex":"The infection {spread} to nearby villages.","note":"spread sth; spread sth over/on; spread to","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"allergy","vi":"dị ứng","note":"allergy (n) → allergic (adj)","full":"dị ứng → bị/gây dị ứng.","ex":"She is {allergic} to peanuts.","hint":"allergy","k":"wf"},{"w":"aware/unaware","vi":"biết/không biết","note":"aware/unaware (adj) → awareness (n)","full":"biết/không biết → nhận thức.","ex":"The campaign raised {awareness} of diabetes.","hint":"aware/unaware","k":"wf"},{"w":"benefit","vi":"lợi ích/có lợi","note":"benefit (n/v) → beneficial (adj)","full":"lợi ích/có lợi → có lợi.","ex":"Exercise is {beneficial} to health.","hint":"benefit","k":"wf"},{"w":"comfort/discomfort","vi":"thoải mái/khó chịu; trạng từ tương ứng.","note":"comfort/discomfort (n) → comfortable/uncomfortable (adj), comfortably/uncomfortably (adv)","full":"thoải mái/khó chịu; trạng từ tương ứng.","ex":"The patient slept {comfortably}.","hint":"comfort/discomfort","k":"wf"},{"w":"emphasis","vi":"sự nhấn mạnh","note":"emphasis (n) → emphasise (v), emphatic (adj)","full":"sự nhấn mạnh → nhấn mạnh; dứt khoát/mạnh mẽ.","ex":"The doctor emphasised the need for rest.","hint":"emphasis","k":"wf"},{"w":"fit/unfit","vi":"có/không có thể lực phù hợp","note":"fit/unfit (adj) → fitness (n)","full":"có/không có thể lực phù hợp → thể lực.","ex":"Her {fitness} has improved.","hint":"fit/unfit","k":"wf"},{"w":"ill","vi":"ốm","note":"ill (adj) → illness (n)","full":"ốm → bệnh/tình trạng ốm.","ex":"He recovered from a serious {illness}.","hint":"ill","k":"wf"},{"w":"inject","vi":"tiêm","note":"inject (v) → injection (n)","full":"tiêm → mũi/việc tiêm.","ex":"The {injection} was almost painless.","hint":"inject","k":"wf"},{"w":"injure","vi":"làm bị thương","note":"injure (v) → injury (n), injuries (số nhiều)","full":"làm bị thương → vết thương.","ex":"She escaped without {injury}.","hint":"injure","k":"wf"},{"w":"operate","vi":"vận hành/phẫu thuật; ca mổ; người vận hành; đang hoạt động; hợp tác; sự hợp tác; hợp tác/không hợp tác.","note":"operate (v) → operation, operator (n), operating (adj); cooperate (v), cooperation (n), cooperative/uncooperative (adj)","full":"vận hành/phẫu thuật; ca mổ; người vận hành; đang hoạt động; hợp tác; sự hợp tác; hợp tác/không hợp tác.","ex":"The operation required close {cooperation}.","hint":"operate","k":"wf"},{"w":"poison","vi":"chất độc/đầu độc","note":"poison (n/v) → poisonous (adj), poisoning (n)","full":"chất độc/đầu độc → độc; sự ngộ độc.","ex":"He was treated for food {poisoning}.","hint":"poison","k":"wf"},{"w":"recover","vi":"hồi phục","note":"recover (v) → recovery (n)","full":"hồi phục → sự hồi phục.","ex":"We wish her a speedy {recovery}.","hint":"recover","k":"wf"},{"w":"strong","vi":"mạnh","note":"strong (adj) → strength (n), strengthen (v), strongly (adv)","full":"mạnh → sức mạnh; làm mạnh; mạnh mẽ.","ex":"The exercises {strengthen} the muscles.","hint":"strong","k":"wf"},{"w":"surgery","vi":"phẫu thuật","note":"surgery (n) → surgeon (n), surgical (adj), surgically (adv)","full":"phẫu thuật → bác sĩ phẫu thuật; thuộc phẫu thuật; bằng phẫu thuật.","ex":"The {surgeon} explained the procedure.","hint":"surgery","k":"wf"},{"w":"treat","vi":"điều trị/đối xử","note":"treat (v) → treatment (n)","full":"điều trị/đối xử → cách điều trị/đối xử.","ex":"The {treatment} was successful.","hint":"treat","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"addicted to N/V-ing","vi":"nghiện","ex":"He is addicted {to} online gaming.","k":"pat"},{"w":"attempt to V","vi":"cố gắng làm","ex":"She attempted {to} stand up.","k":"pat"},{"w":"benefit from; the benefit of","vi":"hưởng lợi từ; lợi ích của","ex":"Patients benefit {from} regular follow-up appointments.","k":"pat"},{"w":"complain (to sb) about; complain of","vi":"than phiền với ai về; kêu bị triệu chứng","ex":"He complained of severe chest pain.","k":"pat"},{"w":"cope with","vi":"đương đầu/xử lí","ex":"She is learning to cope {with} stress.","k":"pat"},{"w":"inject sth into","vi":"tiêm chất gì vào","ex":"The nurse injected the medicine {into} his arm.","k":"pat"},{"w":"lead to N/V-ing","vi":"dẫn đến","ex":"Lack of sleep can lead {to} making mistakes.","k":"pat"},{"w":"likely to V; unlikely that","vi":"có khả năng làm; không có khả năng rằng","ex":"She is likely {to} recover soon.","k":"pat"},{"w":"need to V; need V-ing; in need of; no need for","vi":"cần làm; cần được làm; đang cần; không cần","ex":"You need {to} rest. The dressing needs changing.","k":"pat"},{"w":"operate on sb","vi":"phẫu thuật cho","ex":"The surgeon operated {on} her knee.","k":"pat"},{"w":"suffer from; suffer sth","vi":"mắc/chịu bệnh; chịu tổn thất/vết thương","ex":"He suffers {from} asthma and suffered a minor injury yesterday.","k":"pat"},{"w":"tired of N/V-ing","vi":"chán; khác tired from = mệt vì","ex":"I am tired {of} waiting.","k":"pat"},{"w":"try to V; try V-ing; try and V","vi":"cố làm; thử cách làm; try and thường dùng trong lời nói","ex":"Try drinking some water; try {to} stay calm.","k":"pat"},{"w":"worry about; worried that/about/by","vi":"lo về; lo rằng/vì/bởi","ex":"She is worried {about} the test results.","k":"pat"},{"w":"worth N/V-ing","vi":"đáng giá/đáng làm; không dùng worth to V","ex":"The book is worth reading.","k":"pat"}]}]},{"g":2,"u":16,"title":"Food and Drink","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"chop","pos":"v","vi":"chặt/băm","ex":"{Chop} the onion, slice the tomatoes and grate the cheese.","grp":["chop","slice","grate"],"k":"topic"},{"w":"slice","pos":"v","vi":"thái lát","ex":"Chop the onion, {slice} the tomatoes and grate the cheese.","grp":["chop","slice","grate"],"k":"topic"},{"w":"grate","pos":"v","vi":"bào sợi/vụn","ex":"Chop the onion, slice the tomatoes and {grate} the cheese.","grp":["chop","slice","grate"],"k":"topic"},{"w":"bake","pos":"v","vi":"nướng bánh/lò","ex":"{Bake} the bread, roast the chicken and boil the potatoes.","grp":["bake","grill","fry","roast","boil"],"k":"topic"},{"w":"grill","pos":"v","vi":"nướng nhiệt trực tiếp","ex":"Bake the bread, roast the chicken and boil the potatoes.","grp":["bake","grill","fry","roast","boil"],"k":"topic"},{"w":"fry","pos":"v","vi":"chiên","ex":"Bake the bread, roast the chicken and boil the potatoes.","grp":["bake","grill","fry","roast","boil"],"k":"topic"},{"w":"roast","pos":"v","vi":"quay/nướng thịt","ex":"Bake the bread, {roast} the chicken and boil the potatoes.","grp":["bake","grill","fry","roast","boil"],"k":"topic"},{"w":"boil","pos":"v","vi":"luộc/đun sôi","ex":"Bake the bread, roast the chicken and {boil} the potatoes.","grp":["bake","grill","fry","roast","boil"],"k":"topic"},{"w":"cook","pos":"n","vi":"người nấu ăn","ex":"The chef is a skilled {cook} who uses a gas cooker.","grp":["cook","cooker","chef"],"k":"topic"},{"w":"cooker","pos":"n","vi":"bếp nấu","ex":"The chef is a skilled cook who uses a gas {cooker}.","grp":["cook","cooker","chef"],"k":"topic"},{"w":"chef","pos":"n","vi":"đầu bếp chuyên nghiệp","ex":"The {chef} is a skilled cook who uses a gas cooker.","grp":["cook","cooker","chef"],"k":"topic"},{"w":"oven","pos":"n","vi":"lò nướng","ex":"The {oven} is below the hob; the grill is above it.","grp":["oven","grill","hob"],"k":"topic"},{"w":"grill","pos":"n","vi":"bộ phận/vỉ nướng nhiệt trực tiếp","ex":"The oven is below the hob; the {grill} is above it.","grp":["oven","grill","hob"],"k":"topic"},{"w":"hob","pos":"n","vi":"mặt bếp","ex":"The oven is below the {hob}; the grill is above it.","grp":["oven","grill","hob"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"kitchen","pos":"n","vi":"nhà bếp","ex":"The restaurant's {kitchen} specialises in Vietnamese cuisine.","grp":["kitchen","cuisine"],"k":"topic"},{"w":"cuisine","pos":"n","vi":"nền/phong cách ẩm thực","ex":"The restaurant's kitchen specialises in Vietnamese {cuisine}.","grp":["kitchen","cuisine"],"k":"topic"},{"w":"lunch","pos":"n","vi":"bữa trưa","ex":"We had a light {lunch} and a large dinner.","grp":["lunch","dinner"],"k":"topic"},{"w":"dinner","pos":"n","vi":"bữa chính, thường buổi tối","ex":"We had a light lunch and a large {dinner}.","grp":["lunch","dinner"],"k":"topic"},{"w":"plate","pos":"n","vi":"đĩa phẳng","ex":"Serve the soup in a bowl and put the cup on a saucer.","grp":["plate","bowl","saucer","dish"],"k":"topic"},{"w":"bowl","pos":"n","vi":"bát","ex":"Serve the soup in a {bowl} and put the cup on a saucer.","grp":["plate","bowl","saucer","dish"],"k":"topic"},{"w":"saucer","pos":"n","vi":"đĩa lót tách","ex":"Serve the soup in a bowl and put the cup on a {saucer}.","grp":["plate","bowl","saucer","dish"],"k":"topic"},{"w":"dish","pos":"n","vi":"đĩa sâu/đồ đựng/món ăn","ex":"Serve the soup in a bowl and put the cup on a saucer.","grp":["plate","bowl","saucer","dish"],"k":"topic"},{"w":"vegetable","pos":"n/adj","vi":"rau","ex":"The vegan ordered {vegetables} without butter or cheese.","grp":["vegetable","vegetarian","vegan"],"k":"topic"},{"w":"vegetarian","pos":"n/adj","vi":"người/thuộc chế độ không ăn thịt","ex":"The vegan ordered vegetables without butter or cheese.","grp":["vegetable","vegetarian","vegan"],"k":"topic"},{"w":"vegan","pos":"n/adj","vi":"thuần chay, không dùng sản phẩm động vật","ex":"The {vegan} ordered vegetables without butter or cheese.","grp":["vegetable","vegetarian","vegan"],"k":"topic"},{"w":"fast food","pos":"n","vi":"đồ ăn nhanh","ex":"We bought a takeaway from a fast- {food} restaurant.","grp":["fast food","takeaway"],"k":"topic"},{"w":"takeaway","pos":"n","vi":"đồ ăn mua mang đi/quán bán đồ mang đi","ex":"We bought a {takeaway} from a fast- food restaurant.","grp":["fast food","takeaway"],"k":"topic"},{"w":"kettle","pos":"n","vi":"ấm đun nước","ex":"Boil water in the {kettle} and pour it into the teapot.","grp":["kettle","teapot"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"teapot","pos":"n","vi":"bình pha trà","ex":"Boil water in the kettle and pour it into the {teapot}.","grp":["kettle","teapot"],"k":"topic"},{"w":"freezer","pos":"n","vi":"tủ/ngăn đông","ex":"Keep ice cream in the {freezer} and milk in the fridge.","grp":["freezer","fridge"],"k":"topic"},{"w":"fridge","pos":"n","vi":"tủ lạnh","ex":"Keep ice cream in the freezer and milk in the {fridge}.","grp":["freezer","fridge"],"k":"topic"},{"w":"frozen","pos":"adj","vi":"đã đông lạnh","ex":"The {frozen} peas stayed hard in the freezing weather.","grp":["frozen","freezing"],"k":"topic"},{"w":"freezing","pos":"adj","vi":"lạnh cóng hoặc đang đóng băng","ex":"The frozen peas stayed hard in the {freezing} weather.","grp":["frozen","freezing"],"k":"topic"},{"w":"mix","pos":"v","vi":"trộn","ex":"{Mix} the flour, stir the sauce and whisk the eggs.","grp":["mix","stir","whisk"],"k":"topic"},{"w":"stir","pos":"v","vi":"khuấy/đảo","ex":"Mix the flour, {stir} the sauce and whisk the eggs.","grp":["mix","stir","whisk"],"k":"topic"},{"w":"whisk","pos":"v","vi":"đánh bằng phới","ex":"Mix the flour, stir the sauce and {whisk} the eggs.","grp":["mix","stir","whisk"],"k":"topic"},{"w":"soft drink","pos":"n","vi":"nước không cồn","ex":"Choose a {soft drink}; not all soft drinks are fizzy.","grp":["soft drink","fizzy drink"],"k":"topic"},{"w":"fizzy drink","pos":"n","vi":"nước có ga","ex":"Choose a soft {drink}; not all soft drinks are fizzy.","grp":["soft drink","fizzy drink"],"k":"topic"},{"w":"menu","pos":"n","vi":"thực đơn","ex":"We read the {menu}, then ordered plates from a kitchenware catalogue.","grp":["menu","catalogue"],"k":"topic"},{"w":"catalogue","pos":"n","vi":"danh mục sản phẩm","ex":"We read the menu, then ordered plates from a kitchenware {catalogue}.","grp":["menu","catalogue"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"drop in (on)","vi":"ghé thăm bất ngờ/không hẹn","ex":"We dropped in {on} our neighbours.","k":"pv"},{"w":"get on for","vi":"gần đến một giờ/tuổi/con số","ex":"It is getting on {for} seven; dinner is nearly ready.","k":"pv"},{"w":"go off","vi":"ôi thiu, không còn tươi","ex":"The milk has gone {off}.","k":"pv"},{"w":"go on","vi":"tiếp tục; go on to V = chuyển sang làm việc tiếp theo","ex":"She went {on} cooking, then went on to wash the dishes.","k":"pv"},{"w":"go round / come round","vi":"đến nhà ai chơi","ex":"Come {round} for dinner tomorrow.","k":"pv"},{"w":"keep on","vi":"tiếp tục, cứ làm","ex":"He kept {on} stirring the soup.","k":"pv"},{"w":"leave out","vi":"bỏ sót/không cho vào","ex":"Leave {out} the chilli if you prefer mild food.","k":"pv"},{"w":"put off","vi":"làm mất hứng/không muốn làm hoặc thích","ex":"The smell put me {off} eating.","k":"pv"},{"w":"run into","vi":"tình cờ gặp","ex":"I ran {into} an old friend at the market.","k":"pv"},{"w":"run out of","vi":"hết, không còn","ex":"We have run out {of} rice.","k":"pv"},{"w":"take to","vi":"bắt đầu thích; hình thành thói quen","ex":"She has taken {to} baking at weekends.","k":"pv"},{"w":"try out","vi":"thử nghiệm","ex":"Let's try {out} the new recipe.","k":"pv"},{"w":"turn out","vi":"hóa ra/có kết quả như thế nào","ex":"The cake turned {out} well.","k":"pv"},{"w":"turn up","vi":"xuất hiện bất ngờ/không hẹn chắc chắn","ex":"Two extra guests turned {up}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"cook","vi":"người nấu giỏi; nấu; làm việc nấu ăn","ex":"Dad usually does the {cooking}.","note":"a good/great cook; cook a meal/chicken; do the cooking","k":"col"},{"w":"drink","vi":"pha/uống; nâng cốc chúc","ex":"We drank a toast to the chef.","note":"make sb a drink; have a drink of; drink sth; drink to sb / sb's health; drink a toast to sb","k":"col"},{"w":"feed","vi":"cho ăn; ăn thứ gì để sống","ex":"These birds {feed} on seeds.","note":"feed an animal; feed on","k":"col"},{"w":"fill","vi":"làm đầy; chứa đầy","ex":"The bowl was {filled} with fresh fruit.","note":"fill sth (up); filled with; full of","k":"col"},{"w":"food","vi":"chuẩn bị/nấu/phục vụ; đồ nhanh/ít dinh dưỡng/cho thú/tốt sức khỏe","ex":"They serve healthy {food} at school.","note":"make/prepare/cook/serve food; fast/junk/pet/health food","k":"col"},{"w":"meal","vi":"nấu/ăn; đi ăn ngoài","ex":"We went out for a {meal} after work.","note":"make/cook/have a meal; go out for a meal","k":"col"},{"w":"note","vi":"ghi/lưu lại","ex":"Take a {note} of the cooking time.","note":"make/take/keep (a) note of; note sth down","k":"col"},{"w":"occasion","vi":"lần này/kia; đôi khi; nhân dịp; dịp đặc biệt","ex":"We bake this cake on special {occasions}.","note":"on this/that occasion; on occasion; on the occasion of; a special occasion","k":"col"},{"w":"recipe","vi":"làm theo công thức; sách nấu ăn; cách chắc chắn gây tai họa","ex":"Ignoring food safety is a {recipe} for disaster.","note":"follow a recipe; recipe book; a recipe for disaster","k":"col"},{"w":"table","vi":"dọn bày/dọn sạch bàn; đặt bàn","ex":"Please set the {table} while I finish dinner.","note":"lay/set/clear the table; book/reserve a table","k":"col"},{"w":"wash","vi":"rửa bát/tay; máy rửa bát; máy giặt","ex":"{Wash} your hands before doing the cooking.","note":"wash the dishes/one's hands; do the washing-up; dishwasher; washing machine","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"anxious","vi":"lo lắng","note":"anxious (adj) → anxiously (adv), anxiety (n)","full":"lo lắng → một cách lo lắng; sự lo âu.","ex":"She waited {anxiously} for the guests.","hint":"anxious","k":"wf"},{"w":"appreciate","vi":"trân trọng","note":"appreciate (v) → appreciative/unappreciative (adj), appreciatively/unappreciatively (adv), appreciation (n)","full":"trân trọng → biết/không biết trân trọng; sự cảm kích.","ex":"The guests expressed their {appreciation}.","hint":"appreciate","k":"wf"},{"w":"contain","vi":"chứa","note":"contain (v) → container, content(s) (n)","full":"chứa → đồ đựng; nội dung/thứ được chứa.","ex":"Store the contents in a sealed {container}.","hint":"contain","k":"wf"},{"w":"create","vi":"tạo ra","note":"create (v) → creative (adj), creatively (adv), creation, creativity, creator (n)","full":"tạo ra → sáng tạo; sản phẩm/sự sáng tạo; khả năng sáng tạo; người tạo.","ex":"Cooking encourages {creativity}.","hint":"create","k":"wf"},{"w":"disgust","vi":"ghê tởm","note":"disgust (n/v) → disgusting, disgusted (adj)","full":"ghê tởm → gây ghê tởm; cảm thấy ghê tởm.","ex":"The smell was {disgusting}.","hint":"disgust","k":"wf"},{"w":"grow","vi":"lớn/trồng","note":"grow (v) → growth (n), grown-up (n/adj), growing (adj), grown (V3/adj), home- grown (adj), grower (n)","full":"lớn/trồng → tăng trưởng; người lớn/trưởng thành; đang lớn; đã lớn/trồng; trồng tại nhà; người trồng.","ex":"The café uses home-{grown} herbs.","hint":"grow","k":"wf"},{"w":"mix","vi":"trộn","note":"mix (v/n) → mixed (adj), mixture, mixer (n)","full":"trộn → pha trộn; hỗn hợp; máy/người pha trộn.","ex":"Add the eggs to the {mixture}.","hint":"mix","k":"wf"},{"w":"origin","vi":"nguồn gốc","note":"origin (n) → original/unoriginal (adj), originally/unoriginally (adv), originate (v), originator (n)","full":"nguồn gốc → độc đáo/thiếu mới; ban đầu; bắt nguồn; người khởi xướng.","ex":"The dish {originally} came from the north.","hint":"origin","k":"wf"},{"w":"prepare","vi":"chuẩn bị","note":"prepare (v) → preparation (n), preparatory (adj), prepared/unprepared (adj)","full":"chuẩn bị → sự chuẩn bị; mang tính chuẩn bị; sẵn/chưa sẵn.","ex":"Careful {preparation} saves time.","hint":"prepare","k":"wf"},{"w":"safe/unsafe","vi":"an toàn/không an toàn; cứu/tiết kiệm; sự an toàn; vị cứu tinh; người/vật tiết kiệm.","note":"safe/unsafe (adj) → safely/unsafely (adv), save (v), safety, saviour, saver (n)","full":"an toàn/không an toàn; cứu/tiết kiệm; sự an toàn; vị cứu tinh; người/vật tiết kiệm.","ex":"Food {safety} is essential.","hint":"safe/unsafe","k":"wf"},{"w":"surprise","vi":"bất ngờ","note":"surprise (n/v) → surprising/unsurprising (adj), surprisingly/unsurprisingly (adv), surprised (adj)","full":"bất ngờ → gây/không gây ngạc nhiên; thấy ngạc nhiên.","ex":"The meal was {surprisingly} inexpensive.","hint":"surprise","k":"wf"},{"w":"sweet","vi":"ngọt","note":"sweet (adj) → sweetly (adv), sweetener, sweetness (n)","full":"ngọt → ngọt ngào; chất tạo ngọt; vị ngọt.","ex":"The fruit adds natural {sweetness}.","hint":"sweet","k":"wf"},{"w":"thorough","vi":"kĩ lưỡng","note":"thorough (adj) → thoroughly (adv), thoroughness (n)","full":"kĩ lưỡng → hoàn toàn/kĩ; sự kĩ lưỡng.","ex":"Wash the vegetables {thoroughly}.","hint":"thorough","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"associate A with B","vi":"liên hệ A với B","ex":"I associate this soup {with} my childhood.","k":"pat"},{"w":"careful with/about/of","vi":"cẩn thận khi dùng/về/tránh","ex":"Be careful {with} the hot pan.","k":"pat"},{"w":"choose between; choose to V","vi":"chọn giữa; chọn làm","ex":"She chose to order a vegetarian meal.","k":"pat"},{"w":"compliment sb on sth","vi":"khen ai về","ex":"They complimented him {on} the meal.","k":"pat"},{"w":"full of","vi":"đầy","ex":"The basket is full {of} apples.","k":"pat"},{"w":"lack sth; a lack of; lacking in","vi":"thiếu; sự thiếu; không có đủ","ex":"The sauce lacks flavour; it is lacking in salt.","k":"pat"},{"w":"offer sb sth / sth to sb; offer to V","vi":"mời/đưa cho; đề nghị làm","ex":"He offered {to} help and offered me a drink.","k":"pat"},{"w":"regard sb as (being) sth","vi":"coi ai là","ex":"They regard her {as} an excellent chef.","k":"pat"},{"w":"remember to V; remember N/sb/V- ing/that","vi":"nhớ làm việc cần làm; nhớ việc/người đã trải qua/rằng","ex":"Remember {to} buy milk. I remember eating here before.","k":"pat"},{"w":"suggest N/V-ing to sb; suggest that","vi":"gợi ý, đề xuất; không dùng suggest sb to V","ex":"She suggested making soup.","k":"pat"},{"w":"tend to V","vi":"có xu hướng","ex":"I tend {to} eat early.","k":"pat"},{"w":"wait for; wait (for sth) to V; wait and see","vi":"đợi; chờ để làm; chờ xem","ex":"Wait {for} the water to boil.","k":"pat"},{"w":"willing to V","vi":"sẵn lòng","ex":"He is willing {to} do the washing-up.","k":"pat"}]}]},{"g":2,"u":18,"title":"Education and Learning","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"take","pos":"v","vi":"dự thi","ex":"She took the exam in June and passed it.","grp":["take","pass"],"k":"topic"},{"w":"pass","pos":"v","vi":"thi đỗ","ex":"She took the exam in June and {passed} it.","grp":["take","pass"],"k":"topic"},{"w":"read","pos":"v","vi":"đọc","ex":"{Read} the chapter before studying the topic in detail.","grp":["read","study"],"k":"topic"},{"w":"study","pos":"v","vi":"học/nghiên cứu có chủ đích; read a subject cũng có nghĩa học đại học trong Anh Anh","ex":"Read the chapter before {studying} the topic in detail.","grp":["read","study"],"k":"topic"},{"w":"test","pos":"n","vi":"bài kiểm tra/đánh giá","ex":"We have a short {test} before the final exam.","grp":["test","exam"],"k":"topic"},{"w":"exam","pos":"n","vi":"kì/bài thi thường chính thức hơn","ex":"We have a short test before the final {exam}.","grp":["test","exam"],"k":"topic"},{"w":"primary","pos":"adj","vi":"tiểu học","ex":"She moved from {primary} school to secondary school.","grp":["primary","secondary","high"],"k":"topic"},{"w":"secondary","pos":"adj","vi":"trung học","ex":"She moved from primary school to {secondary} school.","grp":["primary","secondary","high"],"k":"topic"},{"w":"high","pos":"adj","vi":"trường trung học, phạm vi tùy hệ thống giáo dục","ex":"She moved from primary school to secondary school.","grp":["primary","secondary","high"],"k":"topic"},{"w":"colleague","pos":"n","vi":"đồng nghiệp","ex":"My {colleague} teaches my former classmate's son.","grp":["colleague","classmate"],"k":"topic"},{"w":"classmate","pos":"n","vi":"bạn cùng lớp","ex":"My colleague teaches my former {classmate}'s son.","grp":["colleague","classmate"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"prefect","pos":"n","vi":"học sinh được giao trách nhiệm quản lí ở trường","ex":"The {prefect} helped new pupils; older students joined the tour.","grp":["prefect","pupil","student"],"k":"topic"},{"w":"pupil","pos":"n","vi":"học sinh, nhất là ở trường phổ thông","ex":"The prefect helped new {pupils}; older students joined the tour.","grp":["prefect","pupil","student"],"k":"topic"},{"w":"student","pos":"n","vi":"người học/sinh viên","ex":"The prefect helped new pupils; older {students} joined the tour.","grp":["prefect","pupil","student"],"k":"topic"},{"w":"qualifications","pos":"n","vi":"bằng cấp/trình độ được chứng nhận","ex":"A good teacher needs both {qualifications} and personal qualities.","grp":["qualifications","qualities"],"k":"topic"},{"w":"qualities","pos":"n","vi":"phẩm chất/đặc tính","ex":"A good teacher needs both qualifications and personal {qualities}.","grp":["qualifications","qualities"],"k":"topic"},{"w":"count","pos":"v","vi":"đếm số lượng","ex":"{Count} the books and measure the shelf.","grp":["count","measure"],"k":"topic"},{"w":"measure","pos":"v","vi":"đo kích thước/lượng","ex":"Count the books and {measure} the shelf.","grp":["count","measure"],"k":"topic"},{"w":"degree","pos":"n","vi":"bằng đại học/học vị","ex":"Her exam results earned her a place on a {degree} course.","grp":["degree","certificate","results"],"k":"topic"},{"w":"certificate","pos":"n","vi":"chứng chỉ/giấy chứng nhận","ex":"Her exam results earned her a place on a degree course.","grp":["degree","certificate","results"],"k":"topic"},{"w":"results","pos":"n","vi":"kết quả/điểm thi","ex":"Her exam {results} earned her a place on a degree course.","grp":["degree","certificate","results"],"k":"topic"},{"w":"speak","pos":"v","vi":"nói/ngôn ngữ, thường trang trọng hơn","ex":"She {speaks} French and talks to her classmates in French.","grp":["speak","talk"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"talk","pos":"v","vi":"trò chuyện/trao đổi","ex":"She speaks French and {talks} to her classmates in French.","grp":["speak","talk"],"k":"topic"},{"w":"lesson","pos":"n","vi":"buổi/bài học","ex":"Today's {lesson} is about a subject I enjoy: physics.","grp":["lesson","subject"],"k":"topic"},{"w":"subject","pos":"n","vi":"môn/chủ đề học","ex":"Today's lesson is about a {subject} I enjoy: physics.","grp":["lesson","subject"],"k":"topic"},{"w":"achieve","pos":"v","vi":"đạt được nhờ nỗ lực","ex":"She {achieved} her goal and reached the required standard.","grp":["achieve","reach"],"k":"topic"},{"w":"reach","pos":"v","vi":"đạt tới mức/điểm","ex":"She achieved her goal and {reached} the required standard.","grp":["achieve","reach"],"k":"topic"},{"w":"task","pos":"n","vi":"nhiệm vụ","ex":"The {task} required a lot of effort.","grp":["task","effort"],"k":"topic"},{"w":"effort","pos":"n","vi":"sự nỗ lực","ex":"The task required a lot of {effort}.","grp":["task","effort"],"k":"topic"},{"w":"know","pos":"v","vi":"biết/quên thuộc","ex":"I {know} her name, but I did not recognise her in the photograph.","grp":["know","recognise"],"k":"topic"},{"w":"recognise","pos":"v","vi":"nhận ra/nhận diện","ex":"I know her name, but I did not {recognise} her in the photograph.","grp":["know","recognise"],"k":"topic"},{"w":"teach","pos":"v","vi":"dạy","ex":"He {teaches} us how to learn independently.","grp":["teach","learn"],"k":"topic"},{"w":"learn","pos":"v","vi":"học/tiếp thu","ex":"He teaches us how to {learn} independently.","grp":["teach","learn"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"catch on","vi":"hiểu ra","ex":"She soon caught {on} to the new method.","k":"pv"},{"w":"come (a)round to","vi":"đổi ý, dần được thuyết phục","ex":"He came round {to} our way of thinking.","k":"pv"},{"w":"cross out","vi":"gạch bỏ chữ","ex":"Cross {out} the wrong answer.","k":"pv"},{"w":"dawn on","vi":"chợt được ai nhận ra; it dawns on sb that","ex":"It dawned {on} me that I had used the wrong formula.","k":"pv"},{"w":"deal with","vi":"xử lí, đối phó","ex":"The next chapter deals {with} probability.","k":"pv"},{"w":"drop out of","vi":"bỏ học/khóa học giữa chừng","ex":"He dropped out {of} college but returned later.","k":"pv"},{"w":"get at","vi":"muốn nói/ám chỉ","ex":"What point are you getting {at}?","k":"pv"},{"w":"get on with","vi":"tiếp tục làm","ex":"Stop chatting and get on {with} your work.","k":"pv"},{"w":"give in","vi":"chịu thua, ngừng cố gắng","ex":"The problem was hard, but she did not give {in}.","k":"pv"},{"w":"keep up with","vi":"theo kịp","ex":"Revision helps me keep up {with} the class.","k":"pv"},{"w":"sail through","vi":"vượt qua dễ dàng","ex":"She sailed {through} the entrance exam.","k":"pv"},{"w":"set out","vi":"trình bày rõ ràng, có thứ tự","ex":"Set {out} your argument in separate paragraphs.","k":"pv"},{"w":"think over","vi":"suy xét kĩ","ex":"Think it {over} before choosing a course.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"attention","vi":"chú ý; thu hút/hướng chú ý","ex":"Please pay {attention} to the instructions.","note":"pay attention to; attract sb's attention; draw sb's attention to","k":"col"},{"w":"break","vi":"nghỉ; giờ nghỉ/quảng cáo; cho ai cơ hội/bớt khắt khe","ex":"Take a short {break} from studying.","note":"have/take a break from N/V-ing; lunch/tea/commercial break; give sb a break","k":"col"},{"w":"discussion","vi":"thảo luận","ex":"We had a {discussion} about changing the timetable.","note":"have a discussion with sb about/on N/V-ing","k":"col"},{"w":"exam","vi":"dự/đỗ/trượt thi","ex":"She is sitting her final {exam} tomorrow.","note":"take/do/have/pass/fail an exam; sit (for) an exam","k":"col"},{"w":"homework","vi":"làm/có bài tập về nhà; homework không đếm được","ex":"I have some {homework} to do.","note":"do your homework; have homework to do","k":"col"},{"w":"idea","vi":"chất vấn; có ý tưởng; ý hay; không biết","ex":"She had a bright {idea} for the project.","note":"question an idea; have an idea; a bright idea; have no idea about","k":"col"},{"w":"learn","vi":"còn nhiều điều cần học; học cách","ex":"We {learnt} how to use the equipment.","note":"have a lot to learn about; learn (how) to V","k":"col"},{"w":"lesson","vi":"học; tiết đôi; rút kinh nghiệm; dạy cho bài học","ex":"I learnt my {lesson} after leaving revision too late.","note":"go to/have a lesson; a double lesson; learn a/your lesson; teach sb a lesson","k":"col"},{"w":"mind","vi":"quyết định; ghi nhớ; phân vân; đổi ý; chợt nghĩ; theo tôi; phiền nếu","ex":"Bear the deadline in {mind} before making up your mind.","note":"make up your mind about; bear sth in mind; in two minds about; change your mind; cross your mind; to my mind; (not) mind if","k":"col"},{"w":"opinion","vi":"theo ý tôi; nêu/có quan điểm","ex":"In my {opinion}, practical work is essential.","note":"in my opinion; give/express/hold/have an opinion of/about","k":"col"},{"w":"pass","vi":"đưa qua; thi đỗ; đi ngang","ex":"{Pass} the worksheet to your partner.","note":"pass sth (over) to sb; pass an exam/test; pass a building","k":"col"},{"w":"point","vi":"hiểu lí lẽ; ích lợi; không ích; chủ ý luôn làm","ex":"There is no {point} in memorising answers without understanding them.","note":"see/take sb's point about; the point in/of; no point in; make a point of V-ing","k":"col"},{"w":"sense","vi":"hiểu; hợp lí; khiếu hài hước/vị giác/thị giác","ex":"The diagram helped us make {sense} of the process.","note":"make sense of; it makes sense to V; a sense of humour/taste/sight","k":"col"},{"w":"suggestion","vi":"đưa/chấp nhận gợi ý","ex":"The class accepted her {suggestion}.","note":"make/accept a suggestion","k":"col"}]},{"type":"v","title":"Cấu tạo từ 1/2 (Word formation)","words":[{"w":"academy","vi":"học viện","note":"academy (n) → academic (adj/n), academically (adv)","full":"học viện → thuộc học thuật/nhà nghiên cứu; về học tập.","ex":"She is doing well {academically}.","hint":"academy","k":"wf"},{"w":"attend","vi":"tham dự","note":"attend (v) → attention (n), attentive/inattentive (adj), attentively/inattentively (adv), attendance, attendant (n)","full":"tham dự → chú ý; chú tâm/thiếu chú tâm; sự có mặt; người phục vụ.","ex":"Regular {attendance} improves progress.","hint":"attend","k":"wf"},{"w":"behave","vi":"cư xử","note":"behave (v) → behaviour (n)","full":"cư xử → hành vi.","ex":"The school encourages responsible {behaviour}.","hint":"behave","k":"wf"},{"w":"certify","vi":"chứng nhận","note":"certify (v) → certificate (n), certified (adj)","full":"chứng nhận → chứng chỉ; được chứng nhận.","ex":"She received a {certificate} of completion.","hint":"certify","k":"wf"},{"w":"educate","vi":"giáo dục","note":"educate (v) → education, educator (n), educational (adj), educationally (adv)","full":"giáo dục → nền/sự giáo dục; nhà giáo; có tính giáo dục.","ex":"The visit was {educational}.","hint":"educate","k":"wf"},{"w":"fail","vi":"thất bại/trượt","note":"fail (v) → failure (n), failing (n/adj)","full":"thất bại/trượt → sự thất bại; điểm yếu/đang suy yếu.","ex":"{Failure} can be an opportunity to learn.","hint":"fail","k":"wf"},{"w":"improve","vi":"cải thiện","note":"improve (v) → improvement (n), improved (adj)","full":"cải thiện → sự cải thiện; đã cải thiện.","ex":"There has been a clear {improvement}.","hint":"improve","k":"wf"},{"w":"intense","vi":"mãnh liệt","note":"intense (adj) → intensity (n), intensify (v), intensely (adv)","full":"mãnh liệt → cường độ; tăng cường; mãnh liệt.","ex":"The course requires intense concentration.","hint":"intense","k":"wf"},{"w":"literate/illiterate","vi":"biết/không biết chữ","note":"literate/illiterate (adj) → literacy/illiteracy, literature (n)","full":"biết/không biết chữ → khả năng đọc viết/nạn mù chữ; văn học.","ex":"The programme promotes {literacy}.","hint":"literate/illiterate","k":"wf"}]},{"type":"v","title":"Cấu tạo từ 2/2 (Word formation)","words":[{"w":"reason","vi":"lí do/lập luận","note":"reason (n/v) → reasonable/unreasonable (adj), reasonably/unreasonably (adv), reasoning (n)","full":"lí do/lập luận → hợp lí/vô lí; suy luận.","ex":"Explain your {reasoning} clearly.","hint":"reason","k":"wf"},{"w":"revise","vi":"ôn/sửa đổi","note":"revise (v) → revision (n), revised (adj)","full":"ôn/sửa đổi → sự ôn/sửa; đã sửa.","ex":"Make a {revision} timetable.","hint":"revise","k":"wf"},{"w":"scholar","vi":"học giả","note":"scholar (n) → scholarship (n), scholarly, scholastic (adj)","full":"học giả → học bổng/học thuật; uyên bác/thuộc nhà trường.","ex":"She won a {scholarship}.","hint":"scholar","k":"wf"},{"w":"solve","vi":"giải","note":"solve (v) → solution (n), solvable/unsolvable (adj)","full":"giải → lời giải; có/không thể giải.","ex":"There is more than one {solution}.","hint":"solve","k":"wf"},{"w":"study","vi":"học/nghiên cứu","note":"study (v/n) → student, studies (n), studious (adj)","full":"học/nghiên cứu → người học; việc học/nghiên cứu; chăm học.","ex":"The {studious} pupil completed every task.","hint":"study","k":"wf"},{"w":"teach","vi":"dạy","note":"teach (v) → teacher (n), taught (V2/V3)","full":"dạy → giáo viên; đã dạy.","ex":"She has {taught} mathematics for years.","hint":"teach","k":"wf"},{"w":"think","vi":"nghĩ","note":"think (v) → thought (V2/V3/n), thinkable/unthinkable, thoughtful, thoughtless (adj)","full":"nghĩ → suy nghĩ; có/không thể nghĩ tới; chu đáo; thiếu suy nghĩ.","ex":"That was a {thoughtful} question.","hint":"think","k":"wf"},{"w":"understand","vi":"hiểu","note":"understand (v) → understanding/misunderstanding (n), understood/misunderstood (V3), understandable (adj), understandably (adv)","full":"hiểu → sự hiểu/hiểu nhầm; đã hiểu/bị hiểu nhầm; có thể thông cảm.","ex":"The {misunderstanding} was resolved.","hint":"understand","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"able to V","vi":"có khả năng làm","ex":"She is able {to} explain the method clearly.","k":"pat"},{"w":"admire sb for N/V-ing","vi":"ngưỡng mộ ai vì","ex":"I admire him {for} working so hard.","k":"pat"},{"w":"boast of/about N/V-ing to sb","vi":"khoe khoang với ai về","ex":"He boasted about getting full marks.","k":"pat"},{"w":"capable of V-ing","vi":"có khả năng","ex":"They are capable {of} solving it independently.","k":"pat"},{"w":"congratulate sb on N/V-ing","vi":"chúc mừng ai về","ex":"We congratulated her {on} passing the exam.","k":"pat"},{"w":"fail to V","vi":"không làm được/không thực hiện","ex":"He failed {to} answer the last question.","k":"pat"},{"w":"hope to V; hope that","vi":"hi vọng làm/rằng","ex":"I hope {to} study engineering.","k":"pat"},{"w":"learn about; learn to V; learn by V- ing","vi":"học về; học cách; học thông qua","ex":"We learn by doing experiments.","k":"pat"},{"w":"settle for/on sth","vi":"chấp nhận lựa chọn chưa tối ưu; quyết định chọn","ex":"They settled on a topic after a long discussion.","k":"pat"},{"w":"similar to","vi":"tương tự với","ex":"This question is similar {to} yesterday's example.","k":"pat"},{"w":"study sth; study for sth","vi":"học môn gì; ôn cho kì thi/bằng cấp","ex":"She is studying {for} her final exams.","k":"pat"},{"w":"succeed in N/V-ing","vi":"thành công trong","ex":"He succeeded {in} improving his score.","k":"pat"},{"w":"suitable for N/V-ing; suitable to V","vi":"phù hợp cho việc/để làm","ex":"This text is suitable {for} beginners.","k":"pat"}]}]},{"g":2,"u":20,"title":"Weather and the Environment","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"urban","pos":"adj","vi":"đô thị","ex":"She moved from a rural village to a suburban home near an {urban} centre.","grp":["urban","suburban","rural"],"k":"topic"},{"w":"suburban","pos":"adj","vi":"ngoại ô","ex":"She moved from a rural village to a {suburban} home near an urban centre.","grp":["urban","suburban","rural"],"k":"topic"},{"w":"rural","pos":"adj","vi":"nông thôn","ex":"She moved from a {rural} village to a suburban home near an urban centre.","grp":["urban","suburban","rural"],"k":"topic"},{"w":"smog","pos":"n","vi":"khói mù ô nhiễm","ex":"Smoke from factories contributed to the {smog}; mist covered the lake.","grp":["smog","fog","smoke","mist"],"k":"topic"},{"w":"fog","pos":"n","vi":"sương mù dày","ex":"Smoke from factories contributed to the smog; mist covered the lake.","grp":["smog","fog","smoke","mist"],"k":"topic"},{"w":"smoke","pos":"n","vi":"khói","ex":"{Smoke} from factories contributed to the smog; mist covered the lake.","grp":["smog","fog","smoke","mist"],"k":"topic"},{"w":"mist","pos":"n","vi":"sương mỏng","ex":"Smoke from factories contributed to the smog; {mist} covered the lake.","grp":["smog","fog","smoke","mist"],"k":"topic"},{"w":"weather","pos":"n","vi":"thời tiết tại thời điểm","ex":"Today's {weather} is cold, although the region has a mild climate.","grp":["weather","climate"],"k":"topic"},{"w":"climate","pos":"n","vi":"khí hậu dài hạn","ex":"Today's weather is cold, although the region has a mild {climate}.","grp":["weather","climate"],"k":"topic"},{"w":"forecast","pos":"n","vi":"dự báo dựa thông tin, thường thời tiết/kinh tế","ex":"The weather {forecast} supported her prediction of rain.","grp":["forecast","prediction"],"k":"topic"},{"w":"prediction","pos":"n","vi":"sự tiên đoán nói chung","ex":"The weather forecast supported her {prediction} of rain.","grp":["forecast","prediction"],"k":"topic"},{"w":"waste","pos":"n","vi":"chất thải/sự lãng phí","ex":"Industrial {waste} polluted the river; litter covered the path.","grp":["waste","litter","rubbish"],"k":"topic"},{"w":"litter","pos":"n","vi":"rác vứt bừa bãi","ex":"Industrial waste polluted the river; {litter} covered the path.","grp":["waste","litter","rubbish"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"rubbish","pos":"n","vi":"rác nói chung (Anh Anh)","ex":"Industrial waste polluted the river; litter covered the path.","grp":["waste","litter","rubbish"],"k":"topic"},{"w":"clean","pos":"adj/v","vi":"sạch/làm sạch","ex":"The water is clear but may not be {clean} enough to drink.","grp":["clean","clear"],"k":"topic"},{"w":"clear","pos":"adj/v","vi":"quang, trong, không bị chắn/dọn thông","ex":"The water is {clear} but may not be clean enough to drink.","grp":["clean","clear"],"k":"topic"},{"w":"pour","pos":"v","vi":"mưa xối xả","ex":"It drizzled at first, then {poured} until the streets flooded.","grp":["pour","drizzle","flood"],"k":"topic"},{"w":"drizzle","pos":"v","vi":"mưa phùn","ex":"It {drizzled} at first, then poured until the streets flooded.","grp":["pour","drizzle","flood"],"k":"topic"},{"w":"flood","pos":"v","vi":"gây ngập/tràn","ex":"It drizzled at first, then poured until the streets {flooded}.","grp":["pour","drizzle","flood"],"k":"topic"},{"w":"environment","pos":"n","vi":"môi trường sống/tự nhiên","ex":"Protect the {environment} and keep your surroundings tidy.","grp":["environment","surroundings"],"k":"topic"},{"w":"surroundings","pos":"n","vi":"khu vực ngay xung quanh","ex":"Protect the environment and keep your {surroundings} tidy.","grp":["environment","surroundings"],"k":"topic"},{"w":"wind","pos":"n","vi":"gió, không khí chuyển động","ex":"Fresh air entered through the {window} as the wind rose.","grp":["wind","air"],"k":"topic"},{"w":"air","pos":"n","vi":"không khí","ex":"Fresh {air} entered through the window as the wind rose.","grp":["wind","air"],"k":"topic"},{"w":"reservoir","pos":"n","vi":"hồ chứa","ex":"Rain filled the {reservoir}, the pond and every puddle in the road.","grp":["reservoir","lake","puddle","pond"],"k":"topic"},{"w":"lake","pos":"n","vi":"hồ","ex":"Rain filled the reservoir, the pond and every puddle in the road.","grp":["reservoir","lake","puddle","pond"],"k":"topic"},{"w":"puddle","pos":"n","vi":"vũng nước","ex":"Rain filled the reservoir, the pond and every {puddle} in the road.","grp":["reservoir","lake","puddle","pond"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"pond","pos":"n","vi":"ao/hồ nhỏ","ex":"Rain filled the reservoir, the {pond} and every puddle in the road.","grp":["reservoir","lake","puddle","pond"],"k":"topic"},{"w":"thunder","pos":"n","vi":"tiếng sấm","ex":"We saw lightning before hearing {thunder}.","grp":["thunder","lightning"],"k":"topic"},{"w":"lightning","pos":"n","vi":"tia chớp/sét","ex":"We saw {lightning} before hearing thunder.","grp":["thunder","lightning"],"k":"topic"},{"w":"global","pos":"adj","vi":"thuộc toàn cầu","ex":"{Global} warming has worldwide effects.","grp":["global","worldwide"],"k":"topic"},{"w":"worldwide","pos":"adj","vi":"trên khắp thế giới (cũng là adv)","ex":"Global warming has {worldwide} effects.","grp":["global","worldwide"],"k":"topic"},{"w":"plain","pos":"n","vi":"đồng bằng","ex":"The fields lie on a {plain}, far from the desert.","grp":["plain","land","field","desert"],"k":"topic"},{"w":"land","pos":"n","vi":"đất/đất liền","ex":"The fields lie on a plain, far from the desert.","grp":["plain","land","field","desert"],"k":"topic"},{"w":"field","pos":"n","vi":"cánh đồng","ex":"The {fields} lie on a plain, far from the desert.","grp":["plain","land","field","desert"],"k":"topic"},{"w":"desert","pos":"n","vi":"sa mạc","ex":"The fields lie on a plain, far from the {desert}.","grp":["plain","land","field","desert"],"k":"topic"},{"w":"extinct","pos":"adj","vi":"tuyệt chủng","ex":"The {extinct} species can no longer be saved, but endangered ones can.","grp":["extinct","endangered"],"k":"topic"},{"w":"endangered","pos":"adj","vi":"có nguy cơ tuyệt chủng","ex":"The extinct species can no longer be saved, but {endangered} ones can.","grp":["extinct","endangered"],"k":"topic"},{"w":"recycle","pos":"v","vi":"tái chế thành vật liệu/sản phẩm","ex":"Reuse the jar and {recycle} the paper packaging.","grp":["recycle","reuse"],"k":"topic"},{"w":"reuse","pos":"v","vi":"dùng lại","ex":"{Reuse} the jar and recycle the paper packaging.","grp":["recycle","reuse"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"call for","vi":"đòi hỏi, cần","ex":"The situation calls {for} immediate action.","k":"pv"},{"w":"call off","vi":"hủy","ex":"They called {off} the picnic because of the storm.","k":"pv"},{"w":"clear up","vi":"trời quang/tốt lên","ex":"The weather should clear {up} by noon.","k":"pv"},{"w":"cut off","vi":"cô lập nơi chốn; ngắt kết nối/cung cấp","ex":"The village was cut {off} by floodwater.","k":"pv"},{"w":"die down","vi":"dịu dần, yếu đi","ex":"The wind died {down} overnight.","k":"pv"},{"w":"do up","vi":"sửa sang","ex":"They are doing {up} an old house.","k":"pv"},{"w":"face up to","vi":"chấp nhận và đối diện vấn đề","ex":"We must face up {to} the effects of pollution.","k":"pv"},{"w":"get sb down","vi":"làm ai buồn/nản","ex":"The constant rain is getting me {down}.","k":"pv"},{"w":"put down to","vi":"cho là do nguyên nhân gì","ex":"They put the poor harvest down {to} drought.","k":"pv"},{"w":"put out","vi":"dập tắt","ex":"Firefighters put {out} the forest fire.","k":"pv"},{"w":"set in","vi":"bắt đầu và có vẻ sẽ kéo dài","ex":"Cold weather has set {in}.","k":"pv"},{"w":"stand for","vi":"viết tắt/đại diện cho; chịu đựng","ex":"What does this symbol stand {for}? I will not stand for littering.","k":"pv"},{"w":"tear down","vi":"phá dỡ","ex":"They tore {down} the unsafe building.","k":"pv"},{"w":"throw away","vi":"vứt bỏ","ex":"Do not throw {away} reusable bags.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"control","vi":"mất/nắm/có kiểm soát","ex":"The fire quickly got out of {control}.","note":"lose/take/have control of; in control; out of control","k":"col"},{"w":"effect","vi":"có ảnh hưởng; bắt đầu hiệu lực","ex":"The new restrictions take {effect} tomorrow.","note":"have an effect on; take effect","k":"col"},{"w":"end","vi":"cuối cùng; ở cuối; kết thúc; kết thúc tốt","ex":"At the {end} of winter, the severe weather came to an end.","note":"in the end; at the end of; come to an end; come to/reach the end of; a happy ending","k":"col"},{"w":"floor","vi":"trên sàn; ở tầng trệt/một/hai (Anh Anh)","ex":"Their flat is on the first {floor} above the ground floor.","note":"on the floor; on the ground/first/second floor","k":"col"},{"w":"fuss","vi":"làm ầm ĩ","ex":"Do not make a {fuss} about a little rain.","note":"make/cause a fuss about N/V-ing","k":"col"},{"w":"long","vi":"trong suốt; lâu; mất nhiều thời gian; khao khát","ex":"They {longed} for the rain to stop.","note":"(for) as long as; (for) a long time; take a long time to V; long to V; long for N (to V)","k":"col"},{"w":"look","vi":"xem; trông giống; nhìn/tìm","ex":"Take a {look} at the sky; it looks like rain.","note":"have/take a look at; look like; look at/for","k":"col"},{"w":"mess","vi":"làm bừa/làm hỏng; hỗn độn","ex":"The storm left the garden in a {mess}.","note":"make a mess of; in a mess","k":"col"},{"w":"responsibility","vi":"chịu/nhận trách nhiệm","ex":"We all have {responsibility} for protecting wildlife.","note":"have/take (the) responsibility for N/V-ing","k":"col"},{"w":"shower","vi":"tắm vòi sen; cơn mưa rào nhẹ/nặng hạt","ex":"A heavy {shower} of rain interrupted the walk.","note":"take/have a shower; a rain shower; a light/heavy shower of rain","k":"col"},{"w":"sight","vi":"thấy/mất dấu; trong tầm thấy; thoạt nhìn","ex":"We lost {sight} of the boat in the fog.","note":"catch/lose sight of; in sight of; at first sight","k":"col"},{"w":"waste","vi":"lãng phí thời gian; chất thải công nghiệp/sinh hoạt","ex":"Throwing away usable food is a {waste} of resources.","note":"a waste of time; waste your time; industrial/household waste","k":"col"},{"w":"weather","vi":"dự báo; không khỏe","ex":"He felt under the {weather} after the trip.","note":"weather forecast; under the weather","k":"col"},{"w":"world","vi":"khắp thế giới; toàn thế giới; kỉ lục","ex":"Scientists around the {world} are studying climate change.","note":"all over/around/throughout the world; the whole world; in the world; world record","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"accurate/inaccurate","vi":"chính xác/sai lệch; độ chính xác/sự sai lệch.","note":"accurate/inaccurate (adj) → accurately/inaccurately (adv), accuracy/inaccuracy (n)","full":"chính xác/sai lệch; độ chính xác/sự sai lệch.","ex":"Forecast {accuracy} has improved.","hint":"accurate/inaccurate","k":"wf"},{"w":"danger","vi":"nguy hiểm","note":"danger (n) → dangerous (adj), dangerously (adv), endanger (v), endangered (adj)","full":"nguy hiểm → nguy hiểm; gây nguy hiểm; có nguy cơ tuyệt chủng.","ex":"Pollution endangers wildlife.","hint":"danger","k":"wf"},{"w":"develop","vi":"phát triển","note":"develop (v) → developed/undeveloped/developing (adj), developer, development (n)","full":"phát triển → đã/chưa/đang phát triển; nhà phát triển; sự phát triển.","ex":"The region needs sustainable {development}.","hint":"develop","k":"wf"},{"w":"environment","vi":"môi trường","note":"environment (n) → environmental (adj), environmentally (adv), environmentalist (n)","full":"môi trường → thuộc môi trường; nhà hoạt động môi trường.","ex":"They support {environmentally} friendly transport.","hint":"environment","k":"wf"},{"w":"extreme","vi":"cực đoan/cực độ","note":"extreme (adj) → extremely (adv), extremity, extremist (n)","full":"cực đoan/cực độ → rất; mức cực độ/đầu mút; người cực đoan.","ex":"Extreme weather is becoming more frequent.","hint":"extreme","k":"wf"},{"w":"freeze","vi":"đóng băng","note":"freeze (v) → froze (V2), frozen (V3/adj), freezing (adj), freezer (n)","full":"đóng băng → đã đóng băng; lạnh cóng; tủ đông.","ex":"The lake {froze} during the night.","hint":"freeze","k":"wf"},{"w":"globe","vi":"địa cầu","note":"globe (n) → global (adj), globally (adv)","full":"địa cầu → toàn cầu; trên toàn cầu.","ex":"The issue matters {globally}.","hint":"globe","k":"wf"},{"w":"great","vi":"lớn/vĩ đại","note":"great (adj) → greatly (adv), greatness (n)","full":"lớn/vĩ đại → rất nhiều; sự vĩ đại.","ex":"The work is {greatly} appreciated.","hint":"great","k":"wf"},{"w":"harm","vi":"tổn hại","note":"harm (n/v) → harmful/harmless (adj), harmfully/harmlessly (adv), harmed/unharmed (adj)","full":"tổn hại → có hại/vô hại; bị/không bị hại.","ex":"The chemical is {harmful} to fish.","hint":"harm","k":"wf"},{"w":"likely/unlikely","vi":"có/không có khả năng","note":"likely/unlikely (adj) → likelihood (n)","full":"có/không có khả năng → khả năng xảy ra.","ex":"There is little {likelihood} of snow.","hint":"likely/unlikely","k":"wf"},{"w":"low","vi":"thấp","note":"low (adj) → lower (adj/v), lowness (n)","full":"thấp → thấp hơn/hạ xuống; sự thấp.","ex":"We need to {lower} emissions.","hint":"low","k":"wf"},{"w":"nature","vi":"tự nhiên","note":"nature (n) → natural/unnatural (adj), naturally/unnaturally (adv)","full":"tự nhiên → tự nhiên/không tự nhiên; trạng từ.","ex":"Protect the {natural} environment.","hint":"nature","k":"wf"},{"w":"neighbour","vi":"hàng xóm","note":"neighbour (n) → neighbourly, neighbouring (adj), neighbourhood (n)","full":"hàng xóm → thân thiện/lân cận; khu dân cư.","ex":"{Neighbouring} villages shared supplies.","hint":"neighbour","k":"wf"},{"w":"pollute","vi":"gây ô nhiễm","note":"pollute (v) → polluted/unpolluted (adj), pollution, pollutant (n)","full":"gây ô nhiễm → ô nhiễm/không ô nhiễm; sự/chất gây ô nhiễm.","ex":"The river contains several pollutants.","hint":"pollute","k":"wf"},{"w":"reside","vi":"cư trú","note":"reside (v) → residential (adj), resident, residence (n)","full":"cư trú → thuộc dân cư; cư dân; nơi cư trú.","ex":"Residents opposed the factory.","hint":"reside","k":"wf"},{"w":"sun","vi":"mặt trời","note":"sun (n) → sunny (adj), sunshine (n)","full":"mặt trời → có nắng; ánh nắng.","ex":"The afternoon was warm and {sunny}.","hint":"sun","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"aware of; aware that","vi":"nhận thức về/rằng","ex":"Are you aware {of} the risk?","k":"pat"},{"w":"covered in/with","vi":"được phủ đầy","ex":"The hills were covered {in} snow.","k":"pat"},{"w":"disappointed with/by sth; disappointed in sb","vi":"thất vọng về việc/bởi việc; thất vọng ở người","ex":"We were disappointed {with} the weather.","k":"pat"},{"w":"except (for) N/V-ing","vi":"ngoại trừ","ex":"The area was quiet except {for} the wind.","k":"pat"},{"w":"expect sth/sb (to V); expect that","vi":"mong/đoán ai/điều gì xảy ra","ex":"We expect the rain {to} stop soon.","k":"pat"},{"w":"familiar with; familiar to sb","vi":"quen/biết điều gì; quen thuộc với ai","ex":"I am familiar {with} this route; the village is familiar to me.","k":"pat"},{"w":"famous for N/V-ing","vi":"nổi tiếng về","ex":"The town is famous {for} its clean beaches.","k":"pat"},{"w":"glance at","vi":"liếc nhìn","ex":"She glanced {at} the forecast.","k":"pat"},{"w":"hard to V; hard V-ing","vi":"khó làm; hard work không có a khi work chỉ công việc","ex":"It is hard {to} predict the weather. It was hard climbing in the heat.","k":"pat"},{"w":"prevent sth; prevent sb from V-ing; prevent sth from happening","vi":"ngăn chặn; ngăn ai làm/ngăn việc xảy ra","ex":"The barrier prevents cars {from} entering.","k":"pat"},{"w":"short of; short on","vi":"thiếu, không đủ (short on thường ít trang trọng)","ex":"The village is short {of} clean water.","k":"pat"},{"w":"warn sb about/against; warn sb of; warn sb not to V; warn (sb) that","vi":"cảnh báo về/đừng làm; báo nguy; cảnh báo rằng","ex":"They warned us not to cross the flooded road.","k":"pat"}]}]},{"g":2,"u":22,"title":"Money and Shopping","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"economic","pos":"adj","vi":"thuộc kinh tế","ex":"{Economic} growth does not always make a car economical to run.","grp":["economic","economical"],"k":"topic"},{"w":"economical","pos":"adj","vi":"tiết kiệm, ít tốn kém","ex":"Economic growth does not always make a car {economical} to run.","grp":["economic","economical"],"k":"topic"},{"w":"receipt","pos":"n","vi":"biên lai đã thanh toán","ex":"Pay the bill and keep the {receipt}.","grp":["receipt","bill"],"k":"topic"},{"w":"bill","pos":"n","vi":"hóa đơn/yêu cầu thanh toán","ex":"Pay the {bill} and keep the receipt.","grp":["receipt","bill"],"k":"topic"},{"w":"make","pos":"n","vi":"hãng/kiểu sản xuất, thường máy/xe","ex":"What {make} is your car? Which brand of coffee do you buy?","grp":["make","brand"],"k":"topic"},{"w":"brand","pos":"n","vi":"nhãn hiệu","ex":"What make is your car? Which {brand} of coffee do you buy?","grp":["make","brand"],"k":"topic"},{"w":"bargain","pos":"n","vi":"món hời","ex":"I found a {bargain} in the summer sale.","grp":["bargain","sale"],"k":"topic"},{"w":"sale","pos":"n","vi":"việc bán/đợt giảm giá","ex":"I found a bargain in the summer {sale}.","grp":["bargain","sale"],"k":"topic"},{"w":"discount","pos":"n","vi":"mức giảm giá","ex":"The special offer includes a ten- percent {discount}.","grp":["discount","offer"],"k":"topic"},{"w":"offer","pos":"n","vi":"ưu đãi/đề nghị","ex":"The special {offer} includes a ten- percent discount.","grp":["discount","offer"],"k":"topic"},{"w":"price","pos":"n","vi":"giá được yêu cầu","ex":"The purchase {price} is low, but running costs are high.","grp":["price","cost"],"k":"topic"},{"w":"cost","pos":"n","vi":"chi phí để mua/làm/vận hành","ex":"The purchase price is low, but running {costs} are high.","grp":["price","cost"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"change","pos":"n","vi":"tiền lẻ/tiền thừa trả lại","ex":"I paid in cash and received some {change}.","grp":["change","cash"],"k":"topic"},{"w":"cash","pos":"n","vi":"tiền mặt","ex":"I paid in {cash} and received some change.","grp":["change","cash"],"k":"topic"},{"w":"wealth","pos":"n","vi":"sự giàu có/tài sản lớn","ex":"He made a fortune but did not display his {wealth}.","grp":["wealth","fortune"],"k":"topic"},{"w":"fortune","pos":"n","vi":"khối tài sản lớn/vận may","ex":"He made a {fortune} but did not display his wealth.","grp":["wealth","fortune"],"k":"topic"},{"w":"till","pos":"n","vi":"máy/quầy thu tiền","ex":"The checkout assistant put the money in the {till}.","grp":["till","checkout"],"k":"topic"},{"w":"checkout","pos":"n","vi":"khu vực thanh toán, nhất là siêu thị","ex":"The {checkout} assistant put the money in the till.","grp":["till","checkout"],"k":"topic"},{"w":"products","pos":"n","vi":"sản phẩm tạo ra","ex":"The factory's {products} are sold with other household goods.","grp":["products","goods"],"k":"topic"},{"w":"goods","pos":"n","vi":"hàng hóa, thường dùng số nhiều","ex":"The factory's products are sold with other household {goods}.","grp":["products","goods"],"k":"topic"},{"w":"refund","pos":"n/v","vi":"hoàn tiền","ex":"You can ask for a {refund} or exchange the shirt.","grp":["refund","exchange"],"k":"topic"},{"w":"exchange","pos":"n/v","vi":"đổi hàng/vật","ex":"You can ask for a refund or {exchange} the shirt.","grp":["refund","exchange"],"k":"topic"},{"w":"fake","pos":"adj/n","vi":"giả/đồ giả","ex":"The {fake} leather bag had a plastic handle.","grp":["fake","plastic"],"k":"topic"},{"w":"plastic","pos":"adj/n","vi":"bằng nhựa/nhựa; vật bằng nhựa không nhất thiết là giả","ex":"The fake leather bag had a {plastic} handle.","grp":["fake","plastic"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"bank on","vi":"trông cậy vào","ex":"Do not bank {on} getting a discount.","k":"pv"},{"w":"come across","vi":"tình cờ tìm thấy/gặp","ex":"I came {across} a rare book in the shop.","k":"pv"},{"w":"come by","vi":"kiếm/thu được, nhất là thứ khó có","ex":"Affordable flats are hard to come {by}.","k":"pv"},{"w":"come into","vi":"thừa hưởng tiền/tài sản","ex":"She came {into} some money last year.","k":"pv"},{"w":"do without","vi":"xoay xở sống không có","ex":"We can do {without} a new television.","k":"pv"},{"w":"get by","vi":"xoay xở đủ sống","ex":"They get {by} on a small income.","k":"pv"},{"w":"get through","vi":"dùng hết, tiêu hết","ex":"We got {through} all our savings.","k":"pv"},{"w":"give away","vi":"cho miễn phí; tiết lộ bí mật","ex":"The shop gave {away} samples; the advert gave away the surprise.","k":"pv"},{"w":"live on","vi":"sống bằng nguồn tiền/thức ăn","ex":"They live {on} a pension.","k":"pv"},{"w":"look round","vi":"xem quanh một nơi","ex":"May I look {round} before deciding?","k":"pv"},{"w":"make out","vi":"điền đầy đủ séc/giấy tờ","ex":"Make the cheque {out} to the school.","k":"pv"},{"w":"make up for","vi":"bù đắp","ex":"The discount made up {for} the delivery charge.","k":"pv"},{"w":"put by","vi":"để dành tiền","ex":"I put a little money {by} each month.","k":"pv"},{"w":"save up for","vi":"tích góp để mua/làm gì","ex":"She is saving up {for} a laptop.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"amount","vi":"lượng; với lượng lớn/nhỏ; tổng cộng","ex":"The repairs {amounted} to two million dong.","note":"an amount of; in large/small amounts; amount to","k":"col"},{"w":"charge","vi":"tính phí; trả phí; nhận/phụ trách","ex":"They {charge} customers a small delivery fee.","note":"charge sb an amount; pay a charge; take charge of; in charge of","k":"col"},{"w":"debt","vi":"mắc nợ; trả hết nợ; mang ơn","ex":"They cleared their {debt} after two years.","note":"in debt to; get in/into debt; clear a debt; owe sb a debt of gratitude","k":"col"},{"w":"demand","vi":"được săn đón; theo yêu cầu; nhu cầu về","ex":"There is growing {demand} for reusable products.","note":"in demand; on demand; a demand for","k":"col"},{"w":"enough","vi":"có đủ/chán ngấy; đủ để; quá đủ rồi","ex":"We have {enough} money to buy the tickets.","note":"have enough of sth; have enough N to V; enough is enough","k":"col"},{"w":"expense","vi":"do ai chi trả; bỏ tiền; chi phí kinh doanh; tài khoản công tác phí","ex":"The company paid our travel {expenses}.","note":"at sb's/your own expense; go to the expense of; business expense; expense account","k":"col"},{"w":"fortune","vi":"kiếm/thắng/tiêu rất nhiều; rất đắt; làm giàu","ex":"The repairs cost a {fortune}.","note":"make/earn/win/spend a fortune; cost a fortune; make your fortune","k":"col"},{"w":"increase","vi":"sự tăng của thứ gì với mức tăng; tăng lương/giá","ex":"There was an {increase} in prices of five percent.","note":"an increase in sth of an amount; a wage/price increase","k":"col"},{"w":"least","vi":"ít nhất; tối thiểu; cuối nhưng vẫn quan trọng; nói giảm đi","ex":"The service was disappointing, to say the {least}.","note":"at least; at the very least; last but not least; to say the least","k":"col"},{"w":"money","vi":"kiếm/thắng/tiết kiệm; tiêu; thiếu; làm vì tiền","ex":"She spends little {money} on clothes.","note":"make/earn/win/save/have money; spend money on N/V- ing; short of money; do sth for the money","k":"col"},{"w":"notice","vi":"thấy cả việc/đang làm; chú ý; báo gấp; báo trước","ex":"We could not arrange delivery at such short {notice}.","note":"notice sb do/V-ing; take notice of; at short notice; give sb notice of","k":"col"},{"w":"profit","vi":"thu lợi nhuận từ","ex":"The shop made a {profit} from online sales.","note":"make a profit from","k":"col"},{"w":"save","vi":"tiết kiệm; để dành","ex":"Buying in bulk can {save} money.","note":"save money/time; save sth for later","k":"col"},{"w":"shopping","vi":"mua đồ cần thiết; đi mua sắm; trung tâm; xem hàng không mua","ex":"We went window {shopping} after doing the grocery shopping.","note":"do the shopping; go shopping; shopping centre; window shopping","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"accept","vi":"chấp nhận","note":"accept (v) → acceptance (n), accepting (adj), acceptable/unacceptable (adj), acceptably/unacceptably (adv)","full":"chấp nhận → sự chấp nhận; bao dung; chấp nhận được/không được.","ex":"The delay was {unacceptable}.","hint":"accept","k":"wf"},{"w":"assist","vi":"giúp","note":"assist (v) → assistance, assistant (n)","full":"giúp → sự giúp đỡ; trợ lí.","ex":"Ask the shop assistant for {assistance}.","hint":"assist","k":"wf"},{"w":"day","vi":"ngày","note":"day (n) → daily (adj/adv), everyday (adj)","full":"ngày → hằng ngày; thông thường; every day là cụm trạng ngữ viết tách.","ex":"These are {everyday} expenses that we pay every day.","hint":"day","k":"wf"},{"w":"economy","vi":"nền kinh tế","note":"economy (n) → economic, economical/uneconomical (adj), economically/uneconomically (adv), economics, economist (n)","full":"nền kinh tế → thuộc kinh tế; tiết kiệm/tốn kém; kinh tế học; nhà kinh tế.","ex":"An {economist} explained the economic changes.","hint":"economy","k":"wf"},{"w":"end","vi":"kết thúc","note":"end (n/v) → endless (adj), endlessly (adv), ending (n), unending (adj)","full":"kết thúc → vô tận; không ngừng; phần kết; không dứt.","ex":"There seemed to be an {endless} queue.","hint":"end","k":"wf"},{"w":"expense","vi":"chi phí","note":"expense (n) → expensive/inexpensive (adj), expensively/inexpensively (adv), expenses (n số nhiều)","full":"chi phí → đắt/rẻ; các khoản chi.","ex":"The meal was surprisingly {inexpensive}.","hint":"expense","k":"wf"},{"w":"finance","vi":"tài chính/cấp vốn","note":"finance (n/v) → financial (adj), financially (adv), finances (n số nhiều)","full":"tài chính/cấp vốn → thuộc tài chính; tình hình tài chính.","ex":"They received {financial} advice.","hint":"finance","k":"wf"},{"w":"invest","vi":"đầu tư","note":"invest (v) → investment, investor (n)","full":"đầu tư → khoản đầu tư; nhà đầu tư.","ex":"The {investment} was profitable.","hint":"invest","k":"wf"},{"w":"luxury","vi":"đồ xa xỉ","note":"luxury (n) → luxuries (số nhiều), luxurious (adj), luxuriously (adv)","full":"đồ xa xỉ → sang trọng; một cách sang trọng.","ex":"They stayed in a {luxurious} hotel.","hint":"luxury","k":"wf"},{"w":"pay","vi":"trả","note":"pay (v) → paid (V2/V3), payment (n), payable (adj)","full":"trả → đã trả; khoản thanh toán; phải/có thể trả.","ex":"{Payment} is due tomorrow.","hint":"pay","k":"wf"},{"w":"poor","vi":"nghèo/kém","note":"poor (adj) → poorly (adv/adj), poverty (n)","full":"nghèo/kém → kém/không khỏe; sự nghèo.","ex":"The charity works to reduce {poverty}.","hint":"poor","k":"wf"},{"w":"real/unreal","vi":"thật/không thật; thực sự; nhận ra; sự nhận ra/thực tế; thực tế.","note":"real/unreal (adj) → really (adv), realise (v), realisation, reality (n), realistic (adj), realistically (adv)","full":"thật/không thật; thực sự; nhận ra; sự nhận ra/thực tế; thực tế.","ex":"We need a {realistic} budget.","hint":"real/unreal","k":"wf"},{"w":"value","vi":"giá trị","note":"value (n/v) → valuable/invaluable (adj), valuably/invaluably (adv), valueless (adj), valuation (n)","full":"giá trị → có giá trị/vô cùng quý; vô giá trị; sự định giá.","ex":"Her advice was {invaluable}.","hint":"value","k":"wf"},{"w":"wealth","vi":"sự giàu có","note":"wealth (n) → wealthy (adj)","full":"sự giàu có → giàu.","ex":"The {wealthy} donor funded the library.","hint":"wealth","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"demand sth from sb; demand that","vi":"đòi điều gì từ ai; yêu cầu rằng","ex":"The customer demanded a refund.","k":"pat"},{"w":"forget to V; forget V-ing; forget about; forget if/whether","vi":"quên làm; quên việc đã làm; quên về; không nhớ liệu","ex":"I forgot {to} pay. I will never forget buying my first bicycle.","k":"pat"},{"w":"lend sth to sb; lend sb sth","vi":"cho ai mượn","ex":"She lent me her calculator.","k":"pat"},{"w":"pay sb for N/V-ing; pay sth to sb","vi":"trả ai tiền cho; trả khoản tiền cho","ex":"We paid the driver {for} waiting.","k":"pat"},{"w":"profit from N/V-ing","vi":"hưởng lợi từ","ex":"Local shops profit {from} tourism.","k":"pat"},{"w":"save sb from; save sth for sb/sth","vi":"cứu/giúp tránh; giữ dành cho","ex":"Online shopping saved us {from} queuing.","k":"pat"},{"w":"spend sth on N/sb/V-ing","vi":"tiêu tiền/nguồn lực cho","ex":"He spent his savings {on} repairing the house.","k":"pat"}]}]},{"g":2,"u":24,"title":"Entertainment","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"enjoy","pos":"v","vi":"thấy thích","ex":"The comedian entertained us, and we {enjoyed} the show.","grp":["enjoy","entertain"],"k":"topic"},{"w":"entertain","pos":"v","vi":"làm người khác vui/chiêu đãi","ex":"The comedian {entertained} us, and we enjoyed the show.","grp":["enjoy","entertain"],"k":"topic"},{"w":"play","pos":"v","vi":"đóng vai/chơi","ex":"She acts professionally, {plays} a detective and stars in the series.","grp":["play","act","star"],"k":"topic"},{"w":"act","pos":"v","vi":"diễn xuất","ex":"She {acts} professionally, plays a detective and stars in the series.","grp":["play","act","star"],"k":"topic"},{"w":"star","pos":"v","vi":"đóng vai chính","ex":"She acts professionally, plays a detective and {stars} in the series.","grp":["play","act","star"],"k":"topic"},{"w":"audition","pos":"n","vi":"buổi thử vai","ex":"She passed the {audition} and attended every rehearsal.","grp":["audition","rehearsal"],"k":"topic"},{"w":"rehearsal","pos":"n","vi":"buổi tập trước biểu diễn","ex":"She passed the audition and attended every {rehearsal}.","grp":["audition","rehearsal"],"k":"topic"},{"w":"rehearse","pos":"v","vi":"tập chương trình/vở diễn","ex":"We {rehearsed} the scene after practising our pronunciation.","grp":["rehearse","practise"],"k":"topic"},{"w":"practise","pos":"v","vi":"luyện kĩ năng nói chung","ex":"We rehearsed the scene after {practising} our pronunciation.","grp":["rehearse","practise"],"k":"topic"},{"w":"scene","pos":"n","vi":"cảnh trong phim/kịch","ex":"The opening {scene} has beautiful scenery; the actors enter the stage together.","grp":["scene","scenery","stage"],"k":"topic"},{"w":"scenery","pos":"n","vi":"phong cảnh/phông cảnh","ex":"The opening scene has beautiful {scenery}; the actors enter the stage together.","grp":["scene","scenery","stage"],"k":"topic"},{"w":"stage","pos":"n","vi":"sân khấu","ex":"The opening scene has beautiful scenery; the actors enter the {stage} together.","grp":["scene","scenery","stage"],"k":"topic"},{"w":"band","pos":"n","vi":"ban nhạc","ex":"The rock {band} performed before the orchestra.","grp":["band","orchestra","group"],"k":"topic"},{"w":"orchestra","pos":"n","vi":"dàn nhạc nhiều bộ nhạc cụ","ex":"The rock band performed before the {orchestra}.","grp":["band","orchestra","group"],"k":"topic"},{"w":"group","pos":"n","vi":"nhóm/nhóm nhạc","ex":"The rock band performed before the orchestra.","grp":["band","orchestra","group"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"review","pos":"n","vi":"bài đánh giá","ex":"The {review} included some criticism of the acting.","grp":["review","criticism"],"k":"topic"},{"w":"criticism","pos":"n","vi":"sự phê bình/nhận xét, không nhất thiết chỉ tiêu cực","ex":"The review included some {criticism} of the acting.","grp":["review","criticism"],"k":"topic"},{"w":"ticket","pos":"n","vi":"vé","ex":"The booking fee is added to the {ticket} price.","grp":["ticket","fee"],"k":"topic"},{"w":"fee","pos":"n","vi":"phí/thù lao","ex":"The booking {fee} is added to the ticket price.","grp":["ticket","fee"],"k":"topic"},{"w":"novel","pos":"n","vi":"tiểu thuyết cụ thể","ex":"She reads fiction and has written two {novels}.","grp":["novel","fiction"],"k":"topic"},{"w":"fiction","pos":"n","vi":"văn học hư cấu (không đếm được)","ex":"She reads {fiction} and has written two novels.","grp":["novel","fiction"],"k":"topic"},{"w":"comic","pos":"n","vi":"truyện tranh/người diễn hài","ex":"The comedian voiced a character in the cartoon.","grp":["comic","cartoon","comedian"],"k":"topic"},{"w":"cartoon","pos":"n","vi":"tranh/phim hoạt hình","ex":"The comedian voiced a character in the {cartoon}.","grp":["comic","cartoon","comedian"],"k":"topic"},{"w":"comedian","pos":"n","vi":"diễn viên hài","ex":"The {comedian} voiced a character in the cartoon.","grp":["comic","cartoon","comedian"],"k":"topic"},{"w":"watch","pos":"v","vi":"theo dõi có diễn biến","ex":"Look at the screen; we are {watching} a film I have never seen.","grp":["watch","see","look"],"k":"topic"},{"w":"see","pos":"v","vi":"thấy/xem trải nghiệm","ex":"Look at the screen; we are watching a film I have never {seen}.","grp":["watch","see","look"],"k":"topic"},{"w":"look","pos":"v","vi":"chủ ý nhìn, thường + at","ex":"{Look} at the screen; we are watching a film I have never seen.","grp":["watch","see","look"],"k":"topic"},{"w":"listen","pos":"v","vi":"chủ ý nghe (+ to)","ex":"I {listened} carefully but could not hear the singer.","grp":["listen","hear"],"k":"topic"},{"w":"hear","pos":"v","vi":"nghe được","ex":"I listened carefully but could not {hear} the singer.","grp":["listen","hear"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"come (a)round","vi":"lại đến theo chu kì","ex":"The festival comes {round} every summer.","k":"pv"},{"w":"count on","vi":"tin cậy, trông mong","ex":"You can count {on} her to arrive early.","k":"pv"},{"w":"drop off","vi":"ngủ thiếp","ex":"I dropped {off} during the long film.","k":"pv"},{"w":"drown out","vi":"át tiếng","ex":"The applause drowned {out} his final words.","k":"pv"},{"w":"fall for","vi":"tin một trò lừa/đùa","ex":"We all fell {for} the joke.","k":"pv"},{"w":"get along with","vi":"get on with: hòa thuận","ex":"The actors get along well {with} each other.","k":"pv"},{"w":"go down as","vi":"được ghi nhớ với tư cách/thành tích","ex":"The concert will go down {as} a historic event.","k":"pv"},{"w":"grow on","vi":"dần làm ai thích hơn","ex":"The song grew {on} me after a few listens.","k":"pv"},{"w":"let down","vi":"làm thất vọng","ex":"The ending let many viewers {down}.","k":"pv"},{"w":"name after","vi":"đặt tên theo","ex":"The theatre was named {after} a local writer.","k":"pv"},{"w":"put on","vi":"tổ chức, trình diễn","ex":"The school put {on} a musical.","k":"pv"},{"w":"show off","vi":"khoe khoang, phô trương","ex":"He kept showing {off} his expensive guitar.","k":"pv"},{"w":"take after","vi":"giống người thân lớn tuổi","ex":"She takes {after} her mother in looks and humour.","k":"pv"},{"w":"take off","vi":"nhanh chóng nổi tiếng/thành công","ex":"His acting career took {off} last year.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"fun","vi":"vui; thú vị; chế giễu","ex":"The game was {fun}, but making fun of others was unkind.","note":"have fun; be fun; make fun of sb","k":"col"},{"w":"funny","vi":"thấy điều gì buồn cười","ex":"I did not find the joke {funny}.","note":"find sth funny","k":"col"},{"w":"home","vi":"cứ tự nhiên; ở/về/rời nhà; tìm đường về","ex":"Make yourself at {home} while we prepare the snacks.","note":"make yourself at home; be/stay at home; go/get/leave home; make your way home","k":"col"},{"w":"impression","vi":"tạo cảm giác; bắt chước; có cảm giác; gây ấn tượng","ex":"Her performance made a strong {impression} on us.","note":"give sb the impression; do an impression of; have the impression; make an impression on","k":"col"},{"w":"joke","vi":"đùa về/với; kể/nghe/hiểu chuyện đùa","ex":"He told a {joke}, but I did not get it.","note":"joke about N/V-ing; joke with sb; tell/make/hear/get/understand a joke","k":"col"},{"w":"laugh","vi":"cười về/nhạo; cười lớn; cười vang; vui cười","ex":"The audience roared with {laughter}.","note":"laugh at/about; laugh out loud; roar with laughter; have a laugh","k":"col"},{"w":"part","vi":"tham gia; là phần của; chia tay/cho đi; có vai","ex":"She took {part} in the show and had a small part in the play.","note":"take part in; be a part of; part with; have a part in a play","k":"col"},{"w":"party","vi":"tổ chức/dự tiệc","ex":"They threw a birthday {party} for the singer.","note":"have/throw/give sb a party; go to a party; dinner/birthday party","k":"col"},{"w":"play","vi":"đóng vai trò/chơi/diễn/xem kịch","ex":"Music {plays} an important role in the film.","note":"play a part/role in; play with; play sth; have a part/role to play; be/act/star in a play; watch/see a play","k":"col"},{"w":"queue","vi":"xếp/đứng/chờ hàng","ex":"We {queued} up outside the theatre.","note":"join a queue; in a queue; queue up; stand/wait in a queue","k":"col"},{"w":"show","vi":"biểu diễn; bày tỏ; cho xem; trưng bày; nổi bật nhất; ngành giải trí","ex":"The youngest performer stole the {show}.","note":"put on a show; show appreciation for; show sth to sb / sb sth; on show; steal the show; TV/radio/quiz/game show; show business","k":"col"},{"w":"silence","vi":"trong im lặng","ex":"The audience listened in {silence}.","note":"in silence","k":"col"},{"w":"voice","vi":"bằng giọng; hát hay/dở; nêu quan điểm","ex":"She {voiced} her opinion in a calm voice.","note":"in a low/deep/high voice; have a good/bad voice; voice an opinion about","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"act","vi":"diễn/hành động","note":"act (v/n) → active/inactive (adj), actively/inactively (adv), acting, actor, actress, action, activity/inactivity (n)","full":"diễn/hành động → tích cực/không hoạt động; diễn xuất; diễn viên nam/nữ; hành động; hoạt động/sự bất động.","ex":"The actor took an {active} role in rehearsals.","hint":"act","k":"wf"},{"w":"amuse","vi":"làm vui","note":"amuse (v) → amusing/unamusing (adj), amusingly/unamusingly (adv), amusement (n)","full":"làm vui → buồn cười/không vui; sự giải trí.","ex":"The story caused great {amusement}.","hint":"amuse","k":"wf"},{"w":"bore","vi":"làm chán","note":"bore (v) → boring (adj), boringly (adv), bored (adj), boredom (n)","full":"làm chán → gây chán; thấy chán; sự buồn chán.","ex":"I felt {bored} during the speech.","hint":"bore","k":"wf"},{"w":"converse","vi":"trò chuyện","note":"converse (v) → conversation (n)","full":"trò chuyện → cuộc trò chuyện.","ex":"Their {conversation} became the basis of a scene.","hint":"converse","k":"wf"},{"w":"current","vi":"hiện tại","note":"current (adj) → currently (adv)","full":"hiện tại → hiện nay.","ex":"She is {currently} rehearsing a new play.","hint":"current","k":"wf"},{"w":"entertain","vi":"giải trí","note":"entertain (v) → entertaining (adj), entertainment, entertainer (n)","full":"giải trí → thú vị; sự giải trí; nghệ sĩ biểu diễn.","ex":"The {entertainer} kept everyone laughing.","hint":"entertain","k":"wf"},{"w":"excite","vi":"làm hào hứng","note":"excite (v) → exciting/unexciting, excited (adj), excitedly (adv), excitement (n)","full":"làm hào hứng → gây/không gây hào hứng; hào hứng; sự phấn khích.","ex":"There was great {excitement} before the final song.","hint":"excite","k":"wf"},{"w":"fame","vi":"danh tiếng","note":"fame (n) → famous/infamous (adj), famously/infamously (adv)","full":"danh tiếng → nổi tiếng/nổi tiếng xấu; trạng từ.","ex":"The director became {famous} worldwide.","hint":"fame","k":"wf"},{"w":"involve","vi":"liên quan","note":"involve (v) → involved/uninvolved (adj), involvement (n)","full":"liên quan → tham gia/không tham gia; sự tham gia.","ex":"Her {involvement} improved the production.","hint":"involve","k":"wf"},{"w":"perform","vi":"biểu diễn","note":"perform (v) → performing (adj), performance, performer (n)","full":"biểu diễn → thuộc biểu diễn; buổi diễn; người biểu diễn.","ex":"The {performance} received excellent reviews.","hint":"perform","k":"wf"},{"w":"popular/unpopular","vi":"được/không được yêu thích","note":"popular/unpopular (adj) → popularly (adv), popularity (n)","full":"được/không được yêu thích → rộng rãi; sự ưa chuộng.","ex":"The band's {popularity} grew quickly.","hint":"popular/unpopular","k":"wf"},{"w":"say","vi":"nói","note":"say (v) → saying (n)","full":"nói → câu nói/tục ngữ.","ex":"There is an old {saying} about practice.","hint":"say","k":"wf"},{"w":"suggest","vi":"gợi ý","note":"suggest (v) → suggested, suggestive (adj), suggestively (adv), suggestion (n)","full":"gợi ý → được đề xuất; gợi liên tưởng/ám chỉ; lời gợi ý.","ex":"We accepted her {suggestion} for the ending.","hint":"suggest","k":"wf"},{"w":"vary","vi":"thay đổi","note":"vary (v) → variable/invariable (adj), variably/invariably (adv), varying, varied, various (adj), variously (adv), variation, variety (n)","full":"thay đổi → biến đổi/không đổi; khác nhau/đa dạng; sự biến đổi; sự đa dạng.","ex":"The programme offers a {variety} of performances.","hint":"vary","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"apologise to sb for N/V-ing","vi":"xin lỗi ai vì","ex":"He apologised for arriving late.","k":"pat"},{"w":"avoid N/sb/V-ing","vi":"tránh; không dùng avoid to V","ex":"Avoid revealing the ending.","k":"pat"},{"w":"bound to V","vi":"chắc chắn/rất có khả năng","ex":"The show is bound {to} be popular.","k":"pat"},{"w":"deserve N/to V","vi":"xứng đáng nhận/làm","ex":"She deserves {to} win the award.","k":"pat"},{"w":"enjoy yourself; enjoy N/V-ing","vi":"vui vẻ; thích","ex":"We enjoyed ourselves at the concert.","k":"pat"},{"w":"happy to V; happy for sb (to V); happy about","vi":"vui/sẵn lòng làm; mừng cho ai/đồng ý cho ai; vui về","ex":"I am happy for her and happy {to} help.","k":"pat"},{"w":"instead of N/V-ing","vi":"thay vì","ex":"We watched a play instead {of} going to the cinema.","k":"pat"},{"w":"like N/V-ing/to V; be like N/sb; be like sb to V","vi":"thích; giống; đúng kiểu tính cách ai khi làm","ex":"It is {like} him to tell a joke at the wrong moment.","k":"pat"},{"w":"promise to V; promise sb sth; promise that","vi":"hứa làm/cho/rằng","ex":"She promised {to} send us the tickets.","k":"pat"},{"w":"prove to V; prove sth to sb","vi":"chứng tỏ/hóa ra; chứng minh điều gì cho ai","ex":"The film proved {to} be a success.","k":"pat"},{"w":"say sth to sb; say that","vi":"nói điều gì với ai/rằng","ex":"He said that the performance was excellent.","k":"pat"},{"w":"supposed to V","vi":"được cho là/phải làm theo dự định hoặc nghĩa vụ","ex":"The concert is supposed {to} start at eight.","k":"pat"},{"w":"talented at N/V-ing","vi":"có tài về","ex":"She is talented {at} writing dialogue.","k":"pat"}]}]},{"g":2,"u":26,"title":"Fashion and Design","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"put on","pos":"v","vi":"hành động mặc/đeo vào","ex":"She {put on} her coat and wore it all evening.","grp":["put on","wear"],"k":"topic"},{"w":"wear","pos":"v","vi":"trạng thái đang mặc/đeo","ex":"She put on her coat and wore it all evening.","grp":["put on","wear"],"k":"topic"},{"w":"costume","pos":"n","vi":"trang phục hóa trang/biểu diễn/truyền thống","ex":"He wore a dark suit to work and a pirate {costume} to the party.","grp":["costume","suit"],"k":"topic"},{"w":"suit","pos":"n","vi":"bộ quần áo đồng bộ, thường áo khoác và quần/váy","ex":"He wore a dark {suit} to work and a pirate costume to the party.","grp":["costume","suit"],"k":"topic"},{"w":"dye","pos":"v/n","vi":"nhuộm/thuốc nhuộm thấm vào vật liệu","ex":"She {dyed} the fabric blue and painted the wooden buttons.","grp":["dye","paint"],"k":"topic"},{"w":"paint","pos":"v/n","vi":"sơn/vẽ bằng lớp màu bề mặt","ex":"She dyed the fabric blue and {painted} the wooden buttons.","grp":["dye","paint"],"k":"topic"},{"w":"fit","pos":"v","vi":"vừa kích thước","ex":"The jacket {fits} me, suits my style and matches my trousers.","grp":["fit","suit","match"],"k":"topic"},{"w":"suit","pos":"v","vi":"hợp người/hoàn cảnh","ex":"The jacket fits me, {suits} my style and matches my trousers.","grp":["fit","suit","match"],"k":"topic"},{"w":"match","pos":"v","vi":"hợp/đồng màu, kiểu với vật khác","ex":"The jacket fits me, suits my style and {matches} my trousers.","grp":["fit","suit","match"],"k":"topic"},{"w":"cloth","pos":"n","vi":"vải, miếng vải","ex":"The {clothing} is made from soft cotton cloth.","grp":["cloth","clothing"],"k":"topic"},{"w":"clothing","pos":"n","vi":"quần áo nói chung, không đếm được","ex":"The {clothing} is made from soft cotton cloth.","grp":["cloth","clothing"],"k":"topic"},{"w":"blouse","pos":"n","vi":"áo kiểu nữ","ex":"She chose a silk {blouse} rather than a casual top.","grp":["blouse","top"],"k":"topic"},{"w":"top","pos":"n","vi":"áo mặc phần trên nói chung","ex":"She chose a silk blouse rather than a casual {top}.","grp":["blouse","top"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"design","pos":"v","vi":"thiết kế","ex":"They {design} the shoes here but manufacture them elsewhere.","grp":["design","manufacture"],"k":"topic"},{"w":"manufacture","pos":"v","vi":"sản xuất, thường hàng loạt bằng máy","ex":"They design the shoes here but {manufacture} them elsewhere.","grp":["design","manufacture"],"k":"topic"},{"w":"current","pos":"adj","vi":"hiện hành/hiện tại","ex":"The new collection updates the {current} range with a modern look.","grp":["current","new","modern"],"k":"topic"},{"w":"new","pos":"adj","vi":"mới","ex":"The {new} collection updates the current range with a modern look.","grp":["current","new","modern"],"k":"topic"},{"w":"modern","pos":"adj","vi":"hiện đại","ex":"The new collection updates the current range with a {modern} look.","grp":["current","new","modern"],"k":"topic"},{"w":"look","pos":"n","vi":"vẻ/phong cách","ex":"A new haircut changed his appearance and gave him a smarter {look}.","grp":["look","appearance"],"k":"topic"},{"w":"appearance","pos":"n","vi":"diện mạo bên ngoài","ex":"A new haircut changed his {appearance} and gave him a smarter look.","grp":["look","appearance"],"k":"topic"},{"w":"supply","pos":"v","vi":"cung cấp","ex":"The factory produces fabric and {supplies} it to local designers.","grp":["supply","produce"],"k":"topic"},{"w":"produce","pos":"v","vi":"sản xuất/tạo ra","ex":"The factory {produces} fabric and supplies it to local designers.","grp":["supply","produce"],"k":"topic"},{"w":"glimpse","pos":"n/v","vi":"thoáng thấy","ex":"I {glimpsed} her in the crowd, then glanced at my watch.","grp":["glimpse","glance"],"k":"topic"},{"w":"glance","pos":"n/v","vi":"chủ ý liếc nhanh","ex":"I glimpsed her in the crowd, then {glanced} at my watch.","grp":["glimpse","glance"],"k":"topic"},{"w":"average","pos":"adj","vi":"trung bình/điển hình","ex":"The {average} customer wants comfortable everyday clothes.","grp":["average","everyday"],"k":"topic"},{"w":"everyday","pos":"adj","vi":"thường ngày, không đặc biệt","ex":"The average customer wants comfortable {everyday} clothes.","grp":["average","everyday"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"catch on","vi":"trở nên thịnh hành","ex":"The style caught {on} quickly.","k":"pv"},{"w":"do away with","vi":"loại bỏ","ex":"The school did away {with} the old uniform.","k":"pv"},{"w":"draw up","vi":"soạn/lập kế hoạch, văn bản","ex":"They drew {up} a design brief.","k":"pv"},{"w":"dress up","vi":"mặc trang trọng/đặc biệt hoặc hóa trang","ex":"The children dressed {up} as animals.","k":"pv"},{"w":"go over","vi":"xem/nghĩ lại kĩ để hiểu","ex":"Let's go {over} the measurements again.","k":"pv"},{"w":"grow out of","vi":"phát triển từ; lớn quá không mặc vừa","ex":"She has grown out {of} her winter coat.","k":"pv"},{"w":"hand down","vi":"truyền/để lại cho thế hệ sau","ex":"The ring was handed {down} to her daughter.","k":"pv"},{"w":"line up","vi":"xếp thành hàng","ex":"The models lined {up} backstage.","k":"pv"},{"w":"pop in / pop into","vi":"ghé nhanh","ex":"I popped {into} the shop on my way home.","k":"pv"},{"w":"show (a)round","vi":"dẫn đi tham quan","ex":"The designer showed us {round} the studio.","k":"pv"},{"w":"take off","vi":"cởi/bỏ đồ đang mặc","ex":"Take {off} your wet shoes.","k":"pv"},{"w":"tear up","vi":"xé thành mảnh","ex":"He tore {up} the unsuccessful sketch.","k":"pv"},{"w":"try on","vi":"mặc thử","ex":"Try the jacket {on} before buying it.","k":"pv"},{"w":"wear out","vi":"mòn/hỏng vì dùng lâu","ex":"These shoes have worn {out}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"art","vi":"tác phẩm; nghệ thuật hiện đại; phòng tranh; triển lãm","ex":"The gallery is holding a modern {art} exhibition.","note":"a work of art; modern art; art gallery; art exhibition","k":"col"},{"w":"clothes","vi":"mặc/thử/cởi; dây/kẹp phơi; đồ đẹp nhất","ex":"Hang the {clothes} on the clothes line.","note":"put on/try on/wear/take off clothes; clothes line; clothes peg; best clothes","k":"col"},{"w":"combination","vi":"kết hợp với; sự kết hợp","ex":"The design uses a {combination} of wool and silk.","note":"in combination with; a combination of","k":"col"},{"w":"compliment","vi":"khen ai về","ex":"She paid him a {compliment} on his jacket.","note":"pay sb a compliment; compliment sb on","k":"col"},{"w":"example","vi":"làm gương; ví dụ của; chẳng hạn; noi gương","ex":"The company set an {example} by recycling fabric.","note":"be/set an example; an example of; for example; follow an/sb's example","k":"col"},{"w":"fashion","vi":"hợp/lỗi mốt; chạy theo mốt; người mẫu/buổi diễn","ex":"This colour is back in {fashion}.","note":"in fashion; be/go out of fashion; follow fashion; fashion model/show","k":"col"},{"w":"hair","vi":"cắt/chải; kiểu tóc mới; cắt tóc; thư giãn hết mình","ex":"She had a {haircut} before the show.","note":"cut/brush sb's hair; have/get a new hairdo/hairstyle; have a haircut; let your hair down","k":"col"},{"w":"make-up","vi":"trang điểm/đang trang điểm/tẩy trang","ex":"She took off her {make-up} after the performance.","note":"put on/apply/wear/take off make-up","k":"col"},{"w":"pattern","vi":"theo mẫu; họa tiết ca-rô/sọc/trơn","ex":"The fabric has a striped {pattern}.","note":"follow a pattern; a checked/striped/plain pattern","k":"col"},{"w":"style","vi":"hợp mốt; lỗi mốt; sang trọng; có phong cách","ex":"They arrived at the ceremony in {style}.","note":"in style; be/go out of style; do sth/go somewhere in style; have style","k":"col"},{"w":"taste","vi":"có gu tốt/kém; phù hợp/kém duyên","ex":"She has good {taste} in clothes.","note":"have/show good/bad taste in; in good/bad taste","k":"col"},{"w":"tendency","vi":"có xu hướng","ex":"This fabric has a {tendency} to shrink.","note":"have a tendency to V","k":"col"},{"w":"trend","vi":"xu hướng; theo/tạo xu hướng","ex":"The designer set a new {trend} in sportswear.","note":"a trend in; follow/set a trend","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"advertise","vi":"quảng cáo","note":"advertise (v) → advertisement, ad/advert, advertising, advertiser (n)","full":"quảng cáo → mẩu quảng cáo; ngành/việc quảng cáo; bên quảng cáo.","ex":"The {advertisement} attracted new customers.","hint":"advertise","k":"wf"},{"w":"attract","vi":"thu hút","note":"attract (v) → attractive/unattractive (adj), attractively/unattractively (adv), attraction (n)","full":"thu hút → hấp dẫn/không hấp dẫn; sức hút.","ex":"The display was {attractively} arranged.","hint":"attract","k":"wf"},{"w":"beauty","vi":"vẻ đẹp","note":"beauty (n) → beautiful (adj), beautifully (adv)","full":"vẻ đẹp → đẹp; một cách đẹp.","ex":"The dress was {beautifully} made.","hint":"beauty","k":"wf"},{"w":"decide","vi":"quyết định","note":"decide (v) → decision (n), decisive/indecisive (adj), decisively/indecisively (adv), undecided (adj)","full":"quyết định → quyết định; dứt khoát/thiếu quyết đoán; chưa quyết.","ex":"She remained {undecided} about the colour.","hint":"decide","k":"wf"},{"w":"desire","vi":"mong muốn","note":"desire (n/v) → desirable/undesirable (adj)","full":"mong muốn → đáng mong muốn/không mong muốn.","ex":"Durability is a {desirable} quality.","hint":"desire","k":"wf"},{"w":"enthuse","vi":"tỏ hứng thú","note":"enthuse (v) → enthusiastic/unenthusiastic (adj), enthusiastically/unenthusiastically (adv), enthusiasm, enthusiast (n)","full":"tỏ hứng thú → nhiệt tình/không nhiệt tình; nhiệt huyết; người say mê.","ex":"The team showed great {enthusiasm}.","hint":"enthuse","k":"wf"},{"w":"expect","vi":"mong đợi","note":"expect (v) → expected/unexpected (adj), expectedly/unexpectedly (adv), expectation, expectancy (n)","full":"mong đợi → dự kiến/bất ngờ; kì vọng; trạng thái mong chờ/tuổi thọ.","ex":"Sales exceeded expectations.","hint":"expect","k":"wf"},{"w":"fashion","vi":"thời trang","note":"fashion (n) → fashionable/unfashionable (adj), fashionably/unfashionably (adv)","full":"thời trang → hợp/không hợp mốt; trạng từ.","ex":"The style became {fashionable} again.","hint":"fashion","k":"wf"},{"w":"like","vi":"thích","note":"like (v) → alike (adj/adv), dislike (v/n), unlike (prep/adj), likeness (n), likeable/unlikeable (adj), liking (n)","full":"thích → giống nhau; không thích; khác; sự giống; dễ/khó mến; sự ưa thích.","ex":"The two designs look {alike}.","hint":"like","k":"wf"},{"w":"produce","vi":"sản xuất","note":"produce (v) → product, producer, production (n), productive/unproductive (adj), productively/unproductively (adv)","full":"sản xuất → sản phẩm; nhà sản xuất; sản xuất; hiệu quả/không hiệu quả.","ex":"The factory increased {production}.","hint":"produce","k":"wf"},{"w":"similar/dissimilar","vi":"giống/khác","note":"similar/dissimilar (adj) → similarly/dissimilarly (adv), similarity (n)","full":"giống/khác → tương tự/khác biệt; nét tương đồng.","ex":"There is a {similarity} between the patterns.","hint":"similar/dissimilar","k":"wf"},{"w":"style","vi":"phong cách","note":"style (n/v) → stylish/unstylish (adj), stylishly/unstylishly (adv), stylist, stylishness (n)","full":"phong cách → sành/không sành điệu; nhà tạo mẫu; vẻ sành điệu.","ex":"A {stylist} helped prepare the models.","hint":"style","k":"wf"},{"w":"succeed","vi":"thành công","note":"succeed (v) → success (n), successful/unsuccessful (adj), successfully/unsuccessfully (adv)","full":"thành công → sự thành công; thành/không thành công.","ex":"The collection sold {successfully}.","hint":"succeed","k":"wf"},{"w":"use","vi":"dùng","note":"use (v/n) → usage (n), useful/useless (adj), usefully/uselessly (adv), user (n), usable/unusable (adj)","full":"dùng → cách dùng; hữu ích/vô ích; người dùng; dùng được/không được.","ex":"The damaged material was {unusable}.","hint":"use","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"criticise sb for N/V-ing","vi":"phê bình vì","ex":"They criticised the company {for} wasting material.","k":"pat"},{"w":"insist on N/V-ing; insist that","vi":"khăng khăng/yêu cầu","ex":"She insisted {on} checking every measurement.","k":"pat"},{"w":"plenty of N; plenty more N; plenty to V","vi":"nhiều/đủ; còn nhiều; nhiều việc để làm","ex":"There is plenty {of} fabric and plenty to do.","k":"pat"},{"w":"prepare sb for sth; prepare to V","vi":"chuẩn bị cho ai trước việc; chuẩn bị làm","ex":"They prepared the models {for} the show.","k":"pat"},{"w":"proud of N/sb/V-ing; proud to V","vi":"tự hào về/được làm","ex":"She is proud {of} designing her own clothes.","k":"pat"},{"w":"refer to; refer sb to sth","vi":"đề cập/tra cứu; hướng ai đến nguồn/nơi","ex":"Refer {to} the size chart before ordering.","k":"pat"},{"w":"seem to be; it seems that","vi":"dường như","ex":"The jacket seems {to} be too small.","k":"pat"},{"w":"stare at","vi":"nhìn chằm chằm","ex":"It is rude to stare {at} people.","k":"pat"},{"w":"use sth for N/V-ing; use sth to V","vi":"dùng thứ gì cho/để","ex":"They use software to design patterns.","k":"pat"},{"w":"useful for N/V-ing; useful to sb","vi":"hữu ích cho việc/ai","ex":"The guide is useful {for} choosing fabrics.","k":"pat"}]}]},{"g":2,"u":28,"title":"Work and Business","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/2 (Topic vocabulary)","words":[{"w":"employer","pos":"n","vi":"người sử dụng lao động","ex":"The {employer} consulted the staff before hiring another employee.","grp":["employer","employee","staff"],"k":"topic"},{"w":"employee","pos":"n","vi":"nhân viên","ex":"The employer consulted the staff before hiring another {employee}.","grp":["employer","employee","staff"],"k":"topic"},{"w":"staff","pos":"n","vi":"tập thể nhân viên","ex":"The employer consulted the {staff} before hiring another employee.","grp":["employer","employee","staff"],"k":"topic"},{"w":"job","pos":"n","vi":"công việc/vị trí cụ thể, đếm được","ex":"Her first {job} gave her useful work experience for her career.","grp":["job","work","career"],"k":"topic"},{"w":"work","pos":"n","vi":"việc làm nói chung, thường không đếm được","ex":"Her first job gave her useful {work} experience for her career.","grp":["job","work","career"],"k":"topic"},{"w":"career","pos":"n","vi":"sự nghiệp","ex":"Her first job gave her useful work experience for her {career}.","grp":["job","work","career"],"k":"topic"},{"w":"earn","pos":"v","vi":"kiếm được nhờ làm/xứng đáng","ex":"She {earns} a salary, won an award and gained valuable experience.","grp":["earn","win","gain"],"k":"topic"},{"w":"win","pos":"v","vi":"thắng/giành giải","ex":"She earns a salary, won an award and gained valuable experience.","grp":["earn","win","gain"],"k":"topic"},{"w":"gain","pos":"v","vi":"có thêm, thu được","ex":"She earns a salary, won an award and {gained} valuable experience.","grp":["earn","win","gain"],"k":"topic"},{"w":"raise","pos":"v","vi":"nâng/tăng cái gì, có tân ngữ","ex":"The company {raised} salaries as living costs rose.","grp":["raise","rise"],"k":"topic"},{"w":"rise","pos":"v","vi":"tự tăng/đi lên, không tân ngữ","ex":"The company raised salaries as living costs rose.","grp":["raise","rise"],"k":"topic"},{"w":"salary","pos":"n","vi":"lương cố định thường tháng/năm","ex":"The factory pays weekly wages; office staff receive a monthly {salary}.","grp":["wage","salary","pay"],"k":"topic"},{"w":"pay","pos":"n","vi":"tiền công/lương nói chung","ex":"The factory {pays} weekly wages; office staff receive a monthly salary.","grp":["wage","salary","pay"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/2 (Topic vocabulary)","words":[{"w":"commute","pos":"v","vi":"đi lại thường xuyên nhà– chỗ làm","ex":"He {commutes} by train and delivers parcels at weekends.","grp":["commute","deliver"],"k":"topic"},{"w":"deliver","pos":"v","vi":"giao hàng/chuyển phát","ex":"He commutes by train and {delivers} parcels at weekends.","grp":["commute","deliver"],"k":"topic"},{"w":"retire","pos":"v","vi":"nghỉ hưu/ngừng sự nghiệp","ex":"She resigned as manager but did not {retire}.","grp":["retire","resign"],"k":"topic"},{"w":"resign","pos":"v","vi":"xin thôi một vị trí","ex":"She {resigned} as manager but did not retire.","grp":["retire","resign"],"k":"topic"},{"w":"make redundant","pos":"v","vi":"cho nghỉ vì vị trí không còn cần","ex":"He was fired for misconduct; others were made {redundant} after the closure.","grp":["fire","sack","make redundant"],"k":"topic"},{"w":"overtime","pos":"n","vi":"giờ làm thêm/tiền tăng ca","ex":"She worked {overtime} before her promotion and paid into a pension fund.","grp":["overtime","promotion","pension"],"k":"topic"},{"w":"promotion","pos":"n","vi":"thăng chức/quảng bá","ex":"She worked overtime before her {promotion} and paid into a pension fund.","grp":["overtime","promotion","pension"],"k":"topic"},{"w":"pension","pos":"n","vi":"lương hưu","ex":"She worked overtime before her promotion and paid into a {pension} fund.","grp":["overtime","promotion","pension"],"k":"topic"},{"w":"company","pos":"n","vi":"công ty","ex":"The law firm advises small businesses and large {companies}.","grp":["company","firm","business"],"k":"topic"},{"w":"firm","pos":"n","vi":"hãng, thường dịch vụ chuyên môn","ex":"The law {firm} advises small businesses and large companies.","grp":["company","firm","business"],"k":"topic"},{"w":"business","pos":"n","vi":"doanh nghiệp/hoạt động kinh doanh","ex":"The law firm advises small {businesses} and large companies.","grp":["company","firm","business"],"k":"topic"},{"w":"union","pos":"n","vi":"công đoàn/liên minh","ex":"The {union} organised a collection for a local charity.","grp":["union","charity"],"k":"topic"},{"w":"charity","pos":"n","vi":"tổ chức/hoạt động từ thiện","ex":"The union organised a collection for a local {charity}.","grp":["union","charity"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"back out of","vi":"rút khỏi việc đã đồng ý","ex":"They backed out {of} the deal.","k":"pv"},{"w":"bring out","vi":"ra mắt, đưa sản phẩm mới ra bán","ex":"The company brought {out} a new device.","k":"pv"},{"w":"close down","vi":"đóng cửa/ngừng hoạt động","ex":"The factory closed {down} last year.","k":"pv"},{"w":"see through (to)","vi":"theo đến cùng, giúp hoàn thành việc khó","ex":"She saw the project through {to} completion.","k":"pv"},{"w":"see to","vi":"lo liệu, xử lí","ex":"I will see {to} the arrangements.","k":"pv"},{"w":"set to","vi":"bắt tay làm quyết tâm/nhiệt tình","ex":"They set {to} and cleaned the office.","k":"pv"},{"w":"set out","vi":"bắt đầu làm nhằm mục tiêu; set out to V","ex":"She set {out} to improve customer service.","k":"pv"},{"w":"set up","vi":"thành lập","ex":"They set {up} a small business.","k":"pv"},{"w":"slow down","vi":"chậm lại/làm chậm","ex":"Production slowed {down} in winter.","k":"pv"},{"w":"speed up","vi":"nhanh lên/đẩy nhanh","ex":"New equipment sped {up} the process.","k":"pv"},{"w":"stand in for","vi":"làm thay khi ai vắng","ex":"Can you stand in {for} me tomorrow?","k":"pv"},{"w":"take on","vi":"tuyển; nhận việc/trách nhiệm","ex":"The firm took {on} ten staff and took on more work.","k":"pv"},{"w":"take over","vi":"tiếp quản","ex":"Her daughter took {over} the business.","k":"pv"},{"w":"turn down","vi":"từ chối","ex":"He turned {down} the job offer.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"agreement","vi":"đi đến/thống nhất về; đồng ý với","ex":"We reached an {agreement} on working hours.","note":"come to/reach an agreement on/about; in agreement on/about/with","k":"col"},{"w":"arrangement","vi":"thu xếp/thỏa thuận","ex":"We have an {arrangement} with a local supplier to deliver weekly.","note":"make an arrangement with/for sb to V; have an arrangement with sb to V","k":"col"},{"w":"business","vi":"kinh doanh với; đang kinh doanh; đi công tác; doanh nghiệp nhỏ/lớn","ex":"She is in Hanoi on {business}.","note":"do business with; in business; go somewhere on business; business trip; small/big business","k":"col"},{"w":"complaint","vi":"phàn nàn/khiếu nại; thư khiếu nại","ex":"He made a {complaint} to the manager about the delay.","note":"have/make a complaint about sth to sb; a letter of complaint to sb about sth","k":"col"},{"w":"day","vi":"nghỉ một ngày; việc chính; chuyến trong ngày; từng ngày; hôm nọ/ngày tiếp","ex":"I took a {day} off after the business trip.","note":"have/take/get a day off; day job; day trip; day by day; the other/next day","k":"col"},{"w":"decision","vi":"quyết định làm/về","ex":"They reached a {decision} about the new office.","note":"make/take a decision to V; come to/reach/make a decision about","k":"col"},{"w":"duty","vi":"làm bổn phận; trách nhiệm; đang/hết ca; có nghĩa vụ","ex":"She was on {duty} when the call arrived.","note":"do one's duty; a sense of duty; on/off duty; have a duty to sb/to V","k":"col"},{"w":"effort","vi":"nỗ lực làm; bỏ công vào","ex":"The team put a lot of {effort} into improving the service.","note":"make an effort to V; put effort into N/V-ing","k":"col"},{"w":"experience","vi":"trải nghiệm cụ thể; có/tích lũy kinh nghiệm; có kinh nghiệm","ex":"She gained {experience} in managing projects.","note":"have an experience; have/gain/get experience in/of N/V- ing; experienced in/at","k":"col"},{"w":"hold","vi":"để ai chờ điện thoại; giữ chặt; cầm/giữ","ex":"Please {hold} on to the receipt while I put you on hold.","note":"put/keep sb on hold; hold on to; hold sth","k":"col"},{"w":"interest","vi":"quan tâm; có lợi cho bạn; hưởng/trả lãi","ex":"It is in your {interest} to read the contract carefully.","note":"have/take/express an interest in; in your interest to V; earn/get/pay interest","k":"col"},{"w":"interview","vi":"có/đi/phỏng vấn tuyển dụng","ex":"She attended a job {interview} yesterday.","note":"have/go to/attend an interview; job interview","k":"col"},{"w":"job","vi":"làm việc; có việc cần làm; xin/nhận/có vị trí","ex":"He applied for a {job} at the factory.","note":"do a job; have a job to do; apply for/take/get a job; in a job","k":"col"},{"w":"work","vi":"làm việc; đi/ở chỗ/không có việc; chăm chỉ; nơi làm việc","ex":"He was out of {work} before finding a job here.","note":"do some work; have work to do; go to/at/out of work; work hard; place of work","k":"col"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"add","vi":"thêm","note":"add (v) → added (adj), addition (n), additional (adj), additionally (adv)","full":"thêm → bổ sung; sự thêm; thêm vào; ngoài ra.","ex":"There is an {additional} delivery charge.","hint":"add","k":"wf"},{"w":"apply","vi":"áp dụng/nộp đơn","note":"apply (v) → applicable/inapplicable (adj), applied (adj), applicant, application (n)","full":"áp dụng/nộp đơn → áp dụng được/không; ứng dụng; ứng viên; đơn/sự áp dụng.","ex":"Every applicant must complete an {application}.","hint":"apply","k":"wf"},{"w":"commerce","vi":"thương mại","note":"commerce (n) → commercial (adj), commercially (adv)","full":"thương mại → thuộc thương mại; về thương mại.","ex":"The product was {commercially} successful.","hint":"commerce","k":"wf"},{"w":"dedicate","vi":"cống hiến","note":"dedicate (v) → dedicated (adj), dedication (n)","full":"cống hiến → tận tâm; sự tận tâm.","ex":"Her {dedication} impressed the team.","hint":"dedicate","k":"wf"},{"w":"effect","vi":"tác động","note":"effect (n/v) → effective/ineffective (adj), effectively/ineffectively (adv)","full":"tác động → hiệu quả/không hiệu quả; trạng từ.","ex":"We need a more {effective} system.","hint":"effect","k":"wf"},{"w":"employ","vi":"thuê","note":"employ (v) → employed/unemployed, employable/unemployable (adj), employment/unemployment, employer, employee, employability (n)","full":"thuê → có/không có việc; có/khó có khả năng được tuyển; việc làm/thất nghiệp; chủ; nhân viên; khả năng tìm được việc.","ex":"Training can improve {employability}.","hint":"employ","k":"wf"},{"w":"help","vi":"giúp","note":"help (v/n) → helpful/unhelpful, helpless (adj), helpfully/unhelpfully/helplessly (adv), helping, helper (n)","full":"giúp → hữu ích/không hữu ích; bất lực; phần thức ăn/người giúp.","ex":"The assistant was very {helpful}.","hint":"help","k":"wf"},{"w":"industry","vi":"ngành công nghiệp","note":"industry (n) → industrial (adj), industrially (adv), industrious (adj), industriously (adv)","full":"ngành công nghiệp → thuộc công nghiệp; chăm chỉ/cần cù.","ex":"The {industrious} team increased industrial output.","hint":"industry","k":"wf"},{"w":"machine","vi":"máy cụ thể","note":"machine (n) → machinery (n)","full":"máy cụ thể → máy móc nói chung, không đếm được.","ex":"The {machinery} needs regular maintenance.","hint":"machine","k":"wf"},{"w":"manage","vi":"quản lí/xoay xở","note":"manage (v) → managing (adj), management, manager (n)","full":"quản lí/xoay xở → điều hành; ban/sự quản lí; quản lí viên.","ex":"The manager attended a {management} course.","hint":"manage","k":"wf"},{"w":"meet","vi":"gặp/đáp ứng","note":"meet (v) → met (V2/V3), meeting (n)","full":"gặp/đáp ứng → đã gặp; cuộc họp.","ex":"We met the supplier at a {meeting}.","hint":"meet","k":"wf"},{"w":"profession","vi":"nghề chuyên môn","note":"profession (n) → professional/unprofessional (adj), professionally/unprofessionally (adv)","full":"nghề chuyên môn → chuyên nghiệp/thiếu chuyên nghiệp; trạng từ.","ex":"Her conduct was {professional}.","hint":"profession","k":"wf"},{"w":"qualify","vi":"đủ trình độ","note":"qualify (v) → qualified/unqualified, qualifying (adj), qualification (n)","full":"đủ trình độ → đủ/không đủ chuyên môn; mang tính vòng loại; bằng cấp.","ex":"The position requires a professional {qualification}.","hint":"qualify","k":"wf"},{"w":"responsible/irresponsible","vi":"có/vô trách nhiệm","note":"responsible/irresponsible (adj) → responsibly/irresponsibly (adv), responsibility/irresponsibility (n)","full":"có/vô trách nhiệm → trạng từ; trách nhiệm/sự vô trách nhiệm.","ex":"Staff must act {responsibly}.","hint":"responsible/irresponsible","k":"wf"},{"w":"supervise","vi":"giám sát","note":"supervise (v) → supervision, supervisor (n)","full":"giám sát → sự giám sát; người giám sát.","ex":"New employees work under {supervision}.","hint":"supervise","k":"wf"},{"w":"work","vi":"làm việc","note":"work (v/n) → working, workable/unworkable (adj), worker, works (n)","full":"làm việc → đang làm/thuộc công việc; khả thi/không; người lao động; tác phẩm/công trình/nhà máy.","ex":"The team proposed a {workable} solution.","hint":"work","k":"wf"}]},{"type":"v","title":"Mẫu kết hợp từ (Word patterns)","words":[{"w":"absent from","vi":"vắng mặt ở","ex":"She was absent {from} work yesterday.","k":"pat"},{"w":"apply for sth; apply in writing","vi":"nộp đơn xin; nộp bằng văn bản","ex":"Apply in writing {for} the post.","k":"pat"},{"w":"attach sth to sth; attached to","vi":"đính/gắn vào; gắn bó với","ex":"Attach your CV {to} the application.","k":"pat"},{"w":"begin N/V-ing/to V; begin by V-ing","vi":"bắt đầu việc/làm; khởi đầu bằng","ex":"Begin by reading the job description.","k":"pat"},{"w":"depend on sb/sth","vi":"phụ thuộc vào","ex":"The schedule depends {on} the delivery date.","k":"pat"},{"w":"experienced in/at N/V-ing","vi":"có kinh nghiệm về","ex":"She is experienced {in} training staff.","k":"pat"},{"w":"good for sb to V; good at; good to sb","vi":"có lợi cho; giỏi; đối tốt với","ex":"She is good at negotiating and good to her colleagues.","k":"pat"},{"w":"qualify as/in","vi":"đủ điều kiện/lấy bằng làm nghề; có bằng trong lĩnh vực","ex":"He qualified {as} an accountant.","k":"pat"},{"w":"responsible for N/V-ing","vi":"chịu trách nhiệm về","ex":"I am responsible {for} checking orders.","k":"pat"},{"w":"specialise in N/V-ing","vi":"chuyên về","ex":"The firm specialises {in} designing software.","k":"pat"},{"w":"train to V","vi":"đào tạo/luyện để làm","ex":"She is training {to} become an engineer.","k":"pat"},{"w":"work as/at/in; work for sb","vi":"làm với vai trò/tại nơi/trong ngành; làm cho ai","ex":"He works {as} a designer for a local company.","k":"pat"}]}]},{"g":3,"u":2,"title":"Thinking and Learning","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"assess","pos":"v","vi":"đánh giá","ex":"We {assessed} the risks and estimated the cost.","grp":["assess","estimate"],"k":"topic"},{"w":"estimate","pos":"v","vi":"ước tính, sự ước tính","ex":"We assessed the risks and {estimated} the cost.","grp":["assess","estimate"],"k":"topic"},{"w":"assume","pos":"v","vi":"cho là đúng khi chưa đủ chứng cứ","ex":"Do not {assume} everyone agrees; I presume you have checked.","grp":["assume","presume"],"k":"topic"},{"w":"presume","pos":"v","vi":"suy đoán là đúng, thường có căn cứ hoặc kỳ vọng","ex":"Do not assume everyone agrees; I {presume} you have checked.","grp":["assume","presume"],"k":"topic"},{"w":"baffle","pos":"n","vi":"làm khó hiểu","ex":"The dilemma {baffled} even the most experienced adviser.","grp":["baffle","dilemma"],"k":"topic"},{"w":"dilemma","pos":"n","vi":"tình thế khó chọn giữa các phương án","ex":"The {dilemma} baffled even the most experienced adviser.","grp":["baffle","dilemma"],"k":"topic"},{"w":"biased","pos":"adj","vi":"thiên lệch","ex":"A {biased} report may reinforce prejudiced attitudes.","grp":["biased","prejudiced"],"k":"topic"},{"w":"prejudiced","pos":"adj","vi":"có định kiến, thường thiếu công bằng với một nhóm","ex":"A biased report may reinforce {prejudiced} attitudes.","grp":["biased","prejudiced"],"k":"topic"},{"w":"concentrate","pos":"v","vi":"tập trung","ex":"{Concentrate} on the facts before considering a solution.","grp":["concentrate","consider"],"k":"topic"},{"w":"consider","pos":"v","vi":"cân nhắc, xem xét","ex":"Concentrate on the facts before {considering} a solution.","grp":["concentrate","consider"],"k":"topic"},{"w":"contemplate","pos":"v","vi":"suy ngẫm, tính đến","ex":"She {contemplated} leaving while the committee deliberated.","grp":["contemplate","deliberate"],"k":"topic"},{"w":"deliberate","pos":"v","vi":"cân nhắc thận trọng","ex":"She contemplated leaving while the committee {deliberated}.","grp":["contemplate","deliberate"],"k":"topic"},{"w":"cynical","pos":"adj","vi":"hoài nghi động cơ tốt của người khác","ex":"He was {cynical} about a promise that seemed convincing to naive voters.","grp":["cynical","naive"],"k":"topic"},{"w":"naive","pos":"adj","vi":"ngây thơ, thiếu kinh nghiệm","ex":"He was cynical about a promise that seemed convincing to {naive} voters.","grp":["cynical","naive"],"k":"topic"},{"w":"deduce","pos":"v","vi":"suy ra theo lí lẽ","ex":"From what I gathered, we could {deduce} that the plan had failed.","grp":["deduce","gather"],"k":"topic"},{"w":"gather","pos":"v","vi":"thu thập, hiểu/suy ra từ thông tin","ex":"From what I {gathered}, we could deduce that the plan had failed.","grp":["deduce","gather"],"k":"topic"},{"w":"discriminate","pos":"v","vi":"phân biệt, đối xử phân biệt","ex":"Can you justify a policy that {discriminates} against beginners?","grp":["discriminate","justify"],"k":"topic"},{"w":"justify","pos":"v","vi":"chứng minh là hợp lí","ex":"Can you {justify} a policy that discriminates against beginners?","grp":["discriminate","justify"],"k":"topic"},{"w":"dubious","pos":"adj","vi":"nghi ngờ hoặc đáng ngờ","ex":"She was sceptical about his {dubious} explanation.","grp":["dubious","sceptical"],"k":"topic"},{"w":"sceptical","pos":"adj","vi":"hoài nghi tính đúng đắn của điều gì","ex":"She was {sceptical} about his dubious explanation.","grp":["dubious","sceptical"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"faith","pos":"n","vi":"niềm tin","ex":"Their {faith} in the movement depended on its ideology.","grp":["faith","ideology"],"k":"topic"},{"w":"ideology","pos":"n","vi":"hệ tư tưởng","ex":"Their faith in the movement depended on its {ideology}.","grp":["faith","ideology"],"k":"topic"},{"w":"genius","pos":"adj","vi":"thiên tài, tài năng xuất chúng","ex":"The young {genius} devised an ingenious solution.","grp":["genius","ingenious"],"k":"topic"},{"w":"ingenious","pos":"adj","vi":"khéo léo, sáng tạo thông minh","ex":"The young genius devised an {ingenious} solution.","grp":["genius","ingenious"],"k":"topic"},{"w":"grasp","pos":"n","vi":"hiểu rõ","ex":"Without {grasping} the principles, your answer is only guesswork.","grp":["grasp","guesswork"],"k":"topic"},{"w":"guesswork","pos":"n","vi":"việc đoán khi thiếu thông tin","ex":"Without grasping the principles, your answer is only {guesswork}.","grp":["grasp","guesswork"],"k":"topic"},{"w":"hunch","pos":"n","vi":"linh cảm cụ thể","ex":"My {hunch} was based on intuition rather than evidence.","grp":["hunch","intuition"],"k":"topic"},{"w":"intuition","pos":"n","vi":"trực giác, khả năng biết mà không suy luận rõ","ex":"My hunch was based on {intuition} rather than evidence.","grp":["hunch","intuition"],"k":"topic"},{"w":"inspiration","pos":"n","vi":"cảm hứng/ý tưởng gợi mở","ex":"The lecture gave her the {inspiration} to question an old notion.","grp":["inspiration","notion"],"k":"topic"},{"w":"notion","pos":"n","vi":"ý niệm, quan niệm","ex":"The lecture gave her the inspiration to question an old {notion}.","grp":["inspiration","notion"],"k":"topic"},{"w":"optimistic","pos":"adj","vi":"lạc quan","ex":"She is {optimistic} about a result that makes him pessimistic.","grp":["optimistic","pessimistic"],"k":"topic"},{"w":"pessimistic","pos":"adj","vi":"bi quan","ex":"She is optimistic about a result that makes him {pessimistic}.","grp":["optimistic","pessimistic"],"k":"topic"},{"w":"paradox","pos":"adj","vi":"điều nghịch lí","ex":"The apparent {paradox} has a plausible explanation.","grp":["paradox","plausible"],"k":"topic"},{"w":"plausible","pos":"adj","vi":"có vẻ hợp lí, đáng tin","ex":"The apparent paradox has a {plausible} explanation.","grp":["paradox","plausible"],"k":"topic"},{"w":"ponder","pos":"v","vi":"suy nghĩ kĩ","ex":"He {pondered} the question and reflected on his experience.","grp":["ponder","reflect"],"k":"topic"},{"w":"reflect","pos":"v","vi":"suy ngẫm, phản ánh","ex":"He pondered the question and {reflected} on his experience.","grp":["ponder","reflect"],"k":"topic"},{"w":"query","pos":"v","vi":"hỏi/chất vấn, câu hỏi","ex":"I {queried} the figure because I reckoned it was too high.","grp":["query","reckon"],"k":"topic"},{"w":"reckon","pos":"v","vi":"cho rằng, ước lượng (thường thân mật)","ex":"I queried the figure because I {reckoned} it was too high.","grp":["query","reckon"],"k":"topic"},{"w":"speculate","pos":"v","vi":"phỏng đoán","ex":"We can {speculate}, but suppose the evidence is misleading?","grp":["speculate","suppose"],"k":"topic"},{"w":"suppose","pos":"v","vi":"cho rằng, giả sử","ex":"We can speculate, but {suppose} the evidence is misleading?","grp":["speculate","suppose"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"academic","pos":"n/adj","vi":"học giả/thuộc học thuật","ex":"The {academic} welcomed the intellectual challenge.","grp":["academic","intellectual"],"k":"topic"},{"w":"intellectual","pos":"n/adj","vi":"trí thức/thuộc tư duy trí tuệ","ex":"The academic welcomed the {intellectual} challenge.","grp":["academic","intellectual"],"k":"topic"},{"w":"conscientious","pos":"adj","vi":"tận tâm, có trách nhiệm","ex":"A {conscientious} student checks what an inattentive student misses.","grp":["conscientious","inattentive"],"k":"topic"},{"w":"inattentive","pos":"adj","vi":"thiếu chú ý","ex":"A conscientious student checks what an {inattentive} student misses.","grp":["conscientious","inattentive"],"k":"topic"},{"w":"cram","pos":"adj","vi":"học nhồi nhét","ex":"An intensive course is more useful than {cramming} overnight.","grp":["cram","intensive"],"k":"topic"},{"w":"intensive","pos":"adj","vi":"chuyên sâu, tập trung cường độ cao","ex":"An {intensive} course is more useful than cramming overnight.","grp":["cram","intensive"],"k":"topic"},{"w":"curriculum","pos":"n","vi":"chương trình học","ex":"The tuition covers the subjects in the national {curriculum}.","grp":["curriculum","tuition"],"k":"topic"},{"w":"tuition","pos":"n","vi":"việc dạy/học phí tùy ngữ cảnh","ex":"The {tuition} covers the subjects in the national curriculum.","grp":["curriculum","tuition"],"k":"topic"},{"w":"distance learning","pos":"n","vi":"học từ xa","ex":"{Distance learning} includes a weekly online tutorial.","grp":["distance learning","tutorial"],"k":"topic"},{"w":"tutorial","pos":"n","vi":"buổi hướng dẫn nhóm nhỏ/cá nhân","ex":"Distance learning includes a weekly online {tutorial}.","grp":["distance learning","tutorial"],"k":"topic"},{"w":"graduate","pos":"n","vi":"tốt nghiệp/người tốt nghiệp","ex":"After {graduating}, she continued her education through self-study.","grp":["graduate","self-study"],"k":"topic"},{"w":"self-study","pos":"n","vi":"tự học","ex":"After graduating, she continued her education through {self-study}.","grp":["graduate","self-study"],"k":"topic"},{"w":"ignorant","pos":"adj","vi":"không biết, thiếu hiểu biết","ex":"A knowledgeable guide explained what I was {ignorant} of.","grp":["ignorant","knowledgeable"],"k":"topic"},{"w":"knowledgeable","pos":"adj","vi":"am hiểu","ex":"A {knowledgeable} guide explained what I was ignorant of.","grp":["ignorant","knowledgeable"],"k":"topic"},{"w":"intelligent","pos":"v","vi":"thông minh","ex":"An {intelligent} argument should not plagiarise someone else's work.","grp":["intelligent","plagiarise"],"k":"topic"},{"w":"plagiarise","pos":"v","vi":"đạo văn, lấy ý/chữ người khác như của mình","ex":"An intelligent argument should not {plagiarise} someone else's work.","grp":["intelligent","plagiarise"],"k":"topic"},{"w":"lecture","pos":"n","vi":"giảng/bài giảng","ex":"We attended a {lecture} before discussing it in a seminar.","grp":["lecture","seminar"],"k":"topic"},{"w":"seminar","pos":"n","vi":"buổi thảo luận chuyên đề","ex":"We attended a lecture before discussing it in a {seminar}.","grp":["lecture","seminar"],"k":"topic"},{"w":"mock exam","pos":"n phr","vi":"thi thử","ex":"The {mock exam} included support for pupils with special needs.","grp":["mock exam","special needs"],"k":"topic"},{"w":"special needs","pos":"n phr","vi":"nhu cầu hỗ trợ giáo dục đặc biệt","ex":"The mock exam included support for pupils with {special needs}.","grp":["mock exam","special needs"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"brush up on","vi":"ôn và cải thiện kiến thức/kĩ năng","ex":"I need to brush up {on} my grammar.","k":"pv"},{"w":"come (a)round to","vi":"đổi quan điểm sau khi được thuyết phục","ex":"She came round {to} our proposal.","k":"pv"},{"w":"come up with","vi":"nghĩ ra ý tưởng/kế hoạch","ex":"They came up {with} a practical solution.","k":"pv"},{"w":"face up to","vi":"chấp nhận và đối diện vấn đề","ex":"We must face up {to} the evidence.","k":"pv"},{"w":"figure out","vi":"hiểu, giải được; hiểu tính cách/động cơ","ex":"I cannot figure {out} why he refused.","k":"pv"},{"w":"hit upon","vi":"chợt nghĩ ra; tình cờ tìm thấy","ex":"She hit {upon} a clever way to explain it.","k":"pv"},{"w":"make out","vi":"nhìn/nghe/hiểu ra khó khăn; ngụ ý","ex":"I could barely make {out} his handwriting.","k":"pv"},{"w":"mull over","vi":"suy nghĩ kĩ trong một thời gian","ex":"Mull it {over} before replying.","k":"pv"},{"w":"piece together","vi":"ghép các thông tin để tìm ra sự thật","ex":"We pieced {together} the sequence of events.","k":"pv"},{"w":"puzzle out","vi":"giải một vấn đề phức tạp bằng suy nghĩ","ex":"They puzzled {out} the final clue.","k":"pv"},{"w":"read up on/about","vi":"đọc nhiều để tìm hiểu chủ đề","ex":"Read up on the topic before the seminar.","k":"pv"},{"w":"swot up on","vi":"học ôn rất kĩ, nhất là để thi","ex":"He swotted up {on} constitutional law.","k":"pv"},{"w":"take in","vi":"hiểu/ghi nhớ; chấp nhận là thật; lừa","ex":"It was too much information to take {in}.","k":"pv"},{"w":"think over","vi":"cân nhắc kĩ","ex":"Think the offer {over} carefully.","k":"pv"},{"w":"think through","vi":"xem xét có hệ thống đến các hệ quả","ex":"We have not thought {through} the consequences.","k":"pv"},{"w":"think up","vi":"nghĩ ra, thường là cớ/ý tưởng","ex":"Can you think {up} a better title?","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations 1/2 (Collocations)","words":[{"w":"account","vi":"account for (giải thích/chiếm); give an account of (tường thuật); take into account / take account of (tính đến); on account of (vì); by all accounts (theo mọi lời kể); on sb's account (vì ai).","ex":"Take the uncertainty into {account} when assessing the result.","note":"account for (giải thích/chiếm); give an account of (tường thuật); take into account / take account of (tính đến); on account of (vì); by all accounts (theo mọi lời kể); on sb's account (vì ai)","k":"col"},{"w":"associate","vi":"liên hệ A với B","ex":"We {associate} that theory with its original author.","note":"associate A with B","k":"col"},{"w":"balance","vi":"hang in the balance (chưa ngã ngũ); strike/redress/upset/alter the balance; balance between/of; on balance (xét tổng thể); off balance (mất thăng bằng/bối rối).","ex":"On {balance}, the advantages outweigh the risks.","note":"hang in the balance (chưa ngã ngũ); strike/redress/upset/alter the balance; balance between/of; on balance (xét tổng thể); off balance (mất thăng bằng/bối rối)","k":"col"},{"w":"basis","vi":"cơ sở; theo chế độ; dựa trên","ex":"The decision was made on the {basis} of evidence.","note":"basis for; on a daily/temporary basis; on the basis of/that","k":"col"},{"w":"belief","vi":"niềm tin và mức phổ biến/chắc chắn","ex":"Contrary to popular {belief}, memory can be trained.","note":"express a belief; belief in/that; contrary to popular belief; beyond belief; in the belief that; a popular/widely held/widespread/firm/strong/growing belief","k":"col"},{"w":"brain","vi":"ngu ngốc; sản phẩm trí tuệ; động não; tẩy não; ý tưởng chợt lóe","ex":"Can I pick your {brains} about this problem?","note":"pick sb's brains (hỏi ý kiến); rack your brains (vắt óc); the brains behind (người chủ chốt); brainless; brainchild of; brainstorm; brainwash; brainwave","k":"col"},{"w":"conclusion","vi":"kết thúc/kết luận; vội kết luận; kết cục chắc trước","ex":"Do not jump to {conclusions} from one example.","note":"bring to a conclusion; come to/arrive at/reach a conclusion; jump/leap to conclusions; in conclusion; conclusion of; logical/foregone conclusion","k":"col"},{"w":"consideration","vi":"cân nhắc; quan tâm; đang xem xét; vì nghĩ cho ai","ex":"The proposal is still under {consideration}.","note":"take into consideration; give consideration to; show consideration for; under consideration; for sb's consideration; out of consideration for","k":"col"},{"w":"doubt","vi":"nghi ngờ, làm dấy nghi ngờ, chắc chắn hoặc còn đáng ngờ","ex":"New evidence cast {doubt} on the original conclusion.","note":"doubt that; have doubts about; cast doubt on; raise doubts; in doubt; doubt as to/about; beyond any doubt; reasonable doubt; without a doubt; open to doubt","k":"col"},{"w":"dream","vi":"mơ/ước; vượt mong đợi; ước thành thật; viển vông; rất trơn tru","ex":"The project worked like a {dream}.","note":"dream of/about/that; have a dream; a dream to V; beyond your wildest dreams; a dream come true; in your dreams; like a dream","k":"col"},{"w":"focus","vi":"tập trung; tâm điểm; rõ/mờ; nhóm thảo luận nghiên cứu","ex":"The main {focus} is on independent learning.","note":"focus on; the focus of/for; in/out of focus; focus group; main/primary/major focus","k":"col"}]},{"type":"v","title":"Cụm từ & collocations 2/2 (Collocations)","words":[{"w":"impression","vi":"cảm giác; bắt chước; gây ấn tượng; tưởng rằng; ấn tượng ban đầu","ex":"I was under the {impression} that the meeting was cancelled.","note":"have/give the false impression that; do an impression of; create/make an impression on; under the impression that; first impressions","k":"col"},{"w":"mental","vi":"ghi nhớ trong đầu; tính nhẩm; bệnh/tuổi/sức khỏe tâm thần","ex":"Make a {mental} note of the key distinction.","note":"make a mental note of/about; mental arithmetic/illness/age/health","k":"col"},{"w":"mind","vi":"quyết định; chợt nghĩ/quên; ghi nhớ; chỉ nghĩ một việc; làm bớt nghĩ; gợi nhớ; phân vân; bận tâm; trạng thái tinh thần; hẹp/rộng/cởi mở/đãng trí","ex":"Bear in {mind} that an open-minded person can still disagree.","note":"make up your mind; cross/slip your mind; have/bear in mind; one-track mind; take your mind off; bring to mind; in two minds about; on your mind; state of mind; narrow/broad/open/absent-minded","k":"col"},{"w":"misapprehen sion","vi":"hiểu nhầm rằng","ex":"He was under the misapprehension that attendance was optional.","note":"under the misapprehension that","k":"col"},{"w":"perspective","vi":"đặt đúng tương quan; góc nhìn; đánh giá đúng/phóng đại","ex":"A second opinion put the problem into {perspective}.","note":"put into perspective; from another/a different/sb's perspective; from the perspective of; in/out of perspective; a sense of perspective","k":"col"},{"w":"principle","vi":"nguyên tắc; về nguyên tắc; vấn đề lập trường","ex":"She refused as a matter of {principle}.","note":"have principles; stand by/stick to your principles; principle of/that; in principle; a matter/issue of principle; against sb's principles; a set of principles","k":"col"},{"w":"question","vi":"beg the question: giả định sẵn điều cần chứng minh, hoặc đặt ra câu hỏi trong cách dùng phổ biến; raise: nêu vấn đề; in question: đang nói tới; out of the question: không thể chấp nhận; without/beyond question: chắc chắn; awkward: khó xử","ex":"The plan in {question} is not out of the question.","note":"beg the question; raise the question of; a/no question of; in question; out of the question; without/beyond question; some question over/as to/about; awkward question","k":"col"},{"w":"sense","vi":"cảm thấy; biết nghĩ; hiểu; đủ khôn; tỉnh ngộ; ý thức/cảm giác; lẽ thường","ex":"Can you make {sense} of these figures?","note":"sense that; see sense; make sense of; have the sense to; come to your senses; a sense of; in a/one sense; common sense","k":"col"},{"w":"side","vi":"về phe; cân hai phía; nhìn tích cực; ưu/nhược điểm; bên cạnh","ex":"Try to see both {sides} before taking sides.","note":"side with sb; take sides; see both sides of an argument; look on the bright side; on the plus/minus side; by/on sb's side; on either side of","k":"col"},{"w":"straight","vi":"đính chính; vào thẳng ý; hiểu rõ; nghĩ tỉnh táo; thẳng thắn","ex":"Let me set the record {straight}.","note":"set/put sb straight about; set/put the record straight; get/come straight to the point; get sth straight; think/see straight; straight talking/answer","k":"col"},{"w":"view","vi":"xem là; cho rằng; không tán thành; hiện ra trong tầm nhìn; xét đến; nhằm mục đích; quan điểm/góc nhìn","ex":"We revised the plan with a {view} to reducing costs.","note":"view sth as; take the view that; take a dim/poor view of; come into view; in view of; with a view to V-ing; a view on/about/that; in sb's view; viewpoint; point of view","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"go to your head","vi":"thành công làm ai tự cao","ex":"Do not let the praise {go to your head}.","k":"idiom"},{"w":"have your wits about you","vi":"tỉnh táo, phản ứng và quyết định nhanh","ex":"Keep {your wits about you} during the interview.","k":"idiom"},{"w":"in the dark about","vi":"không được biết thông tin về","ex":"We were kept {in the dark about} the changes.","k":"idiom"},{"w":"know what's what","vi":"nắm rõ những điều quan trọng trong tình hình","ex":"Ask Linh; she knows {what's what}.","k":"idiom"},{"w":"not have a leg to stand on","vi":"không có căn cứ vững để bảo vệ ý kiến","ex":"Without evidence, they do {not have a leg to stand on}.","k":"idiom"},{"w":"not see the wood for the trees","vi":"quá chú ý tiểu tiết nên không thấy vấn đề chính","ex":"We were so focused on spelling that we could {not see the wood for the trees}.","k":"idiom"},{"w":"put two and two together","vi":"suy ra sự thật từ các dấu hiệu","ex":"She {put two and two together} and identified the cause.","k":"idiom"},{"w":"quick/slow on the uptake","vi":"nhanh/chậm hiểu","ex":"He is quick {on the uptake} and needs little explanation.","k":"idiom"},{"w":"ring a bell","vi":"nghe/nhìn có vẻ quen","ex":"That name rings {a bell}.","k":"idiom"},{"w":"round the bend","vi":"điên, phát cáu (thân mật)","ex":"The constant noise is driving me {round the bend}.","k":"idiom"},{"w":"split hairs","vi":"bắt bẻ những khác biệt vụn vặt","ex":"We are splitting {hairs} over an unimportant detail.","k":"idiom"},{"w":"take stock of","vi":"dừng lại để đánh giá tình hình trước khi hành động","ex":"We took {stock of} our progress.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"assume","vi":"giả định","note":"assume → assumption, assuming, unassuming, assumed","full":"giả định → sự giả định; giả sử; khiêm tốn; được giả định.","ex":"Her {unassuming} manner hid a brilliant mind.","hint":"assume","k":"wf"},{"w":"believe","vi":"tin","note":"believe → disbelieve, belief, disbelief, (un)believer, (un)believable, disbelieving, unbelievably","full":"tin → không tin; niềm tin/hoài nghi; người tin/không tin; đáng/khó tin; không tin; cực kì.","ex":"His explanation was {unbelievable}.","hint":"believe","k":"wf"},{"w":"brilliant","vi":"xuất sắc","note":"brilliant → brilliance, brilliantly","full":"xuất sắc → tài năng/ánh sáng; một cách xuất sắc.","ex":"She argued {brilliantly}.","hint":"brilliant","k":"wf"},{"w":"conceive","vi":"hình thành ý tưởng","note":"conceive → conceptualise, concept, conception, conceptual, (in)conceivable, (in)conceivably","full":"hình thành ý tưởng → khái niệm hóa; khái niệm; quan niệm/sự hình thành; có/không thể tưởng tượng.","ex":"Such a result was previously {inconceivable}.","hint":"conceive","k":"wf"},{"w":"confuse","vi":"làm rối","note":"confuse → confusion, confused, confusing(ly)","full":"làm rối → sự nhầm lẫn; bối rối; gây khó hiểu.","ex":"The instructions caused {confusion}.","hint":"confuse","k":"wf"},{"w":"convince","vi":"thuyết phục","note":"convince → conviction, (un)convinced, (un)convincing(ly)","full":"thuyết phục → niềm tin chắc/sự kết tội; tin/chưa tin; có/thiếu sức thuyết phục.","ex":"She gave a {convincing} account.","hint":"convince","k":"wf"},{"w":"decide","vi":"quyết định","note":"decide → decision, decider, decisiveness, deciding, (in)decisive(ly)","full":"quyết định → quyết định; yếu tố quyết định; tính dứt khoát; có tính quyết định; dứt khoát/do dự.","ex":"Timing was the {deciding} factor.","hint":"decide","k":"wf"},{"w":"define","vi":"định nghĩa","note":"define → definition, defined, definitive(ly), (in)definite(ly)","full":"định nghĩa → định nghĩa; được xác định; mang tính cuối cùng/có thẩm quyền; xác định/không xác định.","ex":"We need a clear {definition}.","hint":"define","k":"wf"},{"w":"doubt","vi":"nghi","note":"doubt → doubter, doubtful(ly), undoubted(ly), doubtless","full":"nghi → người nghi; nghi ngờ; không nghi ngờ; chắc hẳn.","ex":"Her ability is {undoubtedly} exceptional.","hint":"doubt","k":"wf"},{"w":"explain","vi":"giải thích","note":"explain → explanation, explanatory, unexplained, (in)explicable, inexplicably","full":"giải thích → lời giải thích; để giải thích; chưa giải thích; giải thích được/không được.","ex":"The diagram is self-{explanatory}.","hint":"explain","k":"wf"},{"w":"imagine","vi":"tưởng tượng","note":"imagine → imagination, imaginings, imaginary, (un)imaginative(ly)","full":"tưởng tượng → trí tưởng tượng; những điều tưởng tượng; không có thật; giàu/thiếu sáng tạo.","ex":"An imaginary friend is not necessarily an {imaginative} invention.","hint":"imagine","k":"wf"},{"w":"judge","vi":"đánh giá","note":"judge → judg(e)ment, judiciary, judiciousness, judicious, judicial, judg(e)mental, judiciously","full":"đánh giá → phán đoán; ngành tư pháp; sự sáng suốt; sáng suốt; thuộc tòa án; hay phán xét.","ex":"A {judicious} choice prevented further conflict.","hint":"judge","k":"wf"},{"w":"logic","vi":"lô-gic","note":"logic → (il)logical(ly)","full":"lô-gic → hợp/không hợp lí; trạng từ tương ứng.","ex":"The conclusion follows {logically}.","hint":"logic","k":"wf"},{"w":"opinion","vi":"ý kiến","note":"opinion → opinionated","full":"ý kiến → cố chấp, hay khăng khăng ý mình.","ex":"He is knowledgeable but rather {opinionated}.","hint":"opinion","k":"wf"},{"w":"rational","vi":"hợp lí","note":"rational → rationalise, rationalisation, rationalist, rationalism, (ir)rationality, (ir)rational(ly)","full":"hợp lí → hợp lí hóa; người/thuyết duy lí; tính hợp lí/phi lí.","ex":"Fear can lead to {irrational} decisions.","hint":"rational","k":"wf"},{"w":"reason","vi":"lí do/lập luận","note":"reason → reasoning, reasonableness, (un)reasonable, reasoned, (un)reasonably","full":"lí do/lập luận → suy luận; tính hợp lí; hợp/vô lí; có lập luận.","ex":"Give a {reasoned} response rather than a guess.","hint":"reason","k":"wf"},{"w":"sane","vi":"tỉnh táo","note":"sane → (in)sanity, insane(ly)","full":"tỉnh táo → sự tỉnh táo/mất trí; điên rồ; trạng từ.","ex":"It was an {insanely} complicated system.","hint":"sane","k":"wf"},{"w":"sense","vi":"cảm giác","note":"sense → (de)sensitise, nonsense, sensitivity, sensibility, senseless(ness), sensible, nonsensical, sensibly, sensitive(ly)","full":"cảm giác → làm nhạy/giảm nhạy; điều vô lí; độ nhạy; khả năng cảm thụ; vô nghĩa; hợp lí; nhạy cảm.","ex":"A sensible decision may still hurt {sensitive} people.","hint":"sense","k":"wf"},{"w":"think","vi":"nghĩ","note":"think → thought, thinker, thinking, thoughtfulness, thoughtlessness, (un)thinkable, thoughtful(ly), thoughtless(ly)","full":"nghĩ → suy nghĩ; người tư duy; sự chu đáo/thiếu nghĩ; có/không thể nghĩ tới; chu đáo/thiếu suy nghĩ.","ex":"It was {thoughtful} of you to ask.","hint":"think","k":"wf"},{"w":"wise","vi":"khôn ngoan","note":"wise → wisdom, (un)wise(ly)","full":"khôn ngoan → sự khôn ngoan; khôn/không khôn; trạng từ.","ex":"She {wisely} sought a second opinion.","hint":"wise","k":"wf"}]}]},{"g":3,"u":4,"title":"Change and Technology","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"adapt","pos":"v","vi":"thích nghi, sửa cho phù hợp","ex":"We {adapted} the course and adjusted the timetable.","grp":["adapt","adjust"],"k":"topic"},{"w":"adjust","pos":"v","vi":"điều chỉnh cho đúng/vừa","ex":"We adapted the course and {adjusted} the timetable.","grp":["adapt","adjust"],"k":"topic"},{"w":"alternate","pos":"n/adj","vi":"luân phiên/cách một","ex":"We {alternate} between two methods when the alternative is costly.","grp":["alternate","alternative"],"k":"topic"},{"w":"alternative","pos":"n/adj","vi":"lựa chọn khác/thay thế","ex":"We alternate between two methods when the {alternative} is costly.","grp":["alternate","alternative"],"k":"topic"},{"w":"amend","pos":"v","vi":"sửa, bổ sung văn bản/luật","ex":"They revised the proposal and {amended} two clauses.","grp":["amend","revise"],"k":"topic"},{"w":"revise","pos":"v","vi":"xem xét sửa lại hoặc ôn tập","ex":"They {revised} the proposal and amended two clauses.","grp":["amend","revise"],"k":"topic"},{"w":"conservative","pos":"adj","vi":"bảo thủ, ít muốn đổi","ex":"A {conservative} board rejected the radical reforms.","grp":["conservative","radical"],"k":"topic"},{"w":"radical","pos":"adj","vi":"căn bản, triệt để","ex":"A conservative board rejected the {radical} reforms.","grp":["conservative","radical"],"k":"topic"},{"w":"convert","pos":"v","vi":"chuyển dạng/công năng/niềm tin","ex":"They {converted} the barn and transformed its interior.","grp":["convert","transform"],"k":"topic"},{"w":"transform","pos":"v","vi":"thay đổi mạnh diện mạo/bản chất","ex":"They converted the barn and {transformed} its interior.","grp":["convert","transform"],"k":"topic"},{"w":"decay","pos":"v","vi":"mục/rữa/suy tàn","ex":"The wood {decayed} as conditions deteriorated.","grp":["decay","deteriorate"],"k":"topic"},{"w":"deteriorate","pos":"v","vi":"trở nên tệ hơn","ex":"The wood decayed as conditions {deteriorated}.","grp":["decay","deteriorate"],"k":"topic"},{"w":"distort","pos":"v","vi":"bóp méo","ex":"The misleading graph {distorted} the facts and spoilt the presentation.","grp":["distort","spoil"],"k":"topic"},{"w":"spoil","pos":"v","vi":"làm hỏng, phá niềm vui","ex":"The misleading graph distorted the facts and {spoilt} the presentation.","grp":["distort","spoil"],"k":"topic"},{"w":"dynamic","pos":"adj","vi":"năng động, biến đổi","ex":"A {dynamic} team achieved steady growth.","grp":["dynamic","steady"],"k":"topic"},{"w":"steady","pos":"adj","vi":"ổn định/làm ổn định","ex":"A dynamic team achieved {steady} growth.","grp":["dynamic","steady"],"k":"topic"},{"w":"endure","pos":"v","vi":"chịu đựng/kéo dài","ex":"She {endured} criticism and persisted with the project.","grp":["endure","persist"],"k":"topic"},{"w":"persist","pos":"v","vi":"kiên trì hoặc tiếp tục tồn tại","ex":"She endured criticism and {persisted} with the project.","grp":["endure","persist"],"k":"topic"},{"w":"evolve","pos":"v","vi":"phát triển dần","ex":"The idea {evolved} as the designer matured.","grp":["evolve","mature"],"k":"topic"},{"w":"mature","pos":"v","vi":"trưởng thành/chín, chín chắn","ex":"The idea evolved as the designer {matured}.","grp":["evolve","mature"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"influence","pos":"n","vi":"ảnh hưởng","ex":"Online reviews {influence} consumer trends.","grp":["influence","trend"],"k":"topic"},{"w":"trend","pos":"n","vi":"xu hướng","ex":"Online reviews influence consumer {trends}.","grp":["influence","trend"],"k":"topic"},{"w":"innovation","pos":"adj","vi":"đổi mới/ý tưởng mới","ex":"The company rewards {innovation} and innovative thinking.","grp":["innovation","innovative"],"k":"topic"},{"w":"innovative","pos":"adj","vi":"có tính sáng tạo mới","ex":"The company rewards innovation and {innovative} thinking.","grp":["innovation","innovative"],"k":"topic"},{"w":"last","pos":"v","vi":"kéo dài, dùng được bao lâu","ex":"The repair {lasted}, but one problem remained.","grp":["last","remain"],"k":"topic"},{"w":"remain","pos":"v","vi":"vẫn ở/vẫn là","ex":"The repair lasted, but one problem {remained}.","grp":["last","remain"],"k":"topic"},{"w":"maintain","pos":"v","vi":"duy trì/bảo dưỡng","ex":"Regular maintenance helps sustain performance.","grp":["maintain","sustain"],"k":"topic"},{"w":"sustain","pos":"v","vi":"duy trì sức/tồn tại, chống đỡ","ex":"Regular maintenance helps {sustain} performance.","grp":["maintain","sustain"],"k":"topic"},{"w":"modify","pos":"v","vi":"sửa đổi","ex":"We {modified} the design, then refined the details.","grp":["modify","refine"],"k":"topic"},{"w":"refine","pos":"v","vi":"tinh chỉnh, cải tiến cho tinh hơn","ex":"We modified the design, then {refined} the details.","grp":["modify","refine"],"k":"topic"},{"w":"novel","pos":"n/adj","vi":"mới lạ","ex":"The {novel} approach has considerable potential.","grp":["novel","potential"],"k":"topic"},{"w":"potential","pos":"n/adj","vi":"tiềm năng/có khả năng","ex":"The novel approach has considerable {potential}.","grp":["novel","potential"],"k":"topic"},{"w":"progress","pos":"v/n","vi":"tiến bộ/sự tiến bộ","ex":"The reforms allowed the project to {progress}.","grp":["progress","reform"],"k":"topic"},{"w":"reform","pos":"v/n","vi":"cải cách/sự cải cách","ex":"The {reforms} allowed the project to progress.","grp":["progress","reform"],"k":"topic"},{"w":"revolution","pos":"n phr","vi":"cách mạng/thay đổi lớn","ex":"The digital {revolution} challenged the status quo.","grp":["revolution","status quo"],"k":"topic"},{"w":"status quo","pos":"n phr","vi":"hiện trạng","ex":"The digital revolution challenged the {status quo}.","grp":["revolution","status quo"],"k":"topic"},{"w":"shift","pos":"v/n","vi":"chuyển dịch","ex":"A {shift} in demand made us switch suppliers.","grp":["shift","switch"],"k":"topic"},{"w":"switch","pos":"v/n","vi":"đổi sang, công tắc/sự đổi","ex":"A shift in demand made us {switch} suppliers.","grp":["shift","switch"],"k":"topic"},{"w":"breakthrough","pos":"adj","vi":"đột phá","ex":"The {breakthrough} replaced a primitive manufacturing method.","grp":["breakthrough","primitive"],"k":"topic"},{"w":"primitive","pos":"adj","vi":"thô sơ, thuộc giai đoạn sớm","ex":"The breakthrough replaced a {primitive} manufacturing method.","grp":["breakthrough","primitive"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"broadband","pos":"v/n","vi":"băng thông rộng","ex":"{Broadband} connects the school to a wider network.","grp":["broadband","network"],"k":"topic"},{"w":"network","pos":"v/n","vi":"mạng/kết nối thành mạng","ex":"Broadband connects the school to a wider {network}.","grp":["broadband","network"],"k":"topic"},{"w":"click","pos":"n","vi":"nhấp chuột","ex":"{Click} the file to open it.","grp":["click","file"],"k":"topic"},{"w":"file","pos":"n","vi":"tệp/tập hồ sơ","ex":"Click the {file} to open it.","grp":["click","file"],"k":"topic"},{"w":"complex","pos":"adj/n","vi":"phức tạp","ex":"The {complex} device comes with a clear manual.","grp":["complex","manual"],"k":"topic"},{"w":"manual","pos":"adj/n","vi":"thủ công/sách hướng dẫn","ex":"The complex device comes with a clear {manual}.","grp":["complex","manual"],"k":"topic"},{"w":"consumer electronics","pos":"n phr","vi":"đồ điện tử tiêu dùng","ex":"The shop sells {consumer electronics}, including games consoles.","grp":["consumer electronics","games console"],"k":"topic"},{"w":"games console","pos":"n phr","vi":"máy chơi trò chơi điện tử","ex":"The shop sells consumer electronics, including {games consoles}.","grp":["consumer electronics","games console"],"k":"topic"},{"w":"craft","pos":"n","vi":"chế tác/nghề thủ công","ex":"{Crafting} the model requires a precise technique.","grp":["craft","technique"],"k":"topic"},{"w":"technique","pos":"n","vi":"kĩ thuật, phương pháp","ex":"Crafting the model requires a precise {technique}.","grp":["craft","technique"],"k":"topic"},{"w":"data","pos":"n","vi":"dữ liệu","ex":"Reliable {data} is an important research resource.","grp":["data","resource"],"k":"topic"},{"w":"resource","pos":"n","vi":"nguồn lực/tài nguyên","ex":"Reliable data is an important research {resource}.","grp":["data","resource"],"k":"topic"},{"w":"download","pos":"v","vi":"tải xuống/tệp tải","ex":"{Download} the form, complete it and upload the file.","grp":["download","upload"],"k":"topic"},{"w":"upload","pos":"v","vi":"tải lên","ex":"Download the form, complete it and {upload} the file.","grp":["download","upload"],"k":"topic"},{"w":"offline","pos":"adj/adv","vi":"không kết nối mạng","ex":"Draft the text {offline}, then submit it online.","grp":["offline","online"],"k":"topic"},{"w":"online","pos":"adj/adv","vi":"kết nối/trên mạng","ex":"Draft the text offline, then submit it {online}.","grp":["offline","online"],"k":"topic"},{"w":"nuclear","pos":"n","vi":"thuộc hạt nhân","ex":"A programmer developed software for the {nuclear} research team.","grp":["nuclear","programmer"],"k":"topic"},{"w":"programmer","pos":"n","vi":"lập trình viên","ex":"A {programmer} developed software for the nuclear research team.","grp":["nuclear","programmer"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"back up","vi":"sao lưu; lên tiếng ủng hộ; backup (n) = bản dự phòng","ex":"Back {up} the data before updating the system.","k":"pv"},{"w":"change around","vi":"đổi vị trí các đồ vật","ex":"We changed the desks {around}.","k":"pv"},{"w":"change into","vi":"biến thành; thay sang quần áo khác","ex":"The caterpillar changed {into} a butterfly.","k":"pv"},{"w":"change out of","vi":"cởi/thay bộ đồ đang mặc","ex":"Change out {of} your wet clothes.","k":"pv"},{"w":"do away with","vi":"loại bỏ","ex":"The update does away {with} paper forms.","k":"pv"},{"w":"do up","vi":"sửa sang; cài/buộc áo quần","ex":"They did up the house; do your coat {up} before leaving.","k":"pv"},{"w":"fade away","vi":"mờ/biến mất dần","ex":"The old custom gradually faded {away}.","k":"pv"},{"w":"key in","vi":"nhập thông tin bằng bàn phím","ex":"Key {in} your access code.","k":"pv"},{"w":"make into","vi":"biến/chế thành","ex":"They made the warehouse {into} a library.","k":"pv"},{"w":"mix up","vi":"trộn lộn xộn; nhầm lẫn; mix-up (n)","ex":"I mixed {up} the two file names.","k":"pv"},{"w":"switch on/off","vi":"bật/tắt máy, đèn","ex":"Switch the device {off} before cleaning it.","k":"pv"},{"w":"take apart","vi":"tháo thành các bộ phận","ex":"The technician took the motor {apart}.","k":"pv"},{"w":"test out","vi":"dùng thử để kiểm tra hiệu quả","ex":"We tested {out} the prototype.","k":"pv"},{"w":"turn into","vi":"biến thành, làm biến đổi","ex":"The app turns speech {into} text.","k":"pv"},{"w":"use up","vi":"dùng hết","ex":"The process used {up} all our supplies.","k":"pv"},{"w":"wear out","vi":"làm/dùng đến mòn hỏng","ex":"Heavy use wore the components {out}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"access","vi":"có/được/cung cấp quyền vào; kết nối mạng/lối cho xe lăn","ex":"The update provides easier {access} to the archive.","note":"have/gain/provide access to; internet/wheelchair access","k":"col"},{"w":"break","vi":"bỏ thói quen; khác truyền thống; rời bỏ; nghỉ","ex":"The design {breaks} with tradition.","note":"break a habit; break with tradition; make the break from; take/have/need a break; a welcome break from; lunch/tea/coffee break","k":"col"},{"w":"change","vi":"đổi từ/sang; biến thành; đổi lấy; tốt/xấu đi; đổi ý/chủ đề; tạo/trải qua thay đổi","ex":"The system underwent a {change} for the better.","note":"change from A to B; change A into B; change sth for; change for the better/worse; change your mind/the subject; make/undergo a change","k":"col"},{"w":"clock","vi":"chỉnh/nhìn giờ; chạy đua thời gian/liên tục; cùng chiều kim; cơ cấu đồng hồ","ex":"Engineers worked around the {clock}.","note":"set/watch a clock; against/around the clock; clockwise; clockwork","k":"col"},{"w":"date","vi":"có từ; cập nhật; hẹn ngày; đến nay","ex":"The oldest records {date} back to 1900.","note":"date from/back to; keep up to date; set/fix a date; go on/make a date with; at a later/future date; to date","k":"col"},{"w":"demand","vi":"đòi; đáp ứng nhu cầu; được cần/theo yêu cầu","ex":"We cannot meet the {demand} for the new model.","note":"demand sth from sb; meet/satisfy/make a demand; demand for; in/on demand","k":"col"},{"w":"energy","vi":"sức lực/năng lượng, nguồn và nhu cầu","ex":"She put all her {energy} into improving the design.","note":"have/lack energy to V; put/throw energy into; nuclear energy; source of energy; energy needs/crisis","k":"col"},{"w":"form","vi":"hình thành ấn tượng; mang dạng; điền đơn; phong độ","ex":"The warning appeared in the {form} of a message.","note":"form an impression of; take/assume the form of; fill in/out a form; in the form of; in good/bad form; application form","k":"col"},{"w":"good","vi":"có lợi; khá nhiều; tử tế; vì lợi ích; vô ích","ex":"It is no {good} blaming the software without checking the data.","note":"good for sb to V; a good deal; a good many/few; good of sb to V; for sb's own good; no good; it is no good V-ing","k":"col"},{"w":"know","vi":"biết; biết rõ; đủ khôn; báo cho biết; thạo tin; bí quyết","ex":"The project requires technical {know}- how.","note":"know about; know sb/sth to be/do; know better; get/come to know; let sb know; in the know; know-how","k":"col"},{"w":"lead","vi":"dẫn dắt, gây ra, dẫn đầu","ex":"The evidence led us to revise the plan.","note":"lead sb into; lead the way/world; lead sb to V; lead to/down/through; take/hold/follow the lead; in the lead","k":"col"},{"w":"link","vi":"liên kết; nhấp đường dẫn; xác lập liên hệ","ex":"They established a {link} between the two faults.","note":"link to; link A to/with B; click on/follow a link; find/prove/establish a link between","k":"col"},{"w":"place","vi":"đổi/thay chỗ; triển khai; thay vì; lạc lõng","ex":"A new procedure was put in {place}.","note":"change/swap places with; take the place of / take sb's place; put in place; in place of; out of place; place of work; no place for","k":"col"},{"w":"process","vi":"quá trình; đang làm; tiến trình hòa bình; phương pháp loại trừ","ex":"We identified the fault by a {process} of elimination.","note":"the process of; in the process of V-ing; peace process; process of elimination","k":"col"},{"w":"purpose","vi":"có ích; mục đích; ý thức mục tiêu; cố ý","ex":"Every feature serves a clear {purpose}.","note":"serve a purpose; purpose of V-ing; sb's purpose in V-ing; sense of purpose; on purpose","k":"col"},{"w":"reality","vi":"trốn/đối mặt thực tế; thành thật; thực ra; thực tế ảo","ex":"The proposal finally became a {reality}.","note":"escape from/face up to reality; become a reality; in reality; virtual reality; reality TV","k":"col"},{"w":"tool","vi":"công cụ để/của; thanh công cụ; bộ/hộp dụng cụ","ex":"The app is a useful {tool} for tracking progress.","note":"a tool for V-ing; a tool of; toolbar; tool kit/box","k":"col"},{"w":"use","vi":"dùng; đang dùng; hữu ích/vô ích","ex":"There is no {use} installing software you cannot operate.","note":"use sth for V-ing / to V / as; use properly; have many uses; in use; of no use; it is/there is no use V-ing; what is the use of V-ing?","k":"col"},{"w":"web","vi":"lướt mạng; trang web; camera mạng; quản trị web; nhật kí mạng","ex":"The instructions are available on the {website}.","note":"surf/on the Web; website; web page; webcam; World Wide Web; webmaster; weblog/blog","k":"col"},{"w":"wheel","vi":"cầm lái; đang lái; có bánh xe; vòng quay vận may","ex":"She took the {wheel} for the final part of the journey.","note":"take the wheel; at/behind the wheel; on wheels; wheel of fortune","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a leopard can't change its spots","vi":"bản tính khó thay đổi","ex":"He keeps making excuses; {a leopard can't change its spots}.","k":"idiom"},{"w":"all mod cons","vi":"đầy đủ tiện nghi hiện đại","ex":"The flat has {all mod cons}.","k":"idiom"},{"w":"break the mould","vi":"làm khác khuôn mẫu, tạo đột phá","ex":"The new design breaks {the mould}.","k":"idiom"},{"w":"change your tune","vi":"đổi giọng/đổi thái độ","ex":"He changed his {tune} when he saw the results.","k":"idiom"},{"w":"have a change of heart","vi":"đổi ý hoặc đổi cảm nhận về việc đã định","ex":"She had {a change of heart} and accepted.","k":"idiom"},{"w":"know sth inside out","vi":"biết tường tận","ex":"The mechanic knows this engine {inside} out.","k":"idiom"},{"w":"reinvent the wheel","vi":"tốn công làm lại thứ đã có giải pháp tốt","ex":"Use the existing template instead of reinventing {the wheel}.","k":"idiom"},{"w":"stick to your guns","vi":"giữ lập trường dù bị phản đối","ex":"She stuck to her {guns} during the debate.","k":"idiom"},{"w":"the tools of the trade","vi":"kĩ năng, dụng cụ cần cho nghề","ex":"A good dictionary is one of the translator's {tools of the trade}.","k":"idiom"},{"w":"turn over a new leaf","vi":"bắt đầu sống/cư xử tốt hơn","ex":"He promised to {turn over a new leaf}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"adapt","vi":"thích nghi/chuyển thể","note":"adapt → adaptation, adaptor, adaptable","full":"thích nghi/chuyển thể → bản/sự chuyển thể; bộ chuyển; dễ thích nghi.","ex":"{Adaptable} workers learn new systems quickly.","hint":"adapt","k":"wf"},{"w":"adjust","vi":"điều chỉnh","note":"adjust → readjust, adjustment, adjustable","full":"điều chỉnh → chỉnh lại; sự chỉnh; điều chỉnh được.","ex":"The chair has an {adjustable} back.","hint":"adjust","k":"wf"},{"w":"alter","vi":"thay đổi","note":"alter → alteration, unalterable, unaltered, alternate, alternative","full":"thay đổi → sự sửa; không thể/không bị đổi; luân phiên; lựa chọn khác.","ex":"The original plan remained {unaltered}.","hint":"alter","k":"wf"},{"w":"arrange","vi":"sắp xếp","note":"arrange → rearrange, (re)arrangement, arranged","full":"sắp xếp → sắp xếp lại; sự sắp xếp; được sắp đặt.","ex":"We discussed the revised arrangements.","hint":"arrange","k":"wf"},{"w":"capable","vi":"có khả năng","note":"capable → capability, incapable, capably","full":"có khả năng → năng lực; không thể/không đủ năng lực; một cách có năng lực.","ex":"The team demonstrated its technical {capability}.","hint":"capable","k":"wf"},{"w":"change","vi":"thay đổi","note":"change → exchange, changeover, (un)changing, (un)changeable, interchangeable","full":"thay đổi → trao đổi; chuyển đổi hệ thống; biến đổi/không đổi; thay được/không; dùng thay nhau được.","ex":"The two parts are {interchangeable}.","hint":"change","k":"wf"},{"w":"continue","vi":"tiếp tục","note":"continue → discontinue, continuity, continuation, continual(ly), continuous(ly)","full":"tiếp tục → ngừng cung cấp; tính liên tục; sự tiếp tục; lặp đi lặp lại; không gián đoạn.","ex":"{Continuous} monitoring prevents repeated failures.","hint":"continue","k":"wf"},{"w":"convert","vi":"chuyển đổi","note":"convert → conversion, convertible","full":"chuyển đổi → sự chuyển đổi; có thể đổi/xe mui trần.","ex":"The {conversion} took six months.","hint":"convert","k":"wf"},{"w":"electric","vi":"điện","note":"electric → electrify, electrician, electricity, electrified, electrifying, electrical(ly)","full":"điện → điện khí hóa/làm phấn khích; thợ điện; điện năng; đã điện khí hóa; gây phấn khích; thuộc điện.","ex":"An {electrician} checked the electrical wiring.","hint":"electric","k":"wf"},{"w":"endure","vi":"chịu đựng","note":"endure → endurance, (un)endurable, enduring","full":"chịu đựng → sức bền; chịu được/không; lâu dài.","ex":"The material has {enduring} appeal.","hint":"endure","k":"wf"},{"w":"evolve","vi":"tiến hóa","note":"evolve → evolution, evolutionary, evolving","full":"tiến hóa → sự tiến hóa; thuộc tiến hóa; đang phát triển.","ex":"The system is constantly {evolving}.","hint":"evolve","k":"wf"},{"w":"flexible","vi":"linh hoạt","note":"flexible → (in)flexibility, inflexible","full":"linh hoạt → tính linh hoạt/cứng nhắc; không linh hoạt.","ex":"{Flexibility} helps a business adapt.","hint":"flexible","k":"wf"},{"w":"influence","vi":"ảnh hưởng","note":"influence → influential","full":"ảnh hưởng → có ảnh hưởng.","ex":"She became an {influential} designer.","hint":"influence","k":"wf"},{"w":"mature","vi":"trưởng thành","note":"mature → (im)maturity, maturation, immature","full":"trưởng thành → sự trưởng thành/non nớt; quá trình chín; chưa trưởng thành.","ex":"The technology has reached {maturity}.","hint":"mature","k":"wf"},{"w":"modern","vi":"hiện đại","note":"modern → modernise, modernisation, modernism, modernity, modernist","full":"hiện đại → hiện đại hóa; sự hiện đại hóa; chủ nghĩa/tính hiện đại; người theo trường phái hiện đại.","ex":"{Modernisation} improved efficiency.","hint":"modern","k":"wf"},{"w":"new","vi":"mới","note":"new → renew, renewal, newness, renewable, newly, anew","full":"mới → làm mới/gia hạn; sự gia hạn; tính mới; tái tạo được; mới đây; lại từ đầu.","ex":"{Renewable} resources must still be managed carefully.","hint":"new","k":"wf"},{"w":"persist","vi":"kiên trì/tồn tại","note":"persist → persistence, persistent(ly)","full":"kiên trì/tồn tại → sự dai dẳng; dai dẳng/kiên trì; trạng từ.","ex":"{Persistence} helped solve the problem.","hint":"persist","k":"wf"},{"w":"place","vi":"đặt","note":"place → replace, placement, placing, replacement, (ir)replaceable","full":"đặt → thay thế; sự bố trí; thứ hạng; vật thay; có/không thể thay thế.","ex":"The damaged part needs {replacement}.","hint":"place","k":"wf"},{"w":"process","vi":"xử lí","note":"process → processor, processing, processed","full":"xử lí → bộ/người xử lí; việc xử lí; đã qua xử lí.","ex":"The {processor} handles large amounts of data.","hint":"process","k":"wf"},{"w":"revolt","vi":"nổi dậy","note":"revolt → revolutionise, revolution, revolutionary, revolting","full":"nổi dậy → cách mạng hóa; cuộc cách mạng; cách mạng; ghê tởm.","ex":"The invention revolutionised communication.","hint":"revolt","k":"wf"}]}]},{"g":3,"u":6,"title":"Time and Work","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"abrupt","pos":"adj","vi":"đột ngột, cộc lốc","ex":"The change was {abrupt}, and its effect was instantaneous.","grp":["abrupt","instantaneous"],"k":"topic"},{"w":"instantaneous","pos":"adj","vi":"xảy ra ngay lập tức","ex":"The change was abrupt, and its effect was {instantaneous}.","grp":["abrupt","instantaneous"],"k":"topic"},{"w":"anachronism","pos":"adj","vi":"thứ lỗi thời/sai niên đại","ex":"The obsolete machine seemed an {anachronism} in a modern office.","grp":["anachronism","obsolete"],"k":"topic"},{"w":"obsolete","pos":"adj","vi":"không còn được dùng","ex":"The {obsolete} machine seemed an anachronism in a modern office.","grp":["anachronism","obsolete"],"k":"topic"},{"w":"annual","pos":"adj","vi":"hằng năm","ex":"{Annual} figures can hide seasonal changes.","grp":["annual","seasonal"],"k":"topic"},{"w":"seasonal","pos":"adj","vi":"theo mùa","ex":"Annual figures can hide {seasonal} changes.","grp":["annual","seasonal"],"k":"topic"},{"w":"antique","pos":"n/adj","vi":"đồ cổ/cổ","ex":"The shop sells {antique} furniture and vintage clothing.","grp":["antique","vintage"],"k":"topic"},{"w":"vintage","pos":"n/adj","vi":"thuộc niên đại xưa, thường chất lượng hoặc phong cách tiêu biểu","ex":"The shop sells antique furniture and {vintage} clothing.","grp":["antique","vintage"],"k":"topic"},{"w":"century","pos":"n","vi":"thế kỉ, 100 năm","ex":"The discovery shaped the next decade and the whole {century}.","grp":["century","decade"],"k":"topic"},{"w":"decade","pos":"n","vi":"thập kỉ, 10 năm","ex":"The discovery shaped the next {decade} and the whole century.","grp":["century","decade"],"k":"topic"},{"w":"chronological","pos":"adj","vi":"theo thứ tự thời gian","ex":"Put the events in {chronological} order and note any prior warnings.","grp":["chronological","prior"],"k":"topic"},{"w":"prior","pos":"adj","vi":"có trước","ex":"Put the events in chronological order and note any {prior} warnings.","grp":["chronological","prior"],"k":"topic"},{"w":"contemporary","pos":"adj","vi":"đương thời/hiện đại, người cùng thời","ex":"{Contemporary} accounts differed from subsequent interpretations.","grp":["contemporary","subsequent"],"k":"topic"},{"w":"subsequent","pos":"adj","vi":"xảy ra sau","ex":"Contemporary accounts differed from {subsequent} interpretations.","grp":["contemporary","subsequent"],"k":"topic"},{"w":"duration","pos":"v/n","vi":"thời lượng","ex":"The project's {duration} spans three years.","grp":["duration","span"],"k":"topic"},{"w":"span","pos":"v/n","vi":"kéo dài/bao trùm, khoảng thời gian","ex":"The project's duration {spans} three years.","grp":["duration","span"],"k":"topic"},{"w":"elapse","pos":"v","vi":"thời gian trôi","ex":"A year {elapsed} before her membership lapsed.","grp":["elapse","lapse"],"k":"topic"},{"w":"lapse","pos":"v","vi":"hết hiệu lực, sa vào; sơ suất/khoảng gián đoạn","ex":"A year elapsed before her membership {lapsed}.","grp":["elapse","lapse"],"k":"topic"},{"w":"era","pos":"n","vi":"thời đại/kỉ nguyên","ex":"The reform marked a new {era} after a difficult period.","grp":["era","period"],"k":"topic"},{"w":"period","pos":"n","vi":"giai đoạn/khoảng thời gian","ex":"The reform marked a new era after a difficult {period}.","grp":["era","period"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"eternal","pos":"adj","vi":"vĩnh cửu, như kéo dài vô tận","ex":"They sought permanent peace, not {eternal} conflict.","grp":["eternal","permanent"],"k":"topic"},{"w":"permanent","pos":"adj","vi":"lâu dài, không tạm thời","ex":"They sought {permanent} peace, not eternal conflict.","grp":["eternal","permanent"],"k":"topic"},{"w":"expire","pos":"adj","vi":"hết hạn","ex":"My pass {expired}; its renewal is overdue.","grp":["expire","overdue"],"k":"topic"},{"w":"overdue","pos":"adj","vi":"quá hạn hoặc lẽ ra đã có từ lâu","ex":"My pass expired; its renewal is {overdue}.","grp":["expire","overdue"],"k":"topic"},{"w":"frequency","pos":"n","vi":"tần suất","ex":"The {frequency} increased as the intervals became shorter.","grp":["frequency","interval"],"k":"topic"},{"w":"interval","pos":"n","vi":"quãng thời gian giữa hai sự việc","ex":"The frequency increased as the {intervals} became shorter.","grp":["frequency","interval"],"k":"topic"},{"w":"interim","pos":"adj","vi":"thời gian giữa/tạm thời","ex":"An {interim} manager approved a provisional timetable.","grp":["interim","provisional"],"k":"topic"},{"w":"provisional","pos":"adj","vi":"tạm định, có thể sửa","ex":"An interim manager approved a {provisional} timetable.","grp":["interim","provisional"],"k":"topic"},{"w":"lifetime","pos":"n","vi":"đời người/thời gian tồn tại","ex":"Few {lifetimes} witness the start of a millennium.","grp":["lifetime","millennium"],"k":"topic"},{"w":"millennium","pos":"n","vi":"thiên niên kỉ, 1.000 năm","ex":"Few lifetimes witness the start of a {millennium}.","grp":["lifetime","millennium"],"k":"topic"},{"w":"long-standing","pos":"adj","vi":"tồn tại lâu","ex":"A temporary measure will not solve a {long-standing} problem.","grp":["long-standing","temporary"],"k":"topic"},{"w":"temporary","pos":"adj","vi":"tạm thời","ex":"A {temporary} measure will not solve a long-standing problem.","grp":["long-standing","temporary"],"k":"topic"},{"w":"phase","pos":"n","vi":"giai đoạn của quá trình","ex":"She completed a short stint abroad during the research {phase}.","grp":["phase","stint"],"k":"topic"},{"w":"stint","pos":"n","vi":"thời gian làm một công việc/hoạt động","ex":"She completed a short {stint} abroad during the research phase.","grp":["phase","stint"],"k":"topic"},{"w":"postpone","pos":"adj","vi":"hoãn","ex":"A prompt reply may prevent us from {postponing} the meeting.","grp":["postpone","prompt"],"k":"topic"},{"w":"prompt","pos":"adj","vi":"nhanh chóng, đúng lúc không chậm","ex":"A {prompt} reply may prevent us from postponing the meeting.","grp":["postpone","prompt"],"k":"topic"},{"w":"punctual","pos":"adj","vi":"đúng giờ đã hẹn","ex":"The {punctual} courier brought a timely warning.","grp":["punctual","timely"],"k":"topic"},{"w":"timely","pos":"adj","vi":"đúng lúc cần, kịp thời","ex":"The punctual courier brought a {timely} warning.","grp":["punctual","timely"],"k":"topic"},{"w":"simultaneous","pos":"n","vi":"đồng thời","ex":"{Simultaneous} failures caused a brief spell of confusion.","grp":["simultaneous","spell"],"k":"topic"},{"w":"spell","pos":"n","vi":"một đợt/khoảng thời gian","ex":"Simultaneous failures caused a brief {spell} of confusion.","grp":["simultaneous","spell"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"civil service","pos":"n phr","vi":"bộ máy công chức; public/private sector: khu vực nhà nước/tư nhân","ex":"She moved from the {civil service} to the private sector.","grp":["civil service","public-private sector"],"k":"topic"},{"w":"client","pos":"n","vi":"khách hàng dùng dịch vụ chuyên môn","ex":"The consultant discussed the proposal with her {client}.","grp":["client","consultant"],"k":"topic"},{"w":"consultant","pos":"n","vi":"chuyên gia tư vấn","ex":"The {consultant} discussed the proposal with her client.","grp":["client","consultant"],"k":"topic"},{"w":"colleague","pos":"n","vi":"đồng nghiệp","ex":"My {colleague} was promoted to a senior executive.","grp":["colleague","executive"],"k":"topic"},{"w":"executive","pos":"n","vi":"người quản lí/điều hành","ex":"My colleague was promoted to a senior {executive}.","grp":["colleague","executive"],"k":"topic"},{"w":"effective","pos":"adj","vi":"đạt kết quả mong muốn","ex":"The method is {effective} but not energy-efficient.","grp":["effective","efficient"],"k":"topic"},{"w":"efficient","pos":"adj","vi":"đạt kết quả ít lãng phí nguồn lực","ex":"The method is effective but not energy-{efficient}.","grp":["effective","efficient"],"k":"topic"},{"w":"fire / sack","pos":"v","vi":"đều là sa thải; sack thường thân mật hơn.","de":"","ex":"The company fired the manager and sacked two assistants.","k":"topic"},{"w":"headhunt","pos":"v","vi":"chủ động mời người giỏi về làm","ex":"They {headhunted} a director and recruited several trainees.","grp":["headhunt","recruit"],"k":"topic"},{"w":"recruit","pos":"v","vi":"tuyển/người mới được tuyển","ex":"They headhunted a director and {recruited} several trainees.","grp":["headhunt","recruit"],"k":"topic"},{"w":"leave","pos":"v/n","vi":"thời gian nghỉ được phép","ex":"Staff on annual {leave} did not join the strike.","grp":["leave","strike"],"k":"topic"},{"w":"strike","pos":"v/n","vi":"đình công/cuộc đình công","ex":"Staff on annual leave did not join the {strike}.","grp":["leave","strike"],"k":"topic"},{"w":"marketing","pos":"n/adj","vi":"tiếp thị","ex":"She works in {marketing} for a multinational.","grp":["marketing","multinational"],"k":"topic"},{"w":"multinational","pos":"n/adj","vi":"công ty đa quốc gia/thuộc nhiều nước","ex":"She works in marketing for a {multinational}.","grp":["marketing","multinational"],"k":"topic"},{"w":"promotion","pos":"n","vi":"thăng chức/quảng bá","ex":"The training improved her {promotion} prospects.","grp":["promotion","prospects"],"k":"topic"},{"w":"prospects","pos":"n","vi":"triển vọng","ex":"The training improved her promotion {prospects}.","grp":["promotion","prospects"],"k":"topic"},{"w":"redundant","pos":"n","vi":"bị mất việc vì vị trí không cần","ex":"The union supported workers who were made {redundant}.","grp":["redundant","union"],"k":"topic"},{"w":"union","pos":"n","vi":"công đoàn","ex":"The {union} supported workers who were made redundant.","grp":["redundant","union"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"crop up","vi":"xuất hiện/xảy ra bất ngờ","ex":"A problem cropped {up} during testing.","k":"pv"},{"w":"dive in","vi":"bắt đầu đầy nhiệt tình","ex":"She dived {in} without waiting for instructions.","k":"pv"},{"w":"end up","vi":"cuối cùng ở tình trạng/nơi nào","ex":"We ended {up} working late.","k":"pv"},{"w":"kick off with","vi":"bắt đầu bằng","ex":"The workshop kicked off {with} a discussion.","k":"pv"},{"w":"knock off","vi":"ngừng làm việc (thân mật)","ex":"What time do you knock {off}?","k":"pv"},{"w":"knuckle down","vi":"bắt đầu làm chăm chỉ, nghiêm túc","ex":"It is time to knuckle {down} to revision.","k":"pv"},{"w":"lay off","vi":"cho nghỉ việc vì thiếu việc; tạm ngừng làm/dùng thứ gì","ex":"The factory laid {off} fifty workers.","k":"pv"},{"w":"lie ahead","vi":"đang chờ ở tương lai","ex":"Difficult decisions lie ahead.","k":"pv"},{"w":"make up","vi":"làm bù thời gian đã thiếu","ex":"I will make {up} the hours tomorrow.","k":"pv"},{"w":"press ahead/on with","vi":"kiên quyết tiếp tục dù khó khăn","ex":"They pressed ahead {with} the reforms.","k":"pv"},{"w":"set out","vi":"bắt đầu để đạt mục tiêu; outset (n) = khởi đầu","ex":"She set {out} to improve staff training.","k":"pv"},{"w":"be snowed under","vi":"ngập trong việc/thứ cần xử lí","ex":"We are snowed {under} with applications.","k":"pv"},{"w":"take on","vi":"tuyển người; nhận việc/trách nhiệm","ex":"The firm took {on} more staff.","k":"pv"},{"w":"tide over","vi":"giúp vượt qua giai đoạn khó, thường bằng tiền","ex":"The loan will tide us {over} until payday.","k":"pv"},{"w":"while away","vi":"thong thả giết thời gian","ex":"We whiled {away} the afternoon chatting.","k":"pv"},{"w":"wind down","vi":"giảm dần hoạt động; thư giãn","ex":"The business is winding {down} before closing.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"about","vi":"chủ yếu nói về; xử lí; đến lúc; sắp","ex":"It is {about} time we did something about the delay.","note":"partly/mainly/all about; do sth about; about time; about to V","k":"col"},{"w":"age","vi":"cư xử đúng tuổi; độ tuổi; thời đại","ex":"Skills can improve with {age}.","note":"act your age; at/by/from the age of; under age; school/working age; with age; age limit/bracket/group; Stone/Bronze/Iron Age","k":"col"},{"w":"ages","vi":"mất rất lâu; lâu rồi; tưởng như rất lâu","ex":"It seems like {ages} since we last met.","note":"take/spend ages V-ing; ages ago; seem/feel like ages since","k":"col"},{"w":"course","vi":"diễn biến tự nhiên; trong quá trình; đúng lúc sau này; hướng hành động","ex":"You will receive an answer in due {course}.","note":"run its course; in/during the course of; in due course; on a course; course of action/events","k":"col"},{"w":"day","vi":"làm ai rất vui; từng ngày; sắp tới; thời nay; ngày nghỉ/chơi/chuyến trong ngày","ex":"The good news made my {day}.","note":"make sb's day; day by day; from day to day; any day now; in this day and age; day off/out/trip","k":"col"},{"w":"end","vi":"kết thúc; cuối; chưa thấy hồi kết; liên tiếp; cuối cùng","ex":"They worked for days on {end}.","note":"come/bring/put to an end; at/by the very end of; no end in sight to; at an end; for hours/weeks on end; in the end","k":"col"},{"w":"ever","vi":"hiếm khi; nếu có; từng; hơn bao giờ; như mọi khi; suốt từ; mãi mãi","ex":"The service is better than {ever}.","note":"hardly ever; if ever; the first/only ... ever to V; better than ever; as ever; ever since; forever/for ever","k":"col"},{"w":"hours","vi":"giờ giấc đều/khuya; làm lâu; ngoài giờ","ex":"Please call during office {hours}.","note":"keep regular/late hours; work long hours; for hours on end; during school/working hours; at/until all hours; after/out of hours","k":"col"},{"w":"job","vi":"có/tìm/nhận/làm/rời/mất việc; may mà; làm tốt/kém; tận dụng hoàn cảnh xấu; có việc phải làm/khó làm; thất nghiệp; tại chỗ làm; mất việc hàng loạt","ex":"She made a good {job} of organising the meeting.","note":"get/find/take/do/leave/lose a job; it is a good job; make/do a good/bad job of; make the best of a bad job; have a job to do / V-ing; sb's job to V; out of/on the job; job losses","k":"col"},{"w":"moment","vi":"chốc lát; hiện tại; thời khắc quyết định","ex":"The results could arrive any {moment} now.","note":"take/be a moment; just/wait a moment; any moment now; at the moment; at this/that moment in time; in a moment; the right moment to/for; moment of truth","k":"col"},{"w":"never","vi":"biết đâu; không bao giờ nữa; đừng bận tâm; không bao giờ; không dứt","ex":"{Never} mind if the first attempt fails.","note":"you never know; never again; never mind; never mind if/whether; never ever; never-ending","k":"col"},{"w":"now","vi":"từ nay; tạm thời; đến nay; vì giờ đây; thỉnh thoảng","ex":"{Now} that everyone is here, we can begin.","note":"now is the time to; from now on; for now; up to now; right now; now that; any day/moment now; just now; every now and then/again; nowadays","k":"col"},{"w":"office","vi":"nhậm/ứng cử/giữ chức; trụ sở; người giữ chức; tòa nhà/giờ/tiệc văn phòng","ex":"She took {office} in January.","note":"take/run for/hold public office; head office; office holder/block/hours/party","k":"col"},{"w":"on","vi":"đúng giờ; mãi; liên tục; kể từ đó; đồng ý nhận kèo/lời thách","ex":"From then {on}, meetings started on time.","note":"on time; on and on; on end; from now/that moment/then on; You're on!","k":"col"},{"w":"second","vi":"một lát; trong vài giây; tích tắc","ex":"The decision was made in a split {second}.","note":"give/take sb a second to V; in a second; within seconds; seconds later; a split second","k":"col"},{"w":"start","vi":"khởi đầu tốt/xấu; có lợi thế trước; bắt đầu; ngay từ đầu; trước hết; ở đầu; khởi động việc","ex":"We got off to a flying {start}.","note":"have/make a good/fine/bad start; get off to a flying/head/bad start; make a start on/at; right from the start; for a start; at/from the start of; get sth started","k":"col"},{"w":"term","vi":"dài/ngắn hạn; học kì; nhiệm kì; án tù; thời hạn cố định","ex":"The policy should help in the long {term}.","note":"in the long/short term; end of term; term of/in office; term time; prison/jail term; fixed term; long-/short-term","k":"col"},{"w":"time","vi":"giết/dành/thu xếp/mất thời gian; kịp/đúng giờ; đến khi; nhiều lần; bán/toàn thời gian; khung/hạn","ex":"Make {time} for regular revision.","note":"pass/spend/make/find/take time; in/on time; by the time; time after time; part-/full-time; time frame/limit","k":"col"},{"w":"work","vi":"làm việc; rất hiệu quả; tác động hai chiều; lần lượt xử lí","ex":"The new arrangement {works} both ways.","note":"work on/in/with/as/at/for; work like magic / a treat / wonders; work both ways; work your way through/around; at work; out of/in work; a piece of work","k":"col"},{"w":"year","vi":"tuổi; so năm trước; nhiều năm; không đời nào; năm nhuận","ex":"Sales rose {year} on year.","note":"years of age / years old; year on year; for years; not/never in a million years; leap year","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a stitch in time saves nine","vi":"giải quyết sớm sẽ tránh rắc rối lớn sau này","ex":"Fix the small leak now; {a stitch in time saves nine}.","k":"idiom"},{"w":"all in good time","vi":"rồi sẽ đến lúc, cứ kiên nhẫn","ex":"You will hear the decision {all in good time}.","k":"idiom"},{"w":"at the drop of a hat","vi":"ngay lập tức, không do dự","ex":"She would travel {at the drop of a hat}.","k":"idiom"},{"w":"before your time","vi":"trước khi bạn sinh ra/đến làm ở nơi đó","ex":"That system was introduced {before your time}.","k":"idiom"},{"w":"for good","vi":"vĩnh viễn","ex":"The shop has closed {for good}.","k":"idiom"},{"w":"for the time being","vi":"tạm thời, trong lúc này","ex":"We will use the old office {for the time being}.","k":"idiom"},{"w":"from time to time","vi":"thỉnh thoảng","ex":"We meet {from time to time}.","k":"idiom"},{"w":"in/for donkey's years","vi":"rất lâu rồi (thân mật)","ex":"I have not seen him in {donkey's years}.","k":"idiom"},{"w":"in the nick of time","vi":"vừa kịp lúc tránh điều xấu","ex":"They arrived {in the nick of time}.","k":"idiom"},{"w":"once in a blue moon","vi":"rất hiếm khi","ex":"He takes a day off {once in a blue moon}.","k":"idiom"},{"w":"on the spur of the moment","vi":"bộc phát, không tính trước","ex":"We booked the trip {on the spur of the moment}.","k":"idiom"},{"w":"the other day","vi":"một ngày gần đây, hôm nọ","ex":"I saw your colleague {the other day}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"antique","vi":"cổ/đồ cổ","note":"antique → antiquity, antiquated","full":"cổ/đồ cổ → thời cổ/xưa; lỗi thời.","ex":"The office uses an {antiquated} system.","hint":"antique","k":"wf"},{"w":"apply","vi":"áp dụng/nộp đơn","note":"apply → reapply, misapply, applicant, application, (in)applicability, (in)applicable, (mis)applied","full":"áp dụng/nộp đơn → nộp lại/áp sai; ứng viên; đơn; khả năng áp dụng; áp dụng được/không; đã áp dụng/áp sai.","ex":"The rule is not {applicable} here.","hint":"apply","k":"wf"},{"w":"compete","vi":"cạnh tranh","note":"compete → competition, competitor, competitiveness, (un)competitive(ly)","full":"cạnh tranh → cuộc thi; đối thủ; sức cạnh tranh; có/không cạnh tranh.","ex":"Training improves {competitiveness}.","hint":"compete","k":"wf"},{"w":"employ","vi":"tuyển","note":"employ → (un)employment, underemployment, employer, employee, (un)employed, underemployed, (un)employable","full":"tuyển → việc làm/thất nghiệp; thiếu việc làm hoặc chưa dùng hết năng lực; chủ/nhân viên; có/không việc; thiếu việc; dễ/khó được tuyển.","ex":"Many qualified workers are {underemployed}.","hint":"employ","k":"wf"},{"w":"end","vi":"kết thúc","note":"end → ending, unending, endless(ly)","full":"kết thúc → đoạn kết; không dứt/vô tận; trạng từ.","ex":"The task required {endless} patience.","hint":"end","k":"wf"},{"w":"event","vi":"sự kiện","note":"event → eventuality, (un)eventful, eventual(ly)","full":"sự kiện → tình huống có thể xảy ra; nhiều/ít sự kiện; cuối cùng (không phải có thể).","ex":"We prepared for every {eventuality}.","hint":"event","k":"wf"},{"w":"expect","vi":"mong đợi","note":"expect → expectation, expectancy, expectant(ly), (un)expected(ly)","full":"mong đợi → kì vọng; sự mong/tuổi thọ; trông chờ; như dự kiến/bất ngờ.","ex":"The results exceeded expectations.","hint":"expect","k":"wf"},{"w":"future","vi":"tương lai","note":"future → futurist, futuristic(ally)","full":"tương lai → nhà vị lai; có vẻ thuộc tương lai.","ex":"The office has a {futuristic} design.","hint":"future","k":"wf"},{"w":"history","vi":"lịch sử","note":"history → historian, historic, historical(ly)","full":"lịch sử → nhà sử học; có ý nghĩa lịch sử; thuộc lịch sử.","ex":"The {historian} described a historic agreement.","hint":"history","k":"wf"},{"w":"incident","vi":"sự việc","note":"incident → incidence, coincidence, incidental(ly), coincidental(ly)","full":"sự việc → tần suất xảy ra; trùng hợp; phụ/kèm theo, nhân tiện; do trùng hợp.","ex":"The similarity was purely {coincidental}.","hint":"incident","k":"wf"},{"w":"job","vi":"công việc","note":"job → jobbing, jobless","full":"công việc → làm các việc ngắn hạn/lẻ; không có việc.","ex":"The scheme supports {jobless} graduates.","hint":"job","k":"wf"},{"w":"last","vi":"kéo dài","note":"last → outlast, lasting, everlasting, lastly","full":"kéo dài → tồn tại lâu hơn; bền lâu; vĩnh cửu; cuối cùng là.","ex":"The reform had a {lasting} effect.","hint":"last","k":"wf"},{"w":"manage","vi":"quản lí","note":"manage → mismanage, manager, manageress, (mis)management, (un)manageable, mismanaged, managerial, managing","full":"quản lí → quản lí sai; quản lí viên/thuật ngữ nữ ít dùng hiện nay; sự quản lí tốt/kém; xử lí được/không; thuộc quản lí/điều hành.","ex":"Poor management made the workload {unmanageable}.","hint":"manage","k":"wf"},{"w":"moment","vi":"khoảnh khắc","note":"moment → momentous, momentary, momentarily","full":"khoảnh khắc → hệ trọng; chốc lát; trong chốc lát/chẳng bao lâu tùy biến thể tiếng Anh.","ex":"It was a {momentous} decision.","hint":"moment","k":"wf"},{"w":"period","vi":"giai đoạn","note":"period → periodical, periodic(ally)","full":"giai đoạn → ấn phẩm định kì; có tính/diễn ra định kì.","ex":"We carry out {periodic} reviews.","hint":"period","k":"wf"},{"w":"produce","vi":"sản xuất","note":"produce → producer, product, productivity, production, counterproductive, (un)productive(ly)","full":"sản xuất → nhà sản xuất; sản phẩm; năng suất; sản xuất; phản tác dụng; hiệu quả/không.","ex":"Excessive meetings can be {counterproductive}.","hint":"produce","k":"wf"},{"w":"time","vi":"thời gian","note":"time → mistime, timer, timing, overtime, timetable, timelessness, (un)timely, timeless(ly)","full":"thời gian → chọn sai lúc; bộ hẹn; việc chọn lúc; tăng ca; lịch; tính vượt thời gian; đúng/không đúng lúc; không lỗi thời.","ex":"A {timely} warning prevented a delay.","hint":"time","k":"wf"},{"w":"work","vi":"làm","note":"work → rework, overwork, worker, works, reworking, workplace, overworked, working, (un)workable","full":"làm → làm lại/quá sức; người lao động; tác phẩm/nhà máy; sự làm lại; nơi làm; quá tải; đang làm; khả thi/không.","ex":"The revised proposal is {workable}.","hint":"work","k":"wf"}]}]},{"g":3,"u":8,"title":"Movement and Transport","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/4 (Topic vocabulary)","words":[{"w":"accelerate","pos":"n","vi":"tăng tốc","ex":"The car {accelerated} until it reached a safe cruising velocity.","grp":["accelerate","velocity"],"k":"topic"},{"w":"velocity","pos":"n","vi":"vận tốc, có thể bao gồm hướng","ex":"The car accelerated until it reached a safe cruising {velocity}.","grp":["accelerate","velocity"],"k":"topic"},{"w":"approach","pos":"n","vi":"tiến đến/cách tiếp cận","ex":"We {approached} the village by a different route.","grp":["approach","route"],"k":"topic"},{"w":"route","pos":"n","vi":"tuyến đường","ex":"We approached the village by a different {route}.","grp":["approach","route"],"k":"topic"},{"w":"ascend","pos":"v","vi":"đi lên","ex":"We {ascended} the hill and descended before sunset.","grp":["ascend","descend"],"k":"topic"},{"w":"descend","pos":"v","vi":"đi xuống","ex":"We ascended the hill and {descended} before sunset.","grp":["ascend","descend"],"k":"topic"},{"w":"bounce","pos":"v/n","vi":"nảy/cú nảy","ex":"The ball {bounced} twice and rolled away.","grp":["bounce","roll"],"k":"topic"},{"w":"roll","pos":"v/n","vi":"lăn/cuộn","ex":"The ball bounced twice and {rolled} away.","grp":["bounce","roll"],"k":"topic"},{"w":"clamber","pos":"v","vi":"leo trèo khó nhọc bằng tay chân","ex":"We {clambered} over rocks and crawled through a narrow opening.","grp":["clamber","crawl"],"k":"topic"},{"w":"crawl","pos":"v","vi":"bò/di chuyển rất chậm","ex":"We clambered over rocks and {crawled} through a narrow opening.","grp":["clamber","crawl"],"k":"topic"},{"w":"clench","pos":"v","vi":"siết chặt răng/tay","ex":"She {clenched} her teeth and clutched the rope.","grp":["clench","clutch"],"k":"topic"},{"w":"clutch","pos":"v","vi":"nắm chặt vì sợ/để giữ","ex":"She clenched her teeth and {clutched} the rope.","grp":["clench","clutch"],"k":"topic"},{"w":"creep","pos":"v","vi":"đi rón rén/chậm","ex":"A fox crept past while deer roamed freely.","grp":["creep","roam"],"k":"topic"},{"w":"roam","pos":"v","vi":"đi lang thang tự do","ex":"A fox crept past while deer {roamed} freely.","grp":["creep","roam"],"k":"topic"},{"w":"dash","pos":"v","vi":"lao/chạy vội","ex":"He jogged around the park, then {dashed} home.","grp":["dash","jog"],"k":"topic"},{"w":"jog","pos":"v","vi":"chạy chậm đều","ex":"He {jogged} around the park, then dashed home.","grp":["dash","jog"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/4 (Topic vocabulary)","words":[{"w":"drift","pos":"v","vi":"trôi theo dòng/gió, xu hướng","ex":"The boat floated on the lake and {drifted} towards shore.","grp":["drift","float"],"k":"topic"},{"w":"float","pos":"v","vi":"nổi/lơ lửng","ex":"The boat {floated} on the lake and drifted towards shore.","grp":["drift","float"],"k":"topic"},{"w":"emigrate","pos":"n","vi":"rời nước mình để định cư","ex":"They {emigrated} and became immigrants in Canada.","grp":["emigrate","immigrant"],"k":"topic"},{"w":"immigrant","pos":"n","vi":"người nhập cư vào một nước","ex":"They emigrated and became {immigrants} in Canada.","grp":["emigrate","immigrant"],"k":"topic"},{"w":"migrate","pos":"n","vi":"di cư theo mùa/nơi sống","ex":"Some {migrate} for work; refugees flee danger.","grp":["migrate","refugee"],"k":"topic"},{"w":"refugee","pos":"n","vi":"người tị nạn","ex":"Some migrate for work; {refugees} flee danger.","grp":["migrate","refugee"],"k":"topic"},{"w":"flow","pos":"v","vi":"chảy/dòng chảy","ex":"The river {flowed} quietly as a swan glided past.","grp":["flow","glide"],"k":"topic"},{"w":"glide","pos":"v","vi":"lướt nhẹ, êm","ex":"The river flowed quietly as a swan {glided} past.","grp":["flow","glide"],"k":"topic"},{"w":"fumble","pos":"v","vi":"mò mẫm, vụng về thao tác","ex":"He {fumbled} for the handle before grasping it firmly.","grp":["fumble","grasp"],"k":"topic"},{"w":"grasp","pos":"v","vi":"nắm chặt, hiểu rõ","ex":"He fumbled for the handle before {grasping} it firmly.","grp":["fumble","grasp"],"k":"topic"},{"w":"gesture","pos":"v","vi":"ra hiệu/cử chỉ","ex":"She {gestured} to us and pointed towards the exit.","grp":["gesture","point"],"k":"topic"},{"w":"point","pos":"v","vi":"chỉ bằng tay/hướng về","ex":"She gestured to us and {pointed} towards the exit.","grp":["gesture","point"],"k":"topic"},{"w":"grab","pos":"v","vi":"chộp, giật lấy","ex":"He {grabbed} the bag but did not punch anyone.","grp":["grab","punch"],"k":"topic"},{"w":"punch","pos":"v","vi":"đấm","ex":"He grabbed the bag but did not {punch} anyone.","grp":["grab","punch"],"k":"topic"},{"w":"hop","pos":"v/n","vi":"nhảy một chân hoặc bước nhảy nhỏ","ex":"The bird {hopped} along the wall before leaping into the air.","grp":["hop","leap"],"k":"topic"},{"w":"leap","pos":"v/n","vi":"nhảy xa/cao mạnh","ex":"The bird hopped along the wall before {leaping} into the air.","grp":["hop","leap"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/4 (Topic vocabulary)","words":[{"w":"march","pos":"v/n","vi":"bước đều, diễu hành","ex":"The soldiers {marched} while the officer strode ahead.","grp":["march","stride"],"k":"topic"},{"w":"stride","pos":"v/n","vi":"sải bước dài","ex":"The soldiers marched while the officer strode ahead.","grp":["march","stride"],"k":"topic"},{"w":"rotate","pos":"v/n","vi":"xoay quanh trục/luân phiên","ex":"{Rotate} the handle, then step inside.","grp":["rotate","step"],"k":"topic"},{"w":"step","pos":"v/n","vi":"bước, bậc","ex":"Rotate the handle, then {step} inside.","grp":["rotate","step"],"k":"topic"},{"w":"sink","pos":"v","vi":"chìm","ex":"The box slid off the deck and sank.","grp":["sink","slide"],"k":"topic"},{"w":"slide","pos":"v","vi":"trượt theo bề mặt/cầu trượt","ex":"The box {slid} off the deck and sank.","grp":["sink","slide"],"k":"topic"},{"w":"skid","pos":"v","vi":"trượt mất kiểm soát, thường xe","ex":"The car {skidded}; I slipped on the same icy road.","grp":["skid","slip"],"k":"topic"},{"w":"slip","pos":"v","vi":"trượt chân/tuột","ex":"The car skidded; I {slipped} on the same icy road.","grp":["skid","slip"],"k":"topic"},{"w":"skip","pos":"v","vi":"nhảy chân sáo/bỏ qua","ex":"She {skipped} along the path but tripped over a stone.","grp":["skip","trip"],"k":"topic"},{"w":"trip","pos":"v","vi":"vấp","ex":"She skipped along the path but {tripped} over a stone.","grp":["skip","trip"],"k":"topic"},{"w":"wander","pos":"v/n","vi":"đi không mục đích","ex":"We {wandered} along the quay and waved at the boats.","grp":["wander","wave"],"k":"topic"},{"w":"wave","pos":"v/n","vi":"vẫy tay/sóng","ex":"We wandered along the quay and {waved} at the boats.","grp":["wander","wave"],"k":"topic"},{"w":"airline","pos":"v","vi":"hãng hàng không","ex":"The {airline} chartered an extra aircraft.","grp":["airline","charter"],"k":"topic"},{"w":"charter","pos":"v","vi":"thuê nguyên chuyến/tàu","ex":"The airline {chartered} an extra aircraft.","grp":["airline","charter"],"k":"topic"},{"w":"cargo","pos":"v/n","vi":"hàng chuyên chở","ex":"They loaded the {cargo} before dawn.","grp":["cargo","load"],"k":"topic"},{"w":"load","pos":"v/n","vi":"chất hàng/tải trọng","ex":"They {loaded} the cargo before dawn.","grp":["cargo","load"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 4/4 (Topic vocabulary)","words":[{"w":"carriage","pos":"n","vi":"toa tàu/xe ngựa","ex":"The {carriage} was crowded and had little legroom.","grp":["carriage","legroom"],"k":"topic"},{"w":"legroom","pos":"n","vi":"chỗ để chân","ex":"The carriage was crowded and had little {legroom}.","grp":["carriage","legroom"],"k":"topic"},{"w":"commute","pos":"n","vi":"đi làm thường xuyên","ex":"I {commute} daily, although my final destination changes.","grp":["commute","destination"],"k":"topic"},{"w":"destination","pos":"n","vi":"điểm đến","ex":"I commute daily, although my final {destination} changes.","grp":["commute","destination"],"k":"topic"},{"w":"hiker","pos":"n","vi":"người đi bộ đường dài","ex":"The {hiker} met a hitchhiker near the crossroads.","grp":["hiker","hitchhiker"],"k":"topic"},{"w":"hitchhiker","pos":"n","vi":"người xin đi nhờ xe","ex":"The hiker met a {hitchhiker} near the crossroads.","grp":["hiker","hitchhiker"],"k":"topic"},{"w":"passerby","pos":"n","vi":"người tình cờ đi ngang","ex":"A {passerby} helped the injured pedestrian.","grp":["passerby","pedestrian"],"k":"topic"},{"w":"pedestrian","pos":"n","vi":"người đi bộ","ex":"A passerby helped the injured {pedestrian}.","grp":["passerby","pedestrian"],"k":"topic"},{"w":"pier","pos":"n","vi":"cầu tàu vươn ra mặt nước","ex":"We walked along the quay to the {pier}.","grp":["pier","quay"],"k":"topic"},{"w":"quay","pos":"n","vi":"bến chạy dọc mép nước","ex":"We walked along the {quay} to the pier.","grp":["pier","quay"],"k":"topic"},{"w":"return fare","pos":"n phr","vi":"tiền vé khứ hồi","ex":"The {return fare} covers the whole round trip.","grp":["return fare","round trip"],"k":"topic"},{"w":"round trip","pos":"n phr","vi":"chuyến đi và về","ex":"The return fare covers the whole {round trip}.","grp":["return fare","round trip"],"k":"topic"},{"w":"pilot","pos":"v","vi":"lái phương tiện/người lái, thường máy bay","ex":"The {pilot} steered the aircraft away from the storm.","grp":["pilot","steer"],"k":"topic"},{"w":"steer","pos":"v","vi":"điều khiển hướng","ex":"The pilot {steered} the aircraft away from the storm.","grp":["pilot","steer"],"k":"topic"},{"w":"steward","pos":"n","vi":"tiếp viên/người phục vụ trên phương tiện","ex":"The {steward} gave advice on reducing jet lag.","grp":["steward","jet lag"],"k":"topic"},{"w":"jet lag","pos":"n","vi":"mệt do lệch múi giờ","ex":"The steward gave advice on reducing {jet lag}.","grp":["steward","jet lag"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"cordon off","vi":"phong tỏa bằng dây/rào","ex":"Police cordoned {off} the quay.","k":"pv"},{"w":"creep up on","vi":"rón rén tiến lại gần để gây bất ngờ","ex":"The cat crept up {on} the bird.","k":"pv"},{"w":"fall behind","vi":"tụt lại về tốc độ/tiến bộ","ex":"Do not fall {behind} the group.","k":"pv"},{"w":"go astray","vi":"lạc, thất lạc/đi sai hướng","ex":"Two parcels went astray.","k":"pv"},{"w":"head off","vi":"chặn đường; ngăn việc xảy ra","ex":"They headed {off} a possible confrontation.","k":"pv"},{"w":"hold back","vi":"ngăn không cho tiến tới","ex":"The barrier held the crowd {back}.","k":"pv"},{"w":"move in with","vi":"chuyển đến sống ở/với","ex":"She moved in {with} her sister.","k":"pv"},{"w":"move on","vi":"đi tiếp/chuyển sang chủ đề hoặc việc khác","ex":"Let us move {on} to the next issue.","k":"pv"},{"w":"move out","vi":"chuyển khỏi nhà/nơi kinh doanh","ex":"They moved {out} last month.","k":"pv"},{"w":"move over","vi":"dịch sang để nhường chỗ","ex":"Could you move {over} a little?","k":"pv"},{"w":"pull over","vi":"tấp xe vào lề","ex":"The driver pulled {over} safely.","k":"pv"},{"w":"slip away","vi":"lặng lẽ rời đi","ex":"He slipped {away} before anyone noticed.","k":"pv"},{"w":"step aside","vi":"tránh sang bên; nhường vị trí/công việc","ex":"The director stepped {aside} for a successor.","k":"pv"},{"w":"stop off","vi":"ghé một nơi trên hành trình","ex":"We stopped {off} in Hue.","k":"pv"},{"w":"tip up","vi":"nghiêng đầu lên/lật đổ để đồ bên trong ra","ex":"The cart tipped {up} under the heavy load.","k":"pv"},{"w":"walk out","vi":"bỏ ra về vì giận/chán; rời bỏ gia đình, công việc","ex":"Several delegates walked {out} of the meeting.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"back","vi":"lùi vào; có mặt sau giáp; ủng hộ ai làm","ex":"The house {backs} onto a park.","note":"back into; back onto; back sb to V","k":"col"},{"w":"come","vi":"đi đến; lên nắm quyền; hiện ra; gây sốc; dần làm; thành thật","ex":"The decision came as a shock.","note":"come to a conclusion/decision; come to power; come into view; come as a shock; come to V; come true","k":"col"},{"w":"drive","vi":"nhấn cho hiểu; làm phát điên; khiến làm; ám chỉ","ex":"What are you {driving} at?","note":"drive a point home; drive sb crazy/mad; drive sb to V; drive at","k":"col"},{"w":"drop","vi":"làm rơi; thả xuống; cho xuống xe; gợi ý; loại khỏi đội","ex":"She {dropped} a hint about changing the route.","note":"drop sth off/into/onto; drop sb at; drop a hint; drop sb from a team","k":"col"},{"w":"fall","vi":"ốm; thuộc loại; yêu; trở nên rõ/ăn khớp; không đạt; vỡ vụn","ex":"The missing detail made everything {fall} into place.","note":"fall ill; fall into a category; fall in love; fall into place; fall short; fall to pieces","k":"col"},{"w":"fly","vi":"treo cờ/thả diều; trôi nhanh; bật mở; lao vào","ex":"The door {flew} open.","note":"fly a flag/kite; fly by; fly open; fly at","k":"col"},{"w":"follow","vi":"hiểu lập luận; làm theo; theo gương/lời khuyên; như sau","ex":"The other firms soon {followed} suit.","note":"follow an argument; follow suit; follow sb's lead/advice; as follows","k":"col"},{"w":"get","vi":"bắt đầu/tiến triển; trở nên; làm vật bị; có cơ hội; lấy cho; nhờ/khiến","ex":"We need to {get} the engine running.","note":"get going/somewhere; get ill/angry/upset; get sth wet/dirty; get to V; get sb sth; get sth done/doing","k":"col"},{"w":"go","vi":"đi làm; trở nên; thiếu trong nhiều ngày; chịu đói/không có","ex":"They went without food for a day.","note":"go and V; go deaf/grey/crazy/bad; go for days without; go hungry; go without; go to V","k":"col"},{"w":"head","vi":"hướng đến; đánh đầu; đứng đầu ủy ban/danh sách","ex":"She {heads} the safety committee.","note":"head towards/for; head a ball/committee/list","k":"col"},{"w":"jump","vi":"chớp cơ hội; chen hàng; vội kết luận; hành động quá sớm","ex":"Do not {jump} the gun before approval arrives.","note":"jump at the chance to V; jump the queue; jump to conclusions; jump the gun","k":"col"},{"w":"move","vi":"nhanh lên; theo dõi từng cử động; bắt đầu/rời đi; đang di chuyển","ex":"We should get a {move} on.","note":"move it; get a move on; follow sb's every move; make a move; on the move","k":"col"},{"w":"point","vi":"chỉ; vào/lạc ý; chủ ý; phần nào; điều nhạy cảm","ex":"The cost is beside the {point}.","note":"point at/to/towards; get to/miss the point; make a point of V-ing; make your point; at some point; beside the point; up to a point; sore point","k":"col"},{"w":"raise","vi":"giơ; nêu; nuôi; làm tăng/gợi ra; lập quân đội","ex":"I {raised} the issue with the manager.","note":"raise your hand; raise sth with sb; raise a child/family; raise hopes/expectations/a smile/your voice/an army","k":"col"},{"w":"run","vi":"điều hành; hỗn loạn; chạy bằng; xả bồn; xem qua; chịu rủi ro","ex":"You {run} the risk of missing the deadline.","note":"run a business/campaign; run riot; run on petrol/electricity; run sb a bath; run through; run the risk of V-ing; run into problems","k":"col"},{"w":"rush","vi":"vội; hấp tấp; giờ cao điểm; đợt mua sắm đông","ex":"We reached the station during {rush} hour.","note":"rush to conclusions; in a rush to V; do sth in a rush; a mad rush; rush hour; the Christmas rush","k":"col"},{"w":"steady","vi":"giữ vững/bình tâm; ổn định; ánh nhìn vững; nhịp đều","ex":"She {steadied} her nerves before starting.","note":"steady yourself/your nerves; hold sth steady; steady relationship/growth/look/pace","k":"col"},{"w":"track","vi":"theo dõi/mất dấu; sai hướng; đúng tiến độ","ex":"The project is on {track} to finish soon.","note":"keep/lose track of time; on the wrong track; on track to V","k":"col"},{"w":"turn","vi":"quay để; chĩa súng; nhờ ai; trở nên; bước sang tuổi","ex":"She {turned} to a colleague for help.","note":"turn to V; turn a gun on sb; turn to sb; turn cold/nasty; turn forty","k":"col"},{"w":"way","vi":"cản đường; biết/lạc; xử lí cho xong; nhường; trên đường; nhân tiện","ex":"Please make {way} for the emergency team.","note":"get in sb's way; know/lose your way; get sth out of the way; make way for; in/on the way; in this way; a way of V-ing; by the way","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a stone's throw away/from","vi":"rất gần","ex":"The pier is a stone's throw from our hotel.","k":"idiom"},{"w":"as the crow flies","vi":"tính theo đường thẳng","ex":"The villages are ten kilometres apart {as the crow flies}.","k":"idiom"},{"w":"follow your nose","vi":"đi thẳng; làm theo trực giác","ex":"{Follow your nose} until you reach the bridge.","k":"idiom"},{"w":"in the middle of nowhere","vi":"ở nơi rất xa khu dân cư","ex":"The bus broke down {in the middle of nowhere}.","k":"idiom"},{"w":"lose your bearings","vi":"mất phương hướng","ex":"We lost our {bearings} in the fog.","k":"idiom"},{"w":"make a beeline for","vi":"đi thẳng nhanh nhất tới","ex":"She made {a beeline for} the exit.","k":"idiom"},{"w":"off the beaten track","vi":"xa tuyến du lịch/đường quen thuộc","ex":"We explored villages {off the beaten track}.","k":"idiom"},{"w":"stop dead in your tracks","vi":"đột ngột đứng khựng lại","ex":"The noise made me stop dead in my {tracks}.","k":"idiom"},{"w":"take a short cut to","vi":"đi đường tắt đến","ex":"We took {a short cut to} the station.","k":"idiom"},{"w":"take the scenic route","vi":"chọn đường xa hơn nhưng đẹp hơn","ex":"We took {the scenic route} along the coast.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"access","vi":"tiếp cận","note":"access → accessibility, (in)accessible","full":"tiếp cận → tính dễ tiếp cận; tiếp cận được/không.","ex":"The building is {accessible} to wheelchair users.","hint":"access","k":"wf"},{"w":"come","vi":"đến","note":"come → overcome, comeback, newcomer, outcome, income, coming, oncoming, incoming","full":"đến → vượt qua; trở lại; người mới; kết quả; thu nhập; sắp đến; đang tới; đi vào.","ex":"The {newcomer} overcame several difficulties.","hint":"come","k":"wf"},{"w":"go","vi":"đi","note":"go → undergo/underwent/undergone; for(e)go/for(e)went/for(e)gone; ongoing, outgoing","full":"đi → trải qua; từ bỏ (forgo); ongoing: đang diễn ra; outgoing: sắp rời chức/cởi mở/đi ra. Forego còn có nghĩa đi trước.","ex":"The {ongoing} repairs mean we must forgo the trip.","hint":"go","k":"wf"},{"w":"land","vi":"đất/hạ cánh","note":"land → landing, landed, landless","full":"đất/hạ cánh → việc hạ cánh; có đất; không có đất.","ex":"The plane made a safe {landing}.","hint":"land","k":"wf"},{"w":"mobile","vi":"di động","note":"mobile → (im)mobilise, (im)mobility, mobilisation, immobile","full":"di động → huy động/làm bất động; khả năng/không thể di chuyển; sự huy động; bất động.","ex":"The injury reduced his {mobility}.","hint":"mobile","k":"wf"},{"w":"motion","vi":"chuyển động","note":"motion → motionless","full":"chuyển động → bất động.","ex":"The boat lay {motionless}.","hint":"motion","k":"wf"},{"w":"move","vi":"di chuyển","note":"move → mover, movement, (im)movable, moving","full":"di chuyển → người/bên thúc đẩy; chuyển động; dời được/không; đang chuyển/cảm động.","ex":"The exhibition contains a {moving} account of migration.","hint":"move","k":"wf"},{"w":"pass","vi":"đi qua","note":"pass → passage, (im)passable, passing","full":"đi qua → lối/sự đi qua; qua được/không; thoáng qua.","ex":"The road was {impassable} after the flood.","hint":"pass","k":"wf"},{"w":"progress","vi":"tiến bộ","note":"progress → progression, progressive(ly)","full":"tiến bộ → sự tiến triển; dần dần/cấp tiến; trạng từ.","ex":"We saw a {progressive} improvement.","hint":"progress","k":"wf"},{"w":"rapid","vi":"nhanh","note":"rapid → rapidity, rapidly","full":"nhanh → tốc độ nhanh; nhanh chóng.","ex":"The water level rose {rapidly}.","hint":"rapid","k":"wf"},{"w":"speed","vi":"tốc độ","note":"speed → sped, speeding, speedy, speedily","full":"tốc độ → quá khứ sped; chạy quá tốc độ; nhanh; nhanh chóng.","ex":"We wish you a {speedy} recovery.","hint":"speed","k":"wf"},{"w":"stable","vi":"ổn định","note":"stable → (de)stabilise, (in)stability, destabilisation, stabiliser, (de)stabilising, unstable","full":"ổn định → làm ổn/mất ổn định; tính ổn/bất ổn; sự gây bất ổn; bộ ổn định; không ổn.","ex":"The {stabiliser} keeps the camera steady.","hint":"stable","k":"wf"},{"w":"stand","vi":"đứng","note":"stand → withstand, withstood, standing, upstanding, outstanding, notwithstanding","full":"đứng → chịu được; đã chịu; vị thế/đang đứng; ngay thẳng; xuất sắc/còn tồn đọng; mặc dù.","ex":"The bridge can {withstand} strong winds.","hint":"stand","k":"wf"},{"w":"steady","vi":"vững/đều","note":"steady → unsteady, (un)steadily","full":"vững/đều → không vững; đều/không vững.","ex":"She walked {unsteadily} after the journey.","hint":"steady","k":"wf"},{"w":"transit","vi":"quá cảnh/vận chuyển","note":"transit → transition, transitory, transitional, transitionally","full":"quá cảnh/vận chuyển → chuyển tiếp; tạm thời; thuộc giai đoạn chuyển tiếp.","ex":"The country entered a {transitional} period.","hint":"transit","k":"wf"},{"w":"up","vi":"lên","note":"up → upper, uppermost, upright, upward(s), upwardly","full":"lên → phía trên; cao nhất/trong tâm trí nhất; thẳng đứng/ngay thẳng; hướng lên.","ex":"Keep the container {upright}.","hint":"up","k":"wf"}]}]},{"g":3,"u":10,"title":"Communication and the Media","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"allege","pos":"v","vi":"cáo buộc/nói là có khi chưa chứng minh","ex":"They {alleged} misconduct, but he asserted his innocence.","grp":["allege","assert"],"k":"topic"},{"w":"assert","pos":"v","vi":"khẳng định chắc chắn","ex":"They alleged misconduct, but he {asserted} his innocence.","grp":["allege","assert"],"k":"topic"},{"w":"ambiguous","pos":"adj","vi":"có nhiều cách hiểu","ex":"The {ambiguous} wording made an already vague instruction worse.","grp":["ambiguous","vague"],"k":"topic"},{"w":"vague","pos":"adj","vi":"mơ hồ, thiếu chi tiết","ex":"The ambiguous wording made an already {vague} instruction worse.","grp":["ambiguous","vague"],"k":"topic"},{"w":"blunt","pos":"adj","vi":"thẳng thừng, có thể thiếu tế nhị","ex":"His {blunt} reply used several colloquial expressions.","grp":["blunt","colloquial"],"k":"topic"},{"w":"colloquial","pos":"adj","vi":"thuộc lời nói thân mật","ex":"His blunt reply used several {colloquial} expressions.","grp":["blunt","colloquial"],"k":"topic"},{"w":"boast","pos":"v","vi":"khoe khoang","ex":"He {boasted} about his success while flattering the manager.","grp":["boast","flatter"],"k":"topic"},{"w":"flatter","pos":"v","vi":"tâng bốc/khen để làm vui hoặc có lợi","ex":"He boasted about his success while {flattering} the manager.","grp":["boast","flatter"],"k":"topic"},{"w":"clarification","pos":"v","vi":"sự làm rõ","ex":"We sought {clarification} before confirming the agreement.","grp":["clarification","confirm"],"k":"topic"},{"w":"confirm","pos":"v","vi":"xác nhận","ex":"We sought clarification before {confirming} the agreement.","grp":["clarification","confirm"],"k":"topic"},{"w":"comprehend","pos":"n","vi":"hiểu đầy đủ","ex":"I grasped the gist without {comprehending} every detail.","grp":["comprehend","gist"],"k":"topic"},{"w":"gist","pos":"n","vi":"ý chính","ex":"I grasped the {gist} without comprehending every detail.","grp":["comprehend","gist"],"k":"topic"},{"w":"confide","pos":"v","vi":"tâm sự bí mật với người tin cậy","ex":"She {confided} in a friend but disclosed nothing publicly.","grp":["confide","disclose"],"k":"topic"},{"w":"disclose","pos":"v","vi":"tiết lộ thông tin","ex":"She confided in a friend but {disclosed} nothing publicly.","grp":["confide","disclose"],"k":"topic"},{"w":"context","pos":"adj","vi":"bối cảnh/ngữ cảnh","ex":"The detail is only relevant in its original {context}.","grp":["context","relevant"],"k":"topic"},{"w":"relevant","pos":"adj","vi":"liên quan, phù hợp vấn đề","ex":"The detail is only {relevant} in its original context.","grp":["context","relevant"],"k":"topic"},{"w":"contradict","pos":"v","vi":"nói trái/phủ nhận","ex":"He insisted he was right although the records {contradicted} him.","grp":["contradict","insist"],"k":"topic"},{"w":"insist","pos":"v","vi":"khăng khăng, nhất quyết","ex":"He {insisted} he was right although the records contradicted him.","grp":["contradict","insist"],"k":"topic"},{"w":"convey","pos":"v","vi":"truyền đạt ý/cảm xúc","ex":"She uttered no words, but her expression {conveyed} disappointment.","grp":["convey","utter"],"k":"topic"},{"w":"utter","pos":"v","vi":"thốt/nói ra","ex":"She {uttered} no words, but her expression conveyed disappointment.","grp":["convey","utter"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"declare","pos":"v","vi":"tuyên bố chính thức","ex":"The minister {declared} support and denounced the attacks.","grp":["declare","denounce"],"k":"topic"},{"w":"denounce","pos":"v","vi":"công khai lên án","ex":"The minister declared support and {denounced} the attacks.","grp":["declare","denounce"],"k":"topic"},{"w":"exaggerate","pos":"adj","vi":"phóng đại","ex":"He {exaggerated}; the phrase was not a literal description.","grp":["exaggerate","literal"],"k":"topic"},{"w":"literal","pos":"adj","vi":"theo nghĩa đen/chính xác từng chữ","ex":"He exaggerated; the phrase was not a {literal} description.","grp":["exaggerate","literal"],"k":"topic"},{"w":"illegible","pos":"v/n","vi":"khó/không đọc được chữ","ex":"Her scribbled notes were almost {illegible}.","grp":["illegible","scribble"],"k":"topic"},{"w":"scribble","pos":"v/n","vi":"viết nguệch ngoạc/nét viết vội","ex":"Her {scribbled} notes were almost illegible.","grp":["illegible","scribble"],"k":"topic"},{"w":"inkling","pos":"v/n","vi":"chút nhận biết/linh cảm","ex":"A subtle hint gave us an {inkling} of the plan.","grp":["inkling","hint"],"k":"topic"},{"w":"hint","pos":"v/n","vi":"gợi ý, dấu hiệu","ex":"A subtle {hint} gave us an inkling of the plan.","grp":["inkling","hint"],"k":"topic"},{"w":"jargon","pos":"n/adj","vi":"thuật ngữ biệt ngữ chuyên ngành","ex":"Technical {jargon} and slang can both confuse outsiders.","grp":["jargon","slang"],"k":"topic"},{"w":"slang","pos":"n/adj","vi":"tiếng lóng, thường rất thân mật","ex":"Technical jargon and {slang} can both confuse outsiders.","grp":["jargon","slang"],"k":"topic"},{"w":"mumble","pos":"v/n","vi":"nói lí nhí, không rõ","ex":"He {mumbled} an answer while others murmured in agreement.","grp":["mumble","murmur"],"k":"topic"},{"w":"murmur","pos":"v/n","vi":"nói khẽ/tiếng rì rầm","ex":"He mumbled an answer while others {murmured} in agreement.","grp":["mumble","murmur"],"k":"topic"},{"w":"petition","pos":"n","vi":"đơn kiến nghị có chữ kí","ex":"They signed a {petition} and carried placards.","grp":["petition","placard"],"k":"topic"},{"w":"placard","pos":"n","vi":"bảng/biểu ngữ cầm hoặc trưng","ex":"They signed a petition and carried {placards}.","grp":["petition","placard"],"k":"topic"},{"w":"quibble","pos":"n","vi":"bắt bẻ tiểu tiết","ex":"Instead of {quibbling}, offer a practical tip.","grp":["quibble","tip"],"k":"topic"},{"w":"tip","pos":"n","vi":"mẹo/lời khuyên hữu ích","ex":"Instead of quibbling, offer a practical {tip}.","grp":["quibble","tip"],"k":"topic"},{"w":"rant","pos":"v","vi":"nói dài đầy giận dữ","ex":"He {ranted} about the delay but raved about the performance.","grp":["rant","rave"],"k":"topic"},{"w":"rave","pos":"v","vi":"nói say mê khen hoặc nói cuồng loạn tùy ngữ cảnh","ex":"He ranted about the delay but {raved} about the performance.","grp":["rant","rave"],"k":"topic"},{"w":"stumble","pos":"v/n","vi":"vấp lời, nói ngập ngừng","ex":"She {stumbled} over the name and briefly stuttered.","grp":["stumble","stutter"],"k":"topic"},{"w":"stutter","pos":"v/n","vi":"nói lắp","ex":"She stumbled over the name and briefly {stuttered}.","grp":["stumble","stutter"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"anchor","pos":"v/n","vi":"dẫn chương trình/người dẫn chính","ex":"She {anchored} the live broadcast.","grp":["anchor","broadcast"],"k":"topic"},{"w":"broadcast","pos":"v/n","vi":"phát sóng/chương trình phát","ex":"She anchored the live {broadcast}.","grp":["anchor","broadcast"],"k":"topic"},{"w":"caption","pos":"n","vi":"chú thích ảnh","ex":"The photo has a {caption}, and the film has subtitles.","grp":["caption","subtitles"],"k":"topic"},{"w":"subtitles","pos":"n","vi":"phụ đề lời thoại","ex":"The photo has a caption, and the film has {subtitles}.","grp":["caption","subtitles"],"k":"topic"},{"w":"columnist","pos":"n","vi":"người viết chuyên mục","ex":"The foreign correspondent later became a political {columnist}.","grp":["columnist","correspondent"],"k":"topic"},{"w":"correspondent","pos":"n","vi":"phóng viên phụ trách nơi/lĩnh vực","ex":"The foreign {correspondent} later became a political columnist.","grp":["columnist","correspondent"],"k":"topic"},{"w":"coverage","pos":"n","vi":"việc/mức đưa tin","ex":"The weekend supplement provides extensive arts {coverage}.","grp":["coverage","supplement"],"k":"topic"},{"w":"supplement","pos":"n","vi":"phần/ấn phẩm bổ sung","ex":"The weekend {supplement} provides extensive arts coverage.","grp":["coverage","supplement"],"k":"topic"},{"w":"critic","pos":"n","vi":"nhà phê bình/người chỉ trích","ex":"The reviewer quoted a well-known film {critic}.","grp":["critic","reviewer"],"k":"topic"},{"w":"reviewer","pos":"n","vi":"người viết đánh giá tác phẩm/sản phẩm","ex":"The {reviewer} quoted a well-known film critic.","grp":["critic","reviewer"],"k":"topic"},{"w":"footnote","pos":"n","vi":"chú thích cuối trang","ex":"The {footnote} explains the title printed on the spine.","grp":["footnote","spine"],"k":"topic"},{"w":"spine","pos":"n","vi":"gáy sách","ex":"The footnote explains the title printed on the {spine}.","grp":["footnote","spine"],"k":"topic"},{"w":"ghostwriter","pos":"n","vi":"người viết thuê dưới tên người khác","ex":"The novelist also worked as a {ghostwriter}.","grp":["ghostwriter","novelist"],"k":"topic"},{"w":"novelist","pos":"n","vi":"nhà tiểu thuyết","ex":"The {novelist} also worked as a ghostwriter.","grp":["ghostwriter","novelist"],"k":"topic"},{"w":"handbook","pos":"n","vi":"sách hướng dẫn/tra cứu","ex":"The pamphlet summarises advice from the {handbook}.","grp":["handbook","pamphlet"],"k":"topic"},{"w":"pamphlet","pos":"n","vi":"tập sách mỏng cung cấp thông tin hoặc lập luận","ex":"The {pamphlet} summarises advice from the handbook.","grp":["handbook","pamphlet"],"k":"topic"},{"w":"manifesto","pos":"n","vi":"cương lĩnh/tuyên ngôn","ex":"The tabloid summarised the party's {manifesto}.","grp":["manifesto","tabloid"],"k":"topic"},{"w":"tabloid","pos":"n","vi":"báo khổ nhỏ, thường thiên tin giật gân","ex":"The {tabloid} summarised the party's manifesto.","grp":["manifesto","tabloid"],"k":"topic"},{"w":"prerecorded","pos":"n","vi":"thu sẵn","ex":"A {prerecorded} introduction was followed by the trailer.","grp":["prerecorded","trailer"],"k":"topic"},{"w":"trailer","pos":"n","vi":"đoạn quảng bá phim/chương trình","ex":"A prerecorded introduction was followed by the {trailer}.","grp":["prerecorded","trailer"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"blurt out","vi":"buột miệng nói khi chưa nghĩ kĩ","ex":"He blurted {out} the answer.","k":"pv"},{"w":"catch on","vi":"hiểu ra; trở nên phổ biến","ex":"The phrase caught {on} quickly.","k":"pv"},{"w":"come out","vi":"ra mắt; lộ rõ/được biết; được diễn đạt thành thế nào","ex":"Her words came {out} differently from what she intended.","k":"pv"},{"w":"come out with","vi":"bất ngờ nói điều gây sốc/ngạc nhiên","ex":"She came out {with} an extraordinary claim.","k":"pv"},{"w":"dry up","vi":"quên lời, không nói tiếp được","ex":"The speaker suddenly dried {up}.","k":"pv"},{"w":"get across","vi":"truyền đạt cho người khác hiểu","ex":"The diagram gets the idea {across}.","k":"pv"},{"w":"get (a)round","vi":"tin tức lan truyền","ex":"News of the decision got around.","k":"pv"},{"w":"get through to","vi":"nối điện thoại được; làm ai hiểu","ex":"I finally got through {to} the editor.","k":"pv"},{"w":"let on","vi":"tiết lộ điều nên giữ kín","ex":"Do not let {on} that you know.","k":"pv"},{"w":"pass on","vi":"chuyển tiếp tin/đồ nhận từ người khác","ex":"Please pass the message {on}.","k":"pv"},{"w":"put across/over","vi":"trình bày cho dễ hiểu","ex":"She put her argument across clearly.","k":"pv"},{"w":"set down","vi":"ghi lại; quy định chính thức","ex":"The rules are set {down} in writing.","k":"pv"},{"w":"shout down","vi":"la át không cho ai nói","ex":"The crowd tried to shout the speaker {down}.","k":"pv"},{"w":"speak out","vi":"công khai lên tiếng mạnh mẽ","ex":"Staff spoke {out} against the policy.","k":"pv"},{"w":"talk over","vi":"bàn bạc","ex":"Talk the plan {over} with your colleagues.","k":"pv"},{"w":"talk round","vi":"thuyết phục đổi ý; nói vòng quanh né trọng tâm","ex":"She talked him {round}, but he kept talking round the main issue.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"answer","vi":"chịu trách nhiệm; đáp; giải trình; đáp ứng; khớp mô tả","ex":"The director has a lot to {answer} for.","note":"answer to sb; give an answer; answer charges/criticisms/a need/sb's prayers/the description; have a lot to answer for; in answer to","k":"col"},{"w":"argument","vi":"tranh cãi; lí lẽ ủng hộ/phản đối","ex":"She presented a strong {argument} against the change.","note":"have/get into an argument with; win/lose; argument about/over; argument for/against; without argument","k":"col"},{"w":"ask","vi":"tự hỏi; nhờ; đòi hỏi; mời; có sẵn nếu xin; tự chuốc rắc rối; theo tôi","ex":"The information is available for the {asking}.","note":"ask yourself; ask sb a favour; ask a lot/too much of; ask sb over/round/in; for the asking; ask for trouble; if you ask me","k":"col"},{"w":"book","vi":"hiểu rõ; đúng quy trình; khó/dễ hiểu; theo tôi; được quý/bị ghét","ex":"We handled the complaint by the {book}.","note":"read sb like a book; by the book; a book about/on; a closed/open book; in my book; in sb's good/bad books","k":"col"},{"w":"discussion","vi":"thảo luận; đang bàn; tranh luận gay gắt","ex":"The proposal is under {discussion}.","note":"have a discussion about/on/with; discussion of; in discussion with; under discussion; heated discussion; discussion group","k":"col"},{"w":"letter","vi":"thư; tuân từng chữ; mặt chữ luật; bom thư/hộp thư","ex":"Follow the instructions to the {letter}.","note":"get/receive a letter from; send/write sb a letter; a letter of; follow/obey to the letter; the letter of the law; letter bomb/box","k":"col"},{"w":"notice","vi":"làm chú ý; nhận thấy/bỏ sót; chú ý; báo gấp; đến thông báo mới","ex":"The office is closed until further {notice}.","note":"bring to sb's notice; come to/escape sb's notice; take notice of; at short/a moment's/a few hours' notice; until further notice","k":"col"},{"w":"paper","vi":"mảnh/tờ giấy; trình bày bài nghiên cứu; trên lí thuyết; che giấu vấn đề; chẳng có giá trị; tuyến giao báo; bằng cấp trên giấy; giấy tờ hành chính","ex":"The plan looks good on {paper} but hides practical problems.","note":"a piece/sheet of paper; present/write a paper on; on paper; paper over the cracks; not worth the paper it is written on; paper round; paper qualifications; paperwork","k":"col"},{"w":"pen","vi":"bắt đầu viết; ngòi bút mạnh hơn vũ lực; người làm giấy tờ; bạn qua thư","ex":"She finally put {pen} to paper.","note":"put pen to paper; the pen is mightier than the sword; pen- pusher; pen friend/pal","k":"col"},{"w":"print","vi":"in trên/bằng; còn/không còn được xuất bản","ex":"The handbook is now out of {print}.","note":"print on/in; in/out of print","k":"col"},{"w":"read","vi":"đoán ý; hiểu rõ; đọc hàm ý; đọc khẩu hình; coi là đã chấp nhận; sách đáng đọc","ex":"{Read} between the lines of the statement.","note":"read sb's mind; read sb like a book; read between the lines; read sb's lips; take sth as read; a good/depressing read","k":"col"},{"w":"record","vi":"lưu hồ sơ; đính chính; được ghi; công khai/không để trích dẫn","ex":"The source spoke off the {record}.","note":"keep/maintain/compile a record of; set/put the record straight; on record; on/off the record","k":"col"},{"w":"say","vi":"nêu ý; quyết cuối; hiển nhiên; ra lời; hết sức công bằng; nói phần mình","ex":"Everyone should have their {say}.","note":"have your say; have the final say; go without saying that; say the word; can't say fairer than that; say your piece; a strange thing to say","k":"col"},{"w":"speak","vi":"đánh giá ai; nói cho mình; nói thẳng; nói không đúng lượt; không đáng kể; có thể nói","ex":"She spoke highly of the new editor.","note":"speak well/highly/badly/ill of; speak for yourself; speak your mind; speak out of turn; not much to speak of; so to speak","k":"col"},{"w":"speaking","vi":"nói chung; còn nói chuyện với nhau; nhắc đến; nói với tư cách","ex":"Generally {speaking}, the coverage was balanced.","note":"broadly/generally speaking; on speaking terms; speaking of; speaking as","k":"col"},{"w":"talk","vi":"thuyết phục làm/đừng làm; dùng lời để thoát/đạt; nói cho hiểu lẽ phải; cùng cách nghĩ; trò chuyện; chỉ nói không làm; chủ đề bàn tán; nói thì dễ","ex":"They {talked} me out of publishing the rumour.","note":"talk sb into/out of V-ing; talk your way into/out of; talk sense into; talk the same language as; have a talk with; be all talk; the talk of; talk is cheap","k":"col"},{"w":"tell","vi":"nói thật/dối; tự nhủ; phân biệt; xem giờ; nói thẳng; không thể biết; quá đúng; không tiết lộ đâu","ex":"There is no {telling} how readers will react.","note":"tell the truth/a lie; tell yourself that; tell the difference; tell the time; tell it like it is; there is no telling; you're telling me; that would be telling","k":"col"},{"w":"understandin g","vi":"đạt thỏa thuận; có hiểu biết; với điều kiện đã hiểu","ex":"We agreed on the understanding that names would remain private.","note":"come to/reach an understanding; have an understanding with; an understanding of; on the understanding that","k":"col"},{"w":"word","vi":"nói đỡ; nói chuyện riêng; truyền tin; gán lời người khác không nói; ra lệnh/báo hiệu; ngay từ đầu; truyền miệng; nói cách khác","ex":"The story spread by {word} of mouth.","note":"put in a good word for; have a word with about; spread the word; put words in sb's mouth; give/say the word; from the word go; word of mouth; in other words","k":"col"},{"w":"write","vi":"viết cho; lộ rõ trên mặt; không có gì đặc sắc; bí ý khi viết","ex":"Her disappointment was {written} all over her face.","note":"write for; have sth/be written all over your face; nothing to write home about; writer's block","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"big mouth","vi":"người hay buột miệng/không giữ kín chuyện","ex":"His {big mouth} nearly ruined the surprise.","k":"idiom"},{"w":"come clean about","vi":"thú nhận sự thật đã giấu","ex":"She came {clean about} the mistake.","k":"idiom"},{"w":"get/catch sb's drift","vi":"hiểu ý chính/hàm ý của ai","ex":"I get your {drift}, but I disagree.","k":"idiom"},{"w":"get sth off your chest","vi":"nói điều làm mình bận lòng để nhẹ nhõm","ex":"He needed to get his worries off his {chest}.","k":"idiom"},{"w":"get the wrong end of the stick","vi":"hiểu sai hoàn toàn","ex":"You have got {the wrong end of the stick}.","k":"idiom"},{"w":"give sb your word","vi":"hứa chắc với ai","ex":"I gave her my {word} that I would help.","k":"idiom"},{"w":"hear on/through the grapevine","vi":"nghe tin truyền miệng không chính thức","ex":"I heard it through the {grapevine}.","k":"idiom"},{"w":"keep sb posted","vi":"liên tục cập nhật tình hình cho ai","ex":"Keep me {posted} on the negotiations.","k":"idiom"},{"w":"keep sth under your hat","vi":"giữ bí mật (thân mật)","ex":"Keep the announcement under {your} hat for now.","k":"idiom"},{"w":"lay/put your cards on the table","vi":"nói rõ suy nghĩ/ý định để mọi người biết","ex":"It is time to put our cards on the {table}.","k":"idiom"},{"w":"speak volumes","vi":"cho thấy rất nhiều, thường không cần nói trực tiếp","ex":"Her silence spoke {volumes}.","k":"idiom"},{"w":"tell tales","vi":"mách người có thẩm quyền để ai bị phạt","ex":"The children accused him of telling {tales}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"declare","vi":"tuyên bố","note":"declare → declaration, (un)declared","full":"tuyên bố → lời tuyên bố; được/chưa công bố.","ex":"The {declaration} surprised the press.","hint":"declare","k":"wf"},{"w":"edit","vi":"biên tập","note":"edit → edition, editor, editorship, (un)edited, editorial(ly)","full":"biên tập → ấn bản; biên tập viên; chức vụ biên tập; đã/chưa biên tập; thuộc biên tập/bài xã luận.","ex":"The latest edition includes an {editorial}.","hint":"edit","k":"wf"},{"w":"exclaim","vi":"thốt lên","note":"exclaim → exclamation, exclamatory","full":"thốt lên → lời/dấu cảm thán; mang tính cảm thán.","ex":"An {exclamation} interrupted the discussion.","hint":"exclaim","k":"wf"},{"w":"express","vi":"bày tỏ","note":"express → expression, expressiveness, expressionism, expressionist, expressive(ly), expressionless(ly), expressly","full":"bày tỏ → biểu cảm; tính biểu cảm; trường phái/người theo biểu hiện; giàu/không biểu cảm; minh thị/đích thân vì mục đích.","ex":"The warning {expressly} prohibits copying.","hint":"express","k":"wf"},{"w":"hear","vi":"nghe","note":"hear → overhear, hearing, hearsay","full":"nghe → nghe lỏm; thính lực/phiên điều trần; tin nghe kể.","ex":"The report was based on {hearsay}.","hint":"hear","k":"wf"},{"w":"imply","vi":"hàm ý","note":"imply → implicate, implication, implicit(ly)","full":"hàm ý → dính líu; hàm ý/hệ quả; ngầm.","ex":"The criticism was {implicit} rather than direct.","hint":"imply","k":"wf"},{"w":"insist","vi":"khăng khăng","note":"insist → insistence, insistent","full":"khăng khăng → sự khăng khăng; một mực đòi.","ex":"At her {insistence}, we checked again.","hint":"insist","k":"wf"},{"w":"mean","vi":"có nghĩa","note":"mean → meaning, meaninglessness, meaningless, meaningful(ly)","full":"có nghĩa → nghĩa; sự vô nghĩa; vô/có ý nghĩa.","ex":"We need a {meaningful} discussion.","hint":"mean","k":"wf"},{"w":"phrase","vi":"diễn đạt","note":"phrase → rephrase, paraphrase, phrasing, phraseology","full":"diễn đạt → nói lại; diễn giải bằng cách khác; cách dùng câu/từ.","ex":"Please {paraphrase} the argument.","hint":"phrase","k":"wf"},{"w":"print","vi":"in","note":"print → reprint, printing, printer, printout, imprint, printed, (un)printable","full":"in → in lại; việc in; máy in; bản in; dấu ấn; đã in; có/không thích hợp để in.","ex":"Keep a {printout} of the confirmation.","hint":"print","k":"wf"},{"w":"public","vi":"công chúng/công khai","note":"public → publicise, publicity, publication, publicist, publicly","full":"công chúng/công khai → quảng bá; sự quảng bá; xuất bản/ấn phẩm; người quảng bá; công khai.","ex":"The publisher publicised the new {publication}.","hint":"public","k":"wf"},{"w":"say","vi":"nói","note":"say → gainsay, saying, unsaid","full":"nói → phủ nhận (trang trọng); câu nói; chưa nói.","ex":"Some concerns remained {unsaid}.","hint":"say","k":"wf"},{"w":"speak","vi":"nói","note":"speak → spoke, speech, speaker, spokesman/men/woman/women/person/p eople, outspokenness, (un)spoken, speechless, unspeakable, unspeakably, outspoken(ly)","full":"nói → quá khứ spoke; bài nói; người nói/đại diện; sự thẳng thắn; được/không nói; câm lặng vì xúc động; kinh khủng; thẳng tính.","ex":"The spokesperson was unusually {outspoken}.","hint":"speak","k":"wf"},{"w":"state","vi":"nêu","note":"state → restate, overstate, understate, statement, understatement, overstatement, understated, overstated","full":"nêu → nhắc lại; nói quá/nói giảm; tuyên bố; sự nói giảm/quá; kín đáo/bị nói quá.","ex":"It would be an {overstatement} to call it a disaster.","hint":"state","k":"wf"},{"w":"suggest","vi":"gợi ý","note":"suggest → suggestion, suggestibility, suggested, suggestive(ly), suggestible","full":"gợi ý → lời gợi ý; tính dễ bị ám thị; được gợi; gợi liên tưởng; dễ bị tác động.","ex":"Children can be highly {suggestible}.","hint":"suggest","k":"wf"},{"w":"talk","vi":"nói","note":"talk → talker, talkie, talkback, talkative","full":"nói → người nói; phim có tiếng; chương trình/thiết bị đối thoại; hay nói.","ex":"The normally {talkative} child was quiet.","hint":"talk","k":"wf"},{"w":"type","vi":"loại/đánh máy","note":"type → typeset, typecast, typify, typist, typewriter, typeface, typesetting, typesetter, typescript, typewritten, typical(ly)","full":"loại/đánh máy → sắp chữ; đóng khung kiểu vai; là điển hình; người/máy đánh máy; kiểu chữ; bản thảo đánh máy; điển hình.","ex":"Choose a readable {typeface}.","hint":"type","k":"wf"},{"w":"word","vi":"từ","note":"word → reword, (re)wording, wordplay, wordy, (re)worded, wordless(ly)","full":"từ → diễn đạt lại; cách diễn đạt; chơi chữ; dài dòng; không lời.","ex":"The original statement was rather {wordy}.","hint":"word","k":"wf"},{"w":"write","vi":"viết","note":"write → rewrite, (re)wrote, (re)written, writing(s), writer, unwritten","full":"viết → viết lại; các dạng quá khứ/phân từ; bài viết; người viết; bất thành văn.","ex":"The writer {rewrote} the opening paragraph.","hint":"write","k":"wf"}]}]},{"g":3,"u":12,"title":"Chance and Nature","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"approximate","pos":"n","vi":"xấp xỉ/ước tính","ex":"The statistics give an {approximate} picture of the risk.","grp":["approximate","statistics"],"k":"topic"},{"w":"statistics","pos":"n","vi":"số liệu thống kê hoặc môn thống kê","ex":"The {statistics} give an approximate picture of the risk.","grp":["approximate","statistics"],"k":"topic"},{"w":"ascribe / attribute","pos":"v","vi":"ascribe/attribute A to B: quy A cho B như nguyên nhân/tác giả","ex":"They attributed the error to haste and ascribed no blame to her.","k":"topic"},{"w":"assign","pos":"v","vi":"phân công, ấn định","ex":"The committee {assigned} roles and determined the order.","grp":["assign","determine"],"k":"topic"},{"w":"determine","pos":"v","vi":"quyết định/xác định","ex":"The committee assigned roles and {determined} the order.","grp":["assign","determine"],"k":"topic"},{"w":"blow","pos":"n","vi":"cú đánh/cú sốc bất lợi","ex":"The mishap was a {blow} to their confidence.","grp":["blow","mishap"],"k":"topic"},{"w":"mishap","pos":"n","vi":"sự cố không may, thường nhỏ","ex":"The {mishap} was a blow to their confidence.","grp":["blow","mishap"],"k":"topic"},{"w":"cause","pos":"adj","vi":"gây ra/nguyên nhân","ex":"Her evidence was instrumental in identifying the {cause}.","grp":["cause","instrumental"],"k":"topic"},{"w":"instrumental","pos":"adj","vi":"đóng vai trò quan trọng trong việc tạo kết quả","ex":"Her evidence was {instrumental} in identifying the cause.","grp":["cause","instrumental"],"k":"topic"},{"w":"coincidence","pos":"n","vi":"sự trùng hợp","ex":"Was their meeting a {coincidence} or fate?","grp":["coincidence","fate"],"k":"topic"},{"w":"fate","pos":"n","vi":"số phận/kết cục","ex":"Was their meeting a coincidence or {fate}?","grp":["coincidence","fate"],"k":"topic"},{"w":"curse","pos":"adj","vi":"nguyền rủa/lời nguyền","ex":"They joked that the jinxed project was under a {curse}.","grp":["curse","jinxed"],"k":"topic"},{"w":"jinxed","pos":"adj","vi":"bị cho là xui xẻo","ex":"They joked that the {jinxed} project was under a curse.","grp":["curse","jinxed"],"k":"topic"},{"w":"deliberate","pos":"adj","vi":"cố ý","ex":"The omission was inadvertent rather than {deliberate}.","grp":["deliberate","inadvertent"],"k":"topic"},{"w":"inadvertent","pos":"adj","vi":"vô tình, do sơ suất","ex":"The omission was {inadvertent} rather than deliberate.","grp":["deliberate","inadvertent"],"k":"topic"},{"w":"fluctuate","pos":"v","vi":"dao động lên xuống","ex":"Prices {fluctuate}, while an unstable ladder may wobble.","grp":["fluctuate","wobble"],"k":"topic"},{"w":"wobble","pos":"v","vi":"lắc lư/chao đảo","ex":"Prices fluctuate, while an unstable ladder may {wobble}.","grp":["fluctuate","wobble"],"k":"topic"},{"w":"foresee","pos":"v","vi":"thấy trước","ex":"Nobody foresaw what would transpire.","grp":["foresee","transpire"],"k":"topic"},{"w":"transpire","pos":"v","vi":"xảy ra hoặc hóa ra/được biết","ex":"Nobody foresaw what would {transpire}.","grp":["foresee","transpire"],"k":"topic"},{"w":"freak","pos":"adj","vi":"người/vật rất khác thường, bất thường","ex":"A {freak} storm interrupted the random sampling.","grp":["freak","random"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"random","pos":"adj","vi":"ngẫu nhiên, không theo mẫu","ex":"A freak storm interrupted the {random} sampling.","grp":["freak","random"],"k":"topic"},{"w":"gamble","pos":"n","vi":"đánh cược/liều","ex":"Do not {gamble} without understanding the odds.","grp":["gamble","odds"],"k":"topic"},{"w":"odds","pos":"n","vi":"khả năng/tỉ lệ cược","ex":"Do not gamble without understanding the {odds}.","grp":["gamble","odds"],"k":"topic"},{"w":"haphazard","pos":"adj","vi":"thiếu trật tự/kế hoạch","ex":"A spontaneous decision need not lead to {haphazard} work.","grp":["haphazard","spontaneous"],"k":"topic"},{"w":"spontaneous","pos":"adj","vi":"tự phát, không gượng ép","ex":"A {spontaneous} decision need not lead to haphazard work.","grp":["haphazard","spontaneous"],"k":"topic"},{"w":"hazard","pos":"n","vi":"nguồn/mối nguy","ex":"The hidden {hazard} increased uncertainty.","grp":["hazard","uncertainty"],"k":"topic"},{"w":"uncertainty","pos":"n","vi":"sự không chắc chắn","ex":"The hidden hazard increased {uncertainty}.","grp":["hazard","uncertainty"],"k":"topic"},{"w":"likelihood","pos":"v","vi":"khả năng xảy ra","ex":"We can only speculate about the {likelihood} of success.","grp":["likelihood","speculate"],"k":"topic"},{"w":"speculate","pos":"v","vi":"phỏng đoán/đầu cơ","ex":"We can only {speculate} about the likelihood of success.","grp":["likelihood","speculate"],"k":"topic"},{"w":"lucky charm","pos":"n","vi":"bùa/vật may mắn","ex":"His {lucky charm} reflects an old superstition.","grp":["lucky charm","superstition"],"k":"topic"},{"w":"superstition","pos":"n","vi":"mê tín hoặc niềm tin mê tín","ex":"His lucky charm reflects an old {superstition}.","grp":["lucky charm","superstition"],"k":"topic"},{"w":"superstitious","pos":"n","vi":"mê tín","ex":"A {superstitious} person may interpret a coincidence as a sign.","grp":["superstitious","sign"],"k":"topic"},{"w":"sign","pos":"n","vi":"dấu hiệu/điềm","ex":"A superstitious person may interpret a coincidence as a {sign}.","grp":["superstitious","sign"],"k":"topic"},{"w":"meander","pos":"v","vi":"uốn khúc/đi vòng vèo","ex":"The path {meandered}, and we strayed from it.","grp":["meander","stray"],"k":"topic"},{"w":"stray","pos":"v","vi":"lạc khỏi đường, đi lạc/con vật lạc","ex":"The path meandered, and we {strayed} from it.","grp":["meander","stray"],"k":"topic"},{"w":"mutate","pos":"v","vi":"đột biến/thay đổi dạng","ex":"The discovery that the virus had {mutated} startled researchers.","grp":["mutate","startle"],"k":"topic"},{"w":"startle","pos":"v","vi":"làm giật mình","ex":"The discovery that the virus had mutated {startled} researchers.","grp":["mutate","startle"],"k":"topic"},{"w":"pick","pos":"n phr","vi":"chọn/lựa chọn","ex":"You can {pick} a room or take pot luck.","grp":["pick","pot luck"],"k":"topic"},{"w":"pot luck","pos":"n phr","vi":"kết quả tùy may rủi, không chọn trước","ex":"You can pick a room or take {pot luck}.","grp":["pick","pot luck"],"k":"topic"},{"w":"agriculture","pos":"n","vi":"nông nghiệp","ex":"{Agriculture} depends on healthy crops.","grp":["agriculture","crop"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"crop","pos":"n","vi":"cây trồng/mùa màng","ex":"Agriculture depends on healthy {crops}.","grp":["agriculture","crop"],"k":"topic"},{"w":"appreciate","pos":"v","vi":"trân trọng/nhận thức rõ","ex":"We should {appreciate} nature rather than exploit it carelessly.","grp":["appreciate","exploit"],"k":"topic"},{"w":"exploit","pos":"v","vi":"khai thác/lợi dụng","ex":"We should appreciate nature rather than {exploit} it carelessly.","grp":["appreciate","exploit"],"k":"topic"},{"w":"catastrophe","pos":"n","vi":"tai họa lớn","ex":"The natural disaster became a humanitarian {catastrophe}.","grp":["catastrophe","natural disaster"],"k":"topic"},{"w":"natural disaster","pos":"n","vi":"thiên tai","ex":"The {natural disaster} became a humanitarian catastrophe.","grp":["catastrophe","natural disaster"],"k":"topic"},{"w":"drought","pos":"n","vi":"hạn hán","ex":"The prolonged {drought} contributed to famine.","grp":["drought","famine"],"k":"topic"},{"w":"famine","pos":"n","vi":"nạn đói nghiêm trọng","ex":"The prolonged drought contributed to {famine}.","grp":["drought","famine"],"k":"topic"},{"w":"evacuate","pos":"v/n","vi":"sơ tán","ex":"Residents {evacuated} before the flood arrived.","grp":["evacuate","flood"],"k":"topic"},{"w":"flood","pos":"v/n","vi":"làm/ngập lụt, trận lụt","ex":"Residents evacuated before the {flood} arrived.","grp":["evacuate","flood"],"k":"topic"},{"w":"fossil fuels","pos":"n phr","vi":"nhiên liệu hóa thạch","ex":"Burning {fossil fuels} contributes to global warming.","grp":["fossil fuels","global warming"],"k":"topic"},{"w":"global warming","pos":"n phr","vi":"sự nóng lên toàn cầu","ex":"Burning fossil fuels contributes to {global warming}.","grp":["fossil fuels","global warming"],"k":"topic"},{"w":"greenery","pos":"n","vi":"cây lá xanh","ex":"Urban {greenery} provides a habitat for birds.","grp":["greenery","habitat"],"k":"topic"},{"w":"habitat","pos":"n","vi":"môi trường sống tự nhiên","ex":"Urban greenery provides a {habitat} for birds.","grp":["greenery","habitat"],"k":"topic"},{"w":"harvest","pos":"adj","vi":"thu hoạch/vụ thu hoạch","ex":"Food became scarce after a poor {harvest}.","grp":["harvest","scarce"],"k":"topic"},{"w":"scarce","pos":"adj","vi":"khan hiếm","ex":"Food became {scarce} after a poor harvest.","grp":["harvest","scarce"],"k":"topic"},{"w":"hurricane","pos":"n","vi":"bão nhiệt đới mạnh","ex":"The animals' instinct led them to shelter before the {hurricane}.","grp":["hurricane","instinct"],"k":"topic"},{"w":"instinct","pos":"n","vi":"bản năng","ex":"The animals' {instinct} led them to shelter before the hurricane.","grp":["hurricane","instinct"],"k":"topic"},{"w":"resource","pos":"n","vi":"tài nguyên/nguồn lực","ex":"Protecting {resources} helps vulnerable species survive.","grp":["resource","species"],"k":"topic"},{"w":"species","pos":"n","vi":"loài, dạng số ít và nhiều giống nhau","ex":"Protecting resources helps vulnerable {species} survive.","grp":["resource","species"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"chance upon","vi":"tình cờ bắt gặp/tìm thấy","ex":"We chanced {upon} an old map.","k":"pv"},{"w":"come across","vi":"tình cờ gặp/thấy","ex":"She came {across} a rare plant.","k":"pv"},{"w":"cool down","vi":"nguội/làm mát; bình tĩnh lại theo ngữ cảnh","ex":"Let the sample cool {down}.","k":"pv"},{"w":"cut back on","vi":"cắt giảm lượng dùng/chi","ex":"They cut back {on} water consumption.","k":"pv"},{"w":"die out","vi":"yếu dần rồi biến mất/tuyệt chủng","ex":"The species may die {out}.","k":"pv"},{"w":"dig up","vi":"đào lên; tìm ra thông tin cũ","ex":"Reporters dug {up} new evidence.","k":"pv"},{"w":"dry up","vi":"cạn nước; nguồn cung không còn","ex":"The stream dried {up} in July.","k":"pv"},{"w":"get through","vi":"dùng hết; vượt qua; xử lí xong","ex":"We got {through} the supplies in a week.","k":"pv"},{"w":"heat up","vi":"nóng/làm nóng lên","ex":"Heat {up} the water gradually.","k":"pv"},{"w":"kill off","vi":"làm chết phần lớn/toàn bộ một nhóm sinh vật","ex":"Pollution killed {off} the fish.","k":"pv"},{"w":"put down to","vi":"cho rằng nguyên nhân là","ex":"They put the failure down {to} bad luck.","k":"pv"},{"w":"slip up","vi":"sơ suất, mắc lỗi; slip-up (n)","ex":"Someone slipped {up} when checking the figures.","k":"pv"},{"w":"spring up","vi":"xuất hiện/phát triển nhanh bất ngờ","ex":"New shoots sprang {up} after the rain.","k":"pv"},{"w":"store up","vi":"tích trữ; gây vấn đề cho tương lai","ex":"Ignoring the leak stores {up} trouble.","k":"pv"},{"w":"throw out","vi":"vứt; đuổi; bác bỏ kế hoạch","ex":"The committee threw {out} the proposal.","k":"pv"},{"w":"throw up","vi":"tạo ra điều mới/bất ngờ; làm bụi/nước tung lên","ex":"The research threw {up} several questions.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"bet","vi":"cược; đặt cược; lựa chọn/dự đoán khá chắc","ex":"It is a safe {bet} that demand will rise.","note":"bet sth on; make a bet with; a safe bet","k":"col"},{"w":"certain","vi":"biết chắc; chắc sẽ; bảo đảm; một lượng nào đó","ex":"We cannot say for {certain} what caused it.","note":"know/say for certain; certain to V; make certain; certain of/about; a certain amount","k":"col"},{"w":"chance","vi":"liều thử; phó may rủi; tình cờ; có tình cờ không; khả năng/cơ hội; cơ hội thứ hai/cuối; hoàn toàn ngẫu nhiên; rất có/không có khả năng","ex":"Do not leave the safety checks to {chance}.","note":"take a chance on; leave to chance; by chance; by any chance; chances of V-ing; chance to V; second/last chance; pure/sheer chance; every/no chance that","k":"col"},{"w":"dint","vi":"nhờ vào nỗ lực/phẩm chất nào đó","ex":"She succeeded by {dint} of hard work.","note":"by dint of","k":"col"},{"w":"disposal","vi":"xử lí chất thải; sẵn cho ai sử dụng","ex":"All the equipment is at your {disposal}.","note":"waste disposal; at sb's disposal / at the disposal of","k":"col"},{"w":"find","vi":"nhận ra mình đang; bắt gặp; thấy điều gì; tìm đường","ex":"I found myself reconsidering the explanation.","note":"find yourself V-ing; find sb V-ing; find sth difficult/interesting; find your way","k":"col"},{"w":"green","vi":"chính trị môi trường; vành đai xanh; cho phép; nhà kính/hiệu ứng nhà kính","ex":"The council gave the project the {green} light.","note":"green politics; green belt; give sb the green light; greenhouse; greenhouse effect","k":"col"},{"w":"guess","vi":"đoán; ước chừng/may mắn/vô căn cứ/có cơ sở","ex":"It is an educated {guess} rather than a certainty.","note":"guess at/that/right; take/make/hazard a guess at; rough/lucky/wild/educated guess; at a guess","k":"col"},{"w":"happen","vi":"tình cờ; trùng hợp là; thực ra tình cờ","ex":"I {happen} to know the researcher.","note":"happen to V; it so happens that; as it happens","k":"col"},{"w":"lightning","vi":"sấm chớp; tia sét; bị sét đánh; cực nhanh","ex":"The tree was struck by {lightning}.","note":"thunder and lightning; a bolt/flash of lightning; struck by lightning; at lightning speed","k":"col"},{"w":"luck","vi":"liều quá; chúc may; phó may; phần may rủi","ex":"As {luck} would have it, help arrived.","note":"push your luck; wish sb luck; trust to/bring luck; luck of the draw; stroke/piece of luck; as luck would have it; in luck; with any luck","k":"col"},{"w":"natural","vi":"tự nhiên; nguyên nhân tự nhiên; năng khiếu; tài nguyên; chọn lọc tự nhiên","ex":"{Natural} selection favours certain inherited traits.","note":"completely/totally natural; natural causes/ability/resources/selection","k":"col"},{"w":"nature","vi":"bản chất; vốn là; trong tự nhiên; tạo hóa; bản tính người; thành thạo như bản năng","ex":"Checking sources should become second {nature}.","note":"the nature of; by/in nature; Mother Nature; human nature; second nature","k":"col"},{"w":"odds","vi":"khả năng; có khả năng rằng; thuận/bất lợi; bất chấp rất ít hi vọng","ex":"They survived against all the {odds}.","note":"the odds of V-ing; the odds are that; odds in favour of/against; against all the odds","k":"col"},{"w":"rain","vi":"mưa lớn/nhẹ; cầu vồng; nước mưa; gặp mưa","ex":"We were caught in heavy {rain}.","note":"rain hard/heavily; pour with rain; heavy/light rain; rainbow; rainwater; caught in the rain","k":"col"},{"w":"risk","vi":"liều; gây/chịu rủi ro","ex":"The chemicals pose a {risk} to wildlife.","note":"risk sth on; risk V-ing/your life; take a risk; run the risk of; put at risk; pose a risk to; risk of; at the risk of V-ing","k":"col"},{"w":"sun","vi":"phơi nắng; ánh nắng; bình minh; hoàng hôn","ex":"Avoid leaving the samples in the {sun}.","note":"sun yourself; in the sun; sunbathe; sunlight; sunrise; sunset; sunshine","k":"col"},{"w":"threat","vi":"đe dọa; bị đe dọa; lời dọa suông/đánh bom/giết","ex":"The habitat is under {threat}.","note":"pose a threat to; face a threat; under threat; threat of; idle/bomb/death threat","k":"col"},{"w":"weather","vi":"thời tiết; bất thường; mọi thời tiết; không khỏe; dự báo; chống chịu thời tiết","ex":"Volunteers work in all {weathers}.","note":"good/bad/freak weather; in all weathers; under the weather; weather forecast; weatherproof","k":"col"},{"w":"wind","vi":"gió nhẹ/mạnh; cơn gió giật; có dấu hiệu sắp xảy ra; làn sóng đổi thay","ex":"A gust of {wind} scattered the papers.","note":"light/strong wind; a gust of wind; in the wind; winds of change","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"an act of God","vi":"sự kiện thiên nhiên ngoài kiểm soát của con người","ex":"The flood was treated as {an act of God}.","k":"idiom"},{"w":"come rain or shine","vi":"bất kể thời tiết/khó khăn","ex":"We meet every Friday, {come rain or shine}.","k":"idiom"},{"w":"down on your luck","vi":"trong giai đoạn kém may, nhất là thiếu việc/tiền","ex":"The charity helps people down on their {luck}.","k":"idiom"},{"w":"draw the short straw","vi":"bị chọn nhận phần việc khó chịu","ex":"I drew {the short straw} and cleaned up.","k":"idiom"},{"w":"have green fingers","vi":"có tài trồng cây","ex":"My grandmother has {green fingers}.","k":"idiom"},{"w":"let nature take its course","vi":"để quá trình tự nhiên diễn ra","ex":"We decided to {let nature take its course}.","k":"idiom"},{"w":"no rhyme or reason","vi":"không có lí lẽ/trật tự dễ hiểu","ex":"There is {no rhyme or reason} to the pattern.","k":"idiom"},{"w":"out of the blue","vi":"bất ngờ, không báo trước","ex":"The offer arrived {out of the blue}.","k":"idiom"},{"w":"the luck of the draw","vi":"kết quả do may rủi hơn là mình kiểm soát","ex":"Getting the best room is {the luck of the draw}.","k":"idiom"},{"w":"touch wood","vi":"nói để mong vận may tiếp tục, tránh điều xấu","ex":"We have had no delays, {touch wood}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"assess","vi":"đánh giá","note":"assess → reassess, (re)assessment, assessor, assessed","full":"đánh giá → đánh giá lại; sự đánh giá; người đánh giá; được đánh giá.","ex":"The risk {assessment} was revised.","hint":"assess","k":"wf"},{"w":"cause","vi":"gây ra","note":"cause → causation, causal, causative","full":"gây ra → quan hệ nhân quả; thuộc nguyên nhân; gây ra/thuộc cấu trúc nhờ làm.","ex":"Correlation does not establish {causation}.","hint":"cause","k":"wf"},{"w":"conserve","vi":"bảo tồn","note":"conserve → conservation, conservationist, conservatism, conservative(ly)","full":"bảo tồn → bảo tồn; nhà bảo tồn; tư tưởng bảo thủ; bảo thủ/thận trọng.","ex":"Conservationists opposed the development.","hint":"conserve","k":"wf"},{"w":"ecology","vi":"sinh thái học","note":"ecology → ecologist, ecological(ly)","full":"sinh thái học → nhà sinh thái; thuộc sinh thái.","ex":"The project has {ecological} benefits.","hint":"ecology","k":"wf"},{"w":"elude","vi":"lẩn tránh/khó nắm bắt","note":"elude → elusiveness, elusive(ly)","full":"lẩn tránh/khó nắm bắt → tính khó nắm; khó tìm/hiểu.","ex":"A clear answer remained {elusive}.","hint":"elude","k":"wf"},{"w":"erode","vi":"xói mòn","note":"erode → erosion","full":"xói mòn → sự xói mòn.","ex":"Tree roots help prevent {erosion}.","hint":"erode","k":"wf"},{"w":"erupt","vi":"phun trào/bùng phát","note":"erupt → eruption","full":"phun trào/bùng phát → sự phun trào.","ex":"The {eruption} forced residents to evacuate.","hint":"erupt","k":"wf"},{"w":"extinct","vi":"tuyệt chủng","note":"extinct → extinction","full":"tuyệt chủng → sự tuyệt chủng.","ex":"The species faces {extinction}.","hint":"extinct","k":"wf"},{"w":"favour","vi":"ưu ái","note":"favour → favouritism, favourite, (un)favourable, (un)favourably","full":"ưu ái → thiên vị; yêu thích; thuận/không thuận lợi; trạng từ.","ex":"The forecast is {favourable}.","hint":"favour","k":"wf"},{"w":"fortune","vi":"may mắn/tài sản","note":"fortune → misfortune, (un)fortunate(ly), fortuitous(ly)","full":"may mắn/tài sản → bất hạnh; may/không may; fortuitous: tình cờ, không nhất thiết may.","ex":"The discovery was {fortuitous} rather than planned.","hint":"fortune","k":"wf"},{"w":"instinct","vi":"bản năng","note":"instinct → instinctive(ly)","full":"bản năng → theo bản năng.","ex":"Her response was {instinctive}.","hint":"instinct","k":"wf"},{"w":"intend","vi":"định","note":"intend → intention, (un)intended, (un)intentional(ly)","full":"định → ý định; có/không được dự định; cố ý/vô tình.","ex":"The damage was {unintentional}.","hint":"intend","k":"wf"},{"w":"mount","vi":"leo/tăng","note":"mount → surmount, mountain, mountaineer(ing), (in)surmountable, mountainous","full":"leo/tăng → vượt qua; núi; người/môn leo núi; vượt được/không; nhiều núi.","ex":"The obstacle seemed {insurmountable}.","hint":"mount","k":"wf"},{"w":"mystery","vi":"bí ẩn","note":"mystery → mystify, mystification, mysterious(ly)","full":"bí ẩn → làm khó hiểu; sự hoang mang; bí ẩn.","ex":"The cause remained {mysterious}.","hint":"mystery","k":"wf"},{"w":"occur","vi":"xảy ra","note":"occur → recur, occurrence, recurrence, recurring, recurrent","full":"xảy ra → tái diễn; sự việc; sự tái diễn; lặp lại.","ex":"We investigated the {recurring} fault.","hint":"occur","k":"wf"},{"w":"probable","vi":"có khả năng","note":"probable → (im)probability, improbable, (im)probably","full":"có khả năng → xác suất/sự khó có; khó có khả năng; trạng từ.","ex":"The outcome was highly {improbable}.","hint":"probable","k":"wf"},{"w":"risk","vi":"rủi ro/liều","note":"risk → risky","full":"rủi ro/liều → có rủi ro.","ex":"It was a {risky} experiment.","hint":"risk","k":"wf"},{"w":"seem","vi":"dường như","note":"seem → seeming(ly)","full":"dường như → bề ngoài, có vẻ.","ex":"A {seemingly} minor error changed the result.","hint":"seem","k":"wf"},{"w":"threat","vi":"mối đe dọa","note":"threat → threaten, threatened, threatening(ly)","full":"mối đe dọa → đe dọa; bị đe dọa; có vẻ đe dọa.","ex":"Several {threatened} species live here.","hint":"threat","k":"wf"},{"w":"wild","vi":"hoang dã","note":"wild → wilderness, wildlife, wildness, wildly","full":"hoang dã → vùng hoang vu; động thực vật hoang dã; tính hoang; rất/điên cuồng.","ex":"The estimates varied {wildly}.","hint":"wild","k":"wf"}]}]},{"g":3,"u":14,"title":"Quantity and Money","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"abundant","pos":"adj","vi":"dồi dào","ex":"The region has {abundant} resources and ample space.","grp":["abundant","ample"],"k":"topic"},{"w":"ample","pos":"adj","vi":"đủ nhiều, dư cho nhu cầu","ex":"The region has abundant resources and {ample} space.","grp":["abundant","ample"],"k":"topic"},{"w":"area","pos":"n","vi":"diện tích/khu vực","ex":"Measure each dimension before calculating the {area}.","grp":["area","dimension"],"k":"topic"},{"w":"dimension","pos":"n","vi":"chiều kích/kích thước","ex":"Measure each {dimension} before calculating the area.","grp":["area","dimension"],"k":"topic"},{"w":"average","pos":"v/n","vi":"mức trung bình/trung bình","ex":"The {average} growth rate has fallen.","grp":["average","rate"],"k":"topic"},{"w":"rate","pos":"v/n","vi":"đánh giá, tốc độ/tỉ lệ/mức giá","ex":"The average growth {rate} has fallen.","grp":["average","rate"],"k":"topic"},{"w":"batch","pos":"n","vi":"nhóm/mẻ, chia theo mẻ","ex":"We produce each {batch} in bulk.","grp":["batch","bulk"],"k":"topic"},{"w":"bulk","pos":"n","vi":"khối lượng lớn/phần lớn","ex":"We produce each batch in {bulk}.","grp":["batch","bulk"],"k":"topic"},{"w":"considerable","pos":"adj","vi":"đáng kể","ex":"The project needs {considerable} funding and immense effort.","grp":["considerable","immense"],"k":"topic"},{"w":"immense","pos":"adj","vi":"rất lớn","ex":"The project needs considerable funding and {immense} effort.","grp":["considerable","immense"],"k":"topic"},{"w":"countless","pos":"adj","vi":"nhiều không đếm xuể","ex":"Demand may seem {countless}, but resources are finite.","grp":["countless","finite"],"k":"topic"},{"w":"finite","pos":"adj","vi":"hữu hạn","ex":"Demand may seem countless, but resources are {finite}.","grp":["countless","finite"],"k":"topic"},{"w":"diminish","pos":"v","vi":"giảm mức độ/lượng","ex":"As demand {diminished}, the market shrank.","grp":["diminish","shrink"],"k":"topic"},{"w":"shrink","pos":"v","vi":"co nhỏ/thu hẹp","ex":"As demand diminished, the market shrank.","grp":["diminish","shrink"],"k":"topic"},{"w":"equation","pos":"n","vi":"phương trình","ex":"The {equation} shows that the sum is fixed.","grp":["equation","sum"],"k":"topic"},{"w":"sum","pos":"n","vi":"tổng/phép cộng/khoản tiền","ex":"The equation shows that the {sum} is fixed.","grp":["equation","sum"],"k":"topic"},{"w":"equidistant","pos":"adj","vi":"cách đều","ex":"The markers were {equidistant}, but the ground was uneven.","grp":["equidistant","uneven"],"k":"topic"},{"w":"uneven","pos":"adj","vi":"không đều, không bằng phẳng","ex":"The markers were equidistant, but the ground was {uneven}.","grp":["equidistant","uneven"],"k":"topic"},{"w":"expand","pos":"n","vi":"mở rộng","ex":"The survey {expanded} to establish the full extent of the damage.","grp":["expand","extent"],"k":"topic"},{"w":"extent","pos":"n","vi":"phạm vi/mức độ","ex":"The survey expanded to establish the full {extent} of the damage.","grp":["expand","extent"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"force","pos":"n","vi":"ép buộc/lực","ex":"The {force} increased as the storm gained intensity.","grp":["force","intensity"],"k":"topic"},{"w":"intensity","pos":"n","vi":"cường độ","ex":"The force increased as the storm gained {intensity}.","grp":["force","intensity"],"k":"topic"},{"w":"fraction","pos":"n","vi":"phân số/phần nhỏ","ex":"Only a small {fraction} of the sample represented that proportion accurately.","grp":["fraction","proportion"],"k":"topic"},{"w":"proportion","pos":"n","vi":"tỉ lệ/phần trong tổng","ex":"Only a small fraction of the sample represented that {proportion} accurately.","grp":["fraction","proportion"],"k":"topic"},{"w":"heap","pos":"n","vi":"chất đống/đống","ex":"They {heaped} the material into a dense mass.","grp":["heap","mass"],"k":"topic"},{"w":"mass","pos":"n","vi":"khối lượng/khối lớn","ex":"They heaped the material into a dense {mass}.","grp":["heap","mass"],"k":"topic"},{"w":"imbalance","pos":"n","vi":"sự mất cân bằng","ex":"The unequal ratio revealed an {imbalance}.","grp":["imbalance","ratio"],"k":"topic"},{"w":"ratio","pos":"n","vi":"tỉ số","ex":"The unequal {ratio} revealed an imbalance.","grp":["imbalance","ratio"],"k":"topic"},{"w":"magnitude","pos":"n","vi":"độ lớn/tầm quan trọng","ex":"The volume of waste shows the {magnitude} of the problem.","grp":["magnitude","volume"],"k":"topic"},{"w":"volume","pos":"n","vi":"thể tích/khối lượng hoạt động/âm lượng","ex":"The {volume} of waste shows the magnitude of the problem.","grp":["magnitude","volume"],"k":"topic"},{"w":"major","pos":"adj","vi":"lớn/chính/quan trọng","ex":"A minor adjustment prevented a {major} loss.","grp":["major","minor"],"k":"topic"},{"w":"minor","pos":"adj","vi":"nhỏ/thứ yếu","ex":"A {minor} adjustment prevented a major loss.","grp":["major","minor"],"k":"topic"},{"w":"meagre","pos":"adj","vi":"ít ỏi, không đủ","ex":"The {meagre} allowance was not sufficient for the trip.","grp":["meagre","sufficient"],"k":"topic"},{"w":"sufficient","pos":"adj","vi":"đủ","ex":"The meagre allowance was not {sufficient} for the trip.","grp":["meagre","sufficient"],"k":"topic"},{"w":"minute","pos":"adj","vi":"cực nhỏ, đọc /maɪˈnjuːt/","ex":"A {minute} error can have vast consequences.","grp":["minute","vast"],"k":"topic"},{"w":"vast","pos":"adj","vi":"mênh mông/rất lớn","ex":"A minute error can have {vast} consequences.","grp":["minute","vast"],"k":"topic"},{"w":"multiple","pos":"v","vi":"bội số/nhiều","ex":"We must quantify the {multiple} effects.","grp":["multiple","quantify"],"k":"topic"},{"w":"quantify","pos":"v","vi":"đo hoặc diễn đạt bằng số lượng","ex":"We must {quantify} the multiple effects.","grp":["multiple","quantify"],"k":"topic"},{"w":"ration","pos":"adj","vi":"phân phối định lượng/khẩu phần","ex":"Widespread shortages forced the authorities to {ration} supplies.","grp":["ration","widespread"],"k":"topic"},{"w":"widespread","pos":"adj","vi":"phổ biến trên phạm vi rộng","ex":"{Widespread} shortages forced the authorities to ration supplies.","grp":["ration","widespread"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"benefit","pos":"n","vi":"hưởng lợi/lợi ích/trợ cấp","ex":"Workers received {benefits} and compensation after the closure.","grp":["benefit","compensation"],"k":"topic"},{"w":"compensation","pos":"n","vi":"tiền hoặc sự bồi thường","ex":"Workers received benefits and {compensation} after the closure.","grp":["benefit","compensation"],"k":"topic"},{"w":"damages","pos":"n","vi":"tiền bồi thường theo pháp lí, thường số nhiều","ex":"The insurance covered the {damages} awarded by the court.","grp":["damages","insurance"],"k":"topic"},{"w":"insurance","pos":"n","vi":"bảo hiểm","ex":"The {insurance} covered the damages awarded by the court.","grp":["damages","insurance"],"k":"topic"},{"w":"debt","pos":"n","vi":"khoản/tình trạng nợ","ex":"The overdraft increased her total {debt}.","grp":["debt","overdraft"],"k":"topic"},{"w":"overdraft","pos":"n","vi":"khoản thấu chi tài khoản ngân hàng","ex":"The {overdraft} increased her total debt.","grp":["debt","overdraft"],"k":"topic"},{"w":"deduct","pos":"v","vi":"khấu trừ","ex":"They {deducted} the fee before he withdrew the balance.","grp":["deduct","withdraw"],"k":"topic"},{"w":"withdraw","pos":"v","vi":"rút tiền/rút lại","ex":"They deducted the fee before he withdrew the balance.","grp":["deduct","withdraw"],"k":"topic"},{"w":"deposit","pos":"n phr","vi":"gửi tiền/tiền đặt cọc","ex":"The {deposit} formed part of the down payment.","grp":["deposit","down payment"],"k":"topic"},{"w":"down payment","pos":"n phr","vi":"khoản trả trước khi mua trả góp","ex":"The deposit formed part of the {down payment}.","grp":["deposit","down payment"],"k":"topic"},{"w":"direct debit","pos":"n phr","vi":"lệnh ghi nợ tự động","ex":"You can pay a lump sum or use a monthly {direct debit}.","grp":["direct debit","lump sum"],"k":"topic"},{"w":"lump sum","pos":"n phr","vi":"khoản tiền trả một lần","ex":"You can pay a {lump sum} or use a monthly direct debit.","grp":["direct debit","lump sum"],"k":"topic"},{"w":"dividend","pos":"n","vi":"cổ tức","ex":"Each share entitled its owner to a {dividend}.","grp":["dividend","share"],"k":"topic"},{"w":"share","pos":"n","vi":"cổ phần/phần được chia","ex":"Each {share} entitled its owner to a dividend.","grp":["dividend","share"],"k":"topic"},{"w":"finance","pos":"n","vi":"cấp vốn/tài chính","ex":"They {financed} the purchase with a mortgage.","grp":["finance","mortgage"],"k":"topic"},{"w":"mortgage","pos":"n","vi":"khoản vay thế chấp, thường mua nhà","ex":"They financed the purchase with a {mortgage}.","grp":["finance","mortgage"],"k":"topic"},{"w":"interest","pos":"n","vi":"lãi/tiền lãi","ex":"The pension fund earned {interest} on its deposits.","grp":["interest","pension"],"k":"topic"},{"w":"pension","pos":"n","vi":"lương hưu/quỹ hưu trí","ex":"The {pension} fund earned interest on its deposits.","grp":["interest","pension"],"k":"topic"},{"w":"investment","pos":"v","vi":"sự/khoản đầu tư","ex":"He distinguished long-term {investment} from speculating for quick gains.","grp":["investment","speculate"],"k":"topic"},{"w":"speculate","pos":"v","vi":"đầu cơ chấp nhận rủi ro để kiếm lời hoặc phỏng đoán","ex":"He distinguished long-term investment from {speculating} for quick gains.","grp":["investment","speculate"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"add up to","vi":"cộng thành tổng; kết hợp tạo kết quả","ex":"The payments add up {to} a large sum.","k":"pv"},{"w":"break down","vi":"chia tổng thành các phần; breakdown (n)","ex":"Break the costs {down} by category.","k":"pv"},{"w":"build up","vi":"tích lũy/tăng dần; đề cao; bồi dưỡng; build-up (n)","ex":"She built {up} a small emergency fund.","k":"pv"},{"w":"buy off","vi":"đưa tiền mua chuộc để không chống lại","ex":"They tried to buy the witness {off}.","k":"pv"},{"w":"buy out","vi":"mua lại phần sở hữu của đối tác; buyout (n)","ex":"One partner bought the other {out}.","k":"pv"},{"w":"buy up","vi":"mua số lượng lớn/toàn bộ","ex":"Investors bought {up} the available land.","k":"pv"},{"w":"carry over","vi":"chuyển phần dư/quyền lợi sang kì sau; carry-over (n)","ex":"Unused leave can be carried {over}.","k":"pv"},{"w":"clock up","vi":"tích lũy đạt số lượng/thời gian","ex":"He clocked {up} hundreds of training hours.","k":"pv"},{"w":"club together","vi":"góp tiền chung","ex":"We clubbed {together} to buy a gift.","k":"pv"},{"w":"drum up","vi":"tìm cách thu hút khách/sự ủng hộ","ex":"The campaign drummed {up} new business.","k":"pv"},{"w":"mount up","vi":"tăng lên nhiều","ex":"Small expenses soon mount {up}.","k":"pv"},{"w":"pay back","vi":"trả lại tiền đã vay","ex":"I will pay you {back} next week.","k":"pv"},{"w":"pay out","vi":"chi/trả tiền, thường nhiều; khoản đầu tư trả ra","ex":"The insurer paid {out} promptly.","k":"pv"},{"w":"size up","vi":"đánh giá người/tình hình","ex":"She sized {up} the opportunity carefully.","k":"pv"},{"w":"take away","vi":"lấy đi; trừ một lượng","ex":"Take five {away} from the total.","k":"pv"},{"w":"weigh down","vi":"đè nặng về vật lí/tinh thần","ex":"Debt weighed the family {down}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"big","vi":"làm quá; thành công lớn; mê; rộng lượng; kinh doanh lớn/tự cao/tốt bụng","ex":"Do not make a {big} thing out of a small delay.","note":"make a big thing out of; make it big; big on; big of sb to V; great big; big business/headed/hearted; Big Bang; big name/money/game","k":"col"},{"w":"deal","vi":"kinh doanh hàng gì/xử lí; giáng đòn; làm quá; đạt thỏa thuận; mua được hời; có gì to tát đâu (thường mỉa mai); rất nhiều","ex":"They struck a {deal} with a supplier.","note":"deal in/with; deal a blow to; make a big deal out of; cut/make/reach/strike a deal with; get a good deal on; big deal; a good/great deal of","k":"col"},{"w":"depth","vi":"chuyên sâu; độ sâu; phẩm chất tiềm ẩn; mức tệ nhất; vượt khả năng","ex":"The report examines the issue in {depth}.","note":"in depth; to/at a depth of; hidden depths; the depths of; out of your depth","k":"col"},{"w":"fat","vi":"béo/làm giàu nhờ; hầu như không có cơ hội; chẳng ích gì (mỉa mai)","ex":"A {fat} lot of good that warning did after the event!","note":"get/grow fat on; fat chance; a fat lot of good/help/use","k":"col"},{"w":"high","vi":"tìm khắp; rủi ro/ưu tiên cao; vui; tài chính lớn; đến lúc; công nghệ cao/phố chính","ex":"Demand reached an all-time {high}.","note":"look/search high and low; high risk/priority/spirits/finance/time; on a high; a new/all- time/record high; high tech/street","k":"col"},{"w":"large","vi":"xuất hiện rõ trước mắt; tự do/chưa bị bắt; phần lớn; nổi bật hơn thường; quy mô lớn","ex":"The scheme failed in {large} part because of cost.","note":"as large as life; at large; in large measure/part; larger than life; large-scale","k":"col"},{"w":"length","vi":"hết sức; khắp chiều dài rộng; dài bằng/khác; một hồi lâu/chi tiết","ex":"She explained the figures at {length}.","note":"go to great/any lengths; run the length and breadth of; of unequal/equal length; in length; for any length of time; at some/great length","k":"col"},{"w":"load","vi":"chất; ngồi nghỉ; rất nhiều; gánh nặng","ex":"The repayment is a heavy {load} to bear.","note":"load sth with/into; take a load off your feet; a whole load of/loads of; a heavy load to bear/carry","k":"col"},{"w":"long","vi":"xem xét thật kĩ; cuối cùng cũng; khoảng cách xa; về dài hạn; lâu không gặp; miễn là; đường dài; suốt ngày/tuần","ex":"The investment may help in the {long} run.","note":"take a long hard look at; at long last; a long way; in the long run/term; long time no see; as/so long as; long- distance; all day/week long","k":"col"},{"w":"lot","vi":"hết phần; rất bận; rất nhiều; nhiều nỗi lo; toàn bộ; số phận","ex":"I have a {lot} on this week.","note":"that's your lot; have a lot on; lots/a lot/an awful lot of; a lot on your mind; the lot; sb's lot in life","k":"col"},{"w":"money","vi":"kiếm/tiêu; đáng tiền; hành động theo lời; trả nhiều; lắm tiền; theo tôi","ex":"The course gives students their {money}'s worth.","note":"make/earn/spend/cost money; get your money's worth; put your money where your mouth is; pay good money for; made of money; for my money","k":"col"},{"w":"pay","vi":"trả giá đắt; khen; tự trả phần mình; viếng; chịu hậu quả; làm sẽ có lợi; tăng/đóng băng lương; trả phí rồi trưng vé; lương thực nhận","ex":"It {pays} to read the agreement carefully.","note":"pay dearly for; pay sb a compliment; pay your way; pay your last respects; pay the penalty/price; it pays to; pay rise; pay and display; pay freeze; take-home pay","k":"col"},{"w":"poor","vi":"thua xa vị trí nhất; người thua cay cú; đáng thương; người/thứ bị lép vế; bản rẻ/kém hơn","ex":"The service came a {poor} second to its rival.","note":"come a poor second; poor loser; poor girl/boy; poor relation; a poor man's sth","k":"col"},{"w":"rich","vi":"giàu về; cực giàu; giới giàu nổi tiếng; người giàu/nghèo","ex":"The area is {rich} in natural resources.","note":"rich in; filthy/stinking rich; the rich and famous; the rich and the poor","k":"col"},{"w":"share","vi":"chia; chia đều; phần; cổ đông; chỉ số/quyền mua/chia phần","ex":"The cost was {shared} among the participants.","note":"share with/between/among; share and share alike; share in/of; shareholder; share index/option/out","k":"col"},{"w":"short","vi":"thiếu; nóng tính; nhận phần xui; làm nhanh gọn; một thời gian ngắn; báo gấp; ngắn mà đủ; danh sách chọn lọc","ex":"We made {short} work of the routine checks.","note":"run short of; have a short temper/fuse; draw/get the short straw; make short work of; a short while/period/spell; at short notice; short and sweet; shortlist","k":"col"},{"w":"size","vi":"đại khái là vậy; cắt đúng cỡ; về kích cỡ; cỡ thật; thu nhỏ/cắt nhân sự","ex":"The firm decided to downsize.","note":"that's about the size of it; cut to size; in size; full size; size of; downsize","k":"col"},{"w":"small","vi":"thấy kém cỏi; thế giới nhỏ; ít/nhiều; theo nghĩa thường; tiền lẻ/giờ khuya/truyền hình/chuyện xã giao","ex":"Her work contributed in no {small} way to our success.","note":"feel/look small; a small world; in a/some/no small way; with a small c; small change/hours/screen/talk","k":"col"},{"w":"thin","vi":"dễ tự ái; làm điều rủi ro; từ/vào hư không; ít/ít tóc","ex":"Experienced staff are {thin} on the ground.","note":"have a thin skin; skate on thin ice; out of/from/into thin air; thin on the ground/top","k":"col"},{"w":"weak","vi":"bủn rủn; yếu về; thiếu cơ sở; lí lẽ/điểm yếu; thiếu ý chí","ex":"The claim is on {weak} ground.","note":"weak at the knees; weak on; on weak ground; weak argument/point/spot; weak-willed","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a drop in the ocean","vi":"lượng rất nhỏ so với nhu cầu","ex":"The grant is {a drop in the ocean}.","k":"idiom"},{"w":"break even","vi":"hòa vốn","ex":"The business finally broke {even}.","k":"idiom"},{"w":"fall short","vi":"không đạt mức/mục tiêu","ex":"The results fell {short} of expectations.","k":"idiom"},{"w":"fifty-fifty","vi":"ngang nhau/chia đều hai phần","ex":"We split the cost {fifty-fifty}.","k":"idiom"},{"w":"go halves","vi":"mỗi người trả một nửa","ex":"Shall we {go halves} on the gift?","k":"idiom"},{"w":"it is as broad as it is long","vi":"hai lựa chọn xét cho cùng ngang nhau","ex":"Either route costs the same; {it is as broad as it is long}.","k":"idiom"},{"w":"keep up with the Joneses","vi":"cố bằng hàng xóm/người xung quanh về vật chất/địa vị","ex":"They bought it just to {keep up with the Joneses}.","k":"idiom"},{"w":"knee-high to a grasshopper","vi":"còn rất nhỏ tuổi","ex":"I have known her since she was knee- high {to a grasshopper}.","k":"idiom"},{"w":"line your pockets","vi":"kiếm lợi cho mình, thường bất chính","ex":"The scheme helped officials line their {pockets}.","k":"idiom"},{"w":"lock stock and barrel","vi":"toàn bộ mọi thứ","ex":"They sold the business lock, {stock and barrel}.","k":"idiom"},{"w":"six of one and half a dozen of the other","vi":"hai bên/lựa chọn cũng như nhau về tốt xấu","ex":"Neither option is better: {six of one and half a dozen of the other}.","k":"idiom"},{"w":"a tidy sum/amount","vi":"một khoản tiền khá lớn","ex":"The repairs cost a tidy sum.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"add","vi":"thêm","note":"add → addition, addendum, addenda, additive, additional(ly)","full":"thêm → phép/sự thêm; phụ lục (số nhiều addenda); chất phụ gia; bổ sung.","ex":"The addendum lists {additional} charges.","hint":"add","k":"wf"},{"w":"benefit","vi":"lợi ích","note":"benefit → beneficiary, beneficial(ly)","full":"lợi ích → người thụ hưởng; có lợi.","ex":"She is the {beneficiary} of the fund.","hint":"benefit","k":"wf"},{"w":"brief","vi":"ngắn/báo cáo","note":"brief → debrief, (de)briefing, brevity, briefs, briefly","full":"ngắn/báo cáo → hỏi rút kinh nghiệm; buổi báo cáo; sự ngắn gọn; hồ sơ/quần lót tùy nghĩa; ngắn gọn.","ex":"Please explain the proposal {briefly}.","hint":"brief","k":"wf"},{"w":"broad","vi":"rộng","note":"broad → broaden, breadth, broadly","full":"rộng → mở rộng; bề rộng; nói chung/rộng rãi.","ex":"Training broadened her knowledge.","hint":"broad","k":"wf"},{"w":"consider","vi":"cân nhắc","note":"consider → consideration, considered, considering, (in)considerable, considerably","full":"cân nhắc → sự cân nhắc; được nghĩ kĩ; xét đến; đáng/không đáng kể; đáng kể.","ex":"Costs rose {considerably}.","hint":"consider","k":"wf"},{"w":"deep","vi":"sâu","note":"deep → deepen, depth, deeply","full":"sâu → làm sâu; độ sâu; sâu sắc.","ex":"We {deeply} appreciate your support.","hint":"deep","k":"wf"},{"w":"distant","vi":"xa","note":"distant → (equi)distance, equidistant, (equi)distantly","full":"xa → khoảng cách/khoảng cách bằng nhau; cách đều; một cách xa/cách đều.","ex":"The points are {equidistant} from the centre.","hint":"distant","k":"wf"},{"w":"draw","vi":"vẽ/kéo","note":"draw → withdraw, withdrew, drew, drawn, withdrawal, drawing, overdraft, overdrawn, withdrawn","full":"vẽ/kéo → rút; các dạng quá khứ; sự rút; bản vẽ; thấu chi; bị thấu chi; thu mình/đã rút.","ex":"The {withdrawal} left the account overdrawn.","hint":"draw","k":"wf"},{"w":"extend","vi":"mở rộng","note":"extend → extent, extension, (un)extended, extensive(ly)","full":"mở rộng → phạm vi; sự gia hạn/phần mở; mở rộng/chưa mở; rộng lớn; rộng rãi.","ex":"The survey was {extensive}.","hint":"extend","k":"wf"},{"w":"finite","vi":"hữu hạn","note":"finite → infinity, infinitive, infinite(ly), infinitesimal(ly)","full":"hữu hạn → vô hạn; động từ nguyên mẫu; vô hạn; cực kì nhỏ.","ex":"The difference is {infinitesimal}.","hint":"finite","k":"wf"},{"w":"high","vi":"cao","note":"high → heighten, highlight, height, Highness, heightened, highbrow, highly","full":"cao → tăng; nhấn mạnh; chiều cao; tước hiệu Điện hạ; gia tăng; trí thức bác học; rất/đánh giá cao.","ex":"The incident {heightened} concern.","hint":"high","k":"wf"},{"w":"large","vi":"lớn","note":"large → enlarge, enlargement, largely","full":"lớn → làm lớn; sự phóng to; phần lớn.","ex":"The photograph needs {enlargement}.","hint":"large","k":"wf"},{"w":"long","vi":"dài","note":"long → prolong, lengthen, length, longevity, longhand, longing(ly), long- winded, lengthy, prolonged, lengthways, lengthwise","full":"dài → kéo dài; chiều dài; tuổi thọ; chữ viết tay; khao khát; dài dòng; dài/lâu; theo chiều dọc.","ex":"A lengthy delay {prolonged} the uncertainty.","hint":"long","k":"wf"},{"w":"lot","vi":"phần","note":"lot → allot, allotment","full":"phần → phân bổ; phần/sự phân bổ, mảnh vườn thuê.","ex":"Each team was allotted a budget.","hint":"lot","k":"wf"},{"w":"magnify","vi":"phóng đại","note":"magnify → magnificence, magnification, magnificent(ly), magnifying","full":"phóng đại → vẻ tráng lệ; độ phóng đại; tráng lệ; phóng đại.","ex":"The lens provides greater {magnification}.","hint":"magnify","k":"wf"},{"w":"major","vi":"chính/lớn","note":"major → majority, majorette","full":"chính/lớn → đa số; người biểu diễn gậy dẫn đoàn diễu hành.","ex":"The {majority} supported the plan.","hint":"major","k":"wf"},{"w":"minor","vi":"nhỏ/thứ yếu","note":"minor → minority","full":"nhỏ/thứ yếu → thiểu số.","ex":"A small {minority} disagreed.","hint":"minor","k":"wf"},{"w":"pay","vi":"trả","note":"pay → overpay, underpay, repay, overpayment, underpayment, (re)payment, payback, payee, payer, payload, payoff, payout, payroll, payslip, overpaid, underpaid, payable","full":"trả → trả thừa/thiếu/lại; khoản trả; bên nhận/trả; tải hữu ích; kết quả/tiền chi; bảng lương; phiếu lương; phải trả.","ex":"Check the payee's name before making {payment}.","hint":"pay","k":"wf"},{"w":"portion","vi":"phần","note":"portion → apportion","full":"phần → phân chia/phân bổ.","ex":"The cost was apportioned between departments.","hint":"portion","k":"wf"},{"w":"weigh","vi":"cân","note":"weigh → weight, weightlifter, weightlifting, weighting, overweight, underweight, weighted, weightless, weighty","full":"cân → trọng lượng; người/môn cử tạ; hệ số trọng số; quá/thiếu cân; có trọng số; không trọng lượng; nặng/quan trọng.","ex":"The findings raise {weighty} questions.","hint":"weigh","k":"wf"}]}]},{"g":3,"u":16,"title":"Materials and the Built Environment","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/4 (Topic vocabulary)","words":[{"w":"block","pos":"v/adj","vi":"chặn/khối đặc","ex":"Compact the material into a solid {block}.","grp":["block","compact"],"k":"topic"},{"w":"compact","pos":"v/adj","vi":"nén, ép gọn/nhỏ gọn","ex":"{Compact} the material into a solid block.","grp":["block","compact"],"k":"topic"},{"w":"brittle","pos":"adj","vi":"cứng nhưng dễ vỡ vụn","ex":"The {brittle} plastic made the whole object fragile.","grp":["brittle","fragile"],"k":"topic"},{"w":"fragile","pos":"adj","vi":"dễ vỡ/hư hại nói chung","ex":"The brittle plastic made the whole object {fragile}.","grp":["brittle","fragile"],"k":"topic"},{"w":"chip","pos":"v/n","vi":"mẻ/mảnh vỡ nhỏ","ex":"The cup {chipped}, and paint flaked from the shelf.","grp":["chip","flake"],"k":"topic"},{"w":"flake","pos":"v/n","vi":"bong thành vảy/mảnh mỏng","ex":"The cup chipped, and paint {flaked} from the shelf.","grp":["chip","flake"],"k":"topic"},{"w":"concentrate","pos":"v","vi":"tăng nồng độ dung dịch","ex":"Heating {concentrates} the solution; adding water dilutes it.","grp":["concentrate","dilute"],"k":"topic"},{"w":"dilute","pos":"v","vi":"pha loãng/loãng","ex":"Heating concentrates the solution; adding water {dilutes} it.","grp":["concentrate","dilute"],"k":"topic"},{"w":"crack","pos":"v/n","vi":"nứt/vết nứt","ex":"The glass {cracked}, and the fabric tore.","grp":["crack","tear"],"k":"topic"},{"w":"tear","pos":"v/n","vi":"xé/vết rách","ex":"The glass cracked, and the fabric tore.","grp":["crack","tear"],"k":"topic"},{"w":"crumb","pos":"n","vi":"vụn bánh/thức ăn khô","ex":"There was not a {crumb} of bread or a speck of dust.","grp":["crumb","speck"],"k":"topic"},{"w":"speck","pos":"n","vi":"hạt/chấm rất nhỏ","ex":"There was not a crumb of bread or a {speck} of dust.","grp":["crumb","speck"],"k":"topic"},{"w":"crush","pos":"v/n","vi":"nghiền/bóp hỏng, đám đông chen chúc","ex":"{Crush} the can, but do not squash the carton containing glass.","grp":["crush","squash"],"k":"topic"},{"w":"squash","pos":"v/n","vi":"ép bẹp, cảnh chật ních","ex":"Crush the can, but do not {squash} the carton containing glass.","grp":["crush","squash"],"k":"topic"},{"w":"dense","pos":"adj","vi":"đặc, khối lượng lớn so với thể tích","ex":"The {dense} base supports a hollow column.","grp":["dense","hollow"],"k":"topic"},{"w":"hollow","pos":"adj","vi":"rỗng bên trong","ex":"The dense base supports a {hollow} column.","grp":["dense","hollow"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/4 (Topic vocabulary)","words":[{"w":"dissolve","pos":"n/adj","vi":"hòa tan","ex":"The salt {dissolved} in the warm liquid.","grp":["dissolve","liquid"],"k":"topic"},{"w":"liquid","pos":"n/adj","vi":"chất lỏng/dạng lỏng","ex":"The salt dissolved in the warm {liquid}.","grp":["dissolve","liquid"],"k":"topic"},{"w":"fabric","pos":"adj","vi":"vải","ex":"The {fabric} contains synthetic fibres.","grp":["fabric","synthetic"],"k":"topic"},{"w":"synthetic","pos":"adj","vi":"tổng hợp, nhân tạo","ex":"The fabric contains {synthetic} fibres.","grp":["fabric","synthetic"],"k":"topic"},{"w":"firm","pos":"adj","vi":"chắc nhưng không nhất thiết cứng","ex":"A {firm} cushion rested against a stiff board.","grp":["firm","stiff"],"k":"topic"},{"w":"stiff","pos":"adj","vi":"cứng, khó uốn","ex":"A firm cushion rested against a {stiff} board.","grp":["firm","stiff"],"k":"topic"},{"w":"friction","pos":"n","vi":"ma sát","ex":"{Friction} slows the object while gravity pulls it down.","grp":["friction","gravity"],"k":"topic"},{"w":"gravity","pos":"n","vi":"lực hấp dẫn/trọng lực","ex":"Friction slows the object while {gravity} pulls it down.","grp":["friction","gravity"],"k":"topic"},{"w":"grain","pos":"n","vi":"hạt nhỏ","ex":"A lump of sugar contains many small {grains}.","grp":["grain","lump"],"k":"topic"},{"w":"lump","pos":"n","vi":"cục không đều, gộp nhóm","ex":"A {lump} of sugar contains many small grains.","grp":["grain","lump"],"k":"topic"},{"w":"grind","pos":"v","vi":"nghiền thành hạt nhỏ/bột","ex":"{Grind} the spices, but do not smash the bowl.","grp":["grind","smash"],"k":"topic"},{"w":"smash","pos":"v","vi":"đập vỡ mạnh thành nhiều mảnh","ex":"Grind the spices, but do not {smash} the bowl.","grp":["grind","smash"],"k":"topic"},{"w":"mineral","pos":"n","vi":"khoáng chất","ex":"The sample contains a {mineral} and an unknown substance.","grp":["mineral","substance"],"k":"topic"},{"w":"substance","pos":"n","vi":"chất thuộc thể rắn/lỏng/khí","ex":"The sample contains a mineral and an unknown {substance}.","grp":["mineral","substance"],"k":"topic"},{"w":"mould","pos":"n","vi":"tạo hình/khuôn","ex":"{Mould} the clay carefully to preserve its texture.","grp":["mould","texture"],"k":"topic"},{"w":"texture","pos":"n","vi":"kết cấu/cảm giác bề mặt","ex":"Mould the clay carefully to preserve its {texture}.","grp":["mould","texture"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/4 (Topic vocabulary)","words":[{"w":"opaque","pos":"adj","vi":"không nhìn xuyên được","ex":"The bathroom window is {opaque}; the drinking glass is transparent.","grp":["opaque","transparent"],"k":"topic"},{"w":"transparent","pos":"adj","vi":"trong suốt","ex":"The bathroom window is opaque; the drinking glass is {transparent}.","grp":["opaque","transparent"],"k":"topic"},{"w":"pat","pos":"v/n","vi":"vỗ nhẹ vài lần","ex":"She {patted} the dog, then stroked its fur.","grp":["pat","stroke"],"k":"topic"},{"w":"stroke","pos":"v/n","vi":"vuốt nhẹ dọc bề mặt","ex":"She patted the dog, then {stroked} its fur.","grp":["pat","stroke"],"k":"topic"},{"w":"pile","pos":"v/n","vi":"chất/đống","ex":"Do not {pile} the boxes randomly; stack them safely.","grp":["pile","stack"],"k":"topic"},{"w":"stack","pos":"v/n","vi":"xếp thành chồng có trật tự/chồng","ex":"Do not pile the boxes randomly; {stack} them safely.","grp":["pile","stack"],"k":"topic"},{"w":"polish","pos":"v/n","vi":"đánh bóng/chất đánh bóng","ex":"Scrub the surface before {polishing} it.","grp":["polish","scrub"],"k":"topic"},{"w":"scrub","pos":"v/n","vi":"chà rửa mạnh/lần chà rửa","ex":"{Scrub} the surface before polishing it.","grp":["polish","scrub"],"k":"topic"},{"w":"scratch","pos":"v/n","vi":"cào/gãi, vết xước","ex":"Do not {scratch} the surface when squeezing the parts together.","grp":["scratch","squeeze"],"k":"topic"},{"w":"squeeze","pos":"v/n","vi":"bóp/ép, cái bóp","ex":"Do not scratch the surface when {squeezing} the parts together.","grp":["scratch","squeeze"],"k":"topic"},{"w":"solid","pos":"v/n","vi":"chất rắn/rắn chắc","ex":"Do not stuff {solid} objects into the soft case.","grp":["solid","stuff"],"k":"topic"},{"w":"stuff","pos":"v/n","vi":"nhét/đồ vật, vật liệu nói chung, thường không đếm được","ex":"Do not {stuff} solid objects into the soft case.","grp":["solid","stuff"],"k":"topic"},{"w":"built-up","pos":"adj","vi":"có nhiều công trình","ex":"The densely populated area is heavily {built-up}.","grp":["built-up","populated"],"k":"topic"},{"w":"populated","pos":"adj","vi":"có người sinh sống","ex":"The densely {populated} area is heavily built-up.","grp":["built-up","populated"],"k":"topic"},{"w":"bypass","pos":"n","vi":"đi vòng tránh/đường vòng","ex":"The new {bypass} improves local transport infrastructure.","grp":["bypass","infrastructure"],"k":"topic"},{"w":"infrastructure","pos":"n","vi":"hạ tầng","ex":"The new bypass improves local transport {infrastructure}.","grp":["bypass","infrastructure"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 4/4 (Topic vocabulary)","words":[{"w":"construct","pos":"v","vi":"xây dựng","ex":"They demolished the warehouse and {constructed} new housing.","grp":["construct","demolish"],"k":"topic"},{"w":"demolish","pos":"v","vi":"phá dỡ có chủ đích","ex":"They {demolished} the warehouse and constructed new housing.","grp":["construct","demolish"],"k":"topic"},{"w":"district","pos":"n","vi":"khu vực/quận","ex":"The housing estate lies in a quiet {district}.","grp":["district","estate"],"k":"topic"},{"w":"estate","pos":"n","vi":"khu nhà xây theo dự án hoặc điền sản tùy nghĩa","ex":"The housing {estate} lies in a quiet district.","grp":["district","estate"],"k":"topic"},{"w":"dwell","pos":"v","vi":"sinh sống, thường trang trọng","ex":"Many families {dwell} in buildings originally occupied by factories.","grp":["dwell","occupy"],"k":"topic"},{"w":"occupy","pos":"v","vi":"ở/sử dụng/chiếm chỗ","ex":"Many families dwell in buildings originally {occupied} by factories.","grp":["dwell","occupy"],"k":"topic"},{"w":"evict","pos":"n","vi":"trục xuất khỏi chỗ ở theo thủ tục","ex":"The housing service helped tenants threatened with {eviction}.","grp":["evict","housing"],"k":"topic"},{"w":"housing","pos":"n","vi":"nhà ở nói chung","ex":"The {housing} service helped tenants threatened with eviction.","grp":["evict","housing"],"k":"topic"},{"w":"high-rise","pos":"n","vi":"cao tầng","ex":"The skyline includes {high-rise} blocks and several skyscrapers.","grp":["high-rise","skyscraper"],"k":"topic"},{"w":"skyscraper","pos":"n","vi":"nhà chọc trời","ex":"The skyline includes high-rise blocks and several {skyscrapers}.","grp":["high-rise","skyscraper"],"k":"topic"},{"w":"inner city","pos":"adj","vi":"khu nội đô, thường gắn vấn đề xã hội","ex":"She moved from an inner-{city} flat to a suburban house.","grp":["inner city","suburban"],"k":"topic"},{"w":"suburban","pos":"adj","vi":"thuộc ngoại ô","ex":"She moved from an inner-city flat to a {suburban} house.","grp":["inner city","suburban"],"k":"topic"},{"w":"skyline","pos":"n","vi":"đường nét nhà/núi trên nền trời","ex":"The new structure changed the city's {skyline}.","grp":["skyline","structure"],"k":"topic"},{"w":"structure","pos":"n","vi":"kết cấu/công trình","ex":"The new {structure} changed the city's skyline.","grp":["skyline","structure"],"k":"topic"},{"w":"surroundings","pos":"adj","vi":"khu vực xung quanh","ex":"The park offers peaceful {surroundings} in an urban area.","grp":["surroundings","urban"],"k":"topic"},{"w":"urban","pos":"adj","vi":"thuộc đô thị","ex":"The park offers peaceful surroundings in an {urban} area.","grp":["surroundings","urban"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"board up","vi":"đóng ván che cửa","ex":"They boarded {up} the empty house.","k":"pv"},{"w":"close up","vi":"khóa cửa, đóng cửa cơ sở","ex":"The shopkeeper closed {up} for the night.","k":"pv"},{"w":"come out","vi":"vết bẩn được tẩy sạch; cho kết quả nhất định","ex":"The stain came {out} in the wash.","k":"pv"},{"w":"cut out","vi":"cắt bỏ; ngừng ăn/làm điều có hại","ex":"Cut {out} the damaged section.","k":"pv"},{"w":"fix up","vi":"sửa sang, trang trí","ex":"They fixed {up} the old cottage.","k":"pv"},{"w":"knock/pull/tear down","vi":"phá dỡ công trình/tường","ex":"The unsafe wall was pulled {down}.","k":"pv"},{"w":"pile up","vi":"chất đống, tăng nhiều","ex":"Unfinished work piled {up}.","k":"pv"},{"w":"prop up","vi":"chống đỡ vật; hỗ trợ một hệ thống tồn tại","ex":"They propped {up} the damaged roof.","k":"pv"},{"w":"put in","vi":"lắp đặt; nộp yêu cầu/đề nghị","ex":"We put {in} new heating and a request for insulation.","k":"pv"},{"w":"put together","vi":"lắp ráp; tổ chức/tập hợp","ex":"She put {together} a team of designers.","k":"pv"},{"w":"put up","vi":"dựng/xây; cho ở nhờ","ex":"They put {up} a fence and put us up overnight.","k":"pv"},{"w":"set up","vi":"dựng/lắp để sẵn sử dụng","ex":"Set {up} the equipment before the demonstration.","k":"pv"},{"w":"spread out","vi":"tản ra, phủ diện tích rộng","ex":"The houses spread {out} along the valley.","k":"pv"},{"w":"take down","vi":"tháo công trình thành phần; ghi lại","ex":"They took {down} the temporary stage.","k":"pv"},{"w":"water down","vi":"pha loãng; làm nội dung nhẹ/yếu hơn","ex":"The final proposal was watered {down}.","k":"pv"},{"w":"wear down","vi":"mài mòn; làm kiệt sức/mất tự tin dần","ex":"Constant friction wore the surface {down}.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"bend","vi":"uốn; phát điên; khúc cua gấp","ex":"{Bend} the wire into a circle.","note":"bend sth into shape/a circle; go round the bend; a sharp/tight bend","k":"col"},{"w":"block","vi":"cản đường; khối nhà; tắc ý","ex":"A fallen tree {blocked} our way.","note":"block sb's way; a block of flats; apartment/high-rise block; mental/writer's block","k":"col"},{"w":"brick","vi":"gạch vữa/cơ sở vật chất; tường gạch; thợ xây","ex":"The business invested in {bricks} and mortar.","note":"bricks and mortar; brick wall; bricklayer","k":"col"},{"w":"erect","vi":"dựng; đứng/tư thế thẳng","ex":"They {erected} a monument to the founders.","note":"erect a statue/monument to sb; stand erect; erect posture","k":"col"},{"w":"floor","vi":"phát biểu; tầng; tiết mục biểu diễn/sơ đồ/ván sàn","ex":"The architect had the {floor} for ten minutes.","note":"take/have the floor; ground/first floor; floor show/plan/board","k":"col"},{"w":"fold","vi":"gấp đôi; gấp gọn/phẳng; khoanh tay","ex":"{Fold} the diagram in half.","note":"fold in half/two; fold neatly/carefully; fold flat; fold your arms","k":"col"},{"w":"foundation","vi":"đặt nền; không cơ sở; khóa dự bị/đá đặt móng","ex":"The allegation was without {foundation}.","note":"lay the foundations of; have no foundation; without foundation; foundation course/stone","k":"col"},{"w":"house","vi":"chuyển nhà; miễn phí do quán mời; việc nhà; quản gia; nội trợ; chăm nhà tươm tất","ex":"The drinks are on the {house}.","note":"move house; on the house; housework; housekeeping; housekeeper; housewife; houseproud","k":"col"},{"w":"mark","vi":"đánh dấu; để lại dấu; nửa chặng; phản ứng nhanh/chậm; đúng/trượt đích","ex":"The reform passed the halfway {mark}.","note":"mark with/on; leave a mark on; burn/scratch mark; halfway mark; quick/slow off the mark; hit/miss the mark","k":"col"},{"w":"material","vi":"vật chất/tài sản/phần thưởng/nguồn lực; nguyên liệu","ex":"The factory reuses raw {materials}.","note":"material goods/possessions/rewards/resources; raw materials","k":"col"},{"w":"matter","vi":"vấn đề của; chỉ trong vài ngày; dù thế nào; tệ hơn nữa; thực ra/đương nhiên/khẩn cấp; tùy quan điểm; nội dung chủ đề","ex":"The repair was completed in a {matter} of hours.","note":"a matter of; in a matter of days; no matter how/what; to make matters worse; as a matter of fact/course/urgency; a matter of opinion; subject matter","k":"col"},{"w":"metal","vi":"kim loại quý; máy dò kim loại","ex":"The device can detect precious {metals}.","note":"precious metal; metal detector","k":"col"},{"w":"shape","vi":"tạo hình; mang hình; hình thành rõ; khỏe/mất dáng; đủ hình cỡ","ex":"The plan is beginning to take {shape}.","note":"shape into; take the shape of; take shape; in/out of shape; all shapes and sizes","k":"col"},{"w":"sharp","vi":"theo dõi kĩ; tăng/giảm mạnh; phê bình gay gắt; cay nghiệt","ex":"Keep a {sharp} eye on the pressure gauge.","note":"keep a sharp eye on; sharp rise/increase/drop/fall; sharp criticism; a sharp tongue","k":"col"},{"w":"smooth","vi":"tạo thuận lợi; nói khéo; suôn sẻ; người giỏi xoay xở","ex":"The agreement {smoothed} the way for construction.","note":"smooth the way for; smooth-talking; smooth sailing; smooth operator","k":"col"},{"w":"surface","vi":"bề ngoài/bên dưới; diện tích bề mặt; mặt bếp","ex":"The fault lay beneath the {surface}.","note":"on/beneath/under the surface; surface area; kitchen surface","k":"col"},{"w":"table","vi":"dọn bàn; đưa đề xuất ra bàn theo cách dùng Anh Anh; đang xem xét; phép lịch sự; thời gian biểu","ex":"A revised proposal is on the {table}.","note":"set/clear/lay the table; table a proposal; on the table; table manners; timetable","k":"col"},{"w":"tough","vi":"cứng rắn với; khắc nghiệt; xui; yêu thương nghiêm khắc; người mạnh mẽ","ex":"The regulator got {tough} with unsafe builders.","note":"get tough with; tough on; tough luck/love/guy","k":"col"},{"w":"town","vi":"quy hoạch; thị trấn; vùng rìa; trung tâm","ex":"The factory moved to the outskirts of {town}.","note":"town planning; the town of; outskirts/edge of town; town centre","k":"col"},{"w":"window","vi":"xem hàng; tô vẽ bề ngoài; bị bỏ qua; góc nhìn vào","ex":"The display offers a {window} into local history.","note":"window-shopping; window dressing; out of the window; a window on/onto/into","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a home from home","vi":"nơi thoải mái như nhà mình","ex":"The small hotel became {a home from home}.","k":"idiom"},{"w":"a blot on the landscape","vi":"thứ làm xấu cảnh quan","ex":"The abandoned tower is {a blot on the landscape}.","k":"idiom"},{"w":"commuter belt","vi":"vành đai nơi cư dân sống và đi làm ở thành phố lớn","ex":"They bought a house in the {commuter belt}.","k":"idiom"},{"w":"concrete jungle","vi":"khu đô thị bê tông dày đặc, thiếu dễ chịu","ex":"The park is an escape from the {concrete jungle}.","k":"idiom"},{"w":"home sweet home","vi":"vui mừng khi trở về nhà","ex":"{Home sweet home}, she said as she opened the door.","k":"idiom"},{"w":"in the sticks","vi":"ở vùng xa đô thị (thân mật)","ex":"Their cottage is out {in the sticks}.","k":"idiom"},{"w":"make yourself at home","vi":"cứ tự nhiên như ở nhà","ex":"Please {make yourself at home}.","k":"idiom"},{"w":"on the street","vi":"không có chỗ ở trong nghĩa đang học","ex":"The closure left several people {on the street}.","k":"idiom"},{"w":"on the town","vi":"đi chơi tối ở quán, nhà hát, câu lạc bộ","ex":"They spent a night {on the town}.","k":"idiom"},{"w":"satellite town","vi":"đô thị vệ tinh phụ thuộc thành phố lớn","ex":"A railway connects the {satellite town} to the city.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"analyse","vi":"phân tích","note":"analyse → analysis, analyst, analytic(al), analytically","full":"phân tích → sự phân tích; nhà phân tích; thuộc phân tích.","ex":"The analyst examined the results {analytically}.","hint":"analyse","k":"wf"},{"w":"architect","vi":"kiến trúc sư","note":"architect → architecture, architectural(ly)","full":"kiến trúc sư → kiến trúc; thuộc kiến trúc.","ex":"The building has {architectural} importance.","hint":"architect","k":"wf"},{"w":"dense","vi":"đặc","note":"dense → density, densely","full":"đặc → mật độ; dày đặc.","ex":"It is a {densely} populated district.","hint":"dense","k":"wf"},{"w":"house","vi":"nhà","note":"house → housing, household(er), houseful","full":"nhà → nhà ở; hộ gia đình/chủ hộ; một nhà đầy người/đồ.","ex":"Housing costs affect every {household}.","hint":"house","k":"wf"},{"w":"inhabit","vi":"cư trú","note":"inhabit → inhabitant, habitat, habitation, habitable, (un)inhabitable, (un)inhabited","full":"cư trú → cư dân; môi trường sống; sự/nơi cư trú; ở được/không; có/không có người ở.","ex":"The island is {uninhabited} but habitable.","hint":"inhabit","k":"wf"},{"w":"manufacture","vi":"sản xuất","note":"manufacture → manufacturer, manufacturing","full":"sản xuất → nhà sản xuất; ngành/việc sản xuất.","ex":"The {manufacturer} changed the material.","hint":"manufacture","k":"wf"},{"w":"material","vi":"vật liệu/vật chất","note":"material → materialise, materialism, materialistic, immaterial, materially","full":"vật liệu/vật chất → thành hiện thực; chủ nghĩa vật chất; trọng vật chất; không liên quan; đáng kể/về vật chất.","ex":"The promised support never materialised.","hint":"material","k":"wf"},{"w":"metal","vi":"kim loại","note":"metal → metallic, metallurgy","full":"kim loại → có tính kim loại; luyện kim.","ex":"The surface has a {metallic} shine.","hint":"metal","k":"wf"},{"w":"object","vi":"vật/phản đối","note":"object → objective, objection, objectivity, objector, (un)objectionable, objectively","full":"vật/phản đối → mục tiêu/khách quan; phản đối; tính khách quan; người phản đối; đáng/không đáng phản đối.","ex":"Assess the objection {objectively}.","hint":"object","k":"wf"},{"w":"repair","vi":"sửa","note":"repair → repairman/men, repairer, reparation, repairable, irreparable, irreparably","full":"sửa → thợ/người sửa; bồi thường/khắc phục thiệt hại; sửa được; không thể khắc phục.","ex":"The accident caused {irreparable} damage.","hint":"repair","k":"wf"},{"w":"reside","vi":"cư trú","note":"reside → residence, residency, resident, residing, residential(ly)","full":"cư trú → nơi cư trú; tình trạng/quyền cư trú; cư dân; đang cư trú; thuộc khu dân cư.","ex":"The area is mainly {residential}.","hint":"reside","k":"wf"},{"w":"rigid","vi":"cứng/không linh hoạt","note":"rigid → rigidity, rigidly","full":"cứng/không linh hoạt → tính cứng nhắc; cứng nhắc.","ex":"The frame provides {rigidity}.","hint":"rigid","k":"wf"},{"w":"round","vi":"tròn","note":"round → surround, surroundings, roundness, roundabout, surrounding, roundly","full":"tròn → bao quanh; môi trường xung quanh; độ tròn; vòng xuyến/vòng vo; xung quanh; thẳng thừng/mạnh mẽ.","ex":"The proposal was {roundly} criticised.","hint":"round","k":"wf"},{"w":"shelf","vi":"kệ","note":"shelf → shelve, shelves, shelving","full":"kệ → xếp lên kệ/gác kế hoạch; số nhiều shelves; hệ kệ.","ex":"They shelved the expansion plan.","hint":"shelf","k":"wf"},{"w":"slip","vi":"trượt","note":"slip → slippage, slippery","full":"trượt → sự trượt/trễ tiến độ; trơn.","ex":"The wet floor is {slippery}.","hint":"slip","k":"wf"},{"w":"soft","vi":"mềm","note":"soft → soften, softener, softly","full":"mềm → làm mềm; chất làm mềm; nhẹ nhàng.","ex":"Heat softened the material.","hint":"soft","k":"wf"},{"w":"solid","vi":"rắn/chắc","note":"solid → solidify, solidity","full":"rắn/chắc → làm rắn; độ vững chắc.","ex":"The liquid slowly solidified.","hint":"solid","k":"wf"},{"w":"space","vi":"không gian","note":"space → spacing, spaciousness, spacious(ly)","full":"không gian → khoảng cách bố trí; độ rộng; rộng rãi.","ex":"The rooms are {spacious}.","hint":"space","k":"wf"},{"w":"structure","vi":"kết cấu","note":"structure → infrastructure, structural(ly), (un)structured","full":"kết cấu → hạ tầng; thuộc kết cấu; có/không được tổ chức.","ex":"An engineer checked the {structural} damage.","hint":"structure","k":"wf"},{"w":"substance","vi":"chất/cơ sở","note":"substance → substantiate, substantiation, unsubstantiated, (in)substantial(ly)","full":"chất/cơ sở → chứng minh có căn cứ; sự chứng minh; chưa có căn cứ; đáng/không đáng kể.","ex":"The claim remains {unsubstantiated}.","hint":"substance","k":"wf"}]}]},{"g":3,"u":18,"title":"Reactions and Health","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"acknowledge","pos":"n","vi":"thừa nhận/ghi nhận","ex":"He {acknowledged} the error and accepted its consequences.","grp":["acknowledge","consequence"],"k":"topic"},{"w":"consequence","pos":"n","vi":"hậu quả/kết quả","ex":"He acknowledged the error and accepted its {consequences}.","grp":["acknowledge","consequence"],"k":"topic"},{"w":"agonise","pos":"v","vi":"khổ sở cân nhắc","ex":"She {agonised} over the choice and resented the pressure.","grp":["agonise","resent"],"k":"topic"},{"w":"resent","pos":"v","vi":"bất bình, ấm ức vì bị đối xử","ex":"She agonised over the choice and {resented} the pressure.","grp":["agonise","resent"],"k":"topic"},{"w":"apathy","pos":"n","vi":"thờ ơ, thiếu quan tâm","ex":"{Apathy} and inertia delayed the reform.","grp":["apathy","inertia"],"k":"topic"},{"w":"inertia","pos":"n","vi":"sức ì, thiếu hành động/thay đổi","ex":"Apathy and {inertia} delayed the reform.","grp":["apathy","inertia"],"k":"topic"},{"w":"avoid","pos":"v","vi":"tránh tiếp xúc/không làm","ex":"{Avoiding} the hazard may prevent an accident.","grp":["avoid","prevent"],"k":"topic"},{"w":"prevent","pos":"v","vi":"ngăn điều gì xảy ra","ex":"Avoiding the hazard may {prevent} an accident.","grp":["avoid","prevent"],"k":"topic"},{"w":"behaviour","pos":"n","vi":"hành vi/cách cư xử","ex":"The report criticised his {behaviour} and professional conduct.","grp":["behaviour","conduct"],"k":"topic"},{"w":"conduct","pos":"n","vi":"cách ứng xử, thường trang trọng; tiến hành/điều hành","ex":"The report criticised his behaviour and professional {conduct}.","grp":["behaviour","conduct"],"k":"topic"},{"w":"chuckle","pos":"v/n","vi":"cười khẽ trầm","ex":"The adults {chuckled} while the children giggled.","grp":["chuckle","giggle"],"k":"topic"},{"w":"giggle","pos":"v/n","vi":"cười khúc khích, thường vì buồn cười hoặc ngượng","ex":"The adults chuckled while the children {giggled}.","grp":["chuckle","giggle"],"k":"topic"},{"w":"comfort","pos":"n","vi":"an ủi/sự dễ chịu","ex":"The familiar room brought {comfort} and contentment.","grp":["comfort","contentment"],"k":"topic"},{"w":"contentment","pos":"n","vi":"sự hài lòng thanh thản","ex":"The familiar room brought comfort and {contentment}.","grp":["comfort","contentment"],"k":"topic"},{"w":"cross","pos":"adj","vi":"bực/giận","ex":"She grew {cross} and impatient after the delay.","grp":["cross","impatient"],"k":"topic"},{"w":"impatient","pos":"adj","vi":"thiếu kiên nhẫn, nôn nóng","ex":"She grew cross and {impatient} after the delay.","grp":["cross","impatient"],"k":"topic"},{"w":"dignity","pos":"n","vi":"phẩm giá/sự điềm đạm","ex":"Good manners help preserve everyone's {dignity}.","grp":["dignity","manners"],"k":"topic"},{"w":"manners","pos":"n","vi":"phép cư xử","ex":"Good {manners} help preserve everyone's dignity.","grp":["dignity","manners"],"k":"topic"},{"w":"disgust","pos":"adj","vi":"làm ghê tởm/sự ghê tởm","ex":"The scandal {disgusted} voters and left them disillusioned.","grp":["disgust","disillusioned"],"k":"topic"},{"w":"disillusioned","pos":"adj","vi":"vỡ mộng, mất niềm tin","ex":"The scandal disgusted voters and left them {disillusioned}.","grp":["disgust","disillusioned"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"fed up","pos":"adj","vi":"chán ngán","ex":"He looked glum and said he was {fed up}.","grp":["fed up","glum"],"k":"topic"},{"w":"glum","pos":"adj","vi":"buồn rầu, ủ rũ","ex":"He looked {glum} and said he was fed up.","grp":["fed up","glum"],"k":"topic"},{"w":"glance","pos":"v/n","vi":"chủ ý liếc nhanh","ex":"I {glanced} outside and glimpsed a familiar face.","grp":["glance","glimpse"],"k":"topic"},{"w":"glimpse","pos":"v/n","vi":"thoáng thấy","ex":"I glanced outside and {glimpsed} a familiar face.","grp":["glance","glimpse"],"k":"topic"},{"w":"gloat","pos":"v","vi":"hả hê trước thành công mình/thất bại người khác","ex":"Do not {gloat} or smirk when your opponent loses.","grp":["gloat","smirk"],"k":"topic"},{"w":"smirk","pos":"v","vi":"cười nhếch mép tự mãn","ex":"Do not gloat or {smirk} when your opponent loses.","grp":["gloat","smirk"],"k":"topic"},{"w":"grimace","pos":"v/n","vi":"nhăn mặt vì đau/khó chịu","ex":"He {grimaced} at the pain, then managed a grin.","grp":["grimace","grin"],"k":"topic"},{"w":"grin","pos":"v/n","vi":"cười rộng miệng","ex":"He grimaced at the pain, then managed a {grin}.","grp":["grimace","grin"],"k":"topic"},{"w":"handle","pos":"v","vi":"xử lí/điều khiển","ex":"She {handled} the controls and manoeuvred the chair carefully.","grp":["handle","manoeuvre"],"k":"topic"},{"w":"manoeuvre","pos":"v","vi":"khéo di chuyển/thao tác, mưu tính","ex":"She handled the controls and {manoeuvred} the chair carefully.","grp":["handle","manoeuvre"],"k":"topic"},{"w":"moan","pos":"v","vi":"rên/than phiền","ex":"He {moaned} about the work, and others mocked his complaints.","grp":["moan","mock"],"k":"topic"},{"w":"mock","pos":"v","vi":"chế giễu/nhại","ex":"He moaned about the work, and others {mocked} his complaints.","grp":["moan","mock"],"k":"topic"},{"w":"neglect","pos":"adj","vi":"sao nhãng/bỏ bê","ex":"A resolute manager will not {neglect} serious complaints.","grp":["neglect","resolute"],"k":"topic"},{"w":"resolute","pos":"adj","vi":"kiên quyết","ex":"A {resolute} manager will not neglect serious complaints.","grp":["neglect","resolute"],"k":"topic"},{"w":"peep","pos":"v","vi":"nhìn trộm qua khe/nhìn hé","ex":"She {peeped} through the door and peered into the darkness.","grp":["peep","peer"],"k":"topic"},{"w":"peer","pos":"v","vi":"nhìn chăm chú vì khó thấy","ex":"She peeped through the door and {peered} into the darkness.","grp":["peep","peer"],"k":"topic"},{"w":"rejoice","pos":"n","vi":"vui mừng lớn","ex":"They {rejoiced} when the period of terror ended.","grp":["rejoice","terror"],"k":"topic"},{"w":"terror","pos":"n","vi":"nỗi khiếp sợ","ex":"They rejoiced when the period of {terror} ended.","grp":["rejoice","terror"],"k":"topic"},{"w":"snap","pos":"n","vi":"cáu gắt nói gọn/đột ngột gãy","ex":"His tactic was to stay calm even when others {snapped} at him.","grp":["snap","tactic"],"k":"topic"},{"w":"tactic","pos":"n","vi":"chiến thuật cụ thể","ex":"His {tactic} was to stay calm even when others snapped at him.","grp":["snap","tactic"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"administer","pos":"v","vi":"cho dùng thuốc/tiến hành điều trị","ex":"The doctor prescribed the medicine, and a nurse {administered} it.","grp":["administer","prescribe"],"k":"topic"},{"w":"prescribe","pos":"v","vi":"kê đơn/chỉ định","ex":"The doctor {prescribed} the medicine, and a nurse administered it.","grp":["administer","prescribe"],"k":"topic"},{"w":"admit","pos":"n","vi":"tiếp nhận vào viện","ex":"She was {admitted} to the children's ward.","grp":["admit","ward"],"k":"topic"},{"w":"ward","pos":"n","vi":"phòng/khu bệnh","ex":"She was admitted to the children's {ward}.","grp":["admit","ward"],"k":"topic"},{"w":"agony","pos":"adj","vi":"đau đớn dữ dội","ex":"The anaesthetic made the area numb and relieved the {agony}.","grp":["agony","numb"],"k":"topic"},{"w":"numb","pos":"adj","vi":"tê, mất cảm giác","ex":"The anaesthetic made the area {numb} and relieved the agony.","grp":["agony","numb"],"k":"topic"},{"w":"antidote","pos":"n phr","vi":"thuốc giải độc/biện pháp đối trị","ex":"The {antidote} was effective but had side effects.","grp":["antidote","side effect"],"k":"topic"},{"w":"side effect","pos":"n phr","vi":"tác dụng phụ","ex":"The antidote was effective but had {side effects}.","grp":["antidote","side effect"],"k":"topic"},{"w":"consultant","pos":"n","vi":"bác sĩ chuyên khoa cấp cao trong ngữ cảnh Anh","ex":"The {consultant} confirmed the diagnosis.","grp":["consultant","diagnosis"],"k":"topic"},{"w":"diagnosis","pos":"n","vi":"chẩn đoán","ex":"The consultant confirmed the {diagnosis}.","grp":["consultant","diagnosis"],"k":"topic"},{"w":"inoculate","pos":"n","vi":"tiêm chủng","ex":"The clinic {inoculated} patients with the vaccine.","grp":["inoculate","vaccine"],"k":"topic"},{"w":"vaccine","pos":"n","vi":"vắc- xin","ex":"The clinic inoculated patients with the {vaccine}.","grp":["inoculate","vaccine"],"k":"topic"},{"w":"irritation","pos":"n","vi":"sự kích ứng/khó chịu","ex":"The plaster caused mild skin {irritation}.","grp":["irritation","plaster"],"k":"topic"},{"w":"plaster","pos":"n","vi":"băng cá nhân/thạch cao bó bột","ex":"The {plaster} caused mild skin irritation.","grp":["irritation","plaster"],"k":"topic"},{"w":"nursing home","pos":"n phr","vi":"cơ sở chăm sóc dài hạn","ex":"An employee at the {nursing home} was on sick leave.","grp":["nursing home","sick leave"],"k":"topic"},{"w":"sick leave","pos":"n phr","vi":"nghỉ việc vì ốm","ex":"An employee at the nursing home was on {sick leave}.","grp":["nursing home","sick leave"],"k":"topic"},{"w":"paralysis","pos":"n","vi":"tình trạng liệt","ex":"The specialist explained the prognosis after the {paralysis}.","grp":["paralysis","prognosis"],"k":"topic"},{"w":"prognosis","pos":"n","vi":"tiên lượng diễn biến bệnh","ex":"The specialist explained the {prognosis} after the paralysis.","grp":["paralysis","prognosis"],"k":"topic"},{"w":"preventive","pos":"n","vi":"y học dự phòng","ex":"Vaccination is {preventive} medicine; the nurse prepared a syringe.","grp":["preventive","preventative medicine","syringe"],"k":"topic"},{"w":"syringe","pos":"n","vi":"ống tiêm","ex":"Vaccination is preventive medicine; the nurse prepared a {syringe}.","grp":["preventive","preventative medicine","syringe"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"black out","vi":"ngất; tắt đèn làm tối nơi nào; blackout (n)","ex":"He blacked {out} briefly.","k":"pv"},{"w":"come out in","vi":"nổi mẩn/ban khắp","ex":"She came out {in} a rash.","k":"pv"},{"w":"come round","vi":"tỉnh lại; lại đến theo chu kì; ghé thăm; đổi ý","ex":"He came {round} a few minutes after fainting.","k":"pv"},{"w":"cotton on","vi":"bắt đầu hiểu/nhận ra (thân mật)","ex":"She soon cottoned {on} to the joke.","k":"pv"},{"w":"crease up","vi":"cười rất nhiều, làm ai cười","ex":"His expression made us crease {up}.","k":"pv"},{"w":"follow up","vi":"theo dõi sau điều trị; tìm hiểu tiếp; follow-up (n)","ex":"The clinic followed {up} the initial treatment.","k":"pv"},{"w":"get down","vi":"làm buồn/nản","ex":"The long delay got her {down}.","k":"pv"},{"w":"get over","vi":"hồi phục, vượt qua chuyện buồn/vấn đề","ex":"He is getting {over} the operation.","k":"pv"},{"w":"go down well/badly with","vi":"được tiếp nhận tốt/xấu","ex":"The announcement went down badly {with} staff.","k":"pv"},{"w":"lash out","vi":"đột ngột đánh/tấn công; nói giận dữ","ex":"He lashed {out} at the criticism.","k":"pv"},{"w":"pass away/on","vi":"qua đời, cách nói giảm","ex":"Her grandfather passed away peacefully.","k":"pv"},{"w":"play up","vi":"gây khó chịu/đau; cư xử hư","ex":"My knee has been playing {up}.","k":"pv"},{"w":"pull through","vi":"qua khỏi bệnh nặng; vượt tình huống khó","ex":"The doctors expect her to pull {through}.","k":"pv"},{"w":"shrivel up","vi":"teo quắt, khô héo; suy yếu","ex":"The leaves shrivelled {up} in the heat.","k":"pv"},{"w":"summon up","vi":"cố huy động can đảm/năng lượng/phản ứng","ex":"She summoned {up} the courage to speak.","k":"pv"},{"w":"ward off","vi":"ngăn điều nguy hại đến gần/xảy ra","ex":"The barrier wards {off} unwanted contact.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"act","vi":"hành động thiện/thiếu thiện chí; vì tuyệt vọng/cần thiết; đóng vai; theo lời khuyên/lệnh/thay mặt; giả vờ; chấn chỉnh; đang thực hiện việc","ex":"They {acted} in good faith on the information available.","note":"act in good/bad faith; out of desperation/necessity; act the part/role of; act on advice/orders/sb's behalf; put on an act; get your act together; in the act of V-ing","k":"col"},{"w":"behaviour","vi":"hành vi đối với; khuôn mẫu; cư xử tốt; các kiểu hành vi","ex":"The children were on their best {behaviour}.","note":"behaviour towards; a pattern of behaviour; on your best behaviour; aggressive/antisocial/violent/good/exemplary behaviour","k":"col"},{"w":"consequence","vi":"chịu hậu quả; vì thế; không/ít quan trọng","ex":"The omission was of little {consequence}.","note":"accept/face the consequences; consequence of; serious/disastrous/dire consequences; as/in consequence; of no/little consequence","k":"col"},{"w":"cry","vi":"khóc vì/về; kêu cứu; khóc đến ngủ; khóc hết nước mắt; tâm sự nhờ an ủi; khóc một trận; tiếng kêu; khác xa","ex":"The current conditions are a far {cry} from the original plan.","note":"cry with pain/happiness/relief; cry over/about; cry for help; cry yourself to sleep; cry your eyes/heart out; cry on sb's shoulder; have a good cry; a cry of; a far cry from","k":"col"},{"w":"dead","vi":"hết hoạt động; chết; kiên quyết phản đối; rất rắc rối; im phăng phắc/chính giữa; kiệt sức/ngay phía trước","ex":"She is {dead} set against the proposal.","note":"go/drop dead; dead set against V-ing; in dead trouble; dead and buried/gone; dead silence/centre; dead tired/ahead","k":"col"},{"w":"effect","vi":"ảnh hưởng; hiệu lực; để gây ấn tượng; thực chất; kể từ","ex":"The policy comes into {effect} next month.","note":"have an/no/little/some effect on; come into effect; put/bring into effect; adverse/beneficial effect; for effect; in effect; with effect from","k":"col"},{"w":"feel","vi":"có cảm nhận về; cứ tự nhiên; muốn; cảm thấy như; có quan điểm mạnh; thấy tác động/lợi ích; áy náy; dò dẫm; thoải mái như ở nhà","ex":"{Feel} free to ask for clarification.","note":"get/have a feel for; feel free; feel like V-ing; feel as if/though; feel strongly about; feel effects/benefits; feel guilty; feel your way; feel at home","k":"col"},{"w":"health","vi":"sức khỏe và hệ thống/dịch vụ liên quan","ex":"The committee reviewed {health} and safety.","note":"good/bad for health; in good/poor health; ill health; health and safety; health hazard/risk/centre/club/food/service","k":"col"},{"w":"ill","vi":"đổ bệnh; nguy kịch/nặng/giai đoạn cuối","ex":"He was taken {ill} during the trip.","note":"fall/be taken ill with; critically/seriously/terminally ill","k":"col"},{"w":"kind","vi":"tử tế; đáp cùng cách; loại; lời chào trân trọng","ex":"It was {kind} of you to help.","note":"kind of sb to V; respond in kind; kinds of; of some/any kind; of a/the kind; kind regards","k":"col"},{"w":"laugh","vi":"cười; cười thẳng mặt; thắng thế sau cùng; chuyện rất buồn cười","ex":"The trip was a {laugh} a minute.","note":"laugh at/about/in sb's face; make sb laugh; have a good laugh; have the last laugh; don't make me laugh; for a laugh; a laugh a minute","k":"col"},{"w":"life","vi":"sinh mạng; sinh động; không đời nào; chất lượng sống","ex":"The new service improved quality of {life}.","note":"put life at risk; lose/save a life; bring to/come to life; not on your life; take your own life; that's life; this is the life; quality of life","k":"col"},{"w":"live","vi":"sống phạm pháp/xa hoa; sống đến tuổi; chấp nhận được; tôn trọng người khác; sống để học; tiêu quá/trong khả năng; hi vọng; sống giả dối; sống sót để kể","ex":"They learned to {live} within their means.","note":"live a life of crime/luxury; live to an age; can live with; live and let live; live and learn; beyond/within your means; live in hope/a lie; live to tell the tale","k":"col"},{"w":"medicine","vi":"uống thuốc; y học thay thế/bổ trợ/thảo dược; tủ thuốc","ex":"Keep {medicine} in a secure medicine cabinet.","note":"take medicine; alternative/complementary/herbal medicine; medicine cabinet","k":"col"},{"w":"polite","vi":"lịch sự với; ai thật lịch sự; xã giao; nói chuyện/nhóm người đúng mực","ex":"He was only being {polite}.","note":"polite to; polite of; just/only being polite; polite conversation/company/society","k":"col"},{"w":"react","vi":"phản ứng với/bằng/chống lại, cho phù hợp","ex":"She {reacted} to the news with relief.","note":"react to; react by V-ing; react accordingly/appropriately; react with; react against","k":"col"},{"w":"reaction","vi":"gây phản ứng; tiêu cực/bản năng/tức thì; dây chuyền","ex":"The decision triggered a chain {reaction}.","note":"cause/produce/provoke/trigger a reaction to; reaction against; adverse/gut/immediate reaction; chain reaction","k":"col"},{"w":"response","vi":"phản hồi đối với/từ; để đáp lại; thời gian phản hồi","ex":"The clinic acted in {response} to the complaint.","note":"response to/from; in response to; no response; response time","k":"col"},{"w":"sick","vi":"xin nghỉ ốm; buồn nôn; rất thất vọng/lo/chán; túi nôn","ex":"She was worried {sick} about the delay.","note":"call in sick; feel/make sb sick; sick as a parrot; worried sick; sick and tired of; sick with fear; sick at heart; sick bag","k":"col"},{"w":"treat","vi":"đối xử; điều trị; coi như; đãi ai; sắp được điều thích","ex":"The staff {treated} every visitor with respect.","note":"treat cruelly/badly/fairly/unjustly; treat sb with/for/like/to; treat an illness/disease/patient; in for a treat","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"cry over spilt milk","vi":"buồn tiếc việc đã xảy ra không sửa được","ex":"There is no use crying {over spilt milk}.","k":"idiom"},{"w":"fly off the handle","vi":"đột nhiên nổi giận quá mức","ex":"He flew {off the handle} over a minor error.","k":"idiom"},{"w":"give sb a taste/dose of their own medicine","vi":"đối xử với ai theo chính cách xấu họ dùng với người khác","ex":"The prank gave him a taste of his own {medicine}.","k":"idiom"},{"w":"give sth a miss","vi":"bỏ qua một hoạt động thường làm","ex":"I will give the party a {miss} tonight.","k":"idiom"},{"w":"grin and bear it","vi":"chịu hoàn cảnh khó mà không than","ex":"We had to {grin and bear it}.","k":"idiom"},{"w":"keep a straight face","vi":"giữ vẻ nghiêm, không bật cười","ex":"I could not {keep a straight face}.","k":"idiom"},{"w":"keep your hair on","vi":"bình tĩnh, đừng nổi nóng (thân mật)","ex":"{Keep your hair on}; we can fix it.","k":"idiom"},{"w":"kick yourself","vi":"rất bực mình vì lỗi/cơ hội đã bỏ lỡ","ex":"I could kick myself for forgetting the date.","k":"idiom"},{"w":"let off steam","vi":"xả giận/năng lượng căng thẳng","ex":"A walk helps me {let off steam}.","k":"idiom"},{"w":"let sleeping dogs lie","vi":"đừng khơi lại chuyện có thể gây rắc rối","ex":"We decided to {let sleeping dogs lie}.","k":"idiom"},{"w":"never look a gift horse in the mouth","vi":"đừng chê bai món được tặng/giúp miễn phí","ex":"The chair is free, so do not {look a gift horse in the mouth}.","k":"idiom"},{"w":"up in arms about","vi":"giận dữ và phản đối mạnh","ex":"Residents were {up in arms about} the closure.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"act","vi":"hành động","note":"act → enact, react, counteract, interact, transact, overact, overreact, (de/re)activate; acting, actor, actress, action, (in)activity, radioactivity, transaction, activist, activism, interaction, (over)reaction, overacting, reactionary, reactor, transactional, active, hyperactive, radioactive, overactive, (in)active(ly)","full":"hành động → ban hành; phản ứng/chống lại/tương tác/giao dịch; diễn quá; kích hoạt/tắt/bật lại; diễn xuất; hoạt động/bất động; phóng xạ; nhà hoạt động; phản động; lò phản ứng; tăng động/quá mức.","ex":"The {activist} reacted against the decision.","hint":"act","k":"wf"},{"w":"approve","vi":"tán thành","note":"approve → disapprove, (dis)approval, (dis)approved, (dis)approving(ly)","full":"tán thành → không tán thành; sự chấp thuận/phản đối; thái độ tương ứng.","ex":"She gave an {approving} smile.","hint":"approve","k":"wf"},{"w":"avoid","vi":"tránh","note":"avoid → avoidance, (un)avoidable, unavoidably","full":"tránh → sự tránh; tránh được/không; không thể tránh.","ex":"The delay was {unavoidable}.","hint":"avoid","k":"wf"},{"w":"content","vi":"hài lòng","note":"content → (dis)contentment, discontent, (dis)contented","full":"hài lòng → sự hài lòng/bất mãn; hài lòng/không.","ex":"There was growing {discontent}.","hint":"content","k":"wf"},{"w":"depend","vi":"phụ thuộc","note":"depend → (in)dependence, dependant, dependency, depending, dependable, (in)dependent(ly)","full":"phụ thuộc → độc lập/phụ thuộc; người phụ thuộc; sự lệ thuộc; đáng tin; độc lập/phụ thuộc.","ex":"She is a {dependable} colleague.","hint":"depend","k":"wf"},{"w":"derive","vi":"bắt nguồn","note":"derive → derivation, derivative","full":"bắt nguồn → nguồn gốc/sự dẫn xuất; phái sinh/thiếu mới lạ.","ex":"The design is rather {derivative}.","hint":"derive","k":"wf"},{"w":"effect","vi":"tác dụng/thực hiện","note":"effect → (in)effectiveness, (in)effectual, (in)effective(ly)","full":"tác dụng/thực hiện → tính hiệu quả/không; có/không hiệu lực.","ex":"The response was {ineffective}.","hint":"effect","k":"wf"},{"w":"fold","vi":"gấp","note":"fold → enfold, unfold, folder, (un)folding, foldaway","full":"gấp → ôm/bọc; mở ra/diễn tiến; bìa/thư mục; gấp/mở; gấp cất được.","ex":"We watched the events {unfold}.","hint":"fold","k":"wf"},{"w":"fruit","vi":"quả","note":"fruit → fruitfulness, fruitlessness, fruition, fruitful(ly), fruitless(ly)","full":"quả → tính hiệu quả/vô ích; sự thành hiện thực; có kết quả/vô ích.","ex":"The discussions were {fruitful}.","hint":"fruit","k":"wf"},{"w":"hand","vi":"tay","note":"hand → handle, handler, handling, handout, handover, handful, handmade, underhand, handy","full":"tay → xử lí; người điều khiển; cách xử lí; tài liệu phát; bàn giao; một nắm/người khó quản; thủ công; gian lận; tiện.","ex":"Keep the instructions {handy}.","hint":"hand","k":"wf"},{"w":"illusion","vi":"ảo tưởng","note":"illusion → disillusion, disillusionment, disillusioned, illusory","full":"ảo tưởng → làm vỡ mộng; sự vỡ mộng; thất vọng; không có thật.","ex":"The apparent improvement was {illusory}.","hint":"illusion","k":"wf"},{"w":"know","vi":"biết","note":"know → acknowledge, knowledge, acknowledgement, knowledgeable, acknowledged, (un)known, knowing","full":"biết → thừa nhận; kiến thức; sự ghi nhận; am hiểu; được công nhận; biết/không biết; tỏ ý biết ngầm.","ex":"She {acknowledged} the limits of her knowledge.","hint":"know","k":"wf"},{"w":"neglect","vi":"bỏ bê","note":"neglect → negligence, negligible, negligibly, negligent(ly), neglectful(ly)","full":"bỏ bê → cẩu thả thiếu trách nhiệm; không đáng kể; sao nhãng.","ex":"The damage was {negligible}, but the conduct was negligent.","hint":"neglect","k":"wf"},{"w":"patient","vi":"kiên nhẫn/bệnh nhân","note":"patient → patience, impatient, (im)patiently","full":"kiên nhẫn/bệnh nhân → sự kiên nhẫn; thiếu kiên nhẫn; trạng từ.","ex":"Please wait {patiently}.","hint":"patient","k":"wf"},{"w":"prevent","vi":"ngăn","note":"prevent → prevention, preventative, preventive, (un)preventable","full":"ngăn → sự phòng ngừa; mang tính phòng; ngăn được/không.","ex":"{Prevention} requires careful planning.","hint":"prevent","k":"wf"},{"w":"regret","vi":"hối tiếc","note":"regret → regrettable, regrettably, regretful(ly)","full":"hối tiếc → đáng tiếc; thật đáng tiếc; cảm thấy tiếc/một cách hối tiếc.","ex":"The error was {regrettable}; her apology sounded regretful.","hint":"regret","k":"wf"},{"w":"resolve","vi":"giải quyết/quyết tâm","note":"resolve → (ir)resolution, resoluteness, (un)resolved, (ir)resolute(ly)","full":"giải quyết/quyết tâm → sự quyết định/do dự; sự kiên định; đã/chưa giải quyết; kiên quyết/do dự.","ex":"Several issues remained {unresolved}.","hint":"resolve","k":"wf"},{"w":"respond","vi":"đáp","note":"respond → response, respondent, (un)responsive(ly)","full":"đáp → phản hồi; người trả lời; có/không phản ứng.","ex":"The respondents gave detailed responses.","hint":"respond","k":"wf"},{"w":"result","vi":"kết quả","note":"result → resultant, resulting","full":"kết quả → phát sinh do đó.","ex":"The {resulting} confusion caused delays.","hint":"result","k":"wf"},{"w":"sense","vi":"cảm giác","note":"sense → (de)sensitise, sensation, (in)sensitivity, hypersensitivity, hypersensitive, oversensitive, sensuality, sensuousness, sensor, sensory, (in)sensitive(ly), (un)sensational(ly), sensual(ly), sensuous(ly)","full":"cảm giác → làm/tước độ nhạy; cảm giác; độ nhạy/thiếu nhạy; quá nhạy; khoái cảm/cảm thụ giác quan; cảm biến; thuộc giác quan; gây/không gây chấn động.","ex":"The sensor is highly {sensitive} to movement.","hint":"sense","k":"wf"}]}]},{"g":3,"u":20,"title":"Power and Social Issues","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"aggression","pos":"adj","vi":"hành vi/tính gây hấn","ex":"A benign approach reduced {aggression}.","grp":["aggression","benign"],"k":"topic"},{"w":"benign","pos":"adj","vi":"lành, không gây hại hoặc hiền hòa","ex":"A {benign} approach reduced aggression.","grp":["aggression","benign"],"k":"topic"},{"w":"authority","pos":"adj","vi":"quyền lực/thẩm quyền","ex":"Only the {authority} entitled to decide may approve it.","grp":["authority","entitled"],"k":"topic"},{"w":"entitled","pos":"adj","vi":"có quyền được nhận/làm","ex":"Only the authority {entitled} to decide may approve it.","grp":["authority","entitled"],"k":"topic"},{"w":"bully","pos":"v","vi":"bắt nạt/kẻ bắt nạt","ex":"The {bully} tried to intimidate younger pupils.","grp":["bully","intimidate"],"k":"topic"},{"w":"intimidate","pos":"v","vi":"hăm dọa làm mất tự tin","ex":"The bully tried to {intimidate} younger pupils.","grp":["bully","intimidate"],"k":"topic"},{"w":"command","pos":"v","vi":"ra lệnh/mệnh lệnh, quyền chỉ huy","ex":"The {commander} summoned the team and issued a command.","grp":["command","summon"],"k":"topic"},{"w":"summon","pos":"v","vi":"triệu tập, gọi đến","ex":"The commander {summoned} the team and issued a command.","grp":["command","summon"],"k":"topic"},{"w":"conquer","pos":"v","vi":"chinh phục","ex":"The army {conquered} the territory, but no group dominated the debate.","grp":["conquer","dominate"],"k":"topic"},{"w":"dominate","pos":"v","vi":"thống trị/chi phối","ex":"The army conquered the territory, but no group {dominated} the debate.","grp":["conquer","dominate"],"k":"topic"},{"w":"consent","pos":"adj","vi":"đồng ý/sự đồng ý","ex":"She was reluctant to {consent} without more information.","grp":["consent","reluctant"],"k":"topic"},{"w":"reluctant","pos":"adj","vi":"miễn cưỡng, không muốn","ex":"She was {reluctant} to consent without more information.","grp":["consent","reluctant"],"k":"topic"},{"w":"controversy","pos":"n/adj","vi":"tranh cãi công chúng","ex":"The {controversy} brought the idea into mainstream discussion.","grp":["controversy","mainstream"],"k":"topic"},{"w":"mainstream","pos":"n/adj","vi":"dòng chính/được đa số chấp nhận","ex":"The controversy brought the idea into {mainstream} discussion.","grp":["controversy","mainstream"],"k":"topic"},{"w":"dictator","pos":"n","vi":"nhà độc tài","ex":"The country replaced its monarch with a {dictator}.","grp":["dictator","monarch"],"k":"topic"},{"w":"monarch","pos":"n","vi":"quân chủ, vua/nữ hoàng","ex":"The country replaced its {monarch} with a dictator.","grp":["dictator","monarch"],"k":"topic"},{"w":"eliminate","pos":"v","vi":"loại bỏ","ex":"The reform aimed to {eliminate} restrictions and liberate creativity.","grp":["eliminate","liberate"],"k":"topic"},{"w":"liberate","pos":"v","vi":"giải phóng","ex":"The reform aimed to eliminate restrictions and {liberate} creativity.","grp":["eliminate","liberate"],"k":"topic"},{"w":"enforce","pos":"v","vi":"thực thi/buộc tuân thủ quy định","ex":"They imposed new rules and {enforced} existing ones.","grp":["enforce","impose"],"k":"topic"},{"w":"impose","pos":"v","vi":"áp đặt","ex":"They {imposed} new rules and enforced existing ones.","grp":["enforce","impose"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"exempt","pos":"adj/v","vi":"được miễn","ex":"The scheme {exempts} some groups but restricts others.","grp":["exempt","restrict"],"k":"topic"},{"w":"restrict","pos":"adj/v","vi":"hạn chế","ex":"The scheme exempts some groups but {restricts} others.","grp":["exempt","restrict"],"k":"topic"},{"w":"former","pos":"v/n","vi":"trước đây/cựu","ex":"The {former} minister wrote about the monarch's reign.","grp":["former","reign"],"k":"topic"},{"w":"reign","pos":"v/n","vi":"trị vì/thời kì trị vì","ex":"The former minister wrote about the monarch's {reign}.","grp":["former","reign"],"k":"topic"},{"w":"inferior","pos":"adj","vi":"thấp/kém hơn","ex":"No employee should be treated as {inferior} to another.","grp":["inferior","superior"],"k":"topic"},{"w":"superior","pos":"adj","vi":"cao/tốt hơn","ex":"No employee should be treated as inferior to another.","grp":["inferior","superior"],"k":"topic"},{"w":"label","pos":"adj","vi":"gán nhãn/nhãn","ex":"{Labelling} the work inferior was a subjective judgement.","grp":["label","subjective"],"k":"topic"},{"w":"subjective","pos":"adj","vi":"chủ quan, theo quan điểm cá nhân","ex":"Labelling the work inferior was a {subjective} judgement.","grp":["label","subjective"],"k":"topic"},{"w":"master","pos":"v","vi":"làm chủ/thành thạo, người chủ/bậc thầy","ex":"{Mastering} the facts reinforced her confidence.","grp":["master","reinforce"],"k":"topic"},{"w":"reinforce","pos":"v","vi":"củng cố/tăng cường","ex":"Mastering the facts {reinforced} her confidence.","grp":["master","reinforce"],"k":"topic"},{"w":"minister","pos":"v","vi":"bộ trưởng","ex":"The {minister} submitted a proposal to parliament.","grp":["minister","submit"],"k":"topic"},{"w":"submit","pos":"v","vi":"trình/nộp hoặc chịu phục tùng","ex":"The minister {submitted} a proposal to parliament.","grp":["minister","submit"],"k":"topic"},{"w":"prohibit","pos":"v","vi":"cấm","ex":"The law {prohibited} discrimination, but some resisted change.","grp":["prohibit","resist"],"k":"topic"},{"w":"resist","pos":"v","vi":"chống lại/kiềm chế","ex":"The law prohibited discrimination, but some {resisted} change.","grp":["prohibit","resist"],"k":"topic"},{"w":"society","pos":"n","vi":"xã hội/hội","ex":"The subject raised questions about {society} and its institutions.","grp":["society","subject"],"k":"topic"},{"w":"subject","pos":"n","vi":"chủ đề/thần dân","ex":"The {subject} raised questions about society and its institutions.","grp":["society","subject"],"k":"topic"},{"w":"undermine","pos":"v","vi":"làm suy yếu dần","ex":"Victimising staff {undermines} trust.","grp":["undermine","victimise"],"k":"topic"},{"w":"victimise","pos":"v","vi":"đối xử bất công/nhắm hại","ex":"{Victimising} staff undermines trust.","grp":["undermine","victimise"],"k":"topic"},{"w":"unrest","pos":"adj","vi":"bất ổn xã hội","ex":"{Unrest} left vulnerable communities without support.","grp":["unrest","vulnerable"],"k":"topic"},{"w":"vulnerable","pos":"adj","vi":"dễ bị tổn thương/tấn công","ex":"Unrest left {vulnerable} communities without support.","grp":["unrest","vulnerable"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"abolish","pos":"n","vi":"bãi bỏ hẳn","ex":"New legislation {abolished} the outdated system.","grp":["abolish","legislation"],"k":"topic"},{"w":"legislation","pos":"n","vi":"luật pháp/quá trình làm luật","ex":"New {legislation} abolished the outdated system.","grp":["abolish","legislation"],"k":"topic"},{"w":"advocate","pos":"n phr","vi":"ủng hộ công khai","ex":"The charity {advocates} prison reform.","grp":["advocate","prison reform"],"k":"topic"},{"w":"prison reform","pos":"n phr","vi":"cải cách nhà tù","ex":"The charity advocates {prison reform}.","grp":["advocate","prison reform"],"k":"topic"},{"w":"alleviate","pos":"n","vi":"làm nhẹ bớt","ex":"The charity works to {alleviate} poverty.","grp":["alleviate","charity"],"k":"topic"},{"w":"charity","pos":"n","vi":"tổ chức/hoạt động từ thiện","ex":"The {charity} works to alleviate poverty.","grp":["alleviate","charity"],"k":"topic"},{"w":"bureaucracy","pos":"n","vi":"hệ thống quan liêu/thủ tục rườm rà","ex":"The institution tried to reduce unnecessary {bureaucracy}.","grp":["bureaucracy","institution"],"k":"topic"},{"w":"institution","pos":"n","vi":"tổ chức/thiết chế","ex":"The {institution} tried to reduce unnecessary bureaucracy.","grp":["bureaucracy","institution"],"k":"topic"},{"w":"class","pos":"adj","vi":"tầng lớp/lớp","ex":"The privileged {classes} had greater access to education.","grp":["class","privileged"],"k":"topic"},{"w":"privileged","pos":"adj","vi":"có đặc quyền, lợi thế","ex":"The {privileged} classes had greater access to education.","grp":["class","privileged"],"k":"topic"},{"w":"community","pos":"n","vi":"cộng đồng","ex":"The {community} protects its cultural heritage.","grp":["community","heritage"],"k":"topic"},{"w":"heritage","pos":"n","vi":"di sản được truyền lại","ex":"The community protects its cultural {heritage}.","grp":["community","heritage"],"k":"topic"},{"w":"convict","pos":"v","vi":"kết tội/người bị kết án","ex":"The authorities prosecuted him, and the court {convicted} him.","grp":["convict","prosecute"],"k":"topic"},{"w":"prosecute","pos":"v","vi":"truy tố","ex":"The authorities {prosecuted} him, and the court convicted him.","grp":["convict","prosecute"],"k":"topic"},{"w":"corruption","pos":"n","vi":"tham nhũng/sự tha hóa","ex":"The report exposed {corruption} and prejudice.","grp":["corruption","prejudice"],"k":"topic"},{"w":"prejudice","pos":"n","vi":"định kiến","ex":"The report exposed corruption and {prejudice}.","grp":["corruption","prejudice"],"k":"topic"},{"w":"deterrent","pos":"n phr","vi":"biện pháp/yếu tố răn đe","ex":"They debated whether the measure would deter industrial action.","grp":["deterrent","industrial action"],"k":"topic"},{"w":"industrial action","pos":"n phr","vi":"hành động tập thể của người lao động, như đình công","ex":"They debated whether the measure would deter {industrial action}.","grp":["deterrent","industrial action"],"k":"topic"},{"w":"immigration","pos":"n","vi":"nhập cư","ex":"The state reviewed its {immigration} policy.","grp":["immigration","state"],"k":"topic"},{"w":"state","pos":"n","vi":"nhà nước/bang/tình trạng","ex":"The {state} reviewed its immigration policy.","grp":["immigration","state"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"back down","vi":"rút yêu cầu/lập trường vì phản đối","ex":"They refused to back {down}.","k":"pv"},{"w":"blend in","vi":"hòa vào xung quanh, không nổi bật","ex":"The building blends {in} with its surroundings.","k":"pv"},{"w":"bring about","vi":"gây ra thay đổi/kết quả","ex":"The campaign brought {about} reform.","k":"pv"},{"w":"crack down on","vi":"xử lí nghiêm hơn; crackdown (n)","ex":"The authorities cracked down {on} corruption.","k":"pv"},{"w":"get in","vi":"được bầu vào vị trí chính trị","ex":"The candidate got {in} by a narrow margin.","k":"pv"},{"w":"get off","vi":"thoát phạt nặng; được nghỉ; gửi đi","ex":"He got {off} with a warning.","k":"pv"},{"w":"give in","vi":"chịu thua; không cưỡng lại ham muốn/cảm xúc","ex":"She would not give {in} to pressure.","k":"pv"},{"w":"hit back","vi":"đáp trả công kích/tổn hại","ex":"The minister hit {back} at the criticism.","k":"pv"},{"w":"lock up","vi":"giam giữ; khóa kĩ tòa nhà","ex":"They locked {up} the building at night.","k":"pv"},{"w":"opt out of","vi":"quyết định không tham gia/rút khỏi","ex":"Members may opt out {of} the scheme.","k":"pv"},{"w":"phase out","vi":"loại bỏ dần","ex":"They phased {out} the old procedure.","k":"pv"},{"w":"push around","vi":"sai khiến, bắt nạt","ex":"Do not let them push you {around}.","k":"pv"},{"w":"single out","vi":"chọn riêng một người để chú ý","ex":"She was singled {out} for praise.","k":"pv"},{"w":"stand up to","vi":"chống lại, không để bị bắt nạt","ex":"He stood up {to} the bully.","k":"pv"},{"w":"take over","vi":"tiếp quản; làm tiếp việc của người khác","ex":"A new team took {over} the project.","k":"pv"},{"w":"talk down to","vi":"nói kiểu bề trên, coi người nghe kém hơn","ex":"Good teachers do not talk down {to} students.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"arm","vi":"trang bị; phòng bị; cầm/hạ vũ khí; phản đối; kiểm soát/chạy đua vũ trang","ex":"{Arm} yourself with accurate information.","note":"arm sb with; arm yourself against; take up/lay down arms; up in arms about; arms control/race","k":"col"},{"w":"authority","vi":"quyền; có nguồn tin chắc; cơ quan chức trách","ex":"I have it on good {authority} that the plan will change.","note":"have/grant authority to V; authority over; have on good authority; in/with authority; the authorities; local authority","k":"col"},{"w":"charge","vi":"buộc tội/tính tiền; nhận/phụ trách; trách nhiệm toàn bộ","ex":"She was put in {charge} of the review.","note":"charge sb with/for; take charge; put/in charge of; overall charge","k":"col"},{"w":"class","vi":"xếp loại; tầng lớp; hệ thống/khác biệt/xung đột giai cấp","ex":"The study examines {class} differences.","note":"class A as B; social/working/middle/upper/ruling class; class system/differences/war","k":"col"},{"w":"crime","vi":"phạm/báo/chứng kiến/phá/chống tội; hiện trường; tội có tổ chức","ex":"The programme focuses on {crime} prevention.","note":"commit/report/witness/solve/fight/combat crime; scene of a crime; organised crime; crime prevention/rate/wave","k":"col"},{"w":"deny","vi":"không cho; bác; phủ nhận; chối trách nhiệm","ex":"He {denied} having received the message.","note":"deny sb sth; deny a request; deny that/V-ing/having V3; deny all responsibility for","k":"col"},{"w":"example","vi":"phạt làm gương; làm/theo/nêu gương; ví dụ điển hình","ex":"The case is a prime {example} of unfair treatment.","note":"make an example of; set/follow/give an example; example of; classic/prime example","k":"col"},{"w":"force","vi":"ép ai làm/nhận; chen vào; gượng cười; bằng sức mạnh; lực lượng cảnh sát/vũ trang","ex":"Nobody should {force} an opinion on others.","note":"force sb to V; force sth on sb; force your way into/through; force a smile; with force; police force; armed forces","k":"col"},{"w":"grant","vi":"cấp/cho phép/chấp thuận/đáp ứng","ex":"The council {granted} permission for the centre.","note":"grant sth to; grant permission/authority/a request/sb's wish","k":"col"},{"w":"law","vi":"thành luật; vi phạm/tuân/bảo vệ; thông qua/sửa/bãi bỏ; ra lệnh cứng rắn; hành nghề luật; trái/trên/theo luật; trật tự pháp luật","ex":"The committee proposed amending the {law}.","note":"become/break/follow/uphold law; pass/amend/repeal a law; lay down the law; practise law; against/above/by/under law; law and order","k":"col"},{"w":"lock","vi":"khóa giữ; tranh luận/đối đầu; khóa kĩ; thợ khóa","ex":"The records are kept under {lock} and key.","note":"lock sth in; lock horns with; under lock and key; locksmith","k":"col"},{"w":"peer","vi":"nhóm người cùng tuổi/vị thế; áp lực đồng trang lứa","ex":"{Peer} pressure influenced the decision.","note":"peer group; peer pressure","k":"col"},{"w":"power","vi":"giành/chiếm/giữ/sử dụng/lạm quyền; cầm quyền; ngoài khả năng; quyền làm; tranh giành quyền; cơ cấu/cơ sở quyền lực","ex":"It is beyond my {power} to change the deadline.","note":"take/seize/hold/exercise/exert/wield/abuse power; in power; beyond sb's power; power to V; power struggle/structure/base","k":"col"},{"w":"prison","vi":"nhà tù; án/kì hạn; cải cách; quản giáo; nhà tù ít hạn chế","ex":"She researches {prison} reform.","note":"go/send to/in prison; prison term/sentence/reform/officer; open prison","k":"col"},{"w":"provoke","vi":"kích động làm; gây phản ứng/phản đối/phẫn nộ","ex":"The statement {provoked} widespread outrage.","note":"provoke sb into V-ing; provoke a reaction/protest/response/outrage","k":"col"},{"w":"right","vi":"có/không có/mọi quyền làm; trao quyền; đúng sai; đúng khi nói/nghĩ; bình đẳng quyền; quyền con người/động vật","ex":"Everyone has the {right} to be heard.","note":"have a/the/no/every right to V; give the right; right and wrong; right in saying/thinking; right of sb to V; equal/human/animal rights","k":"col"},{"w":"rule","vi":"vi phạm/lách/tuân; thường lệ; pháp quyền; quy tắc kinh nghiệm","ex":"As a {rule}, decisions are recorded in writing.","note":"break/bend/follow rules; against the rules; as a rule; rule of law; rule of thumb; rules and regulations","k":"col"},{"w":"sentence","vi":"tuyên; thụ án; án tù/tử hình","ex":"The judge passed {sentence} after hearing the evidence.","note":"sentence sb to; pass/serve a sentence of; prison/death sentence","k":"col"},{"w":"social","vi":"điều kiện; giao tiếp; an sinh; dịch vụ; thăm xã giao; nhân viên công tác xã hội; sinh hoạt","ex":"Local {social} services provided support.","note":"social conditions/contact/security/services/call/worker/club/life","k":"col"},{"w":"subject","vi":"khiến chịu; nêu/bỏ/đổi chủ đề; tùy thuộc/chịu; thần dân","ex":"The proposal is {subject} to approval.","note":"subject sb to; bring up/get onto/drop/change a subject; subject to; subject of; British subject","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"bury your head in the sand","vi":"lờ vấn đề khó và hi vọng nó tự hết","ex":"We cannot bury our heads in the {sand}.","k":"idiom"},{"w":"gain/get/have/take the upper hand","vi":"giành/có lợi thế kiểm soát","ex":"The smaller team gained {the upper hand}.","k":"idiom"},{"w":"get/have your way","vi":"được làm theo ý mình","ex":"He cannot always have his own way.","k":"idiom"},{"w":"live and let live","vi":"chấp nhận cách sống/niềm tin khác mình","ex":"Their attitude is {live and let live}.","k":"idiom"},{"w":"pull a few strings","vi":"dùng quan hệ/ảnh hưởng để đạt điều muốn","ex":"She refused to pull {strings} for special treatment.","k":"idiom"},{"w":"red tape","vi":"thủ tục, quy định gây trì trệ","ex":"The project was delayed by {red tape}.","k":"idiom"},{"w":"take the law into your own hands","vi":"tự trừng phạt, không nhờ cơ quan pháp luật","ex":"The officer warned against taking {the law into your own hands}.","k":"idiom"},{"w":"the powers that be","vi":"những người nắm quyền quyết định","ex":"{The powers that be} rejected the idea.","k":"idiom"},{"w":"throw the book at sb","vi":"phạt/xử lí ai rất nghiêm","ex":"They expected the court to throw the {book} at him.","k":"idiom"},{"w":"under sb's thumb","vi":"bị ai kiểm soát hoàn toàn","ex":"The committee was under the director's {thumb}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"aggression","vi":"gây hấn","note":"aggression → aggressiveness, aggressor, aggressive(ly)","full":"gây hấn → tính hung hăng; bên tấn công; hung hăng.","ex":"His {aggressive} manner undermined the discussion.","hint":"aggression","k":"wf"},{"w":"argue","vi":"tranh luận","note":"argue → argument, argumentative(ly), (un)arguable, arguably","full":"tranh luận → lí lẽ/tranh cãi; hay cãi; có/không thể tranh cãi; có thể cho rằng.","ex":"This is {arguably} the best option.","hint":"argue","k":"wf"},{"w":"charity","vi":"từ thiện","note":"charity → charitableness, (un)charitable, (un)charitably","full":"từ thiện → lòng nhân ái; nhân ái/khắc nghiệt trong đánh giá; trạng từ.","ex":"That was an {uncharitable} remark.","hint":"charity","k":"wf"},{"w":"crime","vi":"tội phạm","note":"crime → (de)criminalise, criminal, criminality, criminally","full":"tội phạm → hình sự hóa/phi hình sự hóa; người phạm tội; tính tội phạm; theo cách phạm tội.","ex":"The debate concerned decriminalisation.","hint":"crime","k":"wf"},{"w":"dominate","vi":"chi phối","note":"dominate → domineer, domination, (pre)dominance, dominant, domineering, dominating, predominant(ly)","full":"chi phối → áp chế; sự thống trị/vượt trội; chủ đạo; độc đoán; nổi bật/chủ yếu.","ex":"One group remained {predominant}.","hint":"dominate","k":"wf"},{"w":"duty","vi":"bổn phận","note":"duty → dutiful(ly)","full":"bổn phận → biết làm bổn phận; trạng từ.","ex":"He {dutifully} completed the checks.","hint":"duty","k":"wf"},{"w":"example","vi":"ví dụ","note":"example → exemplify, exemplification, exemplary","full":"ví dụ → minh họa; sự minh họa; mẫu mực.","ex":"Her conduct was {exemplary}.","hint":"example","k":"wf"},{"w":"govern","vi":"quản trị","note":"govern → misgovern, government, governor, governess, governing, governmental, ungovernable","full":"quản trị → cai trị kém; chính phủ; thống đốc; cô giáo dạy tại gia; thuộc điều hành; không kiểm soát được.","ex":"The report criticised {governmental} policy.","hint":"govern","k":"wf"},{"w":"hard","vi":"cứng/khó","note":"hard → harden, hardship, hardness, hardy, hardly","full":"cứng/khó → làm cứng; gian khổ; độ cứng; dẻo dai; hầu như không.","ex":"{Hardship} strengthened her determination.","hint":"hard","k":"wf"},{"w":"indicate","vi":"chỉ ra","note":"indicate → indication, indicator, indicative","full":"chỉ ra → dấu hiệu; chỉ số; có tính biểu thị.","ex":"The result is {indicative} of a wider problem.","hint":"indicate","k":"wf"},{"w":"institute","vi":"thiết lập","note":"institute → institutionalise, institution, institutional, institutionalised","full":"thiết lập → thể chế hóa/đưa vào cơ sở chăm sóc; tổ chức; thuộc tổ chức; đã thành nếp.","ex":"The practice became {institutionalised}.","hint":"institute","k":"wf"},{"w":"might","vi":"sức mạnh","note":"might → mighty, mightily","full":"sức mạnh → hùng mạnh; rất/mạnh mẽ.","ex":"They struggled {mightily} to finish.","hint":"might","k":"wf"},{"w":"moral","vi":"đạo đức","note":"moral → moralise, demoralise, (im/a)morality, moralist, morale, (im/a)moral, (im/a)morally","full":"đạo đức → lên giọng đạo đức; làm nản; đạo đức/vô đạo đức/không xét đạo đức; nhà đạo đức; tinh thần.","ex":"Low morale can {demoralise} an entire team.","hint":"moral","k":"wf"},{"w":"office","vi":"chức/văn phòng","note":"office → officiate, official(dom), officer, officious, (un)official(ly)","full":"chức/văn phòng → chủ trì; viên chức/giới quan chức; sĩ quan; hay lên mặt can thiệp; chính thức/không.","ex":"An {officious} employee demanded unnecessary forms.","hint":"office","k":"wf"},{"w":"permit","vi":"cho phép","note":"permit → permission, permissiveness, permissible, permissive","full":"cho phép → sự cho phép; tính dễ dãi; được phép; dễ dãi.","ex":"The change requires written {permission}.","hint":"permit","k":"wf"},{"w":"persuade","vi":"thuyết phục","note":"persuade → dissuade, persuasion, persuasiveness, persuasive(ly)","full":"thuyết phục → can ngăn; sự thuyết phục; sức thuyết phục; có sức thuyết phục.","ex":"She dissuaded them from acting hastily.","hint":"persuade","k":"wf"},{"w":"power","vi":"quyền/sức","note":"power → empower, overpower, empowerment, powerlessness, powerful(ly), powerless(ly)","full":"quyền/sức → trao quyền; áp đảo; sự trao quyền/bất lực; mạnh/bất lực.","ex":"The scheme aims to {empower} residents.","hint":"power","k":"wf"},{"w":"prejudice","vi":"định kiến","note":"prejudice → (un)prejudiced, prejudicial","full":"định kiến → có/không định kiến; gây tổn hại.","ex":"Such comments are {prejudicial} to a fair hearing.","hint":"prejudice","k":"wf"},{"w":"provoke","vi":"kích động","note":"provoke → provocation, provocative(ly)","full":"kích động → sự khiêu khích; gây khiêu khích/phản ứng.","ex":"The remark was deliberately {provocative}.","hint":"provoke","k":"wf"},{"w":"signify","vi":"biểu thị","note":"signify → (in)significance, (in)significant(ly)","full":"biểu thị → tầm quan trọng/không đáng kể; quan trọng/không; trạng từ.","ex":"The change is statistically {significant}.","hint":"signify","k":"wf"}]}]},{"g":3,"u":22,"title":"Quality and the Arts","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"aggravate / exacerbate","pos":"v","vi":"đều là làm tình trạng xấu trầm trọng hơn; aggravate còn có nghĩa làm bực.","de":"","ex":"The delay aggravated the problem and exacerbated tensions.","k":"topic"},{"w":"better","pos":"v","vi":"cải thiện/làm tốt hơn","ex":"The changes {bettered} the service and enhanced its reputation.","grp":["better","enhance"],"k":"topic"},{"w":"enhance","pos":"v","vi":"tăng chất lượng/giá trị/sức hấp dẫn","ex":"The changes bettered the service and {enhanced} its reputation.","grp":["better","enhance"],"k":"topic"},{"w":"blemish","pos":"n","vi":"vết làm xấu bề mặt/tiếng xấu","ex":"The stone had a small {blemish} but no structural flaw.","grp":["blemish","flaw"],"k":"topic"},{"w":"flaw","pos":"n","vi":"khuyết điểm trong vật/lập luận","ex":"The stone had a small blemish but no structural {flaw}.","grp":["blemish","flaw"],"k":"topic"},{"w":"chaos","pos":"n","vi":"hỗn loạn","ex":"The office was a shambles, and the move ended in {chaos}.","grp":["chaos","shambles"],"k":"topic"},{"w":"shambles","pos":"n","vi":"tình trạng tổ chức cực kì lộn xộn, thường a shambles","ex":"The office was a {shambles}, and the move ended in chaos.","grp":["chaos","shambles"],"k":"topic"},{"w":"cheapen","pos":"adj","vi":"làm giảm giá trị","ex":"Shoddy materials {cheapened} the whole design.","grp":["cheapen","shoddy"],"k":"topic"},{"w":"shoddy","pos":"adj","vi":"chất lượng/tay nghề kém","ex":"{Shoddy} materials cheapened the whole design.","grp":["cheapen","shoddy"],"k":"topic"},{"w":"contaminate","pos":"adj","vi":"làm nhiễm bẩn","ex":"Rotten waste {contaminated} the water.","grp":["contaminate","rotten"],"k":"topic"},{"w":"rotten","pos":"adj","vi":"thối rữa/rất tệ","ex":"{Rotten} waste contaminated the water.","grp":["contaminate","rotten"],"k":"topic"},{"w":"decay","pos":"v","vi":"mục nát/suy tàn","ex":"The buildings {decayed} as the district declined.","grp":["decay","decline"],"k":"topic"},{"w":"decline","pos":"v","vi":"giảm, suy giảm","ex":"The buildings decayed as the district {declined}.","grp":["decay","decline"],"k":"topic"},{"w":"defective","pos":"adj","vi":"có lỗi, không hoạt động đúng","ex":"The equipment was {defective} and the response inadequate.","grp":["defective","inadequate"],"k":"topic"},{"w":"inadequate","pos":"adj","vi":"không đủ/không đạt yêu cầu","ex":"The equipment was defective and the response {inadequate}.","grp":["defective","inadequate"],"k":"topic"},{"w":"detrimental","pos":"v","vi":"có hại","ex":"The {detrimental} effects worsened over time.","grp":["detrimental","worsen"],"k":"topic"},{"w":"worsen","pos":"v","vi":"trở nên/làm xấu hơn","ex":"The detrimental effects {worsened} over time.","grp":["detrimental","worsen"],"k":"topic"},{"w":"devastate","pos":"v/n","vi":"tàn phá/làm sốc buồn","ex":"The storm {devastated} the coast and wrecked the gallery.","grp":["devastate","wreck"],"k":"topic"},{"w":"wreck","pos":"v/n","vi":"phá hỏng, xác vật bị phá","ex":"The storm devastated the coast and {wrecked} the gallery.","grp":["devastate","wreck"],"k":"topic"},{"w":"exquisite","pos":"adj","vi":"tinh xảo, đẹp đặc biệt","ex":"The exhibition combines {exquisite} craftsmanship with first-rate design.","grp":["exquisite","first-rate"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"first-rate","pos":"adj","vi":"hạng nhất, xuất sắc","ex":"The exhibition combines exquisite craftsmanship with {first-rate} design.","grp":["exquisite","first-rate"],"k":"topic"},{"w":"evaluate","pos":"n/adj","vi":"đánh giá","ex":"{Evaluate} each option to find the optimum solution.","grp":["evaluate","optimum"],"k":"topic"},{"w":"optimum","pos":"n/adj","vi":"mức tối ưu/tối ưu","ex":"Evaluate each option to find the {optimum} solution.","grp":["evaluate","optimum"],"k":"topic"},{"w":"ideal","pos":"adj","vi":"lí tưởng/phù hợp nhất","ex":"The result was satisfactory, although not {ideal}.","grp":["ideal","satisfactory"],"k":"topic"},{"w":"satisfactory","pos":"adj","vi":"đạt mức chấp nhận được","ex":"The result was {satisfactory}, although not ideal.","grp":["ideal","satisfactory"],"k":"topic"},{"w":"invaluable","pos":"n phr","vi":"vô cùng quý","ex":"Her {invaluable} advice was the meeting's only redeeming feature.","grp":["invaluable","redeeming feature"],"k":"topic"},{"w":"redeeming feature","pos":"n phr","vi":"ưu điểm bù lại khuyết điểm","ex":"Her invaluable advice was the meeting's only {redeeming feature}.","grp":["invaluable","redeeming feature"],"k":"topic"},{"w":"outclass","pos":"v","vi":"vượt trội rõ về chất lượng","ex":"The new model {outclassed} rivals and surpassed expectations.","grp":["outclass","surpass"],"k":"topic"},{"w":"surpass","pos":"v","vi":"vượt mức/thành tích/kì vọng","ex":"The new model outclassed rivals and {surpassed} expectations.","grp":["outclass","surpass"],"k":"topic"},{"w":"prime","pos":"adj","vi":"chính/tốt nhất ở mức tiêu biểu","ex":"The {prime} objective was to create the ultimate visitor experience.","grp":["prime","ultimate"],"k":"topic"},{"w":"ultimate","pos":"adj","vi":"cuối cùng/tột đỉnh","ex":"The prime objective was to create the {ultimate} visitor experience.","grp":["prime","ultimate"],"k":"topic"},{"w":"refurbish","pos":"v","vi":"tân trang bằng sửa/trang bị","ex":"They renovated the house and {refurbished} the rooms.","grp":["refurbish","renovate"],"k":"topic"},{"w":"renovate","pos":"v","vi":"sửa để khôi phục tình trạng tốt, thường công trình","ex":"They {renovated} the house and refurbished the rooms.","grp":["refurbish","renovate"],"k":"topic"},{"w":"reinforce","pos":"v","vi":"gia cố/củng cố bằng bổ sung","ex":"Steel {reinforcement} strengthened the structure.","grp":["reinforce","strengthen"],"k":"topic"},{"w":"strengthen","pos":"v","vi":"làm mạnh hơn nói chung","ex":"Steel reinforcement {strengthened} the structure.","grp":["reinforce","strengthen"],"k":"topic"},{"w":"rusty","pos":"adj","vi":"gỉ hoặc lụt kĩ năng","ex":"My French is {rusty}, and these old exercises feel stale.","grp":["rusty","stale"],"k":"topic"},{"w":"stale","pos":"adj","vi":"không còn tươi/mới, cũ mòn","ex":"My French is rusty, and these old exercises feel {stale}.","grp":["rusty","stale"],"k":"topic"},{"w":"sound","pos":"v","vi":"vững, đáng tin, hợp lí","ex":"A {sound} plan helped streamline the process.","grp":["sound","streamline"],"k":"topic"},{"w":"streamline","pos":"v","vi":"tinh giản để hiệu quả hơn","ex":"A sound plan helped {streamline} the process.","grp":["sound","streamline"],"k":"topic"},{"w":"abstract","pos":"n phr","vi":"tranh/phong cách trừu tượng","ex":"The gallery specialises in {abstract} fine art.","grp":["abstract","fine art"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"fine art","pos":"n phr","vi":"mĩ thuật/nghệ thuật tạo hình","ex":"The gallery specialises in abstract {fine art}.","grp":["abstract","fine art"],"k":"topic"},{"w":"auction","pos":"n","vi":"cuộc đấu giá","ex":"The collector's item was sold at {auction}.","grp":["auction","collector's item"],"k":"topic"},{"w":"collector's item","pos":"n","vi":"vật có giá trị sưu tầm","ex":"The {collector's item} was sold at auction.","grp":["auction","collector's item"],"k":"topic"},{"w":"audition","pos":"n","vi":"buổi thử vai/tuyển diễn","ex":"She passed the {audition} and gave her first recital.","grp":["audition","recital"],"k":"topic"},{"w":"recital","pos":"n","vi":"buổi độc tấu/đơn ca/biểu diễn chuyên","ex":"She passed the audition and gave her first {recital}.","grp":["audition","recital"],"k":"topic"},{"w":"bestseller","pos":"n","vi":"sách bán chạy","ex":"The {bestseller} is now available as a paperback.","grp":["bestseller","paperback"],"k":"topic"},{"w":"paperback","pos":"n","vi":"sách bìa mềm","ex":"The bestseller is now available as a {paperback}.","grp":["bestseller","paperback"],"k":"topic"},{"w":"curator","pos":"n","vi":"người phụ trách bộ sưu tập/triển lãm","ex":"The {curator} organised a retrospective of the artist's work.","grp":["curator","retrospective"],"k":"topic"},{"w":"retrospective","pos":"n","vi":"triển lãm nhìn lại sự nghiệp/thuộc hồi cố","ex":"The curator organised a {retrospective} of the artist's work.","grp":["curator","retrospective"],"k":"topic"},{"w":"installation","pos":"n","vi":"tác phẩm sắp đặt","ex":"The {installation} is a remarkable work of art.","grp":["installation","work of art"],"k":"topic"},{"w":"work of art","pos":"n","vi":"tác phẩm nghệ thuật","ex":"The installation is a remarkable {work of art}.","grp":["installation","work of art"],"k":"topic"},{"w":"lines","pos":"n số nhiều","vi":"lời thoại","ex":"The actor learnt his {lines} while the singer revised the lyrics.","grp":["lines","lyrics"],"k":"topic"},{"w":"lyrics","pos":"n số nhiều","vi":"lời bài hát","ex":"The actor learnt his lines while the singer revised the {lyrics}.","grp":["lines","lyrics"],"k":"topic"},{"w":"masterpiece","pos":"n/adj","vi":"kiệt tác","ex":"The museum owns a priceless {masterpiece}.","grp":["masterpiece","priceless"],"k":"topic"},{"w":"priceless","pos":"n/adj","vi":"quý đến mức không thể định giá, cũng có thể rất buồn cười","ex":"The museum owns a {priceless} masterpiece.","grp":["masterpiece","priceless"],"k":"topic"},{"w":"period","pos":"n","vi":"thời kì/thuộc thời xưa","ex":"The {period} drama has an original orchestral score.","grp":["period","score"],"k":"topic"},{"w":"score","pos":"n","vi":"bản nhạc viết/nhạc cho phim","ex":"The period drama has an original orchestral {score}.","grp":["period","score"],"k":"topic"},{"w":"sketch","pos":"adj","vi":"phác họa/bản phác/thành tiểu phẩm","ex":"The damaged {sketch} was not worthless to the collector.","grp":["sketch","worthless"],"k":"topic"},{"w":"worthless","pos":"adj","vi":"vô giá trị","ex":"The damaged sketch was not {worthless} to the collector.","grp":["sketch","worthless"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"brighten up","vi":"sáng/màu sắc hơn; vui lên; trời hửng","ex":"Flowers brightened {up} the room.","k":"pv"},{"w":"brush up on","vi":"ôn, nâng lại kĩ năng","ex":"I brushed up {on} my drawing skills.","k":"pv"},{"w":"check out","vi":"kiểm tra tính đúng/tốt; thông tin được xác minh","ex":"Her account checked {out}.","k":"pv"},{"w":"liven up","vi":"làm/sống động, thú vị hơn","ex":"Music livened {up} the reception.","k":"pv"},{"w":"make over","vi":"thay đổi/cải thiện diện mạo; makeover (n)","ex":"They made the waiting room {over}.","k":"pv"},{"w":"mess up","vi":"làm sai; làm bừa bộn; gây vấn đề cho ai","ex":"I messed {up} the final paragraph.","k":"pv"},{"w":"paper over","vi":"che giấu vấn đề thay vì giải quyết","ex":"The agreement merely papered {over} the cracks.","k":"pv"},{"w":"patch up","vi":"vá/sửa tạm; làm hòa; sơ cứu","ex":"They patched {up} the damage and their friendship.","k":"pv"},{"w":"pick up","vi":"cải thiện","ex":"Sales have started to pick {up}.","k":"pv"},{"w":"run down","vi":"làm khu vực/tổ chức giảm hoạt động, xuống cấp; run-down (adj)","ex":"The neglected district became run-{down}.","k":"pv"},{"w":"scrape through","vi":"vượt qua vừa đủ, không nổi bật","ex":"He scraped {through} the test.","k":"pv"},{"w":"smarten up","vi":"làm sạch gọn, cải thiện diện mạo","ex":"A coat of paint smartened {up} the hall.","k":"pv"},{"w":"stand out","vi":"nổi bật về chất lượng hoặc dễ nhận thấy","ex":"Her performance stood {out}.","k":"pv"},{"w":"touch up","vi":"sửa nhỏ bề mặt cho đẹp","ex":"The artist touched {up} the portrait.","k":"pv"},{"w":"waste away","vi":"gầy yếu dần, thường do bệnh","ex":"The neglected animals wasted {away}.","k":"pv"},{"w":"write off","vi":"hỏng xe đến không đáng sửa; coi ai/thứ gì không có hi vọng; write-off (n)","ex":"Do not write the idea {off} too soon.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"art","vi":"đạt trình độ thuần thục; nghệ thuật; phong cách/trường phái/phòng tranh","ex":"She has organisation down to a fine {art}.","note":"have/get sth down to a fine art; art of V-ing; an art to V- ing; art deco/form/gallery/house","k":"col"},{"w":"bad","vi":"hỏng/xấu; áy náy; có hại/kém; tệ; không thiện chí; người gây hại; hiềm khích","ex":"The dispute created {bad} blood between the teams.","note":"go bad; go from bad to worse; feel bad about; bad for/at; in a bad way; in bad faith; bad apple; bad blood","k":"col"},{"w":"best","vi":"tận dụng tốt; cố hết sức; xét cho cùng là tốt; cùng lắm/lúc phong độ nhất; theo điều mình biết/khả năng tốt nhất; lợi cả đôi đường; bạn thân","ex":"To the {best} of my knowledge, the painting is genuine.","note":"make the best of; do your best; all for the best; at best/your best; to the best of my knowledge/ability; best of both worlds; best friend","k":"col"},{"w":"better","vi":"tốt lên; thắng/chế ngự; nên; tốt hơn nhờ; còn hơn không; chúc may lần sau; khá giả/tốt hơn; hay hơn nữa; dù tốt xấu; bạn đời","ex":"Do not let frustration get the {better} of you.","note":"get better; get the better of; had better; all the better for; better than nothing; better luck next time; better off/yet; for better or worse; better half","k":"col"},{"w":"bottom","vi":"cuối bảng; tìm gốc; thị trường sụp; cốt yếu","ex":"We must get to the {bottom} of the problem.","note":"come bottom; get to the bottom of; the bottom drops/falls out of; at the bottom of; from the bottom of my heart; bottom line","k":"col"},{"w":"clean","vi":"làm sạch; đoạn tuyệt/thú nhận; xác nhận tốt; khởi đầu mới; thắng toàn bộ","ex":"The inspection gave the building a {clean} bill of health.","note":"give a good clean; make a clean break/breast of; clean and tidy; clean bill of health; clean slate/sheet; clean sweep","k":"col"},{"w":"clear","vi":"rõ; lương tâm thanh thản; rất rõ/rất khó hiểu (mỉa mai)","ex":"Her instructions were {clear} as mud.","note":"make/get sth clear; make yourself clear; clear conscience/in your mind; clear as a bell/mud; clear case/evidence/indication","k":"col"},{"w":"dirty","vi":"phản bội; làm việc xấu/khó chịu thay; trực tiếp làm; nhìn khó chịu; mưu bẩn","ex":"They would not do the manager's {dirty} work.","note":"do the dirty on; do sb's dirty work; get your hands dirty; give a dirty look; dirty word/tricks","k":"col"},{"w":"fine","vi":"sát giờ; đồng ý; tiểu tiết; ranh giới mong manh; xem cực kĩ; chữ nhỏ điều khoản","ex":"Read the {fine} print carefully.","note":"cut it fine; fine by sb; fine details/points; a fine line between; with a fine-tooth(ed) comb; fine print","k":"col"},{"w":"fresh","vi":"mới từ; vừa hết; trẻ trung; nước ngọt; khởi đầu/không khí mới","ex":"She wanted a {fresh} start.","note":"fresh from; fresh out of; fresh-faced; freshwater; fresh start/air","k":"col"},{"w":"new","vi":"chưa quen; mới tinh; hoàn toàn mới; như mới; diện mạo mới; trường phái New Age","ex":"The repaired instrument is as good as {new}.","note":"new to; brand new; whole new; as good as new; new- look; new age","k":"col"},{"w":"nice","vi":"tử tế; dễ chịu; rất lịch thiệp; làm tốt lắm","ex":"She was as {nice} as pie to the visitors.","note":"nice of/for sb to V; nice to sb; nice to meet/see; nice and warm/clean; nice as pie; nice one","k":"col"},{"w":"old","vi":"già; đáng thương; tình cũ; người lớn tuổi; người lão luyện; lỗi thời; Cựu Ước","ex":"He is an {old} hand at organising exhibitions.","note":"get/grow old; poor old; old age/flame/folk/hand/hat; old people's home; the Old Testament","k":"col"},{"w":"quality","vi":"chất lượng; phẩm chất; kiểm soát; thời gian dành trọn sự quan tâm","ex":"{Quality} control caught the defect.","note":"high/good/top/poor/bad/low quality; personal/leadership qualities; quality control/of life/time","k":"col"},{"w":"style","vi":"tự xưng/tạo phong cách; hợp/lỗi mốt; có phong cách","ex":"The design never goes out of {style}.","note":"style sth/yourself as; style of; in/out of style; with style","k":"col"},{"w":"top","vi":"thắng cuộc; đè nặng làm quá tải; đầu/trên; nói ngay theo trí nhớ; cực vui; giải cao nhất/ưu tiên hàng đầu/tối mật","ex":"The workload was getting on {top} of her.","note":"come out on top; get on top of sb; at the top of; on top of; off the top of your head; on top of the world; top prize/priority/secret","k":"col"},{"w":"worse","vi":"xấu đi; làm tệ hơn; chuyển xấu; mệt/hư sau sử dụng","ex":"The old costume looked {worse} for wear.","note":"get worse; make matters/things worse; take a turn for the worse; worse for wear","k":"col"},{"w":"worst","vi":"làm điều tệ nhất; lo điều xấu nhất; tự hại mình; trường hợp xấu nhất","ex":"At {worst}, we will postpone the exhibition.","note":"do your worst; fear the worst; your own worst enemy; if the worst comes to the worst; at worst; the worst of both worlds","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"a sight for sore eyes","vi":"người/vật rất vui mừng được thấy","ex":"After the journey, the hotel was {a sight for sore eyes}.","k":"idiom"},{"w":"Achilles' heel","vi":"điểm yếu chí mạng","ex":"Poor planning is the project's {Achilles' heel}.","k":"idiom"},{"w":"add fuel to the fire","vi":"làm tình hình tệ hơn","ex":"His remark added {fuel to the fire}.","k":"idiom"},{"w":"below/under par","vi":"dưới mức thường/được mong đợi; không khỏe","ex":"Her performance was below par.","k":"idiom"},{"w":"clean as a whistle","vi":"cực sạch; hoàn toàn hợp pháp/trong sạch","ex":"The kitchen was {clean as a whistle}.","k":"idiom"},{"w":"draw the line at","vi":"đặt giới hạn điều không chấp nhận","ex":"I {draw the line at} misleading customers.","k":"idiom"},{"w":"the last word in","vi":"loại mới/tốt nhất trong lĩnh vực","ex":"The studio is {the last word in} comfort.","k":"idiom"},{"w":"out of this world","vi":"cực kì tốt/ấn tượng","ex":"The performance was {out of this world}.","k":"idiom"},{"w":"over the top","vi":"quá mức, không thích hợp","ex":"The decorations were rather {over the top}.","k":"idiom"},{"w":"pride of place","vi":"vị trí trung tâm/được trân trọng nhất","ex":"The trophy takes {pride of place}.","k":"idiom"},{"w":"steal the show","vi":"nổi bật nhất, thu hút mọi chú ý","ex":"The youngest performer stole {the show}.","k":"idiom"},{"w":"the edge over","vi":"lợi thế hơn","ex":"The design gives them {the edge over} competitors.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"adequate","vi":"đủ/phù hợp","note":"adequate → (in)adequacy, inadequate, (in)adequately","full":"đủ/phù hợp → sự đủ/thiếu; không đủ; trạng từ.","ex":"The room was {inadequately} lit.","hint":"adequate","k":"wf"},{"w":"admire","vi":"ngưỡng mộ","note":"admire → admiration, admirer, admirable, admirably, admiring(ly)","full":"ngưỡng mộ → sự/người ngưỡng mộ; đáng ngưỡng mộ; thái độ ngưỡng mộ.","ex":"She handled the criticism {admirably}.","hint":"admire","k":"wf"},{"w":"art","vi":"nghệ thuật","note":"art → arts, artfulness, artificiality, artist, artiste, artistry, artlessness, artwork, artifact/artefact, artifice, arty, artistic(ally), artificial(ly), artful(ly), artless(ly)","full":"nghệ thuật → sự khéo/tính nhân tạo; nghệ sĩ/người biểu diễn; tài nghệ; sự hồn nhiên; tác phẩm/cổ vật; mưu mẹo; có vẻ nghệ thuật; tinh ranh/hồn nhiên.","ex":"The artwork combines {artistry} with technical skill.","hint":"art","k":"wf"},{"w":"awe","vi":"kinh ngạc/kính sợ","note":"awe → awfulness, awesomeness, awestruck, awful(ly), awesome(ly)","full":"kinh ngạc/kính sợ → sự tồi tệ; tính đáng kinh ngạc; sững sờ; tệ/rất; tuyệt/đáng sợ.","ex":"We were {awestruck} by the building.","hint":"awe","k":"wf"},{"w":"class","vi":"lớp/loại","note":"class → outclass, (de)classify, classics, classifieds, classification, classlessness, classmate, classroom, classwork, classic, classy, classless, (de)classified, classical(ly)","full":"lớp/loại → vượt trội; phân loại/giải mật; kinh điển; quảng cáo rao vặt; có/không giai cấp; thanh lịch; cổ điển.","ex":"The documents were {declassified}.","hint":"class","k":"wf"},{"w":"collect","vi":"sưu tập","note":"collect → collector, collection, collectable, collected, collective(ly)","full":"sưu tập → người/bộ sưu tập; đáng sưu tầm; bình tĩnh/đã gom; tập thể.","ex":"The collection contains highly {collectable} pieces.","hint":"collect","k":"wf"},{"w":"destroy","vi":"phá","note":"destroy → destroyer, destruction, indestructible, destructive(ly)","full":"phá → vật/người phá; sự phá hủy; không thể phá; có tính phá.","ex":"The material is durable but not {indestructible}.","hint":"destroy","k":"wf"},{"w":"good","vi":"tốt","note":"good → goods, goodness, goodwill, goody/goodie","full":"tốt → hàng hóa; sự tốt; thiện chí; quà nhỏ/người tốt trong truyện.","ex":"The gesture created {goodwill}.","hint":"good","k":"wf"},{"w":"ideal","vi":"lí tưởng","note":"ideal → idealise, idealism, idealisation, idealist, idealistic, idealised, ideally","full":"lí tưởng → lí tưởng hóa; chủ nghĩa lí tưởng; người lí tưởng; theo lí tưởng; lí tưởng là.","ex":"The film presents an {idealised} village.","hint":"ideal","k":"wf"},{"w":"imitate","vi":"bắt chước","note":"imitate → imitation, imitator, imitative, inimitable","full":"bắt chước → bản/sự bắt chước; người bắt chước; có tính bắt chước; không ai bắt chước nổi.","ex":"Her {inimitable} style impressed us.","hint":"imitate","k":"wf"},{"w":"impress","vi":"gây ấn tượng","note":"impress → impression, (un)impressiveness, impressionism, impressionist, (un)impressed, impressionable, impressionistic, (un)impressive(ly)","full":"gây ấn tượng → ấn tượng; độ ấn tượng; trường phái/người ấn tượng; bị/không ấn tượng; dễ bị ảnh hưởng; có tính gợi ấn tượng.","ex":"Young audiences can be {impressionable}.","hint":"impress","k":"wf"},{"w":"improve","vi":"cải thiện","note":"improve → improvement, improvable, improved","full":"cải thiện → sự cải thiện; có thể cải thiện; đã cải thiện.","ex":"The new version is a clear {improvement}.","hint":"improve","k":"wf"},{"w":"match","vi":"ghép/diêm/trận","note":"match → matchmaker, matchmaking, matchstick, matchwood, matchbook, matchbox, matching, unmatched, matchless","full":"ghép/diêm/trận → người/việc mai mối; que/gỗ vụn/bao/hộp diêm; đồng bộ; chưa có ai sánh/không sánh nổi.","ex":"The collection is {unmatched} in this region.","hint":"match","k":"wf"},{"w":"perfect","vi":"hoàn hảo","note":"perfect → (im)perfection, perfectionist, perfectionism, perfectible, perfectly, imperfect(ly)","full":"hoàn hảo → sự hoàn hảo/thiếu sót; người/tính cầu toàn; cải tiến đến hoàn hảo được; hoàn toàn; chưa hoàn hảo.","ex":"{Perfectionism} can delay completion.","hint":"perfect","k":"wf"},{"w":"quality","vi":"chất lượng","note":"quality → qualitative(ly)","full":"chất lượng → định tính, về chất.","ex":"The study used {qualitative} analysis.","hint":"quality","k":"wf"},{"w":"strong","vi":"mạnh","note":"strong → strengthen, strength, stronghold, strongly","full":"mạnh → tăng sức; sức mạnh; thành trì; mạnh mẽ.","ex":"The repair strengthened the frame.","hint":"strong","k":"wf"},{"w":"terror","vi":"kinh sợ","note":"terror → terrorise, terrify, terrorist, terrorism, terrible, terrific, terrifying, terrified, terribly","full":"kinh sợ → khủng bố/làm khiếp; kẻ/chủ nghĩa khủng bố; tồi tệ; tuyệt vời/rất lớn; gây sợ; thấy sợ; rất/tệ.","ex":"The storm was {terrifying}, but the concert was terrific.","hint":"terror","k":"wf"},{"w":"use","vi":"dùng","note":"use → abuse, misuse, reuse, overuse, (ab)user, usefulness, usage, uselessness, (un)used, (un)usable, reusable, abused, abusive(ly), useful(ly), useless(ly)","full":"dùng → lạm/sai/tái/quá dùng; người dùng/lạm dụng; tính hữu dụng/cách dùng/vô dụng; dùng được/không; lăng mạ.","ex":"The packaging is {reusable}.","hint":"use","k":"wf"},{"w":"value","vi":"giá trị","note":"value → revalue, overvalue, evaluate, (re)valuation, evaluation, overvaluation, valuer, valuables, (in)valuable, valueless","full":"giá trị → định giá lại/quá cao/đánh giá; sự định giá; người định giá; đồ quý; có giá trị/vô cùng quý/vô giá trị.","ex":"An independent {valuer} evaluated the collection.","hint":"value","k":"wf"},{"w":"worth","vi":"đáng giá","note":"worth → worthlessness, worthy, worthless, worthwhile","full":"đáng giá → tính vô giá trị; xứng đáng; vô giá trị; đáng công.","ex":"The restoration was {worthwhile}.","hint":"worth","k":"wf"}]}]},{"g":3,"u":24,"title":"Relationships and People","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"adjacent","pos":"v","vi":"liền kề","ex":"The notice was attached to the wall {adjacent} to the door.","grp":["adjacent","attach"],"k":"topic"},{"w":"attach","pos":"v","vi":"gắn/đính kèm","ex":"The notice was {attached} to the wall adjacent to the door.","grp":["adjacent","attach"],"k":"topic"},{"w":"bond","pos":"adj","vi":"gắn kết/mối gắn bó","ex":"Their intimate friendship developed into a lasting {bond}.","grp":["bond","intimate"],"k":"topic"},{"w":"intimate","pos":"adj","vi":"thân mật, gần gũi sâu","ex":"Their {intimate} friendship developed into a lasting bond.","grp":["bond","intimate"],"k":"topic"},{"w":"coexist","pos":"v","vi":"cùng tồn tại","ex":"Different groups can {coexist} and cooperate.","grp":["coexist","cooperate"],"k":"topic"},{"w":"cooperate","pos":"v","vi":"hợp tác","ex":"Different groups can coexist and {cooperate}.","grp":["coexist","cooperate"],"k":"topic"},{"w":"coherent","pos":"adj","vi":"mạch lạc, kết nối hợp lí","ex":"Her explanation was {coherent} and consistent with the evidence.","grp":["coherent","consistent"],"k":"topic"},{"w":"consistent","pos":"adj","vi":"nhất quán/đều đặn","ex":"Her explanation was coherent and {consistent} with the evidence.","grp":["coherent","consistent"],"k":"topic"},{"w":"compatible","pos":"adj","vi":"tương thích, hòa hợp","ex":"Their contrasting personalities were surprisingly {compatible}.","grp":["compatible","contrasting"],"k":"topic"},{"w":"contrasting","pos":"adj","vi":"tương phản","ex":"Their {contrasting} personalities were surprisingly compatible.","grp":["compatible","contrasting"],"k":"topic"},{"w":"comprise","pos":"v","vi":"gồm có, chủ động thường không thêm of","ex":"The team {comprises} six people and involves several departments.","grp":["comprise","involve"],"k":"topic"},{"w":"involve","pos":"v","vi":"bao gồm/đòi hỏi/liên quan","ex":"The team comprises six people and {involves} several departments.","grp":["comprise","involve"],"k":"topic"},{"w":"compromise","pos":"v","vi":"thỏa hiệp/sự thỏa hiệp","ex":"They negotiated for hours before reaching a {compromise}.","grp":["compromise","negotiate"],"k":"topic"},{"w":"negotiate","pos":"v","vi":"thương lượng","ex":"They {negotiated} for hours before reaching a compromise.","grp":["compromise","negotiate"],"k":"topic"},{"w":"conflict","pos":"v/n","vi":"xung đột, mâu thuẫn","ex":"The dispute arose because their interests {conflicted}.","grp":["conflict","dispute"],"k":"topic"},{"w":"dispute","pos":"v/n","vi":"tranh chấp, phủ nhận tính đúng đắn","ex":"The {dispute} arose because their interests conflicted.","grp":["conflict","dispute"],"k":"topic"},{"w":"confront","pos":"v","vi":"đối mặt/chất vấn trực diện","ex":"She {confronted} the problem before a mediator intervened.","grp":["confront","intervene"],"k":"topic"},{"w":"intervene","pos":"v","vi":"can thiệp","ex":"She confronted the problem before a mediator {intervened}.","grp":["confront","intervene"],"k":"topic"},{"w":"contradict","pos":"v","vi":"mâu thuẫn/phản bác","ex":"Distinguish the two claims before saying they {contradict} each other.","grp":["contradict","distinguish"],"k":"topic"},{"w":"distinguish","pos":"v","vi":"phân biệt/nhận ra đặc điểm khác","ex":"{Distinguish} the two claims before saying they contradict each other.","grp":["contradict","distinguish"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"correspond","pos":"n/adj","vi":"tương ứng hoặc trao đổi thư","ex":"The figures {correspond} to roughly equivalent amounts.","grp":["correspond","equivalent"],"k":"topic"},{"w":"equivalent","pos":"n/adj","vi":"thứ tương đương/tương đương","ex":"The figures correspond to roughly {equivalent} amounts.","grp":["correspond","equivalent"],"k":"topic"},{"w":"diverse","pos":"v","vi":"đa dạng","ex":"The project integrates ideas from {diverse} communities.","grp":["diverse","integrate"],"k":"topic"},{"w":"integrate","pos":"v","vi":"hợp nhất/hòa nhập vào hệ thống","ex":"The project {integrates} ideas from diverse communities.","grp":["diverse","integrate"],"k":"topic"},{"w":"divorce","pos":"v","vi":"li hôn/tách rời","ex":"Do not {divorce} the policy from its context; merge the related proposals.","grp":["divorce","merge"],"k":"topic"},{"w":"merge","pos":"v","vi":"hợp nhất","ex":"Do not divorce the policy from its context; {merge} the related proposals.","grp":["divorce","merge"],"k":"topic"},{"w":"exclude","pos":"adj","vi":"loại trừ","ex":"Do not {exclude} a factor that is integral to the process.","grp":["exclude","integral"],"k":"topic"},{"w":"integral","pos":"adj","vi":"thiết yếu, là phần không thể thiếu","ex":"Do not exclude a factor that is {integral} to the process.","grp":["exclude","integral"],"k":"topic"},{"w":"external","pos":"adj","vi":"bên ngoài","ex":"{External} pressure intensified the internal disagreement.","grp":["external","internal"],"k":"topic"},{"w":"internal","pos":"adj","vi":"bên trong","ex":"External pressure intensified the {internal} disagreement.","grp":["external","internal"],"k":"topic"},{"w":"identify","pos":"v","vi":"nhận diện/xác định","ex":"They {identified} the pattern and likened it to a network.","grp":["identify","liken"],"k":"topic"},{"w":"liken","pos":"v","vi":"ví A như B","ex":"They identified the pattern and {likened} it to a network.","grp":["identify","liken"],"k":"topic"},{"w":"interfere","pos":"v/n","vi":"can thiệp gây phiền/cản trở","ex":"The fault {interfered} with the link between the devices.","grp":["interfere","link"],"k":"topic"},{"w":"link","pos":"v/n","vi":"liên kết/mối liên hệ","ex":"The fault interfered with the {link} between the devices.","grp":["interfere","link"],"k":"topic"},{"w":"intermediate","pos":"adj","vi":"ở giữa/trung cấp","ex":"The joint course offers {intermediate}- level training.","grp":["intermediate","joint"],"k":"topic"},{"w":"joint","pos":"adj","vi":"chung, cùng thực hiện","ex":"The {joint} course offers intermediate- level training.","grp":["intermediate","joint"],"k":"topic"},{"w":"mutual","pos":"adj","vi":"lẫn nhau/chung của các bên","ex":"Their related interests led to {mutual} respect.","grp":["mutual","related"],"k":"topic"},{"w":"related","pos":"adj","vi":"có liên hệ/họ hàng","ex":"Their {related} interests led to mutual respect.","grp":["mutual","related"],"k":"topic"},{"w":"relative","pos":"n","vi":"tương đối/so với","ex":"The resemblance is clear, but its importance is {relative}.","grp":["relative","resemblance"],"k":"topic"},{"w":"resemblance","pos":"n","vi":"sự giống nhau","ex":"The {resemblance} is clear, but its importance is relative.","grp":["relative","resemblance"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"acquaintance","pos":"n","vi":"người quen chưa thân","ex":"An {acquaintance} became her travelling companion.","grp":["acquaintance","companion"],"k":"topic"},{"w":"companion","pos":"n","vi":"người đồng hành/bầu bạn","ex":"An acquaintance became her travelling {companion}.","grp":["acquaintance","companion"],"k":"topic"},{"w":"adopt","pos":"v","vi":"nhận làm con nuôi/tiếp nhận","ex":"They fostered children before deciding to {adopt}.","grp":["adopt","foster"],"k":"topic"},{"w":"foster","pos":"v","vi":"nhận chăm sóc nuôi dưỡng, thường tạm thời, hoặc khuyến khích","ex":"They {fostered} children before deciding to adopt.","grp":["adopt","foster"],"k":"topic"},{"w":"ancestor","pos":"n","vi":"tổ tiên","ex":"The descendants preserved records of their {ancestors}.","grp":["ancestor","descendant"],"k":"topic"},{"w":"descendant","pos":"n","vi":"hậu duệ","ex":"The {descendants} preserved records of their ancestors.","grp":["ancestor","descendant"],"k":"topic"},{"w":"citizen","pos":"n","vi":"công dân","ex":"Young {citizens} discussed the issue with their peers.","grp":["citizen","peer"],"k":"topic"},{"w":"peer","pos":"n","vi":"người cùng tuổi/vị thế","ex":"Young citizens discussed the issue with their {peers}.","grp":["citizen","peer"],"k":"topic"},{"w":"dependant","pos":"n","vi":"người sống phụ thuộc","ex":"The guardian provides for two {dependants}.","grp":["dependant","guardian"],"k":"topic"},{"w":"guardian","pos":"n","vi":"người giám hộ/bảo hộ","ex":"The {guardian} provides for two dependants.","grp":["dependant","guardian"],"k":"topic"},{"w":"empathise","pos":"v","vi":"thấu cảm bằng hiểu trải nghiệm/cảm xúc","ex":"I sympathise with her and can {empathise} with her situation.","grp":["empathise","sympathise"],"k":"topic"},{"w":"sympathise","pos":"v","vi":"cảm thông, chia sẻ nỗi buồn hoặc đồng tình","ex":"I {sympathise} with her and can empathise with her situation.","grp":["empathise","sympathise"],"k":"topic"},{"w":"extrovert","pos":"n","vi":"người hướng ngoại","ex":"An {extrovert} may enjoy the event that tires an introvert.","grp":["extrovert","introvert"],"k":"topic"},{"w":"introvert","pos":"n","vi":"người hướng nội","ex":"An extrovert may enjoy the event that tires an {introvert}.","grp":["extrovert","introvert"],"k":"topic"},{"w":"partner","pos":"n","vi":"bạn đời/đối tác","ex":"Employees may invite their {partner} or spouse.","grp":["partner","spouse"],"k":"topic"},{"w":"spouse","pos":"n","vi":"vợ hoặc chồng, thường trang trọng","ex":"Employees may invite their partner or {spouse}.","grp":["partner","spouse"],"k":"topic"},{"w":"sibling","pos":"n","vi":"anh/chị/em ruột","ex":"Her {siblings} welcomed their new stepmother.","grp":["sibling","stepmother- stepfather-stepson- stepdaughter-stepbrother- stepsister"],"k":"topic"},{"w":"predecessor","pos":"n","vi":"người tiền nhiệm","ex":"The successor consulted her {predecessor}.","grp":["predecessor","successor"],"k":"topic"},{"w":"successor","pos":"n","vi":"người kế nhiệm","ex":"The {successor} consulted her predecessor.","grp":["predecessor","successor"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"answer back","vi":"cãi lại hỗn với người có thẩm quyền","ex":"The pupil was warned not to answer {back}.","k":"pv"},{"w":"ask out","vi":"mời đi hẹn hò","ex":"He asked her {out} for dinner.","k":"pv"},{"w":"break up","vi":"chấm dứt quan hệ; chia nhỏ; cuộc họp tan","ex":"The meeting broke {up} at six.","k":"pv"},{"w":"bring out","vi":"làm bộc lộ phẩm chất; ra mắt sản phẩm","ex":"The challenge brought {out} her best qualities.","k":"pv"},{"w":"bring together","vi":"kết nối để gặp và cùng làm việc","ex":"The event brought different communities {together}.","k":"pv"},{"w":"bump into","vi":"tình cờ gặp; va vào","ex":"I bumped {into} an old classmate.","k":"pv"},{"w":"cancel out","vi":"triệt tiêu tác dụng của nhau","ex":"The two effects cancel each other {out}.","k":"pv"},{"w":"come between","vi":"gây bất hòa giữa người với người","ex":"Do not let money come {between} you.","k":"pv"},{"w":"crowd around","vi":"tụ lại đông quanh","ex":"The visitors crowded {around} the display.","k":"pv"},{"w":"go together","vi":"thường đi cùng; kết hợp hài hòa","ex":"The two colours go {together} well.","k":"pv"},{"w":"meet up","vi":"gặp nhau, có hoặc không hẹn trước","ex":"We met {up} after the lecture.","k":"pv"},{"w":"open up","vi":"cởi mở nói cảm xúc; mở nơi đang khóa; tạo thuận lợi đi lại/kinh doanh","ex":"She gradually opened {up} about her worries.","k":"pv"},{"w":"pick on","vi":"liên tục đối xử bất công/bắt nạt","ex":"Nobody should pick {on} a quieter pupil.","k":"pv"},{"w":"sound out","vi":"thăm dò ý kiến/cảm nhận qua trò chuyện","ex":"We sounded the staff {out} about the plan.","k":"pv"},{"w":"take after","vi":"giống người thân lớn tuổi về dáng/tính","ex":"She takes {after} her grandfather.","k":"pv"},{"w":"take to","vi":"bắt đầu thích; hình thành thói quen","ex":"The children took {to} the new teacher.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"born","vi":"sinh để; sinh ngày/nơi/do/vào gia đình; sinh và lớn lên; tái sinh/tái cải đạo; mới sinh","ex":"She was {born} and bred in Hue.","note":"born to V; born on/in/of/into; born and bred; born-again; newborn","k":"col"},{"w":"child","vi":"thời nhỏ; con một; sản phẩm của thời kì; ngược đãi/chăm trẻ; rất dễ; trợ cấp nuôi con","ex":"The task is {child}'s play for an experienced editor.","note":"as a child; only child; a child of; child abuse/care; child's play; child support","k":"col"},{"w":"common","vi":"có chung; phổ biến; chung cho; ngôn ngữ chung; người thường; thông lệ","ex":"We have more in {common} than we expected.","note":"have sth in common with; common for sb to V; common to; common language; common people; common practice","k":"col"},{"w":"equal","vi":"bằng nhau; tương đương; quyền bình đẳng","ex":"All participants have {equal} rights.","note":"of equal size/quality/value; equal in size/quality/value; equal to; roughly equal; equal rights","k":"col"},{"w":"family","vi":"có/lập gia đình; gia đình hạt nhân/mở rộng/đơn thân; gia đình gồm; trong gia đình; như người nhà; gia phả/họ/các giá trị gia đình","ex":"The project records each {family}'s history and family tree.","note":"have/start a family; nuclear/extended/single-parent family; a family of; in the family; one of the family; family tree/name/values","k":"col"},{"w":"feature","vi":"giới thiệu; đặc điểm; nét phân biệt/an toàn; phim dài/người viết chuyên đề","ex":"The design includes several safety {features}.","note":"feature sb/sth in; a feature of; distinguishing/safety features; feature film/writer","k":"col"},{"w":"friend","vi":"kết bạn; bạn thân/tốt/lâu năm; bạn của gia đình; nhóm bạn; có quan hệ bạn bè","ex":"She quickly made {friends} with her new classmates.","note":"make friends with; close/good/great/old friend; friend of the family/family friend; circle of friends; be friends with","k":"col"},{"w":"generation","vi":"thế hệ; khoảng cách thế hệ","ex":"The survey compared the older and younger {generations}.","note":"older/younger generation; generation gap; Generation X; future generations","k":"col"},{"w":"human","vi":"hành vi; con người; lỗi do người; bản tính; nhân loại; nhân quyền","ex":"The delay resulted from {human} error.","note":"human behaviour/being/error/nature/race/rights","k":"col"},{"w":"love","vi":"yêu thích làm; gửi lời yêu thương; phải lòng; tình yêu dành cho; tình yêu thật/sét đánh; chuyện tình; người thân yêu","ex":"She sent her {love} to everyone at home.","note":"love to V/V-ing; give/send your love to; fall/be in love with; love for; true love; love at first sight; love affair; loved ones","k":"col"},{"w":"marriage","vi":"có họ qua hôn nhân; tư vấn/lời thề; hôn nhân vì lợi ích","ex":"They are related by {marriage}.","note":"related by marriage; marriage guidance/vows; marriage of convenience","k":"col"},{"w":"mother","vi":"mẹ; nước gốc; mẹ chồng/vợ; quê hương; tạo hóa; mẹ tương lai; tiếng mẹ đẻ","ex":"Vietnamese is her {mother} tongue.","note":"mother of; mother country/in-law/land; Mother Nature; Mother's Day; mother-to-be; mother tongue","k":"col"},{"w":"national","vi":"lợi ích quốc gia; quốc ca; quốc phục; nợ công; ngày lễ","ex":"The museum displays {national} costumes.","note":"in the national interest; national anthem/costume/dress/debt/holiday","k":"col"},{"w":"native","vi":"theo lối bản địa; bản địa ở; người gốc; người bản ngữ; quê/loài bản địa","ex":"The plant is {native} to this region.","note":"go native; native to; a native of; native/non-native speaker; native land/species","k":"col"},{"w":"near","vi":"gần làm; tương lai gần; khắp nơi; suýt thất bại; gần nhất với; người thân yêu","ex":"Visitors came from {near} and far.","note":"near to V-ing; near future; from near and far; a near thing; nearest thing to; nearest and dearest","k":"col"},{"w":"person","vi":"trực tiếp, đích thân","ex":"She thanked the volunteers in {person}.","note":"do sth/meet sb in person","k":"col"},{"w":"relative","vi":"tương đối; so với; họ gần/xa; mệnh đề/đại từ quan hệ","ex":"The increase is small {relative} to the total.","note":"it is all relative; relative to; close/near/distant relative; a relative of yours; relative clause/pronoun","k":"col"},{"w":"respect","vi":"kính trọng vì/với tư cách; có/mất/đáng được sự kính trọng; đối xử tôn trọng; liên quan đến; ở phương diện này/kia","ex":"With {respect} to attendance, the rules are unchanged.","note":"respect sb for/as; gain/lose/command/deserve/earn/win respect; treat with respect; with respect to; in this/that respect","k":"col"},{"w":"support","vi":"ủng hộ; hỗ trợ tiền; cổ vũ; để ủng hộ","ex":"Residents spoke in {support} of the project.","note":"support V-ing; support sb financially; support an idea/team; offer support; in support of","k":"col"},{"w":"wedding","vi":"kỉ niệm cưới; bánh/lễ/váy/thiệp/nhẫn/quà cưới","ex":"They celebrated their {wedding} anniversary.","note":"wedding anniversary/cake/ceremony/dress/invitation/ring/present","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"be born with a silver spoon in your mouth","vi":"sinh ra trong gia đình giàu, sẵn lợi thế","ex":"He was not born with a silver spoon in his {mouth}.","k":"idiom"},{"w":"be on the same wavelength","vi":"hiểu nhau vì có cách nghĩ giống","ex":"The two designers are {on the same wavelength}.","k":"idiom"},{"w":"get on like a house on fire","vi":"nhanh chóng rất hợp và thân nhau","ex":"The new colleagues got {on like a house on fire}.","k":"idiom"},{"w":"in sb's good/bad books","vi":"được ai hài lòng/bị ai giận","ex":"I was in her bad {books} after being late.","k":"idiom"},{"w":"like two peas in a pod","vi":"giống nhau như đúc","ex":"The siblings are {like two peas in a pod}.","k":"idiom"},{"w":"on good terms with","vi":"có quan hệ tốt với","ex":"She is {on good terms with} her former manager.","k":"idiom"},{"w":"put sth in perspective","vi":"đặt vào tương quan để đánh giá đúng","ex":"The comparison puts the problem in {perspective}.","k":"idiom"},{"w":"sb is only human","vi":"ai cũng có điểm yếu/sai sót đáng thông cảm","ex":"Do not expect perfection; she {is only human}.","k":"idiom"},{"w":"see eye to eye with","vi":"đồng quan điểm với","ex":"We do not always see eye to eye.","k":"idiom"},{"w":"your flesh and blood","vi":"người thân ruột thịt","ex":"He would never abandon his own {flesh and blood}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ 1/2 (Word formation)","words":[{"w":"appear","vi":"xuất hiện","note":"appear → disappear, reappear, (dis/re)appearance, apparition, apparent(ly)","full":"xuất hiện → biến/tái xuất; sự xuất hiện; bóng ma; rõ ràng/bề ngoài; dường như.","ex":"The {apparent} similarity was misleading.","hint":"appear","k":"wf"},{"w":"appreciate","vi":"trân trọng/nhận rõ","note":"appreciate → appreciation, appreciable, appreciably, (un)appreciative(ly)","full":"trân trọng/nhận rõ → sự cảm kích; đáng kể; đáng kể; biết/không biết ơn.","ex":"There was an {appreciable} improvement.","hint":"appreciate","k":"wf"},{"w":"associate","vi":"liên hệ","note":"associate → dissociate, association, associate, associated","full":"liên hệ → tách khỏi; hiệp hội/liên kết; cộng sự; có liên quan.","ex":"She dissociated herself from the claim.","hint":"associate","k":"wf"},{"w":"attach","vi":"gắn","note":"attach → reattach, attachment, (un)attached","full":"gắn → gắn lại; sự gắn bó/tệp đính kèm; gắn/không gắn.","ex":"Please read the {attachment}.","hint":"attach","k":"wf"},{"w":"character","vi":"tính cách","note":"character → characterise, characterisation, (un)characteristic, characterless","full":"tính cách → tiêu biểu hóa/miêu tả; sự miêu tả; điển hình/không; thiếu nét riêng.","ex":"The remark was {uncharacteristic} of him.","hint":"character","k":"wf"},{"w":"connect","vi":"nối","note":"connect → disconnect, reconnect, interconnect, (dis/re)connection, (inter)connecting, (un/dis/inter)connected, connector","full":"nối → ngắt/nối lại/nối lẫn; kết nối/ngắt; nối/có liên thông; bộ nối.","ex":"The systems are interconnected.","hint":"connect","k":"wf"},{"w":"familiar","vi":"quen","note":"familiar → familiarise, (un)familiarity, unfamiliar, familiarly","full":"quen → làm quen; sự quen/không quen; lạ; thân mật.","ex":"{Familiarise} yourself with the procedure.","hint":"familiar","k":"wf"},{"w":"human","vi":"người","note":"human → humanise, humanity, humanism, humanist, humanities, humanitarian, humane, humanly","full":"người → làm nhân văn; nhân loại/lòng nhân ái; nhân văn chủ nghĩa; nhân văn học; nhân đạo; trong khả năng con người.","ex":"We did everything {humanly} possible.","hint":"human","k":"wf"},{"w":"individual","vi":"cá nhân","note":"individual → individualise, individualisation, individuality, individualist, individually","full":"cá nhân → cá thể hóa; sự cá thể hóa; cá tính; người đề cao cá nhân; riêng từng người.","ex":"The programme respects {individuality}.","hint":"individual","k":"wf"},{"w":"inherit","vi":"thừa hưởng","note":"inherit → inheritance, heritage, heredity, hereditary","full":"thừa hưởng → tài sản thừa kế; di sản; tính di truyền; di truyền.","ex":"Language is part of cultural {heritage}.","hint":"inherit","k":"wf"},{"w":"intimate","vi":"thân mật","note":"intimate → intimacy, intimately","full":"thân mật → sự gần gũi; mật thiết.","ex":"The two issues are {intimately} connected.","hint":"intimate","k":"wf"}]},{"type":"v","title":"Cấu tạo từ 2/2 (Word formation)","words":[{"w":"loyal","vi":"trung thành","note":"loyal → (dis)loyalty, disloyal, (dis)loyally","full":"trung thành → sự trung/phản; không trung thành; trạng từ.","ex":"Her {loyalty} was never in doubt.","hint":"loyal","k":"wf"},{"w":"observe","vi":"quan sát/tuân","note":"observe → observation, observance, observer, observatory, observable, observant, observably","full":"quan sát/tuân → sự quan sát; sự tuân thủ; người quan sát; đài thiên văn; quan sát được; tinh ý.","ex":"An {observant} reader noticed the discrepancy.","hint":"observe","k":"wf"},{"w":"parent","vi":"cha mẹ","note":"parent → parenting, parentage, parenthood, parental(ly)","full":"cha mẹ → việc nuôi dạy; nguồn gốc cha mẹ; vai trò làm cha mẹ; thuộc cha mẹ.","ex":"The course offers advice on {parenting}.","hint":"parent","k":"wf"},{"w":"perceive","vi":"nhận thấy","note":"perceive → perception, perceptiveness, (im)perceptible, (im)perceptibly, perceptive(ly)","full":"nhận thấy → nhận thức; sự tinh ý; nhận thấy được/không; sâu sắc.","ex":"The change was barely {perceptible}.","hint":"perceive","k":"wf"},{"w":"person","vi":"người","note":"person → personalise, impersonate, personality, personnel, interpersonal, personalised, (im)personal(ly)","full":"người → cá nhân hóa; giả giọng/đóng giả; tính cách; nhân sự; giữa người; mang/không tính cá nhân.","ex":"The job requires {interpersonal} skills.","hint":"person","k":"wf"},{"w":"race","vi":"chủng tộc/cuộc đua","note":"race → racism, racist, interracial, racial(ly)","full":"chủng tộc/cuộc đua → phân biệt chủng tộc; người/tính phân biệt; giữa các chủng tộc.","ex":"The policy addresses {racial} discrimination.","hint":"race","k":"wf"},{"w":"relate","vi":"liên hệ","note":"relate → relation, relationship, (un)related, relative(ly)","full":"liên hệ → quan hệ/người họ; mối quan hệ; có/không liên quan; tương đối/khá.","ex":"The two events are {unrelated}.","hint":"relate","k":"wf"},{"w":"self","vi":"bản thân","note":"self → (un)selfishness, selflessness, (un)selfish(ly), selfless(ly)","full":"bản thân → ích kỉ/không ích kỉ; vị tha; ích kỉ/không; quên mình.","ex":"Her {selfless} work earned respect.","hint":"self","k":"wf"},{"w":"separate","vi":"tách","note":"separate → separation, (in)separable, separated, separately","full":"tách → sự chia; tách được/không; đã tách/li thân; riêng rẽ.","ex":"The friends seemed {inseparable}.","hint":"separate","k":"wf"},{"w":"sympathy","vi":"cảm thông","note":"sympathy → sympathise, sympathiser, (un)sympathetic, (un)sympathetically","full":"cảm thông → cảm thông; người đồng tình; có/không cảm thông.","ex":"The adviser listened {sympathetically}.","hint":"sympathy","k":"wf"},{"w":"young","vi":"trẻ","note":"young → youngster, youth, youthful","full":"trẻ → người trẻ; tuổi trẻ/thanh niên; trẻ trung.","ex":"She retains a {youthful} enthusiasm.","hint":"young","k":"wf"}]}]},{"g":3,"u":26,"title":"Preference and Leisure Activities","vi":"","lessons":[{"type":"v","title":"Từ vựng chủ đề 1/3 (Topic vocabulary)","words":[{"w":"addiction","pos":"adj","vi":"sự nghiện/lệ thuộc","ex":"His {addiction} to gaming left him obsessed with scores.","grp":["addiction","obsessed"],"k":"topic"},{"w":"obsessed","pos":"adj","vi":"bị ám ảnh, chỉ nghĩ đến","ex":"His addiction to gaming left him {obsessed} with scores.","grp":["addiction","obsessed"],"k":"topic"},{"w":"adore","pos":"v","vi":"yêu thích mãnh liệt","ex":"She {adores} music and fancies learning the cello.","grp":["adore","fancy"],"k":"topic"},{"w":"fancy","pos":"v","vi":"thích/muốn, thường thân mật","ex":"She adores music and {fancies} learning the cello.","grp":["adore","fancy"],"k":"topic"},{"w":"anticipation","pos":"n","vi":"sự mong đợi","ex":"{Anticipation} of the holiday intensified his craving for adventure.","grp":["anticipation","craving"],"k":"topic"},{"w":"craving","pos":"n","vi":"thèm muốn mãnh liệt","ex":"Anticipation of the holiday intensified his {craving} for adventure.","grp":["anticipation","craving"],"k":"topic"},{"w":"appeal","pos":"n","vi":"hấp dẫn/sức hấp dẫn","ex":"The place {appeals} to anyone with a fascination for history.","grp":["appeal","fascination"],"k":"topic"},{"w":"fascination","pos":"n","vi":"sự say mê bị cuốn hút","ex":"The place appeals to anyone with a {fascination} for history.","grp":["appeal","fascination"],"k":"topic"},{"w":"arbitrary","pos":"v","vi":"tùy tiện, thiếu nguyên tắc rõ","ex":"Use clear criteria to differentiate options, not {arbitrary} preferences.","grp":["arbitrary","differentiate"],"k":"topic"},{"w":"differentiate","pos":"v","vi":"phân biệt, làm khác biệt","ex":"Use clear criteria to {differentiate} options, not arbitrary preferences.","grp":["arbitrary","differentiate"],"k":"topic"},{"w":"aspiration","pos":"v","vi":"khát vọng","ex":"She strives to fulfil her {aspirations}.","grp":["aspiration","strive"],"k":"topic"},{"w":"strive","pos":"v","vi":"nỗ lực hết sức","ex":"She {strives} to fulfil her aspirations.","grp":["aspiration","strive"],"k":"topic"},{"w":"bear","pos":"v","vi":"chịu đựng","ex":"He could not {bear} to sacrifice his free time.","grp":["bear","sacrifice"],"k":"topic"},{"w":"sacrifice","pos":"v","vi":"hi sinh/sự hi sinh","ex":"He could not bear to {sacrifice} his free time.","grp":["bear","sacrifice"],"k":"topic"},{"w":"compulsory","pos":"adj","vi":"bắt buộc","ex":"The lecture is {compulsory}, but the outing is optional.","grp":["compulsory","optional"],"k":"topic"},{"w":"optional","pos":"adj","vi":"tùy chọn","ex":"The lecture is compulsory, but the outing is {optional}.","grp":["compulsory","optional"],"k":"topic"},{"w":"content","pos":"adj","vi":"hài lòng","ex":"She was not {content} with a mediocre result.","grp":["content","mediocre"],"k":"topic"},{"w":"mediocre","pos":"adj","vi":"tầm thường, không tốt","ex":"She was not content with a {mediocre} result.","grp":["content","mediocre"],"k":"topic"},{"w":"decline","pos":"v","vi":"từ chối hoặc giảm","ex":"She {declined} the first offer and favoured the second.","grp":["decline","favour"],"k":"topic"},{"w":"favour","pos":"v","vi":"thiên về/ủng hộ, ân huệ","ex":"She declined the first offer and {favoured} the second.","grp":["decline","favour"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 2/3 (Topic vocabulary)","words":[{"w":"dedicated","pos":"v","vi":"tận tâm/dành riêng","ex":"{Dedicated} volunteers devote hours to the project.","grp":["dedicated","devote"],"k":"topic"},{"w":"devote","pos":"v","vi":"dành thời gian/công sức cho","ex":"Dedicated volunteers {devote} hours to the project.","grp":["dedicated","devote"],"k":"topic"},{"w":"delight","pos":"n","vi":"làm vui sướng","ex":"The concert {delighted} her and deepened her liking for jazz.","grp":["delight","liking"],"k":"topic"},{"w":"liking","pos":"n","vi":"sự ưa thích","ex":"The concert delighted her and deepened her {liking} for jazz.","grp":["delight","liking"],"k":"topic"},{"w":"desire","pos":"v","vi":"mong muốn/ước muốn","ex":"He {desired} change and yearned for a quieter life.","grp":["desire","yearn"],"k":"topic"},{"w":"yearn","pos":"v","vi":"khao khát sâu, thường điều khó có","ex":"He desired change and {yearned} for a quieter life.","grp":["desire","yearn"],"k":"topic"},{"w":"envy","pos":"adj","vi":"ghen tị/sự ghen tị","ex":"{Envy} can make an otherwise generous person greedy.","grp":["envy","greedy"],"k":"topic"},{"w":"greedy","pos":"adj","vi":"tham lam/tham ăn","ex":"Envy can make an otherwise generous person {greedy}.","grp":["envy","greedy"],"k":"topic"},{"w":"impulse","pos":"n","vi":"thôi thúc nhất thời","ex":"An {impulse} prompted the purchase, but her deeper motive was unclear.","grp":["impulse","motive"],"k":"topic"},{"w":"motive","pos":"n","vi":"động cơ, lí do hành động","ex":"An impulse prompted the purchase, but her deeper {motive} was unclear.","grp":["impulse","motive"],"k":"topic"},{"w":"inclined","pos":"adj","vi":"có xu hướng/muốn","ex":"I am {inclined} to accept the tempting offer.","grp":["inclined","tempting"],"k":"topic"},{"w":"tempting","pos":"adj","vi":"hấp dẫn khiến muốn làm","ex":"I am inclined to accept the {tempting} offer.","grp":["inclined","tempting"],"k":"topic"},{"w":"mundane","pos":"adj","vi":"thường nhật, tẻ nhạt","ex":"Even {mundane} tasks can be worthwhile.","grp":["mundane","worthwhile"],"k":"topic"},{"w":"worthwhile","pos":"adj","vi":"đáng thời gian/công sức","ex":"Even mundane tasks can be {worthwhile}.","grp":["mundane","worthwhile"],"k":"topic"},{"w":"passion","pos":"n","vi":"đam mê mãnh liệt","ex":"Her taste for classical music became a lifelong {passion}.","grp":["passion","taste"],"k":"topic"},{"w":"taste","pos":"n","vi":"sở thích/gu/vị giác","ex":"Her {taste} for classical music became a lifelong passion.","grp":["passion","taste"],"k":"topic"},{"w":"praise","pos":"v/adj","vi":"khen/lời khen","ex":"We welcomed the proposal and {praised} its clarity.","grp":["praise","welcome"],"k":"topic"},{"w":"welcome","pos":"v/adj","vi":"hoan nghênh/được đón nhận","ex":"We {welcomed} the proposal and praised its clarity.","grp":["praise","welcome"],"k":"topic"},{"w":"absorbing","pos":"adj","vi":"cuốn hút hoàn toàn","ex":"One person finds the puzzle {absorbing}; another finds it tedious.","grp":["absorbing","tedious"],"k":"topic"},{"w":"tedious","pos":"adj","vi":"tẻ nhạt, kéo dài khó chịu","ex":"One person finds the puzzle absorbing; another finds it {tedious}.","grp":["absorbing","tedious"],"k":"topic"}]},{"type":"v","title":"Từ vựng chủ đề 3/3 (Topic vocabulary)","words":[{"w":"casual","pos":"n","vi":"thư giãn/không chính thức/không đều","ex":"His {casual} approach reflects a relaxed lifestyle.","grp":["casual","lifestyle"],"k":"topic"},{"w":"lifestyle","pos":"n","vi":"lối sống","ex":"His casual approach reflects a relaxed {lifestyle}.","grp":["casual","lifestyle"],"k":"topic"},{"w":"exhilarating","pos":"n","vi":"làm phấn chấn mạnh","ex":"The {exhilarating} climb was followed by fatigue.","grp":["exhilarating","fatigue"],"k":"topic"},{"w":"fatigue","pos":"n","vi":"sự mệt mỏi","ex":"The exhilarating climb was followed by {fatigue}.","grp":["exhilarating","fatigue"],"k":"topic"},{"w":"idle","pos":"adj","vi":"không làm gì/nhàn rỗi","ex":"An {idle} afternoon is different from a sedentary lifestyle.","grp":["idle","sedentary"],"k":"topic"},{"w":"sedentary","pos":"adj","vi":"ngồi nhiều, ít vận động","ex":"An idle afternoon is different from a {sedentary} lifestyle.","grp":["idle","sedentary"],"k":"topic"},{"w":"indulge","pos":"v","vi":"chiều thích thú/ham muốn","ex":"She {indulges} her creativity by pursuing photography.","grp":["indulge","pursue"],"k":"topic"},{"w":"pursue","pos":"v","vi":"theo đuổi hoạt động/mục tiêu","ex":"She indulges her creativity by {pursuing} photography.","grp":["indulge","pursue"],"k":"topic"},{"w":"leave","pos":"n","vi":"thời gian nghỉ được phép","ex":"A week of {leave} provided a welcome respite.","grp":["leave","respite"],"k":"topic"},{"w":"respite","pos":"n","vi":"thời gian tạm thoát khó khăn/căng thẳng","ex":"A week of leave provided a welcome {respite}.","grp":["leave","respite"],"k":"topic"},{"w":"outing","pos":"n","vi":"chuyến đi chơi ngắn của nhóm","ex":"They chose a riverside venue for the {outing}.","grp":["outing","venue"],"k":"topic"},{"w":"venue","pos":"n","vi":"địa điểm tổ chức","ex":"They chose a riverside {venue} for the outing.","grp":["outing","venue"],"k":"topic"},{"w":"pastime","pos":"n","vi":"thú tiêu khiển","ex":"Gardening is her favourite {pastime} and form of recreation.","grp":["pastime","recreation"],"k":"topic"},{"w":"recreation","pos":"n","vi":"hoạt động thư giãn nói chung","ex":"Gardening is her favourite pastime and form of {recreation}.","grp":["pastime","recreation"],"k":"topic"},{"w":"socialise","pos":"n","vi":"giao lưu xã hội","ex":"He enjoys {socialising} but also values solitude.","grp":["socialise","solitude"],"k":"topic"},{"w":"solitude","pos":"n","vi":"trạng thái ở một mình","ex":"He enjoys socialising but also values {solitude}.","grp":["socialise","solitude"],"k":"topic"},{"w":"trivial","pos":"v","vi":"vụn vặt, ít quan trọng","ex":"Unwind without worrying about {trivial} problems.","grp":["trivial","unwind"],"k":"topic"},{"w":"unwind","pos":"v","vi":"thư giãn sau căng thẳng","ex":"{Unwind} without worrying about trivial problems.","grp":["trivial","unwind"],"k":"topic"}]},{"type":"v","title":"Cụm động từ (Phrasal verbs)","words":[{"w":"centre around","vi":"xoay quanh một chủ đề/trọng tâm","ex":"The course centres {around} practical projects.","k":"pv"},{"w":"get into","vi":"bắt đầu say mê; đến nơi; vướng tình huống xấu","ex":"She got {into} photography last year.","k":"pv"},{"w":"go in for","vi":"thích/tham gia; chọn môn học/nghề","ex":"He does not go in {for} competitive sports.","k":"pv"},{"w":"go off","vi":"hết thích; nổ; rời đi; thức ăn ôi","ex":"I have gone {off} that programme.","k":"pv"},{"w":"grow on","vi":"dần được ai thích hơn","ex":"The music grew {on} me.","k":"pv"},{"w":"hang out","vi":"dành thời gian ở nơi/với ai; thò người ra ngoài","ex":"We hang {out} at the local café.","k":"pv"},{"w":"keep up","vi":"tiếp tục; theo kịp tốc độ","ex":"Keep {up} the good work.","k":"pv"},{"w":"laze around","vi":"nghỉ ngơi nhàn nhã, không làm việc","ex":"They lazed {around} all Sunday.","k":"pv"},{"w":"mess about/around","vi":"làm linh tinh cho vui; nghịch","ex":"Stop messing {around} with the equipment.","k":"pv"},{"w":"pick up","vi":"học được tự nhiên; đón bằng xe","ex":"She picked {up} the skill from friends.","k":"pv"},{"w":"put in","vi":"bỏ thời gian/công sức; input (n)","ex":"He put {in} hours of practice.","k":"pv"},{"w":"seek out","vi":"chủ động tìm cho được","ex":"We sought {out} a quiet place to read.","k":"pv"},{"w":"take in","vi":"bao gồm/ghé trong lịch trình","ex":"The tour takes {in} three galleries.","k":"pv"},{"w":"take off","vi":"nghỉ một khoảng khỏi công việc; thành công nhanh; take-off (n)","ex":"She took a week {off} to rest.","k":"pv"},{"w":"take out","vi":"đưa ai đi chơi/ăn, thường mình trả","ex":"He took his parents {out} for dinner.","k":"pv"},{"w":"warm up","vi":"khởi động trước hoạt động; warm-up (n)","ex":"The players warmed {up} before the match.","k":"pv"}]},{"type":"v","title":"Cụm từ & collocations (Collocations)","words":[{"w":"choice","vi":"lựa chọn, quyền chọn, lựa chọn có thông tin","ex":"The guide helps visitors make an informed {choice}.","note":"make/exercise a choice; have no choice; choice between/of; personal/parental/consumer/informed/obvious choice; a wide choice","k":"col"},{"w":"choose","vi":"chọn từ/giữa/làm; kén chọn; ít/không khác","ex":"There is little to {choose} between the two designs.","note":"choose from/between; choose A as/out of; choose to V; pick and choose; little/nothing to choose between","k":"col"},{"w":"decide","vi":"quyết định làm/phản đối/ủng hộ/chọn","ex":"We {decided} against travelling at night.","note":"decide to V; decide against/in favour of; decide that/between/for yourself/on","k":"col"},{"w":"delight","vi":"vui thích; làm ai vui","ex":"To our {delight}, the venue was available.","note":"delight in V-ing; take great delight in V-ing; to sb's delight; with/in delight","k":"col"},{"w":"eager","vi":"háo hức, rất sẵn lòng","ex":"The volunteers were only too {eager} to help.","note":"eager to V; eager for; only too eager to V","k":"col"},{"w":"free","vi":"trả tự do; thoát; được tự do; thoải mái; thời gian rảnh","ex":"Use your {free} time as you wish.","note":"set/let sb go free; free sb from; walk free; free to V/from; free and easy; free time","k":"col"},{"w":"impulse","vi":"làm bốc đồng; kiềm thôi thúc","ex":"I bought the ticket on {impulse}.","note":"act/do sth on impulse; control/resist an impulse; an impulse to V","k":"col"},{"w":"keen","vi":"muốn; thích; quan tâm sâu","ex":"She has a {keen} interest in theatre.","note":"keen for sb to V; keen to V/on; a keen interest in","k":"col"},{"w":"leisure","vi":"có thời gian rảnh; lúc thuận tiện; trung tâm/hoạt động/thời gian giải trí","ex":"Read the information at your {leisure}.","note":"have the leisure to V; at your leisure; leisure centre/pursuits/time","k":"col"},{"w":"like","vi":"thích; giống; khác hẳn; không đúng tính; rất; thế này; khoảng","ex":"It is not {like} her to arrive late.","note":"like sb to V/V-ing; like it when; just like; anything/nothing like; not like sb to V; like crazy/mad; like so; something like","k":"col"},{"w":"need","vi":"cần; cần được làm; đáp ứng; không cần; đang cần","ex":"The room {needs} cleaning before the event.","note":"need sb to V; modal need + V; need V-ing; meet a need; have no need of; in need of","k":"col"},{"w":"off","vi":"được/nghỉ; không đi làm/học; nghỉ ốm","ex":"She was given time {off} after the project.","note":"have/take/be given a day off/time off; off work/college; off sick","k":"col"},{"w":"opt","vi":"lựa chọn","ex":"We {opted} for a smaller venue.","note":"opt for; opt to V","k":"col"},{"w":"option","vi":"không còn cách; cân nhắc; giữ khả năng chọn","ex":"We kept our {options} open.","note":"have no option but to V; consider your options; option of V-ing/to V; keep/leave options open","k":"col"},{"w":"play","vi":"thi đấu; chơi; trì hoãn để chờ; làm trò; ứng biến","ex":"We will {play} it by ear if the weather changes.","note":"play against/for/at/by yourself; play for time; play the fool; play by ear; at play","k":"col"},{"w":"praise","vi":"khen; đáng/nhận lời khen; hết lời khen","ex":"The performers earned {praise} for their energy.","note":"praise sb for V-ing; win/earn/deserve praise; full of praise for; in praise of","k":"col"},{"w":"prefer","vi":"thích hơn; muốn ai làm; muốn rằng/nếu","ex":"I would {prefer} it if we started earlier.","note":"prefer A to B; prefer sb to V; prefer V-ing; would prefer that; would prefer it if","k":"col"},{"w":"rest","vi":"tựa; cứ yên tâm; nghỉ; dừng lại/yên","ex":"{Rest} assured that everything is arranged.","note":"rest sth on/against; rest assured that; take/have a rest from; get some rest; come to rest; at rest","k":"col"},{"w":"taste","vi":"dần thích; phù hợp/kém duyên; vị giác; thứ cần quen mới thích","ex":"The music is an acquired {taste}.","note":"develop/have a taste for; in good/bad taste; sense of taste; acquired taste","k":"col"},{"w":"want","vi":"muốn; muốn việc được làm; vì thiếu","ex":"The project failed for {want} of funding.","note":"want sb to V; want sth done; for want of","k":"col"}]},{"type":"v","title":"Thành ngữ (Idioms)","words":[{"w":"at a loose end","vi":"rảnh mà không biết làm gì","ex":"I was {at a loose end} on Sunday.","k":"idiom"},{"w":"couch potato","vi":"người ngồi xem TV nhiều, ít vận động","ex":"He became a {couch potato} during the break.","k":"idiom"},{"w":"do sth on a whim","vi":"làm theo ý thích chợt đến","ex":"We visited the exhibition on a {whim}.","k":"idiom"},{"w":"have time on your hands","vi":"có nhiều thời gian rảnh hơn cần","ex":"She had time on her {hands} after finishing early.","k":"idiom"},{"w":"let your hair down","vi":"thư giãn, vui chơi thoải mái","ex":"The party let everyone let their hair {down}.","k":"idiom"},{"w":"the life and soul of the party","vi":"người làm buổi tiệc sôi nổi","ex":"She is always {the life and soul of the party}.","k":"idiom"},{"w":"put your feet up","vi":"ngồi/ngả nghỉ ngơi","ex":"{Put your feet up} after the long walk.","k":"idiom"},{"w":"recharge your batteries","vi":"nghỉ để lấy lại năng lượng","ex":"A quiet weekend helped recharge my {batteries}.","k":"idiom"},{"w":"set your heart on","vi":"rất quyết tâm muốn có/làm","ex":"He has set his {heart} on studying music.","k":"idiom"},{"w":"variety is the spice of life","vi":"trải nghiệm đa dạng làm cuộc sống thú vị","ex":"Try something new; {variety is the spice of life}.","k":"idiom"}]},{"type":"v","title":"Cấu tạo từ (Word formation)","words":[{"w":"available","vi":"có sẵn","note":"available → (un)availability, unavailable","full":"có sẵn → tình trạng có/không sẵn; không có.","ex":"Check the venue's {availability}.","hint":"available","k":"wf"},{"w":"choose","vi":"chọn","note":"choose → chose, chosen, choice, choosy","full":"chọn → V2 chose; V3 chosen; lựa chọn; kén chọn.","ex":"She is {choosy} about the courses she takes.","hint":"choose","k":"wf"},{"w":"desire","vi":"mong muốn","note":"desire → (un)desirable, desirous, desired, (un)desirably","full":"mong muốn → đáng/không mong muốn; khao khát; được mong; trạng từ.","ex":"The location is highly {desirable}.","hint":"desire","k":"wf"},{"w":"do","vi":"làm","note":"do → overdo, outdo, redo, undo; did/done; overdid/overdone, outdid/outdone, redid/redone, undid/undone; doing, doings","full":"làm → làm quá; vượt hơn; làm lại; tháo/hủy; các dạng quá khứ/phân từ; việc làm/hành vi.","ex":"Do not {overdo} the exercise.","hint":"do","k":"wf"},{"w":"envy","vi":"ghen","note":"envy → (un)enviable, (un)enviably, envious(ly)","full":"ghen → đáng/không đáng ghen tị; đầy ghen tị.","ex":"An envious rival wanted her {enviable} position.","hint":"envy","k":"wf"},{"w":"leisure","vi":"nhàn rỗi","note":"leisure → leisured, leisurely","full":"nhàn rỗi → có nhiều thời gian nhàn; thong thả, không vội.","ex":"We enjoyed a {leisurely} walk.","hint":"leisure","k":"wf"},{"w":"motive","vi":"động cơ","note":"motive → (de)motivated, (de)motivator, (de)motivation, (de)motivating, motivational","full":"động cơ → được/cạn động lực; người/yếu tố thúc/giảm động lực; mang tính động viên.","ex":"The workshop increased {motivation}.","hint":"motive","k":"wf"},{"w":"obsess","vi":"ám ảnh","note":"obsess → obsession, obsessed, obsessive(ly)","full":"ám ảnh → sự ám ảnh; bị ám ảnh; mang tính ám ảnh.","ex":"He became {obsessed} with improving his score.","hint":"obsess","k":"wf"},{"w":"play","vi":"chơi","note":"play → replay, overplay, downplay, player, playful(ly)","full":"chơi → chơi lại; nhấn quá; xem nhẹ; người chơi; vui đùa.","ex":"Do not {downplay} the value of recreation.","hint":"play","k":"wf"},{"w":"prefer","vi":"thích hơn","note":"prefer → preference, preferable, preferred, preferential, preferably","full":"thích hơn → sở thích; đáng chọn hơn; được thích; ưu đãi; tốt nhất là.","ex":"Early booking is {preferable}.","hint":"prefer","k":"wf"},{"w":"pursue","vi":"theo đuổi","note":"pursue → pursuit, pursuer","full":"theo đuổi → sự theo đuổi; người đuổi.","ex":"She finds pleasure in creative pursuits.","hint":"pursue","k":"wf"},{"w":"relax","vi":"thư giãn","note":"relax → relaxation, relaxing, relaxed","full":"thư giãn → sự thư giãn; tạo thư giãn; thấy thoải mái.","ex":"The music was {relaxing}.","hint":"relax","k":"wf"},{"w":"rest","vi":"nghỉ","note":"rest → restlessness, unrest, restive, restful(ly), restless(ly)","full":"nghỉ → bồn chồn; bất ổn xã hội; khó chịu/nóng lòng; yên tĩnh; không yên.","ex":"A restful evening calmed the {restless} child.","hint":"rest","k":"wf"},{"w":"rhythm","vi":"nhịp","note":"rhythm → rhythmic(al), rhythmically","full":"nhịp → có nhịp; theo nhịp.","ex":"The dancers moved {rhythmically}.","hint":"rhythm","k":"wf"},{"w":"satisfy","vi":"làm hài lòng","note":"satisfy → dissatisfy, (un)satisfactory, (dis)satisfied, (un)satisfying(ly), satisfactorily","full":"làm hài lòng → làm không hài lòng; đạt/không đạt yêu cầu; thấy/không thấy hài lòng; tạo/không tạo thỏa mãn.","ex":"The response was {satisfactory} but not entirely satisfying.","hint":"satisfy","k":"wf"},{"w":"select","vi":"chọn","note":"select → deselect, selection, selective(ly)","full":"chọn → bỏ chọn; sự/tập lựa chọn; có chọn lọc.","ex":"The collection is highly {selective}.","hint":"select","k":"wf"},{"w":"sport","vi":"thể thao","note":"sport → sportsman/woman/person, sportsmanship, sports, sporting, sporty","full":"thể thao → vận động viên; tinh thần thể thao; thuộc thể thao; thích thể thao.","ex":"Good {sportsmanship} matters more than winning.","hint":"sport","k":"wf"},{"w":"stimulate","vi":"kích thích","note":"stimulate → stimulation, stimulant, stimulus, stimuli, stimulating, stimulated","full":"kích thích → sự kích thích; chất kích thích; tác nhân (stimulus), số nhiều stimuli; gây hứng thú; được kích thích.","ex":"The discussion was intellectually {stimulating}.","hint":"stimulate","k":"wf"},{"w":"tend","vi":"có xu hướng","note":"tend → tendency","full":"có xu hướng → xu hướng.","ex":"She has a {tendency} to work late.","hint":"tend","k":"wf"},{"w":"zeal","vi":"nhiệt huyết","note":"zeal → zealot, zealous(ly)","full":"nhiệt huyết → người cuồng tín; nhiệt thành; trạng từ.","ex":"The volunteers worked {zealously}.","hint":"zeal","k":"wf"}]}]}];